\begin{algorithm}[t]
\caption{CPPG \& IPPG Training Process}
\label{alg:cppg-alg}
\begin{algorithmic}[1]
    \Require $alg\_name \in \{CPPG,\; IPPG \}$
    \State Initialize $\mathcal{B} \gets \varnothing$
    \For{task $=1,2,\dots$}
        % \State $a_t \sim \pi_{\omega} (a_t|s_t)$ \Comment{Sample joint action}
        % \State $s_{t+1}, r_{t+1} \gets \text{ACT}(s_t, a_t)$ 
        % \State $\mathcal{B} \gets \mathcal{B} \cup \{s_t, u_t, r_{t+1}, s_{t+1}, V_{targ}(s_t)\}$ 
        \If{$alg\_name = CPPG$}
            \State \Call{CentralizedPolicy}{$s_t, \mathcal{B}$}
        \Else
            \State \Call{DeCentralizedPolicy}{$s_t, \mathcal{B}$}
        \EndIf
        \If{task $\% \; N_{update} = 0$}
            \For{$i = 1,2,\dots, N_{Policy}$}  \Comment{Policy training phase}
                \State Optimize $\mathcal{L}^{DClip}$ w.r.t. $\omega, \omega_{v}$ %(\textit{i.e.}, Eq. \eqref{eq:d-clip-loss})
            \EndFor
            \For{$i = 1,2,\dots, N_{aux}$} \Comment{Auxiliary training phase}
                \State Optimize $\mathcal{L}^{Value}$ w.r.t. $\omega_v$ % (\textit{i.e.}, Eq. \eqref{eq:value-loss})
                \State Optimize $\mathcal{L}^{Joint}$ w.r.t. $\omega$ % (\textit{i.e.}, Eq. \eqref{eq:joint-loss})
            \EndFor
            \For{$i = 1,2,\dots, N_{\lambda}$} \Comment{Coefficient training phase}
                \State $\lambda_k \gets \lambda_k + \eta \nabla_{\lambda_k}\mathcal{L}^{\lambda_k}(u_k) \quad \forall k = 1 \dots K$ 
            \EndFor
            \State $\mathcal{B} \gets \varnothing$ \Comment{Clear replay buffer}
            \State $\omega_{old} \gets \omega$, $\omega_{v_{old}} \gets \omega_v$ \Comment{Update target network}
        \EndIf
    \EndFor

    \Procedure{CentralizedPolicy}{$s_t, \mathcal{B}$}
        \State $a_t \sim \pi_{\omega} (a_t|s_t)$ \Comment{Joint offloading action}
        \State $s_{t+1}, r_{t+1} \gets \text{ACT}(s_t, a_t)$ 
        \State $\mathcal{B} \gets \mathcal{B} \cup \{s_t, u_t, r_{t+1}, s_{t+1}, V_{targ}(s_t)\}$ 
        % \State \textbf{return} $a_t, r_{t+1}, s_{t+1}$
    \EndProcedure

    \Procedure{DeCentralizedPolicy}{$s_t, \mathcal{B}$}
        \For{$k=1...K$}
            \State $u_k^t \sim \pi_{\omega}^k (u_k^t|s_k^t)$ \Comment{User $k$ offloading action}
        \EndFor
        \State $a_t = [u_1^t, u_2^t, ..., u_K^t]$
        \State $s_{t+1}, r_{t+1} \gets \text{ACT}(s_t, a_t)$
        \For{$k=1...K$}
            \State $\mathcal{B} \gets \mathcal{B} \cup \{s_k^t, u_t, r^k_{t+1}, s^k_{t+1}, V^k_{targ}(s_k^t)\}$ 
        \EndFor
        % \State \textbf{return} $a_t, r_{t+1}, s_{t+1}$
    \EndProcedure
\end{algorithmic}
\end{algorithm}

