\subsection{Theoretical Analysis}\label{Theory}
Next, we show how the BAI-MCTS algorithm can guarantee an $\epsilon$-optimal solution for the channel allocation problem by deriving two upper bounds for the sampling complexity and the error probability of the proposed algorithm, respectively. For convenience, we first give the notations related to the MCT. Assume that each AP-STA pair has $|{\mathcal{L}}|$ feasible configurations and the network throughput follows a Gaussian distribution $\mathfrak{N}$. In addition, the ${\boldsymbol{\mu}_{q^h}}$ and ${\boldsymbol{w}_{q^h}^*}$ denote the mean reward and the optimal allocation vector of the $q$-th node at layer $h$, respectively. The best node among $\mathcal{C}(q^h)$ is denoted by $d^*({\boldsymbol{\mu}_{q^h}})$, and the suboptimal gap is defined as  $\Delta_{d}:=\{\mu_{{d^*({\boldsymbol{\mu}_{q^h}})}}-\mu_{d}| d\in \mathcal{C}(q^h)\}$. According to \cite{jourdan2023varepsilon}, the asymptotic characteristic time is defined as the time required to verify an $\epsilon$-optimal arm among $\mathcal{C}(q^h)$ with the stopping rule $\text{GLR}_\epsilon$, i.e., 
\begin{equation}
    \begin{split}
        T_{\epsilon}^{h}({\boldsymbol{\mu}_{q^h}})=\operatorname*{min}_{d\in\mathcal{A}_{\epsilon}(\boldsymbol{\mu}_{q^h})}\operatorname*{min}_{\beta\in(0,1)}T_{\epsilon,\beta}^{h}({\boldsymbol{\mu}_{q^h}},d), 
    \end{split}
\end{equation}
where T$_{\epsilon,\beta}^{h}(\boldsymbol{\mu}_{q^h}, d)$ is the $\beta$-characteristic time for arm $d$, which is the time required for identifying whether the arm $d$ is $\epsilon$-optimal or not in terms of proportion $\beta$, i.e., 
\begin{equation}
    \begin{split}
        &{T_{\epsilon,\beta}^{h}({\boldsymbol{\mu}_{q^h}},d)}^{-1} =\\
        &\max _{\boldsymbol{w}_{q^h}\in\triangle_{|{\mathcal{L}}|},{\boldsymbol{w}}_{q^h}(d)=\beta}\min_{d'\neq d}\frac12\frac{({\mu}_{q^h,d}-\mu_{q^h,d'}+\epsilon)^2}{1/\beta+1/\boldsymbol{w}_{q^h}(d')}.
    \end{split}
\end{equation}
The $\triangle_{|{\mathcal{L}}|}$ is a $(|{\mathcal{L}}|-1)$-dimensional probability simplex, i.e., $\triangle_{|{\mathcal{L}}|}:=\left\{\boldsymbol{w}\in\mathbb{R}_{+}^{|{\mathcal{L}}|}\mid  \sum_{i=1}^{|{\mathcal{L}}|}\boldsymbol{w}(i)=1\right\}$. The ${\boldsymbol{w}}_{q^h}(d)$ is the allocation proportion for arm $d$ in terms of ${\boldsymbol{w}}_{q^h}$. We define the characteristic time $\hat T_{\epsilon}^{h}$ at layer $h$ as the maximum characteristic time among all nodes at layer $h$, i.e.,
\begin{equation}
    \begin{split}
        \hat T_{\epsilon}^{h}(\boldsymbol{\mu}^{h})& = \max_{q=1,\ldots,|{\mathcal{L}}|^{h}} T_{\epsilon}^{h}(\boldsymbol{\mu}_{q^h}),
    \end{split}
\end{equation}
where $\boldsymbol{\mu}^{h}$ denotes the mean reward vector for the sets of child nodes associated with all nodes at layer $h$. Now, we can give the upper bound on the expected sample complexity of the BAI-MCTS algorithm in the asymptotic regime.

\begin{theorem}\label{Theorem1}
\textit{For the BAI-MCTS algorithm with the reward bounded within the interval [0, 1] and its distributions vector ${\boldsymbol{\nu}}\sim\mathfrak{N}_{{|\mathcal{L}|}^{N}}$, its upper bound on the expected sample complexity $\mathbb{E}\left[\tau_{\epsilon,\delta}\right]$ in the asymptotic regime is given by
\begin{equation}
    \begin{split}
        \lim\sup_{\delta\to0}\frac{\mathbb{E}_{{\boldsymbol{\nu}}}[\tau_{\epsilon,\delta}]}{\log(1/\delta)}\leq \sum_{h=0}^{N-1}{\hat T_\frac{\epsilon}{N}^{h}}(\boldsymbol{\mu}^{h}).
    \end{split}
    \end{equation}}
\end{theorem}

\begin{proof}
	See Appendix~\ref{convergence}.
	$\hfill\blacksquare$
\end{proof}

\textbf{Remark:} Theorem \ref{Theorem1} establishes that, in the fixed-confidence setting, the proposed algorithm will converge within a finite time slot $\tau_{\epsilon,\delta}$. Moreover, this algorithm can also be used in the anytime setting. The following theorem provides an upper bound on the probability of recommending a non-$\epsilon$-optimal arm when the algorithm has not stopped yet, thereby complementing Theorem \ref{Theorem1}. In practice, due to the relationship $T_{\epsilon,1/2}(\boldsymbol{\mu}) \leq 2T_\epsilon(\boldsymbol{\mu})$ \cite{jourdan2023varepsilon}, we focus on the case where $\beta = 1/2$.


\begin{theorem}  \label{Theorem2}
\textit{At time slot $t$, for ${\boldsymbol{\nu}} \sim \mathfrak{N}_{{|\mathcal{L}|}^{N}}$, $\mathbb{N}_{t,d_{t,\eta}} \geq D_{{\boldsymbol{\mu}}_{d_{t,\eta}}}$, and $\mathbb{N}_{t,d_{t,h}^*} \geq \max\{D_{{\boldsymbol{\mu}}_{d_{t,h}^*}}, T_1({{\boldsymbol{\mu}}_{d_{t,h}^*}})\},\forall h=\eta+1,\ldots, N-1$, if the BAI-MCTS algorithm with a fixed proportion $\beta = 1/2$ has not stopped yet, then $\forall\epsilon\geq0$,}
\begin{equation}
\begin{aligned}
&\mathbb{P}_{\boldsymbol{\nu}}\left(\hat{\mathcal{I}}_t \notin \mathcal{A}_{\epsilon}(\boldsymbol{\mu})\right) \leq \mathds{1}\left(\epsilon < \Delta_{\mathrm{max}}\right)\left(1 - (1-\delta)^{\frac{\eta}{N}} \right) \\
&\times \prod_{h=\eta+1}^{N-1} \frac{1}{4\sqrt{2(|\mathcal{L}| - 1)}} \left(1 - Q\left(|\mathcal{L}|, \mathbb{N}_{t, d_{t, h}^*}, \boldsymbol{\mu}_{d_{t, h}^*}, \frac{\epsilon}{N}\right)\right) \\
&\times \left(1 - Q\left(|\mathcal{L}|, \mathbb{N}_{t, d_{t, \eta}}, \boldsymbol{\mu}_{d_{t, \eta}}, \frac{\epsilon}{N}\right)\right),
\end{aligned}
\end{equation}
\textit{where $T_1(\boldsymbol{\mu})$ is defined in Appendix~\ref{convergence}. Terms $Q(K,t,\boldsymbol{\mu},\epsilon)$ and $D_{\boldsymbol{\mu}}$ are defined in Appendix~\ref{error}.}
\end{theorem}
\begin{proof}
	See Appendix~\ref{error}.
	$\hfill\blacksquare$
\end{proof}

\textbf{Remark:} Theorem~\ref{Theorem1} reveals that the algorithm's sampling complexity has an upper bound closely related to $\epsilon$. By utilizing the BAI technique, the BAI-MCTS algorithm can reduce its reliance on the suboptimal gap, which frequently acts as a bottleneck in existing MAB algorithms. Theorem~\ref{Theorem2} further asserts that, within the non-converged layers, the error probability of BAI-MCTS decreases exponentially as the number of parent-node selections (i.e., the horizon of child nodes) increases.

\section{The LLM-BAI-MCTS Algorithm}\label{SecLLM}
While the BAI-MCTS algorithm provides an efficient search strategy to solve the channel allocation problem, the theoretical analysis reveals that its sampling complexity and error probability depend on the number of layers and nodes. To further reduce the sampling complexity and bolster the generalizability of the proposed algorithm, we propose the LLM-BAI-MCTS algorithm by integrating LLMs into the BAI-MCTS framework. 
The key idea is to provide a high-quality initialization for the BASI-MCTS algorithm by leveraging the LLMs' ICL and CoT capabilities.
This operation enables efficient exploration of the valuable arm area in Fig.~\ref{Insights}, rather than searching the entire space.

\begin{figure}[!t]
\centerline{\includegraphics[scale=0.70]{Figs/LLM.pdf}}
\caption{An example of the LLM-assisted channel allocation.}
\label{LLM}
\end{figure}
\subsection{In-Context Learning}
ICL refers to the ability of LLMs to perform specific tasks by leveraging information provided within the input context without turning the model parameters. The model ``learns'' how to respond or perform a task based on the examples and instructions given in the prompt itself. Instead of training the model separately for each task, ICL allows it to adjust its responses based on the context provided at inference time. The model uses these cues to generate relevant responses tailored to the task, which can be expressed as
\begin{equation}
LLM(D_{task}, \mathfrak{E}) \Rightarrow \text{output},
\end{equation}
where $D_{task}$ is the task description, and $\mathfrak{E}$ is the example set.  

In the dynamic channel allocation problem, the task description includes the problem's background, objectives, and network information, as illustrated in Fig.~\ref{LLM}. Specifically, we regard the LLM as a wireless network expert responsible for configuring channels for STAs to maximize overall network throughput. The background knowledge provides the core concepts of WiFi 7 networks, such as CSMA and MLO. The key network characteristics include the number of STAs, STAs' locations, and their conflicting relationships obtained from the carrier-sensing graph. In simulations, we adopt few-shot learning to enable the LLM to understand the network information and extract the structure information of the channel allocation problem. As shown in Fig.~\ref{LLM}, ICL utilizes examples consisting of three BSSs (i.e., 3 APs and 6 STAs) to learn how to perform channel allocation. Notice that the allocation results of these examples are derived by solving problem \eqref{total} with Algorithm~\ref{BAI-MCTS}. The motivation behind this operation is that solutions to combinatorial optimization problems in small-scale scenarios can serve as examples for ICL. This facilitates efficient knowledge transfer between small- and large-scale scenarios by bridging optimization-based and data-driven methods.

\subsection{Chain of Thought}\label{CoT}
CoT is a powerful prompting technique that encourages LLMs to break down their reasoning process into sequential steps, rather than jumping directly to a conclusion.
This approach enhances the model's ability to handle complex tasks by breaking them down into several manageable parts, improving the accuracy and coherence of the responses. 
In the channel allocation problem, we integrate CoT with ICL to find a high-quality initialization for the BAI-MCTS algorithm by inserting several CoT-augmented examples into LLMs. As shown in Fig. \ref{LLM}, this problem is broken into five steps:
\begin{enumerate}
{\item  \textbf{Perceive network information:} This step gathers the details about available channels and the number/distribution of APs and STAs in the network.
\item  \textbf{Define allocation rules and objectives:} It establishes rules and objectives for the task to balance STA conflicts and maximize throughput following MLO.
\item  \textbf{Analyze conflict relationships:} It focuses on the CSMA protocol and STAs’ conflicts obtained by the carrier-sensing graph constructed based on (\ref{Sensing}).
\item  \textbf{Prioritize the allocation of low-conflict STAs:} This step initially assigns channels to STAs with minimal conflicts within each channel. 
\item  \textbf{Allocate resources to all STAs:} It adjusts the channel assignments by leveraging the MLO benefits and enhances throughput by considering additional network factors.}
\end{enumerate}

It can be seen from Fig.~\ref{LLM} that each step is attached with a well-designed prompt and the example explanations for ICL. 
These steps constitute an AI workflow that can handle complex tasks autonomously. 
By providing the problem descriptions and examples to the LLM, it outputs a high-quality initialization for the channel allocation problem. Then, this result is fed into the BAI-MCTS algorithm to find the $\epsilon$-optimal solution for the channel allocation problem.

\begin{algorithm}[!t]
\caption{LLM-BAI-MCTS at the Central Coordinator}
\label{LLM_BAI-MCTS_v1}
\begin{algorithmic}[1]
\State \textbf{Initialize:}  the BAI-MCTS algorithm
\State \textbf{Input:}  Problem descriptions and examples
\State \textbf{Output:} The channel allocations
\State Insert the ICL and CoT prompts into the LLM
\State Input the problem information into the LLM
\State Obtain a high-quality initialization
\State Insert this initialization into the BAI-MCTS algorithm
\State Output channel allocation results
\end{algorithmic}
\end{algorithm}

\subsection{The LLM-BAI-MCTS Algorithm}
Building upon ICL and CoT paradigms, we introduce the LLM-BAI-MCTS algorithm for the channel allocation problem in dense WiFi 7 networks, as shown in Algorithm~\ref{LLM_BAI-MCTS_v1}. 
It integrates LLMs with the BAI-MCTS algorithm to enhance efficiency and performance. The process begins with initializing the BAI-MCTS algorithm, taking problem descriptions and examples as input, and aiming to output optimal channel allocations. The key innovation is in lines 4-7, where the algorithm leverages ICL and CoT prompting techniques to extract domain knowledge from the LLM. By inserting these prompts and providing problem information to the LLM, the algorithm obtains a high-quality initialization that significantly reduces the search space for the BAI-MCTS algorithm. This initialization is then fed into the BAI-MCTS algorithm, which explores the remaining solution space to find the $\epsilon$-optimal channel allocation. 

The high-quality initialization refers to a strategic partitioning of the channel allocation problem. Specifically, the algorithm identifies $\mathfrak{L}$ STAs whose configurations are determined directly by the LLM's output, where $\mathfrak{L}$ represents the subset of STAs benefiting from LLM-assisted allocation. This selection can be prioritized based on either the LLM's confidence levels for particular allocations or specific performance requirements of certain STAs within the network. Meanwhile, for the remaining $N-\mathfrak{L}$ STAs, the algorithm employs the BAI-MCTS approach to determine optimal channel allocations. This hybrid strategy significantly reduces computational complexity by decreasing the height of MCT by $\mathfrak{L}$ layers, as these LLM-determined allocations no longer require exploration within the tree structure. 

The insight of Algorithm~\ref{LLM_BAI-MCTS_v1} lies in leveraging the LLM's capabilities to comprehend complex wireless network dynamics without explicit domain-specific training. When provided with carefully structured background information, the LLM can efficiently contextualize the channel allocation problem. By incorporating representative examples during ICL, the model extracts the underlying mathematical relationships between network topologies and their optimal allocation strategies, enabling generalization to novel configurations. The CoT technology further enhances solution quality by decomposing the complex optimization process into interpretable reasoning steps, promoting both reliability and verifiability of the generated allocations. This combination of domain knowledge and guided reasoning enables the LLM to facilitate efficient knowledge transfer between small- and large-scale scenarios by bridging the optimization-based and data-driven methods.

\section{Numerical Results}\label{SecNA}
We conduct several experiments to evaluate the proposed algorithms with different settings. We consider a scenario of a $10\times10$ m square network, as shown in Fig.~\ref{topology}, where three APs are located in the vertices of an equilateral triangle, and the STAs are uniformly distributed in this square area. In this uplink WiFi 7 network, all the STAs employ the CSMA protocol to coordinate their transmissions. 
\begin{figure}[!t]
\centerline{\includegraphics[scale=0.6]{Figs/topology.pdf}}
\caption{A simple network with three BSSs distributed in a $10\times10$ m area.}
\label{topology}
\end{figure}
\setlength{\textfloatsep}{4pt}
The access intensity \cite{jiang2009distributed} of all links in the ICN is set to $1$. The transmit power is set to $20$ dBm, and the carrier sensing threshold is $-60$ dBm. The normalized power of the background noise is $-95$ dBm. The large-scale channel fading is set to $({3\times 10^8}/{4\pi f_c\mathscr{D}^2(\text{STA}, \text{AP})})^2$, where $f_c=\{2.4, 5, 6\}$ GHz is the carrier frequency and $\mathscr{D}(\text{STA}, \text{AP})$ is the Euclidean distance between a STA and an AP. The small-scale channel fading follows a Rayleigh distribution with a $\sqrt{1/2}$ scale parameter. The available
transmission rates are $\{20, 50, 100, 150\}$ Mbps. All results are obtained from $10^3$ MC experiments.

We adopt a discrete event simulator in \cite{tong2021throughput} to simulate the CSMA protocol and calculate the network throughput. For convenience, we assume that each frequency band only has one channel. Thus, the MLO configurations for each AP-STA pair are $\{(001)$$, (010)$$, (100)$$, (011)$$, (101)$$, (110)$$, (111)\}$, corresponding to arms 1 to 7 in Fig.~\ref{arm}. For example, arm 1 is only assigned to the channel in 2.4 GHz, while arm 7 has three channels (links) in 2.4, 5, and 6 GHz, respectively. In the following, we compare the BAI-MCTS algorithm with several baselines in terms of the network throughput. 
\begin{itemize}
    \item \textbf{The UCB applied to the Tree (UCT) algorithm} selects nodes in MCTS by maximizing the estimated mean rewards using the UCB1 algorithm \cite{auer2002finite};
    \item \textbf{The DGN-MCTS algorithm} \cite{bai2013bayesian} models accumulated reward uncertainty as a Normal distribution mixture and selects nodes via Thompson sampling in MCTS;
    \item \textbf{The random selection method} randomly chooses arms with equal probabilities, disregarding estimated rewards;
    \item \textbf{The optimal value} is obtained by solving problem~\eqref{total} using the exhaustive search method.
\end{itemize}

