\section{Preliminaries}
Consider a stable \( n^{th} \)-order linear time-invariant (LTI) system \( G(s) \), represented in minimal state-space form as  
\[
G(s) = C(sI - A)^{-1}B + D,
\]  
with matrices \( A \in \mathbb{R}^{n \times n} \), \( B \in \mathbb{R}^{n \times m} \), \( C \in \mathbb{R}^{p \times m} \), and \( D \in \mathbb{R}^{p \times m} \).  

Consider an \( r^{th} \)-order stable reduced-order approximation \( \hat{G}(s) \) of $G(s)$ with minimal state-space realization:
\[
\hat{G}(s) = \hat{C}(sI - \hat{A})^{-1}\hat{B} + D,
\]
where \( \hat{A} \in \mathbb{C}^{r \times r} \), \( \hat{B} \in \mathbb{C}^{r \times m} \), \( \hat{C} \in \mathbb{C}^{p \times r} \), and $r\ll n$.

The reduced-order model ROM $\hat{G}(s)$ is constructed from \( G(s) \) through Petrov-Galerkin projection:  
\[
\hat{A} = \hat{W}^* A \hat{V}, \quad \hat{B} = \hat{W}^* B, \quad \hat{C} = C \hat{V},
\]  
using full-rank projection matrices \( \hat{V}, \hat{W} \in \mathbb{C}^{n \times r} \) satisfying \( \hat{W}^*\hat{V} = I \). Importantly, the ROM remains unchanged under transformations \( \hat{V} \rightarrow \hat{V}T_v \) and \( \hat{W} \rightarrow \hat{W}T_w \), where \( T_v, T_w \in \mathbb{C}^{r \times r} \) are nonsingular. This property allows the complex projection matrices $(\hat{V}, \hat{W})$ and corresponding reduced-order state-space matrices $(\hat{A},\hat{B},\hat{C})$ to be converted to real-valued representations through appropriate similarity transformations \cite{gallivan2004sylvester}.
\subsection{Interpolation Theory \cite{beattie2017model}}
Consider the right interpolation points \((\sigma_1,\dots, \sigma_v)\) and left interpolation points \((\mu_1, \dots, \mu_w)\). In the interpolation framework, the projection matrices \(\hat{V} \in \mathbb{C}^{n \times vm}\) and \(\hat{W} \in \mathbb{C}^{n \times wp}\) are constructed as:
\begin{align}
\hat{V} &= \begin{bmatrix} (\sigma_1 I - A)^{-1} B & \cdots & (\sigma_v I - A)^{-1} B\end{bmatrix},\label{Kry_V}\\
\hat{W} &= \begin{bmatrix} (\mu_1^* I - A^T)^{-1} C^T & \cdots & (\mu_w^*I - A^T)^{-1} C^T\end{bmatrix}.\label{Kry_W}
\end{align}
To enforce the Petrov-Galerkin condition (\(\hat{W}^*\hat{V}=I\)), \(\hat{W}\) is replaced with \(\hat{W}T_w\), where \(T_w=(\hat{V}^*\hat{W})^{-1}\). The resulting ROM satisfies the interpolation conditions:
\begin{align}
G(\sigma_i)= G_r(\sigma_i), \quad G(\mu_i) = G_r(\mu_i).\label{int_cond_1}
\end{align}
Additionally, if there are common right and left interpolation points, i.e., \(\sigma_i = \mu_j\), the following Hermite interpolation conditions are also satisfied for those points:
\begin{align}
G^\prime(\sigma_i) =  G_r^\prime(\sigma_i).\label{int_cond_2}
\end{align}
\subsection{Interpolatory Loewner framework \cite{mayo2007framework}}
The matrix \( D \) can be obtained by sampling the transfer function \( G(s) \) at a sufficiently high frequency, since \( D = \lim_{s \to \infty} G(s) \). Let \( H(s) \) be defined as:  
\begin{align}
H(s)=C(sI-A)^{-1}B.\nonumber
\end{align}Samples of \( H(s_i) \) can be computed from those of \( G(s_i) \) as:  
\begin{align}
H(s_i)=G(s_i)-G(\infty).\nonumber
\end{align}
In the Loewner framework, the following matrices are constructed from \( H(s) \) samples at interpolation points: 
\begin{align}
\hat{W}^*\hat{V}&=\begin{bsmallmatrix}-\frac{H(\sigma_1) - H(\mu_1)}{\sigma_1 - \mu_1}&\cdots&-\frac{H(\sigma_v) - H(\mu_1)}{\sigma_v - \mu_1}\\\vdots&\ddots&\vdots\\-\frac{H(\sigma_1) - H(\mu_w)}{\sigma_1 - \mu_w}&\cdots&-\frac{H(\sigma_v) - H(\mu_w)}{\sigma_v - \mu_w}\end{bsmallmatrix},\nonumber\\
\hat{W}^*A\hat{V}&=\begin{bsmallmatrix}-\frac{\sigma_1 H(\sigma_1) - \mu_1 H(\mu_1)}{\sigma_1 - \mu_1}&\cdots&-\frac{\sigma_v H(\sigma_v) - \mu_1 H(\mu_1)}{\sigma_v - \mu_1}\\\vdots&\ddots&\vdots\\-\frac{\sigma_1 H(\sigma_1) - \mu_w H(\mu_w)}{\sigma_1 - \mu_w}&\cdots&-\frac{\sigma_v H(\sigma_v) - \mu_w H(\mu_w)}{\sigma_v - \mu_w}\end{bsmallmatrix},\nonumber\\
\hat{W}^*B&=\begin{bsmallmatrix}H(\mu_1)\\\vdots\\H(\mu_w)\end{bsmallmatrix},\quad \hat{C}=C\hat{V}=\begin{bsmallmatrix}H(\sigma_1)&\cdots H(\sigma_v)\end{bsmallmatrix},\label{LF}
\end{align}where \( \hat{V} \) and \( \hat{W} \) are as defined in (\ref{Kry_V}) and (\ref{Kry_W}), respectively.
When \( \sigma_j \approx \mu_i \),
\begin{align}
 \frac{H(\sigma_j) - H(\mu_i)}{\sigma_j - \mu_i}&\approx H^\prime(\sigma_j),\nonumber\\
  \frac{\sigma_j H(\sigma_j) - \mu_i H(\mu_i)}{\sigma_j - \mu_i} &\approx H(\sigma_j) + \sigma_j H^\prime(\sigma_j).\nonumber
\end{align}Thus, if the sets of right and left interpolation points share common elements, derivative samples \( H'(\sigma_j) \) are also needed to construct \( \hat{W}^*\hat{V} \) and \( \hat{W}^*A\hat{V} \). The matrices \( \hat{W}^*\hat{V} \) and \( \hat{W}^*A\hat{V} \) exhibit a special structure known as the Loewner matrix and shifted Loewner matrix, respectively, which gives the name ``Interpolatory Loewner Framework''. The matrix \( \hat{W}^*\hat{V} \) is not always invertible, preventing the computation of \( \hat{A} = (\hat{W}^*\hat{V})^{-1} \hat{W}^*A\hat{V} \) and \( \hat{B} = (\hat{W}^*\hat{V})^{-1} \hat{W}^*B \). Instead, the ROM is constructed in descriptor form:  
\begin{align}
\hat{G}(s)=C\hat{V}(s\hat{W}^*\hat{V}-\hat{W}^*A\hat{V})^{-1}\hat{W}^*B+G(\infty).\nonumber
\end{align}
\subsection{Pseudo-optimal Rational Krylov Algorithm \cite{wolf2014h}}
The matrices $S_v$, $S_w$, $L_v$, and $L_w$ are defined as:
\begin{align}
S_v &= \text{diag}(\sigma_1, \dots, \sigma_r)\otimes I_m,& S_w &= \text{diag}(\mu_1, \dots, \mu_r)\otimes I_m,\nonumber\\
L_v &= \begin{bmatrix} 1, \dots, 1 \end{bmatrix}\otimes I_m,& L_w^T &= \begin{bmatrix} 1, \dots, 1 \end{bmatrix}\otimes I_m.\label{SbLbScLc}
\end{align}
The projection matrices \( \hat{V} \) and \( \hat{W} \) in (\ref{Kry_V}) and (\ref{Kry_W}) solve:
\begin{align}
A\hat{V}-\hat{V}S_v+BL_v&=0,\label{sylv_V}\\
A^T\hat{W}-\hat{W}S_w^*+C^TL_w^T&=0.\label{sylv_W}
\end{align}Pre-multiplying (\ref{sylv_V}) with \( \hat{W}^* \) under the condition $\hat{W}^*\hat{V}=I$ reveals that \( \hat{A} = S_v - \hat{B} L_v \). This parameterizes \( A_r \) in terms of \(\hat{B}=\zeta \) while preserving the interpolation conditions induced by \( \hat{V} \), i.e., varying $\zeta$ is equivalent to varying \( \hat{W} \).

Let us assume that all interpolation points $(\sigma_1,\cdots,\sigma_v)$ lie in the right half of the $s$-plane. Consider the observable pair \( (S_v, L_v) \) that satisfies the Lyapunov equation:
\begin{align}
-S_v^* Q_v - Q_v S_v + L_v^T L_v = 0.\label{pork_qs}
\end{align}
With the free parameter \( \zeta = Q_v^{-1} L_v^T \), we obtain \( \hat{A} = S_v - \hat{B} L_v=-Q_v^{-1} S_v^* Q_v \). The resulting ROM
\begin{align}
\hat{A}_r = -Q_v^{-1} S_v^* Q_v,\quad \hat{B} = Q_v^{-1} L_v^T, \quad \hat{C} = C\hat{V},\nonumber
\end{align}
meets the $\mathcal{H}_2$-optimality condition $\frac{\partial}{\partial\hat{C}}\big(||G(s)-\hat{G}(s)||_{\mathcal{H}_2}^2\big)$. This method is referred to as Input PORK (I-PORK) throughout this paper.

Similarly, pre-multiplying (\ref{sylv_W}) with $\hat{V}^*$ shows that \( \hat{A} \) can also be expressed as \( \hat{A} = S_w - L_w \hat{C} \). This parameterizes \( \hat{A} \) in terms of \( \hat{C}=\zeta \) while preserving the interpolation conditions induced by \( \hat{W} \), since changing $\zeta$ is equivalent to varying $ \hat{V} $.

Let us assume that all interpolation points $(\mu_1,\cdots,\mu_w)$ lie in the right half of the $s$-plane. For the controllable pair $ (S_w, L_w) $ that satisfies the Lyapunov equation:  
\begin{align}  
-S_w P_w - P_w S_w^* + L_w L_w^T = 0, \label{pork_ps}  
\end{align}  
choosing the free parameter $ \zeta = L_w^T P_w^{-1} $ leads to the expression $ \hat{A} =S_w-L_w\hat{C}= -P_w S_w^* P_w^{-1} $. The resulting ROM
\begin{align}  
\hat{A} = -P_w S_w^* P_w^{-1}, \quad \hat{B} = \hat{W}^* B, \quad \hat{C} = L_w^T P_w^{-1},  
\end{align}  
satisfies the $\mathcal{H}_2$-optimality condition given by $\frac{\partial}{\partial\hat{B}}\big(\|G(s)-\hat{G}(s)\|_{\mathcal{H}_2}^2\big)$. This approach is referred to as Output PORK (O-PORK) throughout this paper.
\subsection{Balanced Truncation Family}
The controllability Gramian P and observability Gramian Q are defined through the frequency-domain integrals:
\begin{align}
P &= \frac{1}{2\pi} \int_{-\infty}^{\infty} (j\omega I - A)^{-1} BB^T (-j\omega I - A^T)^{-1} \, d\omega, \label{int1}\\
Q &= \frac{1}{2\pi} \int_{-\infty}^{\infty} (-j\omega I - A^T)^{-1} C^T C (j\omega I - A)^{-1} \, d\omega. \label{int2}
\end{align}
These Gramians solve the following Lyapunov equations:
\begin{align}
AP + PA^T + BB^T = 0,\label{lyap_P}\\
A^TQ + QA + C^T C = 0.\label{lyap_Q}
\end{align}
The Cholesky factorizations of the Gramians are given by
\[
P = L_p L_p^T \quad \text{and} \quad Q = L_q L_q^T.
\]
The balanced square-root algorithm (BSA) \cite{tombs1987truncated}  is among the most numerically stable methods for implementing balanced truncation (BT) \cite{moore1981principal}. It begins by computing the singular value decomposition (SVD) of the product \( L_q^T L_p \):
\[
L_q^TL_p = \begin{bmatrix} U_1 & U_2 \end{bmatrix} \begin{bmatrix} \Sigma_{r} & 0 \\ 0 & \Sigma_{n-r} \end{bmatrix} \begin{bmatrix} V_1^T \\ V_2^T \end{bmatrix}.
\]
The projection matrices \( \hat{W} \) and \( \hat{V} \) in BSA are constructed as:  
\[
\hat{W} = L_q U_1 \Sigma_r^{-\frac{1}{2}} \quad \text{and} \quad \hat{V} = L_p V_1 \Sigma_r^{-\frac{1}{2}}.  
\]  
The ROM constructed by BT preserves the stability of the original system \( G(s) \) as well as its \( r \) largest Hankel singular values \( \sqrt{\lambda_i(PQ)} \). To preserve additional properties—such as stable minimum phase, positive-realness, or bounded-realness—generalized versions of BT have been developed, which primarily differ in their definitions of the Gramians.  

In Linear Quadratic Gaussian (LQG) BT (LQG-BT) \cite{jonckheere1983new}, the Gramian-like matrices are computed by solving the following filter and controller Riccati equations:
\begin{align}
AP_{\text{LQG}}+P_{\text{LQG}}A^T+BB^T-P_{\text{LQG}}C^TCP_{\text{LQG}}=0,\\
A^TQ_{\text{LQG}}+Q_{\text{LQG}}A^T+C^TC-Q_{\text{LQG}}BB^TQ_{\text{LQG}}=0.
\end{align}By replacing \( P \) and \( Q \) with \( P_{\text{LQG}} \) and \( Q_{\text{LQG}} \) in BT, respectively, a ROM can be obtained that is suitable for designing a reduced-order LQG controller with good closed-loop performance when used with the original plant.

In \(\mathcal{H}_\infty\) BT (\(\mathcal{H}_\infty\)-BT) \cite{mustafa1991controller}, the Gramian-like matrices are computed by solving the following filter and controller Riccati equations with \(\gamma > 0\):
\begin{align}
AP_{\mathcal{H}_\infty}+P_{\mathcal{H}_\infty}A^T+BB^T-(1-\gamma^{-2})P_{\mathcal{H}_\infty}C^TCP_{\mathcal{H}_\infty}=0,\\
A^TQ_{\mathcal{H}_\infty}+Q_{\mathcal{H}_\infty}A^T+C^TC-(1-\gamma^{-2})Q_{\mathcal{H}_\infty}BB^TQ_{\mathcal{H}_\infty}=0.
\end{align}By replacing \( P \) and \( Q \) with \( P_{\mathcal{H}_\infty} \) and \( Q_{\mathcal{H}_\infty} \) in BT, respectively, a ROM can be obtained that is suitable for designing a reduced-order \(\mathcal{H}_\infty\) controller with good closed-loop performance when used with the original plant.

In positive-real BT (PR-BT) \cite{green1988balanced,phillips2003guaranteed}, the Gramians solve the following Riccati equations:
\begin{align}
AP_{\text{PR}}+P_{\text{PR}}A^T+(B-P_{\text{PR}}C^T)(D+D^T)^{-1}(B-P_{\text{PR}}C^T)^T=0,\label{P_PR}\\
A^TQ_{\text{PR}}+Q_{\text{PR}}A+(C-B^TQ_{\text{PR}})^T(D+D^T)^{-1}(C-B^TQ_{\text{PR}})=0.\label{Q_PR}
\end{align}By replacing \( P \) and \( Q \) with \( P_{\text{PR}} \) and \( Q_{\text{PR}} \) in BT, respectively, a ROM that preserves the positive-realness of the original model can be obtained.

In bounded-real BT (BR-BT) \cite{pernebo2003model,phillips2003guaranteed}, the Gramians solve the following Riccati equations:
\begin{align}
AP_{\text{BR}}+P_{\text{BR}}A^T+BB^T+(P_{\text{BR}}C^T+BD^T)(I-DD^T)^{-1}\nonumber\\
\times(P_{\text{BR}}C^T+BD^T)^T=0,\label{P_BR}\\
A^TQ_{\text{BR}}+Q_{\text{BR}}A+C^TC+(B^TQ_{\text{BR}}+D^TC)^T(I-D^TD)^{-1}\nonumber\\
\times(B^TQ_{\text{BR}}+D^TC)=0.\label{Q_BR}
\end{align}By replacing \( P \) and \( Q \) with \( P_{\text{BR}} \) and \( Q_{\text{BR}} \) in BT, respectively, a ROM that preserves the bounded-realness of the original model can be obtained.

In self-weighted BT (SW-BT) \cite{zhou1995frequency}, the controllability Gramian \( P \) remains the same as in BT, while the weighted observability Gramian \( Q_{\text{SW}} \) solves the following Lyapunov equation:
\begin{align}
(A-BD^{-1}C)^TQ_{\text{SW}}+Q_{\text{SW}}(A-BD^{-1}C)+C^T(DD^T)^{-1}C=0.\label{Q_SW}
\end{align}By replacing \( Q \) with \( Q_{\text{SW}} \) in BT, a ROM that preserves the minimum-phase property of the original model can be obtained.

In balanced stochastic truncation (BST) \cite{green1988balanced,desai1984transformation}, the controllability Gramian \( P \) remains the same as in BT, while the weighted observability Gramian \( Q_{\text{S}} \) solves the following Riccati equation:
\begin{align}
A^TQ_{\text{S}}+Q_{\text{S}}A+\big(C-(CP+DB^T)Q_{\text{S}}\big)^T(DD^T)^{-1}\nonumber\\
\times\big(C-(CP+DB^T)Q_{\text{S}}\big)=0.\label{Q_S}
\end{align}By replacing \( Q \) with \( Q_{\text{S}} \) in BT, a ROM that preserves the minimum-phase property of the original model can be obtained. Unlike SW-BT, BST can handle non-minimum-phase models as well. Both SW-BT and BST minimize the relative error \( G^{-1}(s)(G(s) - \hat{G}(s)) \) and tend to ensure uniform accuracy across the entire frequency spectrum.
\subsection{Quadrature-based Non-intrusive Implementation of Balanced Truncation}
The integrals (\ref{int1}) and (\ref{int2}) can be approximated numerically using quadrature rules as:  
\begin{align}  
P &\approx \tilde{P} = \sum_{i=1}^{n_p} w_{p,i}^2 (j\omega_i I - A)^{-1} B B^T (-j\omega_i I - A^T)^{-1}, \nonumber \\  
Q &\approx \tilde{Q} = \sum_{i=1}^{n_q} w_{q,i}^2 (-j\nu_i I - A^T)^{-1} C^T C (j\nu_i I - A)^{-1}, \nonumber  
\end{align}  
where \(\omega_i\) and \(\nu_i\) are the quadrature nodes, and \(w_{p,i}^2\) and \(w_{q,i}^2\) are their corresponding weights. The factorizations \(\tilde{P} = \tilde{L}_p \tilde{L}_p^T\) and \(\tilde{Q} = \tilde{L}_q \tilde{L}_q^T\) can be expressed as: $\tilde{L}_p = \hat{V} \hat{L}_p$ and $\tilde{L}_q = \hat{W} \hat{L}_q$, with  
\begin{align}  
\hat{V} &= \begin{bmatrix} (j\omega_1 I - A)^{-1} B & \cdots & (j\omega_{n_p} I - A)^{-1} B \end{bmatrix}, \label{V_tild} \\  
\hat{W} &= \begin{bmatrix} (-j\nu_1 I - A^T)^{-1} C^T & \cdots & (-j\nu_{n_q} I - A^T)^{-1} C^T \end{bmatrix}, \label{W_tild} \\  
\hat{L}_p &= \text{diag}(w_{p,1}, \dots, w_{p,n_p}) \otimes I_m, \nonumber \\  
\hat{L}_q &= \text{diag}(w_{q,1}, \dots, w_{q,n_q}) \otimes I_m. \nonumber  
\end{align}  
Here, \(\hat{L}_p\) and \(\hat{L}_q\) depend only on the quadrature weights. Moreover, the terms \(\hat{W}^*\hat{V}\), \(\hat{W}^* A \hat{V}\), \(\hat{W}^* B\), \(C \hat{V}\), and \(D\) can be constructed non-intrusively using samples of \(G(s)\) via the Loewner framework. In the BSA, \(\tilde{L}_p\) and \(\tilde{L}_q\) replace \(L_p\) and \(L_q\), leading to the decomposition:  
\begin{align} 
\hat{L}_q^* (\hat{W}^*\hat{V}) \hat{L}_p = \begin{bmatrix} \tilde{U}_1 & \tilde{U}_2 \end{bmatrix} \begin{bmatrix} \tilde{\Sigma}_r & 0 \\ 0 & \tilde{\Sigma}_{n-r} \end{bmatrix} \begin{bmatrix} \tilde{V}_1^* \\ \tilde{V}_2^* \end{bmatrix}. \label{bsa_svd} 
\end{align} The projection matrices \(W_r\) and \(V_r\) are then defined as:  
\begin{align}
W_r = \hat{L}_q \tilde{U}_1 \tilde{\Sigma}_r^{-1/2} \quad \text{and} \quad V_r = \hat{L}_p \tilde{V}_1 \tilde{\Sigma}_r^{-1/2}.  \label{bsa_proj}
\end{align}
Finally, the ROM in Quadrature-based BT (QuadBT) \cite{goseaQuad} is constructed as:  
\begin{align}  
\hat{A} &= W_r^* (\hat{W}^* A \hat{V}) V_r, & \hat{B} &= W_r^* (\hat{W}^* B), & \hat{C} &= (C \hat{V}) V_r. \label{bsa_rom}
\end{align}  
In \cite{reiter2023generalizations}, the following observations were made about PRBT, BRBT, and BST:
\begin{enumerate}
\item In PR-BT, the Gramians $P_{\text{PR}}$ and $Q_{\text{PR}}$ are respectively the controllability Gramian and observability Gramian associated with state-space realizations of the spectral factorizations of $G(s)+G^*(s)$.
\item In BR-BT, the Gramians $P_{\text{BR}}$ and $Q_{\text{BR}}$ are respectively the controllability Gramian and observability Gramian associated with state-space realizations of the spectral factorizations of $I_m-G^*(s)G(s)$ and $I_p-G(s)G^*(s)$.
\item In BST, the observability Gramian $Q_\text{S}$ is the frequency-weighted observability Gramian with weight associated with the spectral factorization of $G(s)G^*(s)$.
\item The QuadBT framework could be extended to PR-BT, BR-BT, and BST if samples were available for the spectral factorizations of $G(s)+G^*(s)$, $I_m-G^*(s)G(s)$, $I_p-G(s)G^*(s)$, and $G(s)G^*(s)$.
\item Practical methods to obtain these samples do not currently exist and remain as future work.
\end{enumerate}
We do not discuss these generalizations in detail here because we focus on methods requiring only samples of $G(s)$, for which practical measurement methods exist, unlike for the spectral factorizations of $G(s)+G^*(s)$, $I_m-G^*(s)G(s)$, $I_p-G(s)G^*(s)$, and $G(s)G^*(s)$.
\subsection{ADI-based Non-intrusive Implementation of Balanced Truncation}\label{sec3}
In \cite{wolf2016adi}, it is shown that PORK and the ADI method \cite{benner2013efficient} produce identical approximations of Lyapunov equations when the ADI shifts are selected as the mirror images of the interpolation points. Consequently, the ADI-based approximation of \( P \) for the shifts \( (-\sigma_1, \dots, -\sigma_v) \) can be obtained via I-PORK as \( P \approx \tilde{P} = \hat{V} Q_v^{-1} \hat{V}^* \). Similarly, the approximation of \( Q \) for the shifts \( (-\mu_1, \dots, -\mu_w) \) can be computed via O-PORK as \( Q \approx \tilde{Q} = \hat{W} P_w^{-1} \hat{W}^* \). By factorizing \( Q_v^{-1} = \hat{L}_p \hat{L}_p^* \) and \( P_w^{-1} = \hat{L}_q \hat{L}_q^* \), and defining \( \tilde{L}_p = \hat{V} \hat{L}_p \) and \( \tilde{L}_q = \hat{W} \hat{L}_q \), the approximations \( \tilde{P} \) and \( \tilde{Q} \) can be expressed in factorized form as \( \tilde{P} = \tilde{L}_p \tilde{L}_p^* \) and \( \tilde{Q} = \tilde{L}_q \tilde{L}_q^* \). As noted in \cite{zulfiqar2025non}, replacing \( L_p \) and \( L_q \) with \( \tilde{L}_p \) and \( \tilde{L}_q \) in BSA yields a non-intrusive implementation of BT. This is because \( \hat{L}_p \) and \( \hat{L}_q \) depend only on the interpolation points, and the quantities \( \hat{W}^* \hat{V} \), \( \hat{W}^* A \hat{V} \), \( \hat{W}^* B \), \( C \hat{V} \), and \( D \) can be computed non-intrusively within the Loewner framework. Thus, the ADI-based BT algorithm can be implemented non-intrusively using transfer function samples in the right half-plane, unlike QuadBT, which requires samples along the imaginary axis.  
\section{Main Work}
In this section, we present several new results on data-driven model reduction and controller design, outlined as follows:
\begin{enumerate}
\item Recall that the interpolant $\hat{G}(s)=C\hat{V}(sI-S_v+\zeta L_v)^{-1}\zeta+D$ interpolates $G(s)$ at $(\sigma_1,\cdots,\sigma_v)$, where $\hat{V}$ is defined in (\ref{Kry_V}) and $\zeta$ is a free parameter. We identify a specific choice of $\zeta$ such that the RADI \cite{benner2018radi}-based approximation of $P_{\text{LQG}}$ for ADI shifts $(-\sigma_1, \ldots, -\sigma_v)$ can be produced by solving a Lyapunov equation involving only the interpolation points $(\sigma_1, \ldots, \sigma_v)$ and the product $C\hat{V}$.
\item Similarly, for the interpolant $\hat{G}(s) = \zeta(sI - S_w + L_w\zeta)^{-1} \hat{W}^*B + D$, which interpolates $G(s)$ at $(\mu_1, \ldots, \mu_w)$ with $\hat{W}$ defined in (\ref{Kry_W}), we provide a specific $\zeta$ such that the RADI-based approximation of $Q_{\text{LQG}}$ for ADI shifts $(-\mu_1, \ldots, -\mu_w)$ can be computed by solving a Lyapunov equation involving only the interpolation data $(\mu_1, \ldots, \mu_w)$ and $\hat{W}^*B$.
\item Using these approximations of $P_{\text{LQG}}$ and $Q_{\text{LQG}}$, we develop a non-intrusive implementation of LQG-BT, which enables LQG controller design based solely on samples of the plant’s transfer function $G(s)$ in the right-half of the $s$-plane.
\item A similar approach is proposed for the non-intrusive implementation of $\mathcal{H}_\infty$-BT, which enables $\mathcal{H}_\infty$ controller design based solely on samples of the plant’s transfer function $G(s)$ in the right-half of the $s$-plane.
\item The work in \cite{ahmad2011krylov} presents linear matrix inequalities (LMIs)- and Riccati-based methods for choosing $\zeta$ in $\hat{G}(s)=C\hat{V}(sI-S_v+\zeta L_v)^{-1}\zeta+D$ that preserve positive-realness, bounded-realness, and minimum-phase properties. However, the formulas in \cite{ahmad2011krylov} are intrusive since they require access to the state-space matrices $(A,B,C,D)$, and they are also computationally expensive. In contrast, we propose non-intrusive methods to compute $\zeta$ in both $\hat{G}(s)=C\hat{V}(sI-S_v+\zeta L_v)^{-1}\zeta+D$ and $\hat{G}(s)=\zeta(sI-S_w+L_w\zeta)^{-1}\hat{W}^*B+D$ that preserve these system properties. These new formulas require only the transfer function samples and can be derived using Lyapunov and Sylvester equations (or even directly from $G(s)$, as discussed later).
\item We also provide non-intrusive formulas for computing $\zeta$ in the above interpolants that yield the same approximations of $P_{\text{PR}}$, $Q_{\text{PR}}$, $P_{\text{BR}}$, $Q_{\text{BR}}$, $Q_{\text{S}}$ as those produced by RADI. Together with the approximation of $Q_{\text{SW}}$ obtained via O-PORK, we construct non-intrusive implementations of PR-BT, BR-BT, SW-BT, and BST that rely solely on transfer function samples in the right-half of the $s$-plane.
\end{enumerate}
\subsection{RADI-based Non-intrusive Implementation of LQG-BT}
As demonstrated in \cite{wolf2016adi}, the ADI method for computing the low-rank solution of $P$ with shifts $(-\sigma_1,\dots,-\sigma_v)$ corresponds to a Petrov-Galerkin approach. This method implicitly interpolates at $(\sigma_1,\dots,\sigma_v)$ using the projection matrix $\hat{V}$, while the projection matrix $\hat{W}$ is implicitly chosen to satisfy $\hat{W}^*\hat{V}=I$, ensuring that the poles of $\hat{A}$ are placed at $(-\sigma_1^*,\dots,-\sigma_v^*)$. Similarly, \cite{bertram2024family} shows that the low-rank solution of $P_{\text{LQG}}$ obtained via RADI with shifts $(-\sigma_1,\dots,-\sigma_v)$ can be interpreted as a Petrov-Galerkin method. Here, interpolation is implicitly performed at $(\sigma_1,\dots,\sigma_v)$ using $\hat{V}$, and $\hat{W}$ is selected such that $\hat{W}^*\hat{V}=I$, placing the poles of $\hat{A}-\hat{P}_{\text{LQG}}\hat{C}^*\hat{C}$ at $(-\sigma_1^*,\dots,-\sigma_v^*)$. The matrix $\hat{P}_{\text{LQG}}$ solves the projected Riccati equation:  
\begin{align}  
\hat{A}\hat{P}_{\text{LQG}}+\hat{P}_{\text{LQG}}\hat{A}^*+\hat{B}\hat{B}^*-\hat{P}_{\text{LQG}}\hat{C}^*\hat{C}\hat{P}_{\text{LQG}}=0.\label{proj_ricc_lqg}
\end{align}  
In the following theorem, we specify a choice of $\zeta$ for the interpolant $\hat{G}(s)=C\hat{V}(sI-S_v+\zeta L_v)^{-1}\zeta+D$ such that it places the poles of $\hat{A}-\hat{P}_{\text{LQG}}\hat{C}^*\hat{C}$ at $(-\sigma_1^*,\dots,-\sigma_v^*)$, thereby yielding the same approximation as RADI.  
\begin{theorem}\label{Theorem1}
Let \(\hat{V}\) be as defined in (\ref{Kry_V}), with all interpolation points \((\sigma_1, \dots, \sigma_v)\) located in the right half of the \( s \)-plane. Assume further that the pair \((S_v, L_v)\) is observable and that \(Q_v > 0\) uniquely solves the Lyapunov equation:  
\begin{align}
-S_v^* Q_v - Q_v S_v + L_v^T L_v + \hat{C}^* \hat{C} = 0.\label{Qv_LQG}
\end{align} 
Then, the ROM \(\hat{H}(s)\), defined by  
\[
\hat{A} = S_v - \hat{B} L_v, \quad \hat{B} = Q_v^{-1} L_v^T, \quad \hat{C} = C \hat{V},
\]  
which interpolates \(H(s)\) at \((\sigma_1, \dots, \sigma_v)\), satisfies the following properties:
\begin{enumerate}
\item The matrix \(\hat{A}\) equals \(Q_v^{-1}(-S_v^* + \hat{C}^* \hat{C} Q_v^{-1}) Q_v\).  
\item The solution \(\hat{P}_{\text{LQG}}\) to the projected Riccati equation (\ref{proj_ricc_lqg}) is \(Q_v^{-1}\).  
\item The matrix \(\hat{A} - \hat{P}_{\text{LQG}} \hat{C}^* \hat{C}\) is Hurwitz, with eigenvalues at \((-\sigma_1^*, \dots, -\sigma_v^*)\).
\end{enumerate}
\end{theorem}
\begin{proof}
\begin{enumerate}
  \item\label{item1} Pre-multiplying (\ref{Qv_LQG}) by $Q_v^{-1}$ yields:
\begin{align}
-Q_v^{-1}S_v^*Q_v-S_v&+Q_v^{-1}L_v^TL_v+Q_v^{-1}\hat{C}^*\hat{C}=0\nonumber\\
S_v-\hat{B}L_v&=-Q_v^{-1}S_v^*Q_v+Q_v^{-1}\hat{C}^*\hat{C}\nonumber\\
\hat{A}&=Q_v^{-1}(-S_v^*+\hat{C}^*\hat{C}Q_v^{-1})Q_v.\nonumber
\end{align}
\item\label{item2} Consider the expression:
    \begin{align}
&\hat{A}Q_v^{-1}+Q_v^{-1}\hat{A}^*+\hat{B}\hat{B}^*-Q_v^{-1}\hat{C}^*\hat{C}Q_v^{-1}\nonumber\\
&=-Q_v^{-1}S_v^*+Q_v^{-1}\hat{C}^*\hat{C}Q_v^{-1}-S_vQ_v^{-1}+Q_v^{-1}\hat{C}^*\hat{C}Q_v^{-1}\nonumber\\
&\hspace*{4.2cm}+Q_v^{-1}L_v^TL_vQ_v^{-1}-Q_v^{-1}\hat{C}^T\hat{C}Q_v^{-1}\nonumber\\
&=-Q_v^{-1}S_v^*-S_vQ_v^{-1}+Q_v^{-1}L_v^TL_vQ_v^{-1}+Q_v^{-1}\hat{C}^T\hat{C}Q_v^{-1}\nonumber\\
&=Q_v^{-1}\big(-S_v^*Q_v-Q_vS_v+L_v^TL_v+\hat{C}^*\hat{C}\big)Q_v^{-1}\nonumber\\
&=0.\nonumber
    \end{align}This shows that $Q_v^{-1}$ satisfies the projected Riccati equation (\ref{proj_ricc_lqg}).
    \item Given $\hat{A}= \hat{P}_{\text{LQG}}(-S_v^*+\hat{P}_{\text{LQG}} \hat{C}^* \hat{C})\hat{P}_{\text{LQG}}^{-1}$, the eigenvalues of $\hat{A}$ are equal to those of $-S_v^*+\hat{P}_{\text{LQG}}\hat{C}^*\hat{C}$. As $-S_v^*$ is Hurwitz, the matrix $\hat{A}-\hat{P}_{\text{LQG}}\hat{C}^*\hat{C}$ is Hurwitz with eigenvalues at $(-\sigma_1^*,\cdots,-\sigma_v^*)$.
\end{enumerate}
\end{proof}
Note that $Q_{\text{LQG}}$ is the dual of $P_{\text{LQG}}$. For completeness, we present the dual of Theorem \ref{Theorem1} below, which produces the same approximation of $Q_{\text{LQG}}$ as RADI when the shifts are chosen as $(-\mu_1,\cdots,-\mu_w)$.
\begin{theorem}\label{Theorem2}
Let \(\hat{W}\) be as defined in (\ref{Kry_W}), with all interpolation points \((\mu_1, \dots, \mu_w)\) located in the right half of the \( s \)-plane. Assume further that the pair \((S_w, L_w)\) is controllable and that \(P_v > 0\) uniquely solves the Lyapunov equation:  
\begin{align}
-S_wP_w-P_wS_w^*+L_wL_w^T+\hat{B}\hat{B}^*=0.\label{Pw_LQG}
\end{align} 
Then, the ROM \(\hat{H}(s)\), defined by  
\[
\hat{A}=S_w-L_w\hat{C}, \quad \hat{B}=\hat{W}^*B,\quad \hat{C}=L_w^TP_w^{-1},
\]  
which interpolates \(H(s)\) at \((\mu_1, \dots, \mu_w)\), satisfies the following properties:
\begin{enumerate}
\item The matrix \(\hat{A}\) equals \(P_w(-S_w^*+P_w^{-1}\hat{B}\hat{B}^*)P_w^{-1}\).  
\item The solution \(\hat{Q}_{\text{LQG}}\) to the following projected Riccati equation \begin{align}\hat{A}^*\hat{Q}_{\text{LQG}}+\hat{Q}_{\text{LQG}}\hat{A}+\hat{C}^*\hat{C}-\hat{Q}_{\text{LQG}}\hat{B}\hat{B}^*\hat{Q}_{\text{LQG}}=0\end{align}
    is \(P_w^{-1}\).
\item The matrix \(\hat{A}-\hat{B}\hat{B}^*\hat{Q}_{\text{LQG}}\) is Hurwitz, with eigenvalues at \((-\mu_1^*, \dots, -\mu_w^*)\).
\end{enumerate}
\end{theorem}
\begin{proof}
The proof is similar to that of Theorem \ref{Theorem1} and hence omitted for brevity.
\end{proof}
Similar to the ADI-based non-intrusive implementation of BT, the RADI-based non-intrusive implementation of LQG-BT can be directly obtained using the results of Theorems \ref{Theorem1} and \ref{Theorem2}. The pseudo-code for this implementation, named ``Data-driven LQG-BT (DD-LQG-BT)'', is provided in Algorithm \ref{alg1}.
\begin{algorithm}
\caption{DD-LQG-BT}
\textbf{Input:} RADI shifts for approximating $P_{\text{LQG}}$: $(-\sigma_1,\cdots,-\sigma_{v})$; RADI shifts for approximating $Q_{\text{LQG}}$: $(-\mu_1,\cdots,-\mu_{w})$; Data: $\big(H(\sigma_1),\cdots,H(\sigma_{v}),H(\mu_1),\cdots,H(\mu_{w})\big)$ and $H^\prime(\sigma_i)$ for $\sigma_i=\mu_j$; Reduced order: $r$.

\textbf{Output:} ROM: $(\hat{A},\hat{B},\hat{C})$
\begin{algorithmic}[1]\label{alg1}
\STATE Compute the Loewner quadruplet $(\hat{W}^*\hat{V},\hat{W}^*A\hat{V},\hat{W}^*B,C\hat{V})$ from the samples $H(\sigma_i)$ and $H(\mu_i)$ via (\ref{LF}).
\STATE Set $S_v$, $L_v$, $S_w$, $L_w$ as in (\ref{SbLbScLc}).
\STATE Compute $Q_v$ and $P_w$ by solving the Lyapunov equations (\ref{Qv_LQG}) and (\ref{Pw_LQG}).
\STATE Decompose $Q_v^{-1}$ and $P_w^{-1}$ as $Q_v^{-1}=\hat{L}_p\hat{L}_p^*$ and $P_w^{-1}=\hat{L}_q\hat{L}_q^*$.
\STATE Compute $\hat{V}_r$ and $\hat{W}_r$ from (\ref{bsa_svd}) and (\ref{bsa_proj}).
\STATE Compute $\hat{A}$, $\hat{B}$, and $\hat{C}$ from (\ref{bsa_rom}).
\end{algorithmic}
\end{algorithm}
\begin{remark}
$\mathcal{H}_\infty$-BT is similar to LQG-BT with the only difference being in the computation of $Q_v$ and $P_w$. In $\mathcal{H}_\infty$-BT, $Q_v$ and $P_w$ are computed by solving the following Lyapunov equations:
\begin{align}
-S_v^* Q_v - Q_v S_v + L_v^T L_v + (1-\gamma^{-2})\hat{C}^* \hat{C} &= 0,\\
-S_wP_w-P_wS_w^*+L_wL_w^T+(1-\gamma^{-2})\hat{B}\hat{B}^*&=0.
\end{align}All other steps in Algorithm \ref{alg1} remain the same.
\end{remark}
\subsection{RADI-based Non-intrusive Implementation of PR-BT}
Let us define
\begin{align}G_{\text{PR}}(s)=C_{\text{PR}}(sI-A_{\text{PR}})^{-1}B_{\text{PR}},\nonumber
\end{align} where
\begin{align}
A_{\text{PR}}&=A-B_{\text{PR}}C_{\text{PR}},& B_{\text{PR}}&=BR_{\text{PR}}^{-\frac{1}{2}},\nonumber\\
C_{\text{PR}}&=R_{\text{PR}}^{-\frac{1}{2}}C,& R_{\text{PR}}&=D+D^T.\nonumber
\end{align}
Further, define the ROM
\begin{align}
\hat{G}_{\text{PR}}(s)=\hat{C}_{\text{PR}}(sI-\hat{A}_{\text{PR}})^{-1}\hat{B}_{\text{PR}}\nonumber
\end{align}obtained as follows:
\begin{align}
\hat{A}_{\text{PR}}&=W_{\text{PR}}^*(A_{\text{PR}})V_{\text{PR}}=W_{\text{PR}}^*(A-BR_{\text{PR}}^{-1}C)V_{\text{PR}}=\hat{A}-\hat{B}R_{\text{PR}}^{-1}\hat{C},\nonumber\\
\hat{B}_{\text{PR}}&=W_{\text{PR}}^*B_{\text{PR}}=W_{\text{PR}}^*BR_{\text{PR}}^{-\frac{1}{2}}=\hat{B} R_{\text{PR}}^{-\frac{1}{2}},\nonumber\\
\hat{C}_{\text{PR}}&=C_{\text{PR}}V_{\text{PR}}=R_{\text{PR}}^{-\frac{1}{2}}CV_{\text{PR}}=R_{\text{PR}}^{-\frac{1}{2}}\hat{C},\nonumber
\end{align}where $W_{\text{PR}}^*V_{\text{PR}}=I$.

The Riccati equations (\ref{P_PR}) and (\ref{Q_PR}) can be rewritten as follows:
\begin{align}
A_{\text{PR}}P_{\text{PR}}+P_{\text{PR}}A_{\text{PR}}^T+B_{\text{PR}}B_{\text{PR}}^T+P_{\text{PR}}C_{\text{PR}}^TC_{\text{PR}}P_{\text{PR}}=0,\\
A_{\text{PR}}^TQ_{\text{PR}}+Q_{\text{PR}}A_{\text{PR}}+C_{\text{PR}}^TC_{\text{PR}}+Q_{\text{PR}}B_{\text{PR}}B_{\text{PR}}^TQ_{\text{PR}}=0.
\end{align}
From Theorem \ref{Theorem1}, the RADI-based low-rank approximation of $P_{\text{PR}}$ can be obtained as follows. The projection matrix
\begin{align}
V_{\text{PR}}=\begin{bmatrix}(\sigma_1I-A_{\text{PR}})^{-1}B_{\text{PR}}&\cdots&(\sigma_vI-A_{\text{PR}})^{-1}B_{\text{PR}}\end{bmatrix}
\end{align} solves the following Sylvester equation:
\begin{align}
A_{\text{PR}}V_{\text{PR}}-V_{\text{PR}}S_v+B_{\text{PR}}L_v=0.\label{PR_Sylv}
\end{align}
Then $\hat{C}_{\text{PR}}=C_{\text{PR}}V_{\text{PR}}$ can be computed as follows:
\begin{align}
\hat{C}_{\text{PR}}=\begin{bmatrix}G_{\text{PR}}(\sigma_1)&\cdots&G_{\text{PR}}(\sigma_v)\end{bmatrix}.
\end{align}Thereafter, $Q_v$ is computed by solving the Lyapunov equation:
\begin{align}
-S_v^*Q_v-Q_vS_v+L_v^TL_v-\hat{C}_{\text{PR}}^*\hat{C}_{\text{PR}}=0.\label{th3_sylv}
\end{align}
According to Theorem \ref{Theorem1}, the state-space realization of the ROM $\hat{G}_{\text{PR}}(s)=\hat{C}_{\text{PR}}(sI-\hat{A}_{\text{PR}})^{-1}\hat{B}_{\text{PR}}$ (where $\hat{A}_{\text{PR}}=S_v-Q_v^{-1}L_v^TL_v$, $\hat{B}_{\text{PR}}=Q_v^{-1}L_v^T$, and $\hat{C}_{\text{PR}}=C_{\text{PR}}V_{\text{PR}}$) solves the following projected Riccati equations with $\hat{P}_{\text{PR}}=Q_v^{-1}>0$:
\begin{align}
\hat{A}_{\text{PR}}\hat{P}_{\text{PR}}+\hat{P}_{\text{PR}}\hat{A}_{\text{PR}}^*+\hat{B}_{\text{PR}}\hat{B}_{\text{PR}}^*+\hat{P}_{\text{PR}}\hat{C}_{\text{PR}}^*\hat{C}_{\text{PR}}\hat{P}_{\text{PR}}=0.\label{proj_ricc_Ppr}
\end{align}Since
\begin{align}
\hat{A}&=S_v-Q_v^{-1}L_v^TL_v+Q_v^{-1}L_v^T\hat{C}_{\text{PR}},\nonumber\\
\hat{B}&=Q_v^{-1}L_v^TR_{\text{PR}}^{\frac{1}{2}},\quad \hat{C}=R_{\text{PR}}^{\frac{1}{2}}\hat{C}_{\text{PR}},\label{ss_PR}
\end{align} the Riccati equation (\ref{proj_ricc_Ppr}) can be rewritten as follows:
\begin{align}
\hat{A}\hat{P}_{\text{PR}}+\hat{P}_{\text{PR}}\hat{A}^*+(\hat{B}-\hat{P}_{\text{PR}}\hat{C}^*)R_{\text{PR}}^{-1}(\hat{B}-\hat{P}_{\text{PR}}\hat{C}^*)^*=0.
\end{align}
The RADI-based approximation of $P_{\text{PR}}$ is given by $V_{\text{PR}} Q_v^{-1} V_{\text{PR}}^*$.
\begin{theorem}\label{Theorem3}
Let $G(s)$ be a positive-real transfer function. Define $\tilde{L}_v=R_{\text{PR}}^{-\frac{1}{2}}(L_v-\hat{C}_{\text{PR}})=\begin{bmatrix}l_{v,1}&\cdots&l_{v,v}\end{bmatrix}$ and $T_{v}=\text{blkdiag}(l_{v,1},\cdots,l_{v,v})$. Assume that:
\begin{enumerate}
\item The interpolation points \((\sigma_1, \dots, \sigma_v)\) are located in the right half of the \( s \)-plane. 
  \item The pair $(S_v,\tilde{L}_v)$ is observable.
  \item The matrix $T_{v}$ is invertible.
  \item The realization $(\hat{A},\hat{B},\hat{C})$ defined in (\ref{ss_PR}) is minimal.
\end{enumerate}Then the following statements hold:
\begin{enumerate}
  \item The projection matrix $V_\text{PR}$ satisfies $V_\text{PR}=\hat{V}T_{v}$, where $\hat{V}$ is as in (\ref{Kry_V}).
  \item The ROM $\hat{G}(s)=\hat{C}(sI-\hat{A})^{-1}\hat{B}+D$ interpolates $G(s)$ at $(\sigma_1,\cdots,\sigma_v)$.
  \item The ROM $\hat{G}(s)$ is positive-real. 
\end{enumerate}
\end{theorem}
\begin{proof}
By rearranging variables, the Sylvester equations (\ref{PR_Sylv}) can be rewritten as follows:
\begin{align}
AV_{\text{PR}}-V_{\text{PR}}S_v+B\tilde{L}_v=0.
\end{align} It can then readily be noted that \( V_{\text{PR}} = \hat{V}T_{v} \), where \(\hat{V}\) is as in (\ref{Kry_V}). Thus, \( V_{\text{PR}} \) and \(\hat{V}\) enforce the same interpolation conditions, i.e., \( G(\sigma_i) = \hat{G}(\sigma_i) \), since the columns of \( V_{\text{PR}} \) and \(\hat{V}\) span the same subspace and produce the same ROM with different state-space realizations \cite{gallivan2004sylvester}.  

By defining \( K_{\text{PR}} = (\hat{B} - \hat{P}_{\text{PR}}\hat{C}^*)R_{\text{PR}}^{-\frac{1}{2}} \), the following holds:  
\begin{align}
\hat{A}\hat{P}_{\text{PR}}+\hat{P}_{\text{PR}}\hat{A}^*&=-K_{\text{PR}}K_{\text{PR}}^*\nonumber\\
\hat{P}_{\text{PR}}\hat{C}^*-\hat{B}&=-K_{\text{PR}}R_{\text{PR}}^{\frac{1}{2}}\nonumber\\
R_{\text{PR}}^{\frac{1}{2}}(R_{\text{PR}}^{\frac{1}{2}})^T&=D+D^T.
\end{align} Since \(\hat{P}_{\text{PR}} > 0\), \(\hat{G}(s)\) satisfies the positive-real lemma, and thus \(\hat{G}(s)\) is a positive-real transfer function \cite{phillips2003guaranteed}.
\end{proof}
Now, assume that the matrices of the ROM $\hat{G}_{\text{PR}}(s)=\hat{C}_{\text{PR}}(sI-\hat{A}_{\text{PR}})^{-1}\hat{B}_{\text{PR}}$ are obtained as follows:
\begin{align}
\hat{A}_{\text{PR}}&=\hat{W}^*(A_{\text{PR}})\hat{V}=\hat{W}^*(A-BR_{\text{PR}}^{-1}C)\hat{V}=S_v-\zeta L_v-\zeta R_{\text{PR}}^{-1}C\hat{V},\nonumber\\
\hat{B}_{\text{PR}}&=\hat{W}^*B_{\text{PR}}=\hat{W}^*BR_{\text{PR}}^{-\frac{1}{2}}=\zeta R_{\text{PR}}^{-\frac{1}{2}},\nonumber\\
\hat{C}_{\text{PR}}&=C_{\text{PR}}\hat{V}=R_{\text{PR}}^{-\frac{1}{2}}C\hat{V},\label{th3_rom}
\end{align}where $\hat{V}$ is as in (\ref{Kry_V}) and $\hat{W}$ is an unknown projection matrix satisfying $\hat{W}^* \hat{V} = I$. According to Theorem \ref{Theorem3}, the ROM $\hat{G}_{\text{PR}}(s)$ in (\ref{th3_rom}) interpolates $G_{\text{PR}}(s)$ at the interpolation points $(\sigma_1,\cdots,\sigma_v)$ since $V_{\text{PR}}=\hat{V}T_v$. An immediate consequence is that a ROM $\hat{G}_{\text{PR}}(s)$ interpolating $G_{\text{PR}}(s)$ be constructed directly from the ROM $\hat{G}(s)=C\hat{V}(sI-S_v+\zeta L_v)^{-1}\zeta+D$ using the formula (\ref{th3_rom}). We now use this observation to derive an expression for $T_v$.

Note that
\begin{align}
&\hat{C}_{\text{PR}}=C_{\text{PR}}V_{\text{PR}}=\begin{bmatrix}G_{\text{PR}}(\sigma_1)&\cdots&G_{\text{PR}}(\sigma_v)\end{bmatrix}=\begin{bmatrix}\hat{G}_{\text{PR}}(\sigma_1)&\cdots&\hat{G}_{\text{PR}}(\sigma_v)\end{bmatrix}\nonumber\\
&=C_{\text{PR}}\hat{V}\begin{bsmallmatrix}(\sigma_1I-S_v+\zeta L_v+\zeta R_{\text{PR}}^{-1}C\hat{V})^{-1}\zeta R_{\text{PR}}^{-\frac{1}{2}}&\cdots&(\sigma_vI-S_v+\zeta L_v+\zeta R_{\text{PR}}^{-1}C\hat{V})^{-1}\zeta R_{\text{PR}}^{-\frac{1}{2}}\end{bsmallmatrix}\nonumber\\
&=C_{\text{PR}}\hat{V}T_v.\nonumber
\end{align}
It follows directly that the matrix $T_v$ can be computed from the interpolant $\hat{G}(s)=C\hat{V}(sI-S_v+\zeta L_v)^{-1}\zeta+D$ of $G(s)$. Such an interpolant can be generated by I-PORK, with guaranteed stability. Subsequently,
\begin{align}T_v=\begin{bsmallmatrix}(\sigma_1I-S_v+\zeta L_v+\zeta R_{\text{PR}}^{-1}C\hat{V})^{-1}\zeta R_{\text{PR}}^{-\frac{1}{2}}&\cdots&(\sigma_vI-S_v+\zeta L_v+\zeta R_{\text{PR}}^{-1}C\hat{V})^{-1}\zeta R_{\text{PR}}^{-\frac{1}{2}}\end{bsmallmatrix}\nonumber
\end{align}can be obtained by solving the Sylvester equation:
\begin{align}
(S_v-\zeta L_v-\zeta R_{\text{PR}}^{-1}C\hat{V})T_{v}-T_{v}S_v+\zeta R_{\text{PR}}^{-\frac{1}{2}}L_v=0.
\end{align}
An immediate consequence is that positive-realness can be enforced non-intrusively on the ROM produced by I-PORK, using only samples of $G(s)$ at $\sigma_i$ and $G(\infty)$. This is implemented in Algorithm \ref{alg2}, named ``Data-driven Positive-real Interpolation ($V$-type) (DD-PRI-V)''. The resulting ROM is simply a different state-space realization of the ROM defined in (\ref{ss_PR}).
\begin{algorithm}
\caption{DD-PRI-V}
\textbf{Input:} Interpolation points: $(\sigma_1,\cdots,\sigma_{v})$; Data: $\big(H(\sigma_1),\cdots,H(\sigma_{v})\big)$ and $G(\infty)$.

\textbf{Output:} ROM: $(\hat{A},\hat{B},\hat{C},D)$
\begin{algorithmic}[1]\label{alg2}
\STATE Compute $\hat{C}=C\hat{V}$ from the samples $H(\sigma_i)$ via (\ref{LF}).
\STATE Set $D=G(\infty)$ and $R_{\text{PR}}=D+D^T$.
\STATE Set $S_v$ and $L_v$ as in (\ref{SbLbScLc}).
\STATE Compute $Q_v$ by solving the Lyapunov equation (\ref{pork_qs}).
\STATE Compute $T_{v}$ by solving the following Sylvester equation:\\
$(S_v-Q_v^{-1}L_v^TL_v-Q_v^{-1}L_v^TR_{\text{PR}}^{-1}\hat{C})T_{v}-T_{v}S_v+Q_v^{-1}L_v^TR_{\text{PR}}^{-\frac{1}{2}}L_v=0$.
\STATE Set $\hat{C}_{\text{PR}}=R_{\text{PR}}^{-\frac{1}{2}}\hat{C}T_v$.
\STATE Update $Q_v$ by solving the Lyapunov equations (\ref{th3_sylv}).
\STATE Set $\hat{B}=T_vQ_v^{-1}L_v^TR_{\text{PR}}^{\frac{1}{2}}$ and $\hat{A}=S_v-\hat{B}L_v$.
\end{algorithmic}
\end{algorithm}

Next, the RADI-based approximation of $Q_{\text{PR}}$ can be obtained using Theorem \ref{Theorem2} as follows. The projection matrix
\begin{align}
W_{\text{PR}}^*=\begin{bmatrix}C_{\text{PR}}(\mu_1I-A_{\text{PR}})^{-1}\\\vdots\\C_{\text{PR}}(\mu_wI-A_{\text{PR}})^{-1}\end{bmatrix}
\end{align} solves the Sylvester equation:
\begin{align}
A_{\text{PR}}^TW_{\text{PR}}-W_{\text{PR}}S_w^*+C_{\text{PR}}^TL_w^T=0.
\end{align}
Then, $\hat{B}_{\text{PR}}=W_{\text{PR}}^*B_{\text{PR}}$ can be computed as:
\begin{align}
\hat{B}_{\text{PR}}=\begin{bmatrix}G_{\text{PR}}(\mu_1)\\\vdots\\G_{\text{PR}}(\mu_w)\end{bmatrix}.
\end{align}Subsequently, $P_w$ is obtained by solving the Lyapunov equation:
\begin{align}
-S_wP_w-P_wS_w^*+L_wL_w^T-\hat{B}_{\text{PR}}\hat{B}_{\text{PR}}^*=0.\label{th4_sylv}
\end{align}
According to Theorem \ref{Theorem2}, the state-space realization of the ROM $\hat{G}_{\text{PR}}(s)=\hat{C}_{\text{PR}}(sI-\hat{A}_{\text{PR}})^{-1}\hat{B}_{\text{PR}}$ (where $\hat{A}_{\text{PR}}=S_w-L_wL_w^TP_w^{-1}$, $\hat{B}_{\text{PR}}=W_{\text{PR}}^*B_{\text{PR}}$, and $\hat{C}_{\text{PR}}=L_w^TP_w^{-1}$) satisfies the projected Riccati equations with $\hat{Q}_{\text{PR}}=P_w^{-1}>0$
\begin{align}
\hat{A}_{\text{PR}}^*\hat{Q}_{\text{PR}}+\hat{Q}_{\text{PR}}\hat{A}_{\text{PR}}+\hat{C}_{\text{PR}}^*\hat{C}_{\text{PR}}+\hat{Q}_{\text{PR}}\hat{B}_{\text{PR}}\hat{B}_{\text{PR}}^*\hat{Q}_{\text{PR}}=0.\label{proj_ricc_Qpr}
\end{align}Since
\begin{align}
\hat{A}&=S_w-L_wL_w^TP_w^{-1}+\hat{B}_{\text{PR}}L_w^TP_w^{-1},\nonumber\\
\hat{B}&=\hat{B}_{\text{PR}}R_{\text{PR}}^{\frac{1}{2}},\quad \hat{C}=R_{\text{PR}}^{\frac{1}{2}}L_w^TP_w^{-1},\label{ss_PR_2}
\end{align}the Riccati equation (\ref{proj_ricc_Qpr}) can be rewritten as
\begin{align}
\hat{A}^*\hat{Q}_{\text{PR}}+\hat{Q}_{\text{PR}}\hat{A}+(\hat{C}-\hat{B}^*\hat{Q}_{\text{PR}})^*R_{\text{PR}}^{-1}(\hat{C}-\hat{B}^*\hat{Q}_{\text{PR}}))=0.
\end{align}
The RADI-based approximation of $Q_{\text{PR}}$ is then given by $W_{\text{PR}}P_w^{-1}W_{\text{PR}}^*$.
\begin{theorem}\label{Theorem4}
Let $G(s)$ be a positive-real transfer function. Define $\tilde{L}_w^*=R_{\text{PR}}^{-\frac{1}{2}}(L_w^T-\hat{B}_{\text{PR}}^*)=\begin{bmatrix}l_{w,1}^*&\cdots&l_{w,q}^*\end{bmatrix}$ and $T_{w}=\text{blkdiag}(l_{w,1}^*,\cdots,l_{w,q}^*)$. Assume that:
\begin{enumerate}
\item The interpolation points $(\mu_1,\cdots,\mu_w)$ are located in the right half of the $s$-plane.
  \item The pair $(S_w,\tilde{L}_w)$ is controllable.
  \item The matrix $T_{w}$ is invertible.
  \item The realization $(\hat{A},\hat{B},\hat{C})$ defined in (\ref{ss_PR_2}) is minimal.
\end{enumerate}Then the following statements hold:
\begin{enumerate}
  \item The projection matrix $W_\text{PR}$ satisfies $W_\text{PR}=\hat{W}T_{w}$, where $\hat{W}$ is as in (\ref{Kry_W}).
  \item The ROM $\hat{G}(s)=\hat{C}(sI-\hat{A})^{-1}\hat{B}+D$ interpolates $G(s)$ at $(\mu_1,\cdots,\mu_w)$.
  \item The ROM $\hat{G}(s)$ is positive-real. 
\end{enumerate}
\end{theorem}
\begin{proof}
The proof is similar to the proof of Theorem \ref{Theorem3} and hence omitted for brevity.
\end{proof}
We now derive an expression for \( T_{w} \) when \(\hat{W}\) is used to enforce interpolation conditions instead of \( W_{\text{PR}} \). Since \( W_{\text{PR}} \) and \(\hat{W}\) enforce identical interpolation conditions, the following holds:
\begin{align}
\hat{B}_{\text{PR}}&=W_{\text{PR}}^*B_{\text{PR}}=\begin{bmatrix}G_{\text{PR}}(\mu_1)\\\vdots\\G_{\text{PR}}(\mu_w)\end{bmatrix}=\begin{bmatrix}\hat{G}_{\text{PR}}(\mu_1)\\\vdots\\\hat{G}_{\text{PR}}(\mu_w)\end{bmatrix}\nonumber\\
&=\begin{bsmallmatrix}R_{\text{PR}}^{-\frac{1}{2}}\zeta(\mu_1I-S_w+L_w\zeta+\hat{W}^*BR_{\text{PR}}^{-1}\zeta)^{-1}\\\vdots\\R_{\text{PR}}^{-\frac{1}{2}}\zeta(\mu_wI-S_w+L_w\zeta+\hat{W}^*BR_{\text{PR}}^{-1}\zeta)^{-1}\end{bsmallmatrix}\hat{W}^*B_{\text{PR}},\nonumber\\
&=T_{w}^*\hat{W}^*BR_{\text{PR}}^{-\frac{1}{2}},\nonumber
\end{align}
where \(\hat{G}(s) = \zeta (s I - S_w + L_w \zeta)^{-1} \hat{W}^* B + D\) is an interpolant of \( G(s) \). Such an interpolant can be generated by O-PORK, which guarantees stability, and \( T_{w} \) can be constructed from this interpolant by solving the Sylvester equation:
\begin{align}
(S_w-L_w\zeta-\hat{W}^*BR_{\text{PR}}^{-1}\zeta)^*T_{w}-T_{w}S_w^*+\zeta^*R_{\text{PR}}^{-\frac{1}{2}}L_w^T=0.\nonumber
\end{align}
An immediate consequence is that positive-realness can be enforced non-intrusively on the ROM produced by O-PORK, using only samples of \( G(s) \) at \( \mu_i \) and \( G(\infty) \). This is implemented in Algorithm \ref{alg3}, named ``Data-driven Positive-real Interpolation (\( W \)-type) (DD-PRI-W)''. The resulting ROM is simply a different state-space realization of the ROM defined in (\ref{ss_PR_2}).
\begin{algorithm}
\caption{DD-PRI-W}
\textbf{Input:} Interpolation points: $(\mu_1,\cdots,\mu_{w})$; Data: $\big(H(\mu_1),\cdots,H(\mu_{w})\big)$ and $G(\infty)$.

\textbf{Output:} ROM: $(\hat{A},\hat{B},\hat{C},D)$
\begin{algorithmic}[1]\label{alg3}
\STATE Compute $\hat{B}=\hat{W}^*B$ from the samples $H(\mu_i)$ via (\ref{LF}).
\STATE Set $D=G(\infty)$ and $R_{\text{PR}}=D+D^T$.
\STATE Set $S_w$ and $L_w$ as in (\ref{SbLbScLc}).
\STATE Compute $P_w$ by solving the Lyapunov equations (\ref{pork_ps}).
\STATE Compute $T_{w}$ by solving the following Sylvester equation:\\
$(S_w-L_wL_w^TP_w^{-1}-\hat{B}R_{\text{PR}}^{-1}L_w^TP_w^{-1})^*T_{w}-T_{w}S_w^*+P_w^{-1}L_wR_{\text{PR}}^{-\frac{1}{2}}L_w^T=0$.
\STATE Set  $\hat{B}_{\text{PR}}=T_{w}^*\hat{B}R_{\text{PR}}^{-\frac{1}{2}}$.
\STATE Update $P_w$ by solving the Lyapunov equations (\ref{th4_sylv}).
\STATE Set $\hat{C}=R_{\text{PR}}^{\frac{1}{2}}L_w^TP_w^{-1}T_w^*$ and $\hat{A}=S_w-L_w\hat{C}$.
\end{algorithmic}
\end{algorithm}

Similar to the ADI-based non-intrusive implementation of BT, the RADI-based non-intrusive implementation of PR-BT can be directly obtained using the results of Theorems \ref{Theorem3} and \ref{Theorem4}. The pseudo-code for this implementation, named ``Data-driven PR-BT (DD-PR-BT)'', is provided in Algorithm \ref{alg4}.
\begin{algorithm}
RADI shifts for approximating $P_{\text{PR}}$: $(-\sigma_1,\cdots,-\sigma_{v})$; RADI shifts for approximating $Q_{\text{PR}}$: $(-\mu_1,\cdots,-\mu_{w})$; Data: $\big(H(\sigma_1),\cdots,H(\sigma_{v}),H(\mu_1),\cdots,H(\mu_{w}),G(\infty)\big)$ and $H^\prime(\sigma_i)$ for $\sigma_i=\mu_j$; Reduced order: $r$.

\textbf{Output:} ROM: $(\hat{A},\hat{B},\hat{C},D)$
\caption{DD-PR-BT}
\begin{algorithmic}[1]\label{alg4}
\STATE Compute the Loewner quadruplet $(\hat{W}^*\hat{V},\hat{W}^*A\hat{V},\hat{W}^*B,C\hat{V})$ from the samples $H(\sigma_i)$ and $H(\mu_i)$ via (\ref{LF}).
\STATE Set $D=G(\infty)$ and $R_{\text{PR}}=D+D^T$.
\STATE Set $S_v$, $L_v$, $S_w$, $L_w$ as in (\ref{SbLbScLc}).
\STATE Compute $Q_v$ and $P_w$ by solving the Lyapunov equations (\ref{pork_qs}) and (\ref{pork_ps}).
\STATE Compute $T_{v}$ and $T_{w}$ by solving the following Sylvester equations:\\
$(S_v-Q_v^{-1}L_v^TL_v-Q_v^{-1}L_v^TR_{\text{PR}}^{-1}C\hat{V})T_{v}-T_{v}S_v+Q_v^{-1}L_v^TR_{\text{PR}}^{-\frac{1}{2}}L_v=0$,\\
$(S_w-L_wL_w^TP_w^{-1}-\hat{W}^*BR_{\text{PR}}^{-1}L_w^TP_w^{-1})^*T_{w}-T_{w}S_w^*+P_w^{-1}L_wR_{\text{PR}}^{-\frac{1}{2}}L_w^T=0$.
\STATE Set $\hat{C}_{\text{PR}}=R_{\text{PR}}^{-\frac{1}{2}}C\hat{V}T_{v}$ and $\hat{B}_{\text{PR}}=T_{w}^*\hat{W}^*BR_{\text{PR}}^{-\frac{1}{2}}$.
\STATE Update $Q_v$ and $P_w$ by solving the Lyapunov equations (\ref{th3_sylv}) and (\ref{th4_sylv}).
\STATE Decompose $Q_v^{-1}$ and $P_w^{-1}$ as $Q_v^{-1}=\hat{L}_p\hat{L}_p^*$ and $P_w^{-1}=\hat{L}_q\hat{L}_q^*$.
\STATE Compute the following SVD:\\
$\hat{L}_q^*T_w^* (\hat{W}^*\hat{V})T_v \hat{L}_p = \begin{bmatrix} \tilde{U}_1 & \tilde{U}_2 \end{bmatrix} \begin{bmatrix} \tilde{\Sigma}_r & 0 \\ 0 & \tilde{\Sigma}_{n-r} \end{bmatrix} \begin{bmatrix} \tilde{V}_1^* \\ \tilde{V}_2^* \end{bmatrix}$.
\STATE Set $W_r = T_w\hat{L}_q \tilde{U}_1 \tilde{\Sigma}_r^{-1/2}$ and $V_r = T_v\hat{L}_p \tilde{V}_1 \tilde{\Sigma}_r^{-1/2}$.
\STATE Compute $\hat{A}$, $\hat{B}$, and $\hat{C}$ from (\ref{bsa_rom}).
\end{algorithmic}
\end{algorithm}
\subsection{RADI-based Non-intrusive Implementation of BR-BT}
By noting that $D^T(I - DD^T)^{-1} = (I - D^TD)^{-1}D^T$, define the following matrices: $R_p=I-DD^T$, $R_q=I-D^TD$, $R_b=I+D^TR_p^{-1}D$, and $R_c=I+DR_q^{-1}D^T$.
Further, define the transfer functions
\begin{align}
G_{\text{BR}}^{\text{P}}(s)&=C_{\text{BR}}^{\text{P}}(sI-A_{\text{BR}})^{-1}B_{\text{BR}}^{\text{P}},\nonumber\\
G_{\text{BR}}^{\text{Q}}(s)&=C_{\text{BR}}^{\text{Q}}(sI-A_{\text{BR}})^{-1}B_{\text{BR}}^{\text{Q}},\nonumber
\end{align}where
\begin{align}
A_{\text{BR}}&=A+BD^TR_p^{-1}C=A+BR_q^{-1}D^TC,\nonumber\\
B_{\text{BR}}^{\text{P}}&=BR_b^{\frac{1}{2}},\quad C_{\text{BR}}^{\text{P}}=R_p^{-\frac{1}{2}}C,\nonumber\\
B_{\text{BR}}^{\text{Q}}&=BR_q^{-\frac{1}{2}},\quad C_{\text{BR}}^{\text{Q}}=R_c^{\frac{1}{2}}C.\nonumber
\end{align}
Next, define the ROMs  
\begin{align}
\hat{G}_{\text{BR}}^{\text{P}}(s)&=\hat{C}_{\text{BR}}^{\text{P}}(sI-\hat{A}_{\text{BR}})^{-1}\hat{B}_{\text{BR}}^{\text{P}},\nonumber\\
\hat{G}_{\text{BR}}^{\text{Q}}(s)&=\hat{C}_{\text{BR}}^{\text{Q}}(sI-\hat{A}_{\text{BR}})^{-1}\hat{B}_{\text{BR}}^{\text{Q}},\nonumber
\end{align}obtained as
\begin{align}
\hat{A}_{\text{BR}}&=W_{\text{BR}}^*A_{\text{BR}}V_{\text{BR}}=\hat{A}+\hat{B}D^TR_p^{-1}\hat{C}=\hat{A}+\hat{B}R_q^{-1}D^T\hat{C},\nonumber\\
\hat{B}_{\text{BR}}^{\text{P}}&=W_{\text{BR}}^*B_{\text{BR}}^{\text{P}}=\hat{B}R_b^{\frac{1}{2}},\quad \hat{C}_{\text{BR}}^{\text{P}}=C_{\text{BR}}^{\text{P}}V_{\text{BR}}=R_p^{-\frac{1}{2}}\hat{C},\nonumber\\
\hat{B}_{\text{BR}}^{\text{Q}}&=W_{\text{BR}}^*B_{\text{BR}}^{\text{Q}}=\hat{B}R_q^{-\frac{1}{2}},\quad \hat{C}_{\text{BR}}^{\text{Q}}=C_{\text{BR}}^{\text{Q}}V_{\text{BR}}=R_c^{\frac{1}{2}}\hat{C},\nonumber
\end{align}where $W_{\text{BR}}^*V_{\text{BR}}=I$.

The Riccati equations (\ref{P_BR}) and (\ref{Q_BR}) can be rewritten as follows:  
\begin{align}
A_{\text{BR}}P_{\text{BR}}+P_{\text{BR}}A_{\text{BR}}^T+B_{\text{BR}}^{\text{P}}(B_{\text{BR}}^{\text{P}})^*+P_{\text{BR}}(C_{\text{BR}}^{\text{P}})^*C_{\text{BR}}^{\text{P}}P_{\text{BR}}=0,\\
A_{\text{BR}}^TQ_{\text{BR}}+Q_{\text{BR}}A_{\text{BR}}+(C_{\text{BR}}^{\text{Q}})^*C_{\text{BR}}^{\text{Q}}+Q_{\text{BR}}B_{\text{BR}}^{\text{Q}}(B_{\text{BR}}^{\text{Q}})^*Q_{\text{BR}}=0.
\end{align}
By applying Theorem \ref{Theorem1}, the RADI-based approximation of $P_{\text{BR}}$ can be obtained as follows. The projection matrix  
\begin{align}
V_{\text{BR}}=\begin{bmatrix}(\sigma_1I-A_{\text{BR}})^{-1}B_{\text{BR}}^{\text{P}}&\cdots&(\sigma_vI-A_{\text{BR}})^{-1}B_{\text{BR}}^{\text{P}}\end{bmatrix}
\end{align} solves the following Sylvester equation:  
\begin{align}
A_{\text{BR}}V_{\text{BR}}-V_{\text{BR}}S_v+B_{\text{BR}}^{\text{P}}L_v=0.
\end{align}
Then, $\hat{C}_{\text{BR}}^{\text{P}}=C_{\text{BR}}^{\text{P}}V_{\text{BR}}$ can be computed as follows:
\begin{align}
\hat{C}_{\text{BR}}^{\text{P}}=\begin{bmatrix}G_{\text{BR}}^{\text{P}}(\sigma_1)&\cdots&G_{\text{BR}}^{\text{P}}(\sigma_v)\end{bmatrix}.
\end{align}Thereafter, $Q_v$ is computed by solving the Lyapunov equation:
\begin{align}
-S_v^*Q_v-Q_vS_v+L_v^TL_v-(\hat{C}_{\text{BR}}^{\text{P}})^*\hat{C}_{\text{BR}}^{\text{P}}=0.\label{th5_sylv}
\end{align}
According to Theorem \ref{Theorem1}, the ROM $(\hat{A}_{\text{BR}}=S_v-\hat{B}_{\text{BR}}^{\text{P}}L_v,\hat{B}_{\text{BR}}^{\text{P}}=Q_v^{-1}L_v^T,\hat{C}_{\text{BR}}^{\text{P}}=C_{\text{BR}}^{\text{P}}V_{\text{BR}})$ solves the following projected Riccati equation with $\hat{P}_{\text{BR}} = Q_v^{-1} > 0$:  
\begin{align}
\hat{A}_{\text{BR}}\hat{P}_{\text{BR}}+\hat{P}_{\text{BR}}\hat{A}_{\text{BR}}^*+\hat{B}_{\text{BR}}^{\text{P}}(\hat{B}_{\text{BR}}^{\text{P}})^*+\hat{P}_{\text{BR}}(\hat{C}_{\text{BR}}^{\text{P}})^*\hat{C}_{\text{BR}}^{\text{P}}\hat{P}_{\text{BR}}=0.\label{proj_ricc_Pbr}
\end{align}
Since
\begin{align}
\hat{A}&=S_v-Q_v^{-1}L_v^TL_v-\hat{B}D^TR_p^{-1}\hat{C},\nonumber\\
\hat{B}&=Q_v^{-1}L_v^TR_b^{-\frac{1}{2}},\quad\hat{C}=R_p^{\frac{1}{2}}C_{\text{BR}}^{\text{P}}V_{\text{BR}},\label{ss_BR}
\end{align}
the Riccati equation (\ref{proj_ricc_Pbr}) can be rewritten as  
\begin{align}
\hat{A}P_{\text{BR}}+\hat{P}_{\text{BR}}\hat{A}^*+\hat{B}\hat{B}^*+(\hat{P}_{\text{BR}}\hat{C}^*+\hat{B}D^T)R_p^{-1}(\hat{P}_{\text{BR}}\hat{C}^*+\hat{B}D^T)^*=0.\nonumber
\end{align}
\begin{theorem}\label{Theorem5}
Let $G(s)$ be a bounded-real transfer function. Define $\tilde{L}_v=D^TR_p^{-\frac{1}{2}}\hat{C}_{\text{BR}}^{\text{P}}+R_b^{\frac{1}{2}}L_v=\begin{bmatrix}l_{v,1}&\cdots&l_{v,p}\end{bmatrix}$ and $T_{v}=\text{blkdiag}(l_{v,1},\cdots,l_{v,p})$. Assume that:
\begin{enumerate}
\item The interpolation points \((\sigma_1, \dots, \sigma_v)\) are located in the right half of the \( s \)-plane. 
  \item The pair $(S_v,\tilde{L}_v)$ is observable.
  \item The matrix $T_{v}$ is invertible.
  \item The realization $(\hat{A},\hat{B},\hat{C})$ defined in (\ref{ss_BR}) is minimal.
\end{enumerate}Then the following statements hold:
\begin{enumerate}
  \item\label{BRitem1} The projection matrix $V_\text{BR}$ is equal to $\hat{V}T_{v}$ where $\hat{V}$ is as in (\ref{Kry_V}).
  \item\label{BRitem2} The ROM $\hat{G}(s)=\hat{C}(sI-\hat{A})^{-1}\hat{B}+D$ interpolates $G(s)$ at $(\sigma_1,\cdots,\sigma_p)$.
  \item The ROM $\hat{G}(s)$ is bounded-real. 
\end{enumerate}
\end{theorem}
\begin{proof}
The proofs of \ref{BRitem1} and \ref{BRitem2} are similar to Theorem \ref{Theorem3}; hence, they are omitted for brevity.

By defining $K_{\text{BR}}=(\hat{P}_{\text{BR}}\hat{C}^*+\hat{B}D^T)R_p^{-\frac{1}{2}}$, the following relations hold:
\begin{align}
\hat{A}\hat{P}_{\text{BR}}+\hat{P}_{\text{BR}}\hat{A}^*=-\hat{B}\hat{B}^*-K_{\text{BR}}K_{\text{BR}}^*,\nonumber\\
\hat{P}_{\text{BR}}\hat{C}^*+\hat{B}D^T=-K_{\text{BR}}R_p^{\frac{1}{2}},\nonumber\\
R_p^{\frac{1}{2}}(R_p^{\frac{1}{2}})^*=I-DD^T.\nonumber
\end{align}
Since $\hat{P}_{\text{BR}} > 0$, $\hat{G}(s)$ satisfies the bounded-real lemma \cite{phillips2003guaranteed}.
\end{proof}
We now derive an expression for \( T_{v} \) when \( \hat{V} \) is used to enforce interpolation conditions instead of \( V_{\text{BR}} \). Since \( V_{\text{BR}} \) and \( \hat{V} \) enforce the same interpolation conditions, the following holds:
\begin{align}
\hat{C}_{\text{BR}}^{\text{P}}&=C_{\text{BR}}^{\text{P}}V_{\text{BR}}=\begin{bmatrix}G_{\text{BR}}^{\text{P}}(\sigma_1)&\cdots&G_{\text{BR}}^{\text{P}}(\sigma_v)\end{bmatrix}=\begin{bmatrix}\hat{G}_{\text{BR}}^{\text{P}}(\sigma_1)&\cdots&\hat{G}_{\text{BR}}^{\text{P}}(\sigma_v)\end{bmatrix}\nonumber\\
&=C_{\text{BR}}^{\text{P}}\hat{V}\begin{bsmallmatrix}(\sigma_1 I -S_v+\zeta L_v-\zeta D^TR_p^{-1}C\hat{V})^{-1}\zeta R_b^{\frac{1}{2}}&\cdots&(\sigma_v I -S_v+\zeta L_v-\zeta D^TR_p^{-1}C\hat{V})^{-1}\zeta R_b^{\frac{1}{2}}\end{bsmallmatrix}\nonumber\\
&=C_{\text{BR}}^{\text{P}}\hat{V}T_{v}=R_p^{-\frac{1}{2}}C\hat{V}T_{v},\nonumber
\end{align}where \( \hat{G}(s) = C \hat{V} (sI - S_v + \xi L_v)^{-1} \xi + D \) is an interpolant of \( G(s) \). Such an interpolant can be produced by I-PORK, which is guaranteed to be stable, and \( T_{v} \) can be constructed from this interpolant. Specifically, \( T_v \) is the solution to the following Sylvester equation:
\begin{align}
(S_v-\zeta L_v+\zeta D^TR_p^{-1}C\hat{V})T_{v}-T_{v}S_v+\zeta R_b^{\frac{1}{2}}L_v=0.\nonumber
\end{align}
An immediate consequence of this observation is that bounded-realness can be enforced non-intrusively on the ROM produced by I-PORK using only samples of \( G(s) \) at \( \sigma_i \) and the sample \( G(\infty) \). This is implemented in Algorithm \ref{alg5}, named ``Data-driven Bounded-real Interpolation (\( V \)-type) (DD-BRI-V)''. The resulting ROM is simply a different state-space realization of the ROM defined in (\ref{ss_BR}).
\begin{algorithm}
\caption{DD-BRI-V}
\textbf{Input:} Interpolation points: $(\sigma_1,\cdots,\sigma_{v})$; Data: $\big(H(\sigma_1),\cdots,H(\sigma_{v})\big)$ and $G(\infty)$.

\textbf{Output:} ROM: $(\hat{A},\hat{B},\hat{C},D)$
\begin{algorithmic}[1]\label{alg5}
\STATE Compute $\hat{C}=C\hat{V}$ from the samples $H(\sigma_i)$ via (\ref{LF}).
\STATE Set $D=G(\infty)$ $R_p=I-DD^T$, and $R_b=I+D^TR_p^{-1}D$.
\STATE Set $S_v$ and $L_v$ as in (\ref{SbLbScLc}).
\STATE Compute $Q_v$ by solving the Lyapunov equation (\ref{pork_qs}).
\STATE Compute $T_{v}$ by solving the following Sylvester equation:\\
$(S_v-Q_v^{-1}L_v^TL_v+Q_v^{-1}L_v^TD^TR_p^{-1}C\hat{V})T_{v}-T_{v}S_v+Q_v^{-1}L_v^TR_b^{\frac{1}{2}}L_v=0$.
\STATE Set $\hat{C}_{\text{BR}}^{\text{P}}=R_p^{-\frac{1}{2}}\hat{C}T_v$.
\STATE Update $Q_v$ by solving the Lyapunov equations (\ref{th5_sylv}).
\STATE Set $\hat{B}=T_vQ_v^{-1}L_v^TR_b^{-\frac{1}{2}}$ and $\hat{A}=S_v-\hat{B}L_v$.
\end{algorithmic}
\end{algorithm}

As per Theorem \ref{Theorem2}, the RADI-based approximation of \( Q_{\text{BR}} \) can be obtained as follows. The projection matrix
\begin{align}
W_{\text{BR}}^*=\begin{bmatrix}C_{\text{BR}}^{\text{Q}}(\mu_1I-A_{\text{BR}})^{-1}\\\vdots\\C_{\text{BR}}^{\text{Q}}(\mu_wI-A_{\text{BR}})^{-1}\end{bmatrix}
\end{align} solves the following Sylvester equation:
\begin{align}
A_{\text{BR}}^TW_{\text{BR}}-W_{\text{BR}}S_w^*+(C_{\text{BR}}^{\text{Q}})^*L_w^T=0.
\end{align}
Then, \( \hat{B}_{\text{BR}}^{\text{Q}} = W_{\text{BR}}^* B_{\text{BR}}^{\text{Q}} \) can be computed as:
\begin{align}
\hat{B}_{\text{BR}}^{\text{Q}}=\begin{bmatrix}G_{\text{BR}}^{\text{Q}}(\mu_1)\\\vdots\\G_{\text{BR}}^{\text{Q}}(\mu_w)\end{bmatrix}.
\end{align}Thereafter, \( P_w \) is computed by solving the Lyapunov equation:
\begin{align}
-S_wP_w-P_wS_w^*+L_wL_w^T-\hat{B}_{\text{BR}}^{\text{Q}}(\hat{B}_{\text{BR}}^{\text{Q}})^*=0.\label{th6_sylv}
\end{align}
According to Theorem \ref{Theorem2}, the ROM \( (\hat{A}_{\text{BR}} = S_w - L_w\hat{C}_{\text{BR}}^{\text{Q}}, \hat{B}_{\text{BR}}^{\text{Q}} = W_{\text{BR}}^*B_{\text{BR}}^{\text{Q}}, \hat{C}_{\text{BR}}^{\text{Q}} = L_w^TP_{w}^{-1}) \) solves the following projected Riccati equation with \( \hat{Q}_{\text{BR}} = P_w^{-1} > 0 \):
\begin{align}
\hat{A}_{\text{BR}}^*\hat{Q}_{\text{BR}}+\hat{Q}_{\text{BR}}\hat{A}_{\text{BR}}+(\hat{C}_{\text{BR}}^{\text{Q}})^*\hat{C}_{\text{BR}}^{\text{Q}}+\hat{Q}_{\text{BR}}\hat{B}_{\text{BR}}^{\text{Q}}(\hat{B}_{\text{BR}}^{\text{Q}})^*Q_{\text{BR}}=0.\label{proj_ricc_Qbr}
\end{align}
Since
\begin{align}
\hat{A}&=S_w-L_wL_w^TP_w^{-1}-\hat{B}R_q^{-1}D^T\hat{C},\nonumber\\
\hat{B}&=\hat{W}_{\text{BR}}^*B_{\text{BR}}^{\text{Q}}R_q^{\frac{1}{2}},\quad\hat{C}=R_c^{-\frac{1}{2}}L_w^TP_w^{-1},\label{ss_BR_2}
\end{align}the Riccati equation (\ref{proj_ricc_Qbr}) can be rewritten as:
\begin{align}
\hat{A}^*\hat{Q}_{\text{BR}}+\hat{Q}_{\text{BR}}\hat{A}+\hat{C}^*\hat{C}+(\hat{B}^*\hat{Q}_{\text{BR}}+D^T\hat{C})^*R_q^{-1}(\hat{B}^*\hat{Q}_{\text{BR}}+D^T\hat{C})=0.
\end{align}
The RADI-based approximation of \( Q_{\text{BR}} \) is given by \( W_{\text{BR}} P_w^{-1} W_{\text{BR}}^* \).
\begin{theorem}\label{Theorem6}
Let $G(s)$ be a bounded-real transfer function. Define $\tilde{L}_w^*=D^TR_p^{-\frac{1}{2}}\hat{B}_{\text{BR}}^{\text{Q}}+R_c^{\frac{1}{2}}L_w^T=\begin{bmatrix}l_{w,1}^*&\cdots&l_{w,q}^*\end{bmatrix}$ and $T_{w}=\text{blkdiag}(l_{w,1}^*,\cdots,l_{w,q}^*)$. Assume that:
\begin{enumerate}
\item The interpolation points $(\mu_1,\cdots,\mu_w)$ are located in the right half of the $s$-plane.
  \item The pair $(S_w,\tilde{L}_w)$ is controllable.
  \item The matrix $T_{w}$ is invertible.
  \item The realization $(\hat{A},\hat{B},\hat{C})$ defined in (\ref{ss_BR_2}) is minimal.
\end{enumerate}Then the following statements hold:
\begin{enumerate}
  \item The projection matrix $W_\text{BR}$ is equal to $\hat{W}T_{w}$ where $\hat{W}$ is as in (\ref{Kry_W}).
  \item The ROM $\hat{G}(s)=\hat{C}(sI-\hat{A})^{-1}\hat{B}+D$ interpolates $G(s)$ at $(\mu_1,\cdots,\mu_q)$.
  \item The ROM $\hat{G}(s)$ is bounded-real. 
\end{enumerate}
\end{theorem}
\begin{proof}
The proof is similar to that of Theorem \ref{Theorem5} and hence omitted for brevity.
\end{proof}
We now derive an expression for \( T_{w} \) when \(\hat{W}\) is used to enforce interpolation conditions instead of \( W_{\text{BR}} \). Since \( W_{\text{BR}} \) and \(\hat{W}\) enforce identical interpolation conditions, the following holds:
\begin{align}
\hat{B}_{\text{BR}}^\text{Q}&=W_{\text{BR}}^*B_{\text{BR}}^\text{Q}=\begin{bmatrix}G_{\text{BR}}^\text{Q}(\mu_1)\\\vdots\\G_{\text{BR}}^\text{Q}(\mu_w)\end{bmatrix}=\begin{bmatrix}\hat{G}_{\text{PR}}^\text{Q}(\mu_1)\\\vdots\\\hat{G}_{\text{PR}}^\text{Q}(\mu_w)\end{bmatrix}\nonumber\\
&=\begin{bsmallmatrix}R_c^{\frac{1}{2}}\zeta(\mu_1I-S_w+L_w\zeta-\hat{W}^*BR_q^{-1}D^T\zeta)^{-1}\\\vdots\\R_c^{\frac{1}{2}}\zeta(\mu_wI-S_w+L_w\zeta-\hat{W}^*BR_q^{-1}D^T\zeta)^{-1}\end{bsmallmatrix}\hat{W}^*B_{\text{BR}}^\text{Q},\nonumber\\
&=T_{w}^*\hat{W}^*BR_{q}^{-\frac{1}{2}},\nonumber
\end{align}
where \(\hat{G}(s) = \zeta (sI - S_w + L_w \zeta)^{-1} \hat{W}^* B + D\) is an interpolant of \( G(s) \). This interpolant can be produced by O-PORK, which is guaranteed to be stable, and \( T_{w} \) can be constructed from it. Specifically, \( T_w \) is obtained by solving the Sylvester equation:
\begin{align}
(S_w-L_w\zeta+\hat{W}^*BR_q^{-1}D^T\zeta)^*T_{w}-T_{w}S_w^*+\zeta^*R_c^{\frac{1}{2}}L_w^T=0.
\end{align}
An immediate consequence is that bounded-realness can be enforced non-intrusively on the ROM produced by O-PORK, using only samples of \( G(s) \) at \( \mu_i \) and \( G(\infty) \). This approach is implemented in Algorithm \ref{alg6}, named ``Data-driven Bounded-real Interpolation (\( W \)-type) (DD-BRI-W)''. The resulting ROM represents a different state-space realization of the ROM defined in (\ref{ss_BR_2}).
\begin{algorithm}
\caption{DD-BRI-W}
\textbf{Input:} Interpolation points: $(\mu_1,\cdots,\mu_{w})$; Data: $\big(H(\mu_1),\cdots,H(\mu_{w})\big)$ and $G(\infty)$.

\textbf{Output:} ROM: $(\hat{A},\hat{B},\hat{C},D)$
\begin{algorithmic}[1]\label{alg6}
\STATE Compute $\hat{B}=\hat{W}^*B$ from the samples $H(\mu_i)$ via (\ref{LF}).
\STATE Set $D=G(\infty)$, $R_q=I-D^TD$, and $R_c=I+DR_q^{-1}D^T$.
\STATE Set $S_w$ and $L_w$ as in (\ref{SbLbScLc}).
\STATE Compute $P_w$ by solving the Lyapunov equations (\ref{pork_ps}).
\STATE Compute $T_{w}$ by solving the following Sylvester equation:\\
$(S_w-L_wL_w^TP_w^{-1}+\hat{W}^*BR_q^{-1}D^TL_w^TP_w^{-1})^*T_{w}-T_{w}S_w^*+P_w^{-1}L_wR_c^{\frac{1}{2}}L_w^T=0$.
\STATE Set  $\hat{B}_{\text{PR}}=T_w^*\hat{B}R_q^{-\frac{1}{2}}$.
\STATE Update $P_w$ by solving the Lyapunov equations (\ref{th6_sylv}).
\STATE Set $\hat{C}=R_c^{-\frac{1}{2}}L_w^TP_w^{-1}T_w^*$ and $\hat{A}=S_w-L_w\hat{C}$.
\end{algorithmic}
\end{algorithm}

Similar to the ADI-based non-intrusive implementation of BT, the RADI-based non-intrusive implementation of BR-BT can be directly obtained using the results of Theorems \ref{Theorem5} and \ref{Theorem6}. The pseudo-code for this implementation, named ``Data-driven BR-BT (DD-BR-BT)'', is provided in Algorithm \ref{alg7}.
\begin{algorithm}
RADI shifts for approximating $P_{\text{BR}}$: $(-\sigma_1,\cdots,-\sigma_{v})$; RADI shifts for approximating $Q_{\text{BR}}$: $(-\mu_1,\cdots,-\mu_{w})$; Data: $\big(H(\sigma_1),\cdots,H(\sigma_{v}),H(\mu_1),\cdots,H(\mu_{w}),G(\infty)\big)$ and $H^\prime(\sigma_i)$ for $\sigma_i=\mu_j$; Reduced order: $r$.

\textbf{Output:} ROM: $(\hat{A},\hat{B},\hat{C},D)$
\caption{DD-BR-BT}
\begin{algorithmic}[1]\label{alg7}
\STATE Compute the Loewner quadruplet $(\hat{W}^*\hat{V},\hat{W}^*A\hat{V},\hat{W}^*B,C\hat{V})$ from the samples $H(\sigma_i)$ and $H(\mu_i)$ via (\ref{LF}).
\STATE Set $D=G(\infty)$, $R_p=I-DD^T$, $R_b=I+D^TR_p^{-1}D$, $R_q=I-D^TD$, and $R_c=I+DR_q^{-1}D^T$.
\STATE Set $S_v$, $L_v$, $S_w$, and $L_w$ as in (\ref{SbLbScLc}).
\STATE Compute $Q_v$ and $P_w$ by solving the Lyapunov equations (\ref{pork_qs}) and (\ref{pork_ps}).
\STATE Compute $T_{v}$ and $T_{w}$ by solving the following Sylvester equations:\\
$(S_v-Q_v^{-1}L_v^TL_v+Q_v^{-1}L_v^TD^TR_p^{-1}C\hat{V})T_{v}-T_{v}S_v+Q_v^{-1}L_v^TR_b^{\frac{1}{2}}L_v=0$,\\
$(S_w-L_wL_w^TP_w^{-1}+\hat{W}^*BR_q^{-1}D^TL_w^TP_w^{-1})^*T_{w}-T_{w}S_w^*+P_w^{-1}L_wR_c^{\frac{1}{2}}L_w^T=0$.\\
\STATE Set $\hat{C}_{\text{BR}}^{\text{P}}=R_p^{-\frac{1}{2}}C\hat{V}T_{v}$ and $\hat{B}_{\text{BR}}^{\text{Q}}=T_{w}^*\hat{W}^*BR_q^{-\frac{1}{2}}$.
\STATE Update $Q_v$ and $P_w$ by solving the Lyapunov equations (\ref{th5_sylv}) and (\ref{th6_sylv}).
\STATE Decompose $Q_v^{-1}$ and $P_w^{-1}$ as $Q_v^{-1}=\hat{L}_p\hat{L}_p^*$ and $P_w^{-1}=\hat{L}_q\hat{L}_q^*$.
\STATE Compute the following SVD:\\
$\hat{L}_q^*T_w^* (\hat{W}^*\hat{V})T_v \hat{L}_p = \begin{bmatrix} \tilde{U}_1 & \tilde{U}_2 \end{bmatrix} \begin{bmatrix} \tilde{\Sigma}_r & 0 \\ 0 & \tilde{\Sigma}_{n-r} \end{bmatrix} \begin{bmatrix} \tilde{V}_1^* \\ \tilde{V}_2^* \end{bmatrix}$.
\STATE Set $W_r = T_w\hat{L}_q \tilde{U}_1 \tilde{\Sigma}_r^{-1/2}$ and $V_r = T_v\hat{L}_p \tilde{V}_1 \tilde{\Sigma}_r^{-1/2}$.
\STATE Compute $\hat{A}$, $\hat{B}$, and $\hat{C}$ from (\ref{bsa_rom}).
\end{algorithmic}
\end{algorithm}
\subsection{ADI-based Non-intrusive Implementation of SW-BT}
Let us define the transfer function
\begin{align}
G_{\text{SW}}(s)=C_{\text{SW}}(sI-A_{\text{SW}})^{-1}B,\nonumber
\end{align} where $A_{\text{SW}}=A-BC_{\text{SW}}$ and $C_{\text{SW}}=D^{-1}C$. Next, define the ROM $\hat{G}_{\text{SW}}(s)$
\begin{align}
\hat{G}_{\text{SW}}(s)=\hat{C}_{\text{SW}}(sI-\hat{A}_{\text{SW}})^{-1}\hat{B},\nonumber
\end{align} obtained as
\begin{align}
\hat{A}_{\text{SW}}&=W_{\text{SW}}^*A_{\text{SW}}\hat{V}=\hat{A}-\hat{B}D^{-1}\hat{C},\nonumber\\
\hat{B}&=W_{\text{SW}}^*B,\quad \hat{C}_{\text{SW}}=C_{\text{SW}}V_{\text{SW}}=D^{-1}\hat{C},\nonumber
\end{align}where $W_{\text{SW}}^*V_{\text{SW}}=I$.

The Lyapunov equation (\ref{Q_SW}) can be rewritten as:
\begin{align}
A_{\text{SW}}^TQ_{\text{SW}}+Q_{\text{SW}}A_{\text{SW}}+C_{\text{SW}}^TC_{\text{SW}}=0.
\end{align}
The O-PORK-based approximation of $Q_{\text{SW}}$ (equivalent to the ADI method) is computed as follows. First, solve the Sylvester equation for the projection matrix $W_{\text{SW}}$:
\begin{align}
A_{\text{SW}}^TW_{\text{SW}}-W_{\text{SW}}S_w^*+C_{\text{SW}}^TL_w^T=0.
\end{align}
Then, compute $P_w$ by solving the Lyapunov equation (\ref{pork_ps}). The ADI-based approximation of $Q_{\text{SW}}$ is obtained as: $Q_{\text{S}}\approx W_{\text{SW}}P_w^{-1}W_{\text{SW}}^*$. The following ROM $\hat{G}(s)$ can be recovered from the ROM $\hat{G}_{\text{SW}}(s)=L_w^TP_{w}^{-1}(sI-S_w+L_wL_w^TP_w^{-1})^{-1}W_{\text{SW}}^*B$ produced by O-PORK:
\begin{align}
\hat{A}&=S_w+L_wL_w^TP_w^{-1}+W_{\text{S}}^*BL_w^TP_w^{-1},\nonumber\\
\hat{B}&=W_{\text{SW}}^*B,\quad \hat{C}=DL_w^TP_w^{-1}.\label{ss_SW}
\end{align}
\begin{theorem}\label{Theorem7}
Let $G(s)$ be a square stable minimum phase transfer function. Define $\tilde{L}_w^*=D^{-T}(L_w^T-\hat{B}^*)=\begin{bmatrix}l_{w,1}^*&\cdots&l_{w,q}^*\end{bmatrix}$ and $T_{w}=\text{blkdiag}(l_{w,1}^*,\cdots,l_{w,q}^*)$. Assume that:
\begin{enumerate}
\item The interpolation points $(\mu_1,\cdots,\mu_w)$ are located in the right half of the $s$-plane.
  \item The pair $(S_w,\tilde{L}_w)$ is controllable.
  \item The matrix $T_{w}$ is invertible.
  \item The realization $(\hat{A},\hat{B},\hat{C})$ defined in (\ref{ss_SW}) is minimal.
\end{enumerate}Then the following statements hold:
\begin{enumerate}
  \item\label{SWitem1} The projection matrix $W_\text{SW}$ is equal to $\hat{W}T_{w}$ where $\hat{W}$ is as in (\ref{Kry_W}).
  \item\label{SWitem2} The ROM $\hat{G}(s)=\hat{C}(sI-\hat{A})^{-1}\hat{B}+D$ interpolates $G(s)$ at $(\mu_1,\cdots,\mu_q)$.
  \item The ROM $\hat{G}(s)$ is minimum phase. 
\end{enumerate}
\end{theorem}
\begin{proof}
The proof of \ref{SWitem1} and \ref{SWitem2} is similar to that of Theorem \ref{Theorem4} and hence omitted for brevity.

The zeros of $\hat{G}(s)$, i.e., the eigenvalues of $\hat{A}_{\text{SW}}=\hat{A}-\hat{B}D^{-1}\hat{C}$, are $(-\mu_1^*,\cdots,-\mu_w^*)$ in O-PORK. Since the interpolation points in O-PORK are in the right half of the $s$-plane, $\hat{A}_{\text{SW}}$ is Hurwitz and $\hat{G}(s)$ is minimum phase.  
\end{proof}
We now derive an expression for $T_{w}$ when $\hat{W}$ is used for enforcing interpolation conditions instead of $W_{\text{SW}}$. Since $W_{\text{SW}}$ and $\hat{W}$ enforce the same interpolation conditions, the following holds:  
\begin{align}
\hat{B}&=W_{\text{SW}}^*B=\begin{bmatrix}G_{\text{SW}}(\mu_1)\\\vdots\\G_{\text{SW}}(\mu_w)\end{bmatrix}=\begin{bmatrix}\hat{G}_{\text{SW}}(\mu_1)\\\vdots\\\hat{G}_{\text{SW}}(\mu_w)\end{bmatrix}\nonumber\\
&=\begin{bsmallmatrix}D^{-1}\zeta(\mu_1I-S_w+L_w\zeta+\hat{W}^*BD^{-1}\zeta)^{-1}\\\vdots\\D^{-1}\zeta(\mu_wI-S_w+L_w\zeta+\hat{W}^*BD^{-1}\zeta)^{-1}\end{bsmallmatrix}\hat{W}^*B,\nonumber\\
&=T_{w}^*\hat{W}^*B,\nonumber
\end{align}
where $\hat{G}(s)=\zeta(sI-S_w+L_w\zeta)^{-1}\hat{W}^*B+D$ is the interpolant of $G(s)$. Such an interpolant can be produced by O-PORK, which is guaranteed to be stable, and $T_{w}$ can be constructed from this interpolant. $T_w$ can be computed by solving the following Sylvester equation:  
\begin{align}
\big(S_w-L_w\zeta-\hat{W}^*BD^{-1}\zeta\big)^*T_{w}-T_{w}S_w^*+\zeta^*D^{-T}L_w^T=0.\nonumber
\end{align}
An immediate consequence of this observation is that the minimum-phase property can be enforced on the ROM nonintrusively produced by O-PORK using only samples of $G(s)$ at $\mu_i$ and the sample $G(\infty)$. This is implemented in Algorithm \ref{alg8}, named ``Data-driven Minimum-phase Interpolation (DD-MPI)''. The resulting ROM is simply a different state-space realization of the ROM defined in (\ref{ss_SW}). 
\begin{algorithm}
\caption{DD-MPI}
\textbf{Input:} Interpolation points: $(\mu_1,\cdots,\mu_{w})$; Data: $\big(H(\mu_1),\cdots,H(\mu_{w})\big)$ and $G(\infty)$.

\textbf{Output:} ROM: $(\hat{A},\hat{B},\hat{C},D)$
\begin{algorithmic}[1]\label{alg8}
\STATE Compute $\hat{B}=\hat{W}^*B$ from the samples $H(\mu_i)$ via (\ref{LF}) and set $D=G(\infty)$..
\STATE Set $S_w$ and $L_w$ as in (\ref{SbLbScLc}).
\STATE Compute $P_w$ by solving the Lyapunov equations (\ref{pork_ps}).
\STATE Compute $T_{w}$ by solving the following Sylvester equation:\\
$\big(S_w-L_wL_w^TP_w^{-1}-\hat{B}D^{-1}L_w^TP_w^{-1}\big)^*T_{w}-T_{w}S_w^*+P_w^{-1}L_wD^{-T}L_w^T=0$.
\STATE Set $\hat{C}=DL_w^TP_w^{-1}T_w^*$ and $\hat{A}=S_w-L_w\hat{C}$.
\end{algorithmic}
\end{algorithm}

Similar to the ADI-based nonintrusive implementation of BT, the ADI-based nonintrusive implementation of SW-BT can be derived directly using the results of Theorem \ref{Theorem7}. The pseudo-code for this implementation, named ``Data-driven SW-BT (DD-SW-BT)'', is provided in Algorithm \ref{alg9}. 
\begin{algorithm}
ADI shifts for approximating $P$: $(-\sigma_1,\cdots,-\sigma_{v})$; ADI shifts for approximating $Q_{\text{SW}}$: $(-\mu_1,\cdots,-\mu_{w})$; Data: $\big(H(\sigma_1),\cdots,H(\sigma_{v}),H(\mu_1),\cdots,H(\mu_{w}),G(\infty)\big)$ and $H^\prime(\sigma_i)$ for $\sigma_i=\mu_j$; Reduced order: $r$.

\textbf{Output:} ROM: $(\hat{A},\hat{B},\hat{C},D)$
\caption{DD-SW-BT}
\begin{algorithmic}[1]\label{alg9}
\STATE Compute the Loewner quadruplet $(\hat{W}^*\hat{V},\hat{W}^*A\hat{V},\hat{W}^*B,C\hat{V})$ from the samples $H(\sigma_i)$ and $H(\mu_i)$ via (\ref{LF}) and set $D=G(\infty)$.
\STATE Set $S_v$, $L_v$, $S_w$, and $L_w$ as in (\ref{SbLbScLc}).
\STATE Compute $Q_v$ and $P_w$ by solving the Lyapunov equations (\ref{pork_qs}) and (\ref{pork_ps}).
\STATE Compute $T_{w}$ by solving the following Sylvester equation:\\
$\big(S_w-L_wL_w^TP_w^{-1}-\hat{B}D^{-1}L_w^TP_w^{-1}\big)^*T_{w}-T_{w}S_w^*+P_w^{-1}L_wD^{-T}L_w^T=0$.
\STATE Decompose $Q_v^{-1}$ and $P_w^{-1}$ as $Q_v^{-1}=\hat{L}_p\hat{L}_p^*$ and $P_w^{-1}=\hat{L}_q\hat{L}_q^*$.
\STATE Compute the following SVD:\\
$\hat{L}_q^*T_w^* (\hat{W}^*\hat{V})\hat{L}_p = \begin{bmatrix} \tilde{U}_1 & \tilde{U}_2 \end{bmatrix} \begin{bmatrix} \tilde{\Sigma}_r & 0 \\ 0 & \tilde{\Sigma}_{n-r} \end{bmatrix} \begin{bmatrix} \tilde{V}_1^* \\ \tilde{V}_2^* \end{bmatrix}$.
\STATE Set $W_r = T_w\hat{L}_q \tilde{U}_1 \tilde{\Sigma}_r^{-1/2}$ and $V_r =\hat{L}_p \tilde{V}_1 \tilde{\Sigma}_r^{-1/2}$.
\STATE Compute $\hat{A}$, $\hat{B}$, and $\hat{C}$ from (\ref{bsa_rom}).
\end{algorithmic}
\end{algorithm}
\subsection{ADI/RADI-based Non-intrusive Implementation of BST}
Let us define the transfer function
\begin{align}
G_{\text{S}}(s)=C_{\text{S}}(sI-A_{\text{S}})^{-1}B_{\text{S}},\nonumber
\end{align}where 
\begin{align}
A_{\text{S}}&=A-B_{\text{S}}C_{\text{S}},& B_{\text{S}}&=(PC^T+BD^T)R_\text{S}^{-\frac{1}{2}},\nonumber\\
C_{\text{S}}&=R_\text{S}^{-\frac{1}{2}}C,& R_\text{S}&=DD^T.\nonumber
\end{align}
The Riccati equation (\ref{Q_S}) can be rewritten as follows:
\begin{align}
A_{\text{S}}^TQ_{\text{S}}+Q_{\text{S}}A_{\text{S}}+C_{\text{S}}^TC_{\text{S}}+Q_{\text{S}}B_{\text{S}}B_{\text{S}}^TQ_{\text{S}}=0.
\end{align}
Unlike the Riccati equations considered up until now, the RADI-based approximation of this Riccati equation is a bit more involved. We first need to replace $B_{\text{S}}$ with its approximation. Let us replace $P$ in $B_{\text{S}}$ with $\hat{V}Q_v^{-1}\hat{V}^*$, which is an ADI-based approximation of $P$ obtained via I-PORK. Then, $B_{\text{S}}\approx\tilde{B}_{\text{S}}=(\hat{V}Q_v^{-1}\hat{V}^*C^T+BD^T)R_\text{S}^{-\frac{1}{2}}$ and $A_{\text{S}}\approx\tilde{A}_{\text{S}}=A-\tilde{B}_{\text{S}}C_{\text{S}}$. Thereafter, we proceed with the RADI-based approximation of the following Riccati equation:
\begin{align}
\tilde{A}_{\text{S}}^*\tilde{Q}_{\text{S}}+\tilde{Q}_{\text{S}}\tilde{A}_{\text{S}}+C_{\text{S}}^*C_{\text{S}}+\tilde{Q}_{\text{S}}\tilde{B}_{\text{S}}\tilde{B}_{\text{S}}^*\tilde{Q}_{\text{S}}=0.
\end{align}The RADI-based approximation of $\tilde{Q}_{\text{S}}$ can be obtained using Theorem \ref{Theorem2} as follows. The projection matrix $W_\text{S}$ is computed by solving the following Sylvester equation:  
\begin{align}
\tilde{A}_{\text{S}}^*W_\text{S}-W_\text{S}S_w^*+C_{\text{S}}^TL_w^T=0.
\end{align}
The matrix $P_w$ is computed by solving the following Sylvester equation:  
\begin{align}
-S_wP_w-P_wS_w^*+L_wL_w^T-\hat{B}_\text{S}\hat{B}_\text{S}^*=0,\label{bst_sylv}
\end{align}where $\hat{B}_\text{S}=W_\text{S}^*\tilde{B}_\text{S}$.

Once again, it can be shown that $W_\text{S}$ and $\hat{W}$ in (\ref{Kry_W}) enforce the same interpolation conditions and $W_\text{S} = \hat{W} T_{w}$, where $T_{w}$ is invertible. The proof is similar and hence omitted here for brevity.

Let us define the ROM
\begin{align}
\hat{G}_{\text{S}}(s)=\hat{C}_{\text{S}}(sI-\hat{A}_{\text{S}})^{-1}\hat{B}_{\text{S}},\nonumber
\end{align} obtained as
\begin{align}
\hat{A}_{\text{S}}=W_\text{\text{S}}^*\tilde{A}_{\text{S}}V_{\text{S}},\quad \hat{B}_{\text{S}}=W_\text{\text{S}}^*\tilde{B}_{\text{S}},\quad \hat{C}_{\text{S}}=C_{\text{S}}V_{\text{S}},\nonumber
\end{align}where $W_\text{\text{S}}^*V_{\text{S}}=I$.

We now derive an expression for $T_{w}$ when $\hat{W}$ is used for enforcing interpolation conditions instead of $W_{\text{S}}$. Since $W_{\text{S}}$ and $\hat{W}$ enforce the same interpolation conditions, the following holds: 
\begin{align}
\hat{B}_{\text{S}}&=W_{\text{S}}^*\tilde{B}_{\text{S}}=\begin{bmatrix}G_{\text{S}}(\mu_1)\\\vdots\\G_{\text{S}}(\mu_w)\end{bmatrix}=\begin{bmatrix}\hat{G}_{\text{S}}(\mu_1)\\\vdots\\\hat{G}_{\text{S}}(\mu_w)\end{bmatrix}\nonumber\\
&=\begin{bsmallmatrix}R_{\text{S}}^{-\frac{1}{2}}\zeta\big(\mu_1I-S_w+L_w\zeta+(\hat{W}^*\hat{V}Q_v^{-1}\hat{V}^*C^T+\hat{W}^*BD^T)R_{\text{S}}^{-1}\zeta\big)^{-1}\\\vdots\\R_{\text{S}}^{-\frac{1}{2}}\zeta\big(\mu_wI-S_w+L_w\zeta+(\hat{W}^*\hat{V}Q_v^{-1}\hat{V}^*C^T+\hat{W}*BD^T)R_{\text{S}}^{-1}\zeta\big)^{-1}\end{bsmallmatrix}\hat{W}^*B_{\text{X}},\nonumber\\
&=T_{w}^*\hat{W}^*B_{\text{S}},\nonumber\\
&=T_{w}^*\big((\hat{W}^*\hat{V})Q_v^{-1}(C\hat{V})^*+(\hat{W}^*B)D^T\big)R_{\text{S}}^{-\frac{1}{2}},\nonumber
\end{align}
where $\hat{G}(s) = \zeta (sI - S_w + L_w \zeta)^{-1} \hat{W}^* B + D$ is the interpolant of $G(s)$. Such an interpolant can be produced by O-PORK, which is guaranteed to be stable. $T_{w}$ can be constructed from this interpolant by solving the following Sylvester equation:  
\begin{align}
\big(S_w-L_w\zeta-[(\hat{W}^*\hat{V})Q_v^{-1}(C\hat{V})^*+(\hat{W}^*B)D^T]R_{\text{S}}^{-1}\zeta\big)^*T_{w}-T_{w}S_w^*+\zeta^*R_{\text{S}}^{-\frac{1}{2}}L_w^T=0.\nonumber
\end{align}
Similar to the ADI-based nonintrusive implementation of BT, the ADI- and RADI-based nonintrusive implementation of BST can be obtained readily. The pseudo-code for this implementation, named ``Data-driven BST (DD-BST)'', is provided in Algorithm \ref{alg10}.
\begin{algorithm}
ADI shifts for approximating $P$: $(-\sigma_1,\cdots,-\sigma_{v})$; RADI shifts for approximating $Q_{\text{S}}$: $(-\mu_1,\cdots,-\mu_{w})$; Data: $\big(H(\sigma_1),\cdots,H(\sigma_{v}),H(\mu_1),\cdots,H(\mu_{w}),G(\infty)\big)$ and $H^\prime(\sigma_i)$ for $\sigma_i=\mu_j$; Reduced order: $r$.

\textbf{Output:} ROM: $(\hat{A},\hat{B},\hat{C},D)$
\caption{DD-BST}
\begin{algorithmic}[1]\label{alg10}
\STATE Compute the Loewner quadruplet $(\hat{W}^*\hat{V},\hat{W}^*A\hat{V},\hat{W}^*B,C\hat{V})$ from the samples $H(\sigma_i)$ and $H(\mu_i)$ via (\ref{LF}). \STATE Set $D=G(\infty)$ and $R_{\text{S}}=DD^T$.
\STATE Set $S_v$, $L_v$, $S_w$, and $L_w$ as in (\ref{SbLbScLc}).
\STATE Compute $Q_v$ and $P_w$ by solving the Lyapunov equations (\ref{pork_qs}) and (\ref{pork_ps}).
\STATE Compute $T_{w}$ by solving the following Sylvester equation:\\
$(S_w-L_wL_w^TP_w^{-1}-[(\hat{W}^*\hat{V})Q_v^{-1}(C\hat{V})^*+(\hat{W}^*B)D^T]R_{\text{S}}^{-1}L_w^TP_w^{-1})^*T_{w}-T_{w}S_w^*+P_w^{-1}L_wR_{\text{S}}^{-\frac{1}{2}}L_w^T=0$.
\STATE Set $\hat{B}_{\text{S}}=T_w^*\big((\hat{W}^*\hat{V})Q_v^{-1}(C\hat{V})^*+(\hat{W}^*B)D^T\big)R_\text{S}^{-\frac{1}{2}}$.
\STATE Update $P_w$ by solving the Sylvester equation (\ref{bst_sylv}).
\STATE Decompose $Q_v^{-1}$ and $P_w^{-1}$ as $Q_v^{-1}=\hat{L}_p\hat{L}_p^*$ and $P_w^{-1}=\hat{L}_q\hat{L}_q^*$.
\STATE Compute the following SVD:\\
$\hat{L}_q^*T_w^* (\hat{W}^*\hat{V})\hat{L}_p = \begin{bmatrix} \tilde{U}_1 & \tilde{U}_2 \end{bmatrix} \begin{bmatrix} \tilde{\Sigma}_r & 0 \\ 0 & \tilde{\Sigma}_{n-r} \end{bmatrix} \begin{bmatrix} \tilde{V}_1^* \\ \tilde{V}_2^* \end{bmatrix}$.
\STATE Set $W_r = T_w\hat{L}_q \tilde{U}_1 \tilde{\Sigma}_r^{-1/2}$ and $V_r =\hat{L}_p \tilde{V}_1 \tilde{\Sigma}_r^{-1/2}$.
\STATE Compute $\hat{A}$, $\hat{B}$, and $\hat{C}$ from (\ref{bsa_rom}).
\end{algorithmic}
\end{algorithm}
\section{Practical Considerations in Implementation}
The theoretical foundations of the ADI \cite{benner2013efficient} and RADI \cite{benner2018radi} methods are well established. Their performance in approximating Lyapunov and Riccati equations is also well documented. However, the implementation presented in this paper involves inverses \( Q_v^{-1} \) and \( P_w^{-1} \), which can cause numerical problems as the number of samples used for implementation increases. This is because the solution of Lyapunov equations is generally low-rank, enabling low-rank approximation via the low-rank ADI method \cite{benner2013efficient} in the first place. Thus, as the number of samples used for implementation increases, the matrices \( Q_v \) and \( P_w \) start losing rank. Note that these matrices do not appear in the original algorithms. In data-driven modeling, one typically uses as many samples as available to ensure maximum accuracy. As discussed in \cite{zulfiqar2025non}, the inverses \( Q_v^{-1} \) and \( P_w^{-1} \) can be computed conveniently when the interpolation points are lightly damped, i.e.,  
\begin{align}
\sigma_i=\Bigg(\frac{\zeta_{i,\sigma}|\omega_{i,\sigma}|}{\sqrt{1-\zeta_{i,\sigma}^2}}\Bigg)+j\omega_{i,\sigma}\quad\textnormal{and}\quad \mu_i=\Bigg(\frac{\zeta_{i,\mu}|\omega_{i,\mu}|}{\sqrt{1-\zeta_{i,\mu}^2}}\Bigg)+j\omega_{i,\mu},\label{adi_shifts_cont}
\end{align}wherein $\zeta_{i,\sigma}\ll1$ and $\zeta_{i,\mu}\ll 1$. If we select the damping coefficients \( \zeta_{i,\sigma} \approx 0 \) and \( \zeta_{i,\mu} \approx 0 \), this means we are sampling \( G(s) \) in close proximity to the \( j\omega \)-axis, which is also practically reasonable for capturing the frequency response of \( G(s) \). When the interpolation points are lightly damped (i.e., \( \zeta_{i,\sigma} \ll 1 \) and \( \zeta_{i,\mu} \ll 1 \)), \( Q_v \), \( P_w \), \( Q_v^{-1} \), and \( P_w^{-1} \) become diagonally dominant. If \( \zeta_{i,\sigma} \approx 0 \) and \( \zeta_{i,\mu} \approx 0 \), the off-diagonal elements are nearly zero. For details, refer to \cite{gawronski2004dynamics}. Essentially, this means that each diagonal element of \( Q_v^{-1} \) and \( P_w^{-1} \) depends solely on its respective pair \( (\sigma_i, G(\sigma_i)) \) or \( (\mu_i, G(\mu_i)) \), while the dependence on other samples or sampling points becomes negligible.  

Assuming that the interpolation points are lightly damped, we can derive the expressions for the diagonal entries of \( Q_v^{-1} \) and \( P_w^{-1} \) as follows:  

For DD-LQG-BT:
\begin{align}
Q_v^{-1}&\approx\text{blkdiag}\big(2Real(\sigma_1)[I_m+H^*(\sigma_1)H(\sigma_1)]^{-1},\cdots,\nonumber\\
&\hspace*{4cm}2Real(\sigma_v)[I_m+H^*(\sigma_v)H(\sigma_v)]^{-1}\big),\\
P_w^{-1}&\approx\text{blkdiag}\big(2Real(\mu_1)[I_p+H(\mu_1)H^*(\mu_1)]^{-1},\cdots,\nonumber\\
&\hspace*{4cm}2Real(\mu_w)[I_p+H(\mu_w)H^*(\mu_w)]^{-1}\big).
\end{align}
For DD-$\mathcal{H}_\infty$-BT:
\begin{align}
Q_v^{-1}&\approx\text{blkdiag}\big(2Real(\sigma_1)[I_m+(1-\gamma^{-2})H^*(\sigma_1)H(\sigma_1)]^{-1},\cdots,\nonumber\\
&\hspace*{3cm}2Real(\sigma_v)[I_m+(1-\gamma^{-2})H^*(\sigma_v)H(\sigma_v)]^{-1}\big),\\
P_w^{-1}&\approx\text{blkdiag}\big(2Real(\mu_1)[I_p+(1-\gamma^{-2})H(\mu_1)H^*(\mu_1)]^{-1},\cdots,\nonumber\\
&\hspace*{3cm}2Real(\mu_w)[I_p+(1-\gamma^{-2})H(\mu_w)H^*(\mu_w)]^{-1}\big).
\end{align}
For DD-PR-BT:
\begin{align}
Q_v^{-1}&\approx\text{blkdiag}\big(2Real(\sigma_1)[I_m-t_{v,1}^*H^*(\sigma_1)R_{\text{PR}}^{-1}H(\sigma_1)t_{v,1}]^{-1},\cdots,\nonumber\\
&\hspace*{2cm}2Real(\sigma_v)[I_m-t_{v,v}^*H^*(\sigma_v)R_{\text{PR}}^{-1}H(\sigma_v)t_{v,v}]^{-1}\big),\\
P_w^{-1}&\approx\text{blkdiag}\big(2Real(\mu_1)[I_p-t_{w,1}^*H(\mu_1)R_{\text{PR}}^{-1}H^*(\mu_1)t_{w,1}]^{-1},\cdots,\nonumber\\
&\hspace*{2cm}2Real(\mu_w)[I_p-t_{w,w}^*H(\mu_w)R_{\text{PR}}^{-1}H^*(\mu_w)t_{w,w}]^{-1}\big),\\
T_v&\approx\text{blkdiag}\big(t_{v,1},\cdots,t_{v,v}\big),\\
T_w&\approx\text{blkdiag}\big(t_{w,1},\cdots,t_{v,w}\big),
\end{align}where
\begin{align}
t_{v,i}&=[I_m+R_{\text{PR}}^{-1}H(\sigma_i)]^{-1}R_{\text{PR}}^{-\frac{1}{2}},\\
t_{w,i}&=[I_m+R_{\text{PR}}^{-1}H^*(\mu_i)]^{-1}R_{\text{PR}}^{-\frac{1}{2}}.
\end{align}
For DD-BR-BT:
\begin{align}
Q_v^{-1}&\approx\text{blkdiag}\big(2Real(\sigma_1)[I_m-t_{v,1}^*H^*(\sigma_1)R_p^{-1}H(\sigma_1)t_{v,1}]^{-1},\cdots,\nonumber\\
&\hspace*{2cm}2Real(\sigma_v)[I_m+t_{v,v}^*H^*(\sigma_v)R_p^{-1}H(\sigma_v)t_{v,v}]^{-1}\big),\\
P_w^{-1}&\approx\text{blkdiag}\big(2Real(\mu_1)[I_p-t_{w,1}^*H(\mu_1)R_q^{-1}H^*(\mu_1)t_{w,1}]^{-1},\cdots,\nonumber\\
&\hspace*{2cm}2Real(\mu_w)[I_p-t_{w,w}^*H(\mu_w)R_q^{-1}H^*(\mu_w)t_{w,w}]^{-1}\big),\\
T_v&\approx\text{blkdiag}\big(t_{v,1},\cdots,t_{v,v}\big),\\
T_w&\approx\text{blkdiag}\big(t_{w,1},\cdots,t_{v,w}\big),
\end{align}where
\begin{align}
t_{v,i}&=[I_m-D^TR_p^{-1}H(\sigma_i)]^{-1}R_b^{\frac{1}{2}},\\
t_{w,i}&=[I_p-DR_q^{-1}H^*(\mu_i)]^{-1}R_c^{\frac{1}{2}}.
\end{align}
For DD-SW-BT:
\begin{align}
Q_v^{-1}&\approx\text{blkdiag}\big(2Real(\sigma_1)I_m,\cdots,2Real(\sigma_v)I_m\big),\\
P_w^{-1}&\approx\text{blkdiag}\big(2Real(\mu_1)I_p,\cdots,2Real(\mu_w)I_p\big),\\
T_w&\approx\text{blkdiag}\big([G(\mu_1)]^{-*},\cdots,[G(\mu_w)]^{-*}\big).
\end{align}
For DD-BST:
\begin{align}
Q_v^{-1}&\approx\text{blkdiag}\big(2Real(\sigma_1)I_m,\cdots,2Real(\sigma_v)I_m\big),\\
P_w^{-1}&\approx\text{blkdiag}\big(2Real(\mu_1)[I_p-t_{w,1}^*\mathscr{H}(\mu_1)R_{\text{X}}^{-1}\mathscr{H}^*(\mu_1)t_{w,1}]^{-1},\cdots,\nonumber\\
&\hspace*{2cm}2Real(\mu_w)[I_p-t_{w,w}^*\mathscr{H}(\mu_w)R_{\text{X}}^{-1}\mathscr{H}^*(\mu_w)t_{w,w}]^{-1}\big),\\
T_w&\approx\text{blkdiag}\big(t_{w,1},\cdots,t_{v,w}\big),
\end{align}
where
\begin{align}
\mathscr{H}(\mu_i) &= \begin{cases}
\frac{2Real(\sigma_i)}{\mu_i-\sigma_i}\big[H(\sigma_i)-H(\mu_i)\big]H^*(\sigma_i)+H(\mu_i)D^T & \text{if } \sigma_i\neq\mu_i \\
2Real(\sigma_i)H^{\prime}(\sigma_i)H^*(\sigma_i)+H(\mu_i)D^T  & \text{if } \sigma_i=\mu_i
\end{cases},\\
t_{w,i}&=\Big[R_\text{X}+\mathscr{H}^*(\mu_i)\Big]^{-1}R_{\text{X}}^\frac{1}{2}.
\end{align}
Using these formulas, the algorithms proposed in this paper can be efficiently implemented. Even if samples of \( G(s) \) are available along the \( j\omega \)-axis, one can set a near-zero damping value and still use the above formulas and algorithms without significant loss of accuracy.  
\section{Numerical Results}
We present two numerical examples. The first is an illustrative example designed to facilitate convenient verification of the key theoretical results presented in the paper. The second is a modest-order RLC circuit model, which demonstrates the performance of the algorithms in a practical setting. For the state-space matrices of the RLC circuit, refer to \cite{reiter2023generalizations}. The MATLAB codes for reproducing the results of both examples are provided in the Appendices. Readers only need to run these codes to replicate the results presented in this section. All necessary accompanying MATLAB functions are also included in the Appendices. All simulations were conducted in MATLAB R2021b on a laptop with a 2 GHz Intel i7 processor and 16 GB of RAM.
