\section*{Appendix C: Functions Required to Run the Codes (In Alphabetical Order)}
\begin{verbatim}
function [Er,Ar,Br,Cr] = blk_Loewner(Gs,Gu,Gd,s,u)

p=size(Gs,1); nu=length(u); ns=length(s);
nsm=size(Gs,2); m=nsm/ns;
Er=zeros(nu,ns); Ar=zeros(nu,ns);
Br=zeros(nu,m); Cr=zeros(p,ns);

for i=1:length(u)

    ki=(i-1)*m+1; li=i*m;
    Ki=(i-1)*p+1; Li=i*p;
    Br(Ki:Li,:)=Gu(:,ki:li);

    for j=1:length(s)


        kj=(j-1)*m+1; lj=j*m;

        if u(i)==s(j)

          Er(Ki:Li,kj:lj)=-Gd(:,kj:lj);
          Ar(Ki:Li,kj:lj)=-(Gs(:,kj:lj)+s(j)*Gd(:,kj:lj));

        else

        Er(Ki:Li,kj:lj)=(Gs(:,kj:lj)-Gu(:,ki:li))/(u(i)-s(j));

        Ar(Ki:Li,kj:lj)=((s(j)*Gs(:,kj:lj)-u(i)*Gu(:,ki:li)))/(u(i)-s(j));

        end

        Cr(:,kj:lj)=Gs(:,kj:lj);





    end



end



end
\end{verbatim}
\begin{verbatim}
function [P] = br_ricc_P(A,B,C,D)

[p,n]=size(C); I=eye(n); Ip=eye(p); 
Rp=-(Ip-D*D');
P = icare(A',C',B*B',Rp,B*D',I,0);

end
\end{verbatim}
\begin{verbatim}
function [Q] = br_ricc_Q(A,B,C,D)

[n,m]=size(B); I=eye(n); Im=eye(m);
Rq=-(Im-D'*D);
Q = icare(A,B,C'*C,Rq,C'*D,I,0);

end
\end{verbatim}
\begin{verbatim}
function [Lp,Tv,Lq,Tw] = brbt_chol_fact(A,B,C,D,s,u)

ns=length(s); nu=length(u);
[n,m]=size(B); p=size(C,1); Im=eye(m); Ip=eye(p); I=speye(n);
Lp=[]; Lq=[];
Rp=Ip-D*D'; Rq=Im-D'*D; Rb=Im+D'*inv(Rp)*D; Rc=Ip+D*inv(Rq)*D';
Tv=[]; Tw=[];

for i=1:ns

    hsi=C*((s(i)*I-A)\B);
    tvi=inv(Im-D'*inv(Rp)*hsi)*(Rb^0.5);
    qvi=2*real(s(i))*inv(Im-tvi'*hsi'*inv(Rp)*hsi*tvi);
    lp = my_chol(qvi);
    Lp=blkdiag(Lp,lp);
    Tv=blkdiag(Tv,tvi);

end

for i=1:nu

    hui=C*((u(i)*I-A)\B);
    twi=inv(Ip-D'*inv(Rq)*hui')*(Rc^0.5);
    pwi=2*real(u(i))*inv(Ip-twi'*hui*inv(Rq)*hui'*twi);
    lq = my_chol(pwi);
    Lq=blkdiag(Lq,lq);
    Tw=blkdiag(Tw,twi);

end



end
\end{verbatim}
\begin{verbatim}
function [Ar,Br,Cr] = bsq(E,A,B,C,Lp,Lq,r)

[Z,S,Y]=svd(Lq'*E*Lp);

S1=S(1:r,1:r); Z1=Z(:,1:r); Y1=Y(:,1:r);

W=(Lq*Z1)/(sqrtm(S1)); V=(Lp*Y1)/(sqrtm(S1));
Ar=W'*A*V; Br=W'*B; Cr=C*V;

end
\end{verbatim}
\begin{verbatim}
function [Lp,Lq,Tw] = bst_chol_fact(A,B,C,D,s,u)

ns=length(s); nu=length(u);
[n,m]=size(B); p=size(C,1); Im=eye(m); Ip=eye(p); I=speye(n);
Lp=[]; Lq=[]; Rx=D*D'; Tw=[];

for i=1:ns

    lp = sqrt(2*real(s(i)))*Im;
    Lp=blkdiag(Lp,lp);

end

for i=1:nu

    hui=C*((u(i)*I-A)\B);
    hsi=C*((s(i)*I-A)\B);

    if u(i)==s(i)

        ei=(C/(u(i)*I-A))*((u(i)*I-A)\B);

    else

        ei=(hsi-hui)/(u(i)-s(i));

    end
    gui=2*real(s(i))*ei*hsi'+hui*D';
    twi=inv(Rx+gui')*(Rx^0.5);

    pwi=2*real(u(i))*inv(Ip-twi'*gui*inv(Rx)*gui'*twi);
    lq = my_chol(pwi);
    Lq=blkdiag(Lq,lq);
    Tw=blkdiag(Tw,twi);

end



end
\end{verbatim}
\begin{verbatim}
function [Q] = bst_ricc_Q(A,B,C,D)

P=lyap(A,B*B');
Bw=P*C'+B*D';
Ax=A-Bw*inv(D*D')*C;
Q=care(Ax,Bw,C'*inv(D*D')*C,-D*D');

end
\end{verbatim}
\begin{verbatim}
function [Ac,Bc,Cc,Dc] = design_h_inf(A,B,C,D,gm)

rho=1-gm^-2;
Q = care(A, sqrt(rho)*B, C'*C);  
K=B'*Q;

P = care(A', sqrt(rho)*C', B*B'); 
L = P * C';


Ac = A - B*K - L*C + L*D*K;
Bc = L;
Cc = -K;
Dc = zeros(size(B,2), size(C,1));

end
\end{verbatim}
\begin{verbatim}
function [Ac,Bc,Cc,Dc] = design_lqg(A,B,C,D)

Q = care(A, B, C'*C);  
K=B'*Q;

P = care(A', C', B*B'); 
L = P * C';


Ac = A - B*K - L*C + L*D*K;
Bc = L;
Cc = -K;
Dc = zeros(size(B,2), size(C,1));

end
\end{verbatim}
\begin{verbatim}
function [Gs,Gu,Gd] = gen_data_trip(E,A,B,C,s,u)

ns=length(s); nu=length(u);
m=size(B,2); p=size(C,1);
Gs=zeros(p,m*ns); Gd=Gs;
Gu=zeros(p,m*nu);

for i=1:nu

    ui=u(i); ki=(i-1)*m+1; li=i*m;

    Gu(:,ki:li)=C*((ui*E-A)\B);

    for j=1:ns

         sj=s(j); kj=(j-1)*m+1; lj=j*m;

         Gs(:,kj:lj)=C*((sj*E-A)\B);

         if sj==ui

             Gd(:,kj:lj)=-(C/(sj*E-A))*E*((sj*E-A)\B);
         end


    end


end


end
\end{verbatim}
\begin{verbatim}
function [Lp,Lq] = hinfbt_chol_fact(A,B,C,s,u,gm)

ns=length(s); nu=length(u);
[n,m]=size(B); p=size(C,1); Im=eye(m); Ip=eye(p); I=speye(n);
Lp=[]; Lq=[];
gm=2; rho=1-gm^-2;

for i=1:ns

    hsi=C*((s(i)*I-A)\B);
    qvi=2*real(s(i))*inv(Im+rho*hsi'*hsi);
    lp = my_chol(qvi);
    Lp=blkdiag(Lp,lp);

end

for i=1:nu

    hui=C*((u(i)*I-A)\B);
    pwi=2*real(u(i))*inv(Ip+rho*hui*hui');
    lq = my_chol(pwi);
    Lq=blkdiag(Lq,lq);

end



end
\end{verbatim}
\begin{verbatim}
