for i=1:ns

    hsi=C*((s(i)*I-A)\B);
    qvi=2*real(s(i))*inv(Im+hsi'*hsi);
    lp = my_chol(qvi);
    Lp=blkdiag(Lp,lp);

end

for i=1:nu

    hui=C*((u(i)*I-A)\B);
    pwi=2*real(u(i))*inv(Ip+hui*hui');
