function [P] = pr_ricc_P(A,B,C,D)

R=-(D+D');
P = icare(A',-C',0,R,B,eye(size(A)),0);
Rp=D+D';

end
\end{verbatim}
\begin{verbatim}
function [Q] = pr_ricc_Q(A,B,C,D)

R=-(D+D');
