\begin{verbatim}
function [Lp,Tv,Lq,Tw] = prbt_chol_fact(A,B,C,D,s,u)

ns=length(s); nu=length(u);
[n,m]=size(B); p=size(C,1); Im=eye(m); Ip=eye(p); I=speye(n);
Lp=[]; Lq=[]; Rpr=D+D'; Tv=[]; Tw=[];

for i=1:ns

    hsi=C*((s(i)*I-A)\B);
    tvi=inv(Im+inv(Rpr)*hsi)*(Rpr^-0.5);
    qvi=2*real(s(i))*inv(Im-tvi'*hsi'*inv(Rpr)*hsi*tvi);
    lp = my_chol(qvi);
    Lp=blkdiag(Lp,lp);
    Tv=blkdiag(Tv,tvi);

end

for i=1:nu

    hui=C*((u(i)*I-A)\B);
    twi=inv(Im+inv(Rpr)*hui')*(Rpr^-0.5);
    pwi=2*real(u(i))*inv(Ip-twi'*hui*inv(Rpr)*hui'*twi);
    lq = my_chol(pwi);
    Lq=blkdiag(Lq,lq);
    Tw=blkdiag(Tw,twi);

end



end
\end{verbatim}
\begin{verbatim}
function [s,Lp,S,L,Qsi] = s_zw(z,w,m)

s=[]; Lp=[]; Im=eye(m); Qsi=[]; S=[]; L=[]; weights=[];

for k=1:length(w)

s1=((z*abs(w(k)))/sqrt(1-z^2))+j*w(k);
s=[s s1];

end


for k=1:length(s)

    S=blkdiag(S,s(k)*Im);
    L=[L Im];

    qsi=2*real(s(k))*Im;
    Qsi=blkdiag(Qsi,qsi);

    lp=sqrt(2*real(s(k)))*Im;
    Lp=blkdiag(Lp,lp);


end

end
\end{verbatim}
\begin{verbatim}
function [Lp,Lq,Tw] = swbt_chol_fact(A,B,C,D,s,u)

ns=length(s); nu=length(u);
[n,m]=size(B); p=size(C,1); Im=eye(m); Ip=eye(p); I=speye(n);
Lp=[]; Lq=[]; Tw=[];


for i=1:ns


    lp=sqrt(2*real(s(i)));
    Lp=blkdiag(Lp,lp*Im);

end

for i=1:nu

    hui=C*((u(i)*I-A)\B)+D;

    lq = sqrt(2*real(u(i)))*Ip;
    Lq=blkdiag(Lq,lq);
    twi=inv(hui');
    Tw=blkdiag(Tw,twi);

end



end
