\section{Proof of \texorpdfstring{\cref{lem:efficient-computation}}{Proposition
\ref*{lem:efficient-computation}}}\label{app:utilities} In this section of the
appendix, we prove \cref{lem:efficient-computation}, namely the efficient
computation of the utilities.

\subsection{Efficient Utility Computation in Discrete First-Price
Auctions}\label{app:dfpa-utility} In this section, we provide the proof of
\cref{lem:efficient-computation} in the DFPA setting.

\begin{lemma}\label{lem:app-efficient-utilities} Fix a DFPA with correlated
    priors. For any bidder $i \in N$, any value $v_i \in V_i$, and any mixed
    strategy profile of the other bidders $\vec{\beta_{-i}}$, the utility of
    $i$, $u_i(\vec{\gamma},\vec{\beta_{-i}};v_i)$, when playing some
    distribution $\vec{\gamma}$ over her bids, is computable in polynomial time.
    Additionally, the utility is still efficiently computable in the $k$-GSAPV (in particular, SAPV)
    setting, where the joint prior is succinctly represented, when $\vec{\beta}_{-i}$ is symmetric.
\end{lemma}
\begin{proof}
    Without loss of generality, consider a reordering of the bidders such that
    we are computing the utility of the last one (bidder $n=\card{N}$). We can
    use the definition of a mixed strategy to express the utility of $n$ when
    picking a distribution $\vec{\gamma}$ over the bids as
    $u_n(\vec{\gamma},\vec{\beta_{-n}};v_n)=\sum_{b \in B}\vec{\gamma}(b)
    u_n(b,\vec{\beta_{-n}};v_n)$. Thus, for the left-hand side to be efficiently
    computable, it suffices to prove that all of the $\card{B}$ many summands
    are efficiently computable. By the definition of utility
    in~\eqref{eq:utility}, we can express the utility of bidder $n$ when playing
    a bid $b$ as
    $u_n(b,\vec{\beta_{-n}};v_n)=(v_n-b)H_{n}(b,\vec{\beta_{-n}};v_n)$. We now
    proceed to show how to efficiently compute $H_{n}$, by first expressing it
    as:
    \begin{equation}\label{eq:h-fcn-explicit}
        H_{n}(b,\vec{\beta_{-n}};v_n)=\sum_{r=0}^{n-1} \frac{1}{r+1} \cdot \sum_{\vec{v_{-n}}\in\support{F_{n\mid v_n}}} f_{n \mid v_n}(\vec{v_{-n}}) \cdot T_n(b,n-1,r,\vec{v_{-n}})
    \end{equation}
    where, for $0 \leq r \leq \ell \leq n-1$, $T_n(b,n-1,r,\vec{v_{-n}})$
    denotes the probability that exactly $r$ out of the remaining $n-1$ bidders
    bid exactly $b$ and all of the others bid strictly less, when the values of
    the bidders other than $n$ are $\vec{v_{-n}}$. The randomness here stems
    from the mixed strategies $\vec{\beta_{-n}}$ of the bidders.

    We can efficiently compute the support of $F_{n\mid v_n}$ by checking
    whether $v_n=t^j_n$ for each $\vec{t^j}$ in the representation of the
    distribution. Additionally, we can efficiently compute $f_{n \mid
    v_n}(\vec{v_{-n}})$ using the definition of the conditional distribution
    in~\eqref{eq:discrete-conditional}, as we can calculate the marginal
    $f_n(v_n)$ by summing over the points in the support of the distribution
    which we just computed. It remains to show how to efficiently compute each
    $T_n(b,n-1,r,\vec{v_{-n}})$. To make notation easier to follow, it is useful
    to define the following two quantities:
    \begin{equation}\label{eq:g-utility-dfpa}
        g_{j,b} \coloneq \beta_j(v_j)(b)
    \end{equation}
    \begin{equation}\label{eq:G-utility-dfpa}
        G_{j,b} \coloneq \sum_{\substack{b'\in B, \\ b'<b}} g_{j,b'}
    \end{equation}
    where, for any bidder $j$ (who must have value $v_j$
    from~\eqref{eq:h-fcn-explicit}), $g_{j,b}$ represents the probability $j$
    picks bid $b$ and $G_{j,b}$ the probability that she picks some bid strictly
    smaller than $b$, always conditioned on the fact that bidder $n$ has value
    $v_n$. We can then express $T_n(b,n-1,r,\vec{v_{-n}})$ as:
    \begin{equation}\label{eq:winning-prob-explicit}
        T_n(b,n-1,r,\vec{v_{-n}}) = \sum_{\substack{S \subseteq [n-1], \\ \card{S}=r}} \prod_{s \in S} g_{s,b} \prod_{s \in [n-1]\setminus S} G_{s,b}
    \end{equation}

    Notice that in~\eqref{eq:winning-prob-explicit} we are summing over all
    possible subsets of $[n-1]$ of size $r$, which are exponentially many.
    Hence, this is not an efficient way to compute the utility. Instead, we
    proceed with a dynamic programming approach, of similar nature to previous
    work in \cite{fghk24}. We define the DP as follows:
    \begin{align*}
    	T_n(b,0,0,\vec{v_{-n}}) &=1;              &\\
    	T_n(b,\ell,k,\vec{v_{-n}}) &=0,&\quad\text{for}\;\; k>\ell;\\
    	T_n(b,\ell+1,0,\vec{v_{-n}}) &=T_n(b,\ell,0,\vec{v_{-n}})G_{\ell+1,b};&\\
    	T_n(b,\ell+1,k+1,\vec{v_{-n}}) &=T_n(b,\ell,k,\vec{v_{-n}})g_{\ell+1,b} + T_n(b,\ell,k+1,\vec{v_{-n}})G_{\ell+1,b}; &\text{for}\;\; k\leq\ell.
    \end{align*}

    Using this, we can compute any $T_n(b,n-1,k,\vec{v_{-n}})$ for $k \in
    0,1,\ldots,n-1$ with a total number of $O(n^2)$ recursive calls. Therefore,
    following the previous steps in this proof we see that
    $u_n(\vec{\gamma},\vec{\beta_{-n}};v_n)$ is computable in polynomial time.

    We now move to the $k$-GSAPV setting.
    Let $\mathcal{R}=\{(\vec{t^1},p_1),\ldots,(\vec{t^\ell},p_\ell)\}$ be the succinct representation of $F$, as described in \cref{sec:representation-dfpa}.
    Let $\vec{t^j_{-n}}$ be the vector corresponding from removing the first entry (among the ones that correspond to bidder $n$'s group) that matches $v_n$ in $\vec{t^j}$.
    Using the properties of the representation, we can express the conditional distribution at some point $\vec{t^j_{-n}}$ of the support as:
    \begin{equation}\label{eq:app-conditional-representative}
        f_{n \mid v_n}(\vec{t^j_{-n}}) = \frac{p_j}{f_n(v_n)}
    \end{equation}
    where $f_n(v_n)$ denotes the marginal distribution of bidder $n$ evaluated at $v_n$. Notice
    that the marginal distribution can be efficiently computed using the
    properties of the succinct representation by appropriately summing over all
    elements in its support where $v_n$ appears in one of the entries corresponding to $n$'s group. 
    We will then rewrite~\eqref{eq:h-fcn-explicit} as:
    \begin{equation}
        H_{n}(b,\vec{\beta_{-n}};v_n)=\sum_{r=0}^{n-1} \frac{1}{r+1} \cdot \sum_{\substack{(\vec{t^j},p_j)\in \mathcal{R}: \\\vec{t^j_{-n}}\in \support{F_{n \mid v_n}} }} m_j \cdot f_{n \mid v_n}(\vec{t^j_{-n}}) \cdot T_n(b,n-1,r,\vec{t^j_{-n}}) 
    \end{equation} 
    where $m_j$ counts the number of group-valid permutations.
    To compute $m_j$, assume, without loss of generality, that the bidder $n$ belongs in the last group (the $k$-th). Then, $m_j = n_1! n_2!\ldots n_{k-1}!(n_k-1)!$.

    In the above, we used the fact that, due to the symmetry of the bidding strategies $\vec{\beta_{-n}}$, $T_n(b,n-1,r,\vec{v})=T_n(b,n-1,r,\vec{v'})$ for any $\vec{v'}$ that is a group-valid permutation of $\vec{v}$.
    The result that the computation of the utilities takes polynomial time comes from the following facts:
    \begin{itemize}
        \item [-] We can check whether $\vec{t^j_{-n}}\in \support{F_{n \mid v_n}}$ in polynomial time, by simply checking whether $v_n$ appears in $\vec{t^j}$ in the entries corresponding to bidder $n$'s group.
        \item [-] We can efficiently compute $T_n(b,n-1,r,\vec{t^j_{-n}})$ using the same dynamic programming approach we presented in the general correlated setting.
        \item [-] We can efficiently compute $m_j \cdot f_{n \mid v_n}(\vec{t^j_{-n}})$, using the definition of $m_j$ from \cref{sec:representation-dfpa} and \cref{eq:app-conditional-representative}. 
    \end{itemize}
\end{proof}

\subsection{Efficient Utility Computation in Continuous First-Price
Auctions}\label{app:cfpa-utility} We will now show that we can also efficiently
compute the utilities in the CFPA, given the representation of
\cref{sec:CFPA-represent}:

\begin{lemma}\label{lem:app-cfpa-efficient-utilities} Fix a CFPA with correlated
    priors. For any bidder $i \in N$, any value $v_i \in V_i$, and any (pure)
    strategy profile of the other bidders $\vec{\beta_{-i}}$, the utility of
    $i$, $u_i(b,\vec{\beta_{-i}};v_i)$, when bidding $b$, is computable in
    polynomial time. Additionally, the utility is still efficiently computable
    in the $k$-GSAPV (in particular, SAPV) setting, where the prior is succinctly represented, when $\vec{\beta}_{-i}$ is symmetric.
\end{lemma}
\begin{proof}
   Similarly to \cref{lem:app-efficient-utilities}, we begin by considering,
   without loss of generality, a reordering of the bidders such that we are
   computing the utility of the last one (bidder $n=\card{N}$). Using the
   definition of utility in~\eqref{eq:utility}, we have
   $u_n(b,\vec{\beta_{-n}};v_n)=(v_n-b)H_{n}(b,\vec{\beta_{-n}};v_n)$, so it
   suffices to show that the $H$ function is efficiently computable. We can
   express this as:
   \begin{equation}\label{eq:app-cfpa-h-fcn}
    H_{n}(b,\vec{\beta_{-n}};v_n)=\sum_{r=0}^{n-1}\frac{1}{r+1}\int_{\vec{v}_{-n}\in \vec{V}_{-n}}f_{n|v_n}(\vec{v_{-n}}) T_n(b,n-1,r,\vec{v_{-n}})\, \mathrm{d}\vec{v_{-n}}
   \end{equation}
   where we define $T_n(b,n-1,r,\vec{v_{-n}})$ to indicate whether exactly $r$
   out of the remaining $n-1$ bidders bid exactly $b$ and all the others bid
   strictly less, when the values of the bidders other than $n$ are
   $\vec{v_{-n}}$. Firstly, $T_n(b,n-1,r,\vec{v_{-n}})$ is easy to compute using
   the same dynamic approach as in \cref{lem:app-efficient-utilities}, with the
   only difference of redefining~\eqref{eq:g-utility-dfpa}
   and~\eqref{eq:G-utility-dfpa} to:

   \begin{equation}\label{eq:g-utility-cfpa}
    g_{j,b} \coloneq \mathbbm{1}\left[\beta_j(v_j)=b\right]
    \end{equation}
    \begin{equation}\label{eq:G-utility-cfpa}
        G_{j,b} \coloneq \mathbbm{1}\left[\beta_j(v_j)<b\right]
    \end{equation}

    It remains to show how to compute the integral. Notice that, given the
    representation of the CFPA, we can replace the integral by a sum over the
    support of $f_{n\mid v_n}$:
   \begin{equation}\label{eq:cfpa-utility-h-via-repr}
    H_{n}(b,\vec{\beta_{-n}};v_n)=\sum_{r=0}^{n-1}\frac{1}{r+1} \cdot \sum_{\vec{v_{-n}}\in \support{F_{n \mid v_n}}} f_{n|v_n}(\vec{v_{-n}}) T_n(b,n-1,r,\vec{v_{-n}})
   \end{equation}

   We can efficiently compute the support of $F_{n \mid v_n}$ by checking
   whether $v_n \in \vec{R^j_n}$ for each hyperrectangle $\vec{R^j}$, adding
   $\vec{R^j_{-n}}$ to the support if that is the case. For the computation of
   $f_{n|v_n}(\vec{v_{-n}})$, notice that is suffices to be able to compute the
   marginal $f_n(v_n)$, which we can efficiently do by summing over all the
   elements in the support of $F_{n \mid v_n}$, which we just computed. Hence,
   there are polynomially many (to the size of the input) summands, each of
   which can be efficiently computed, which concludes the proof for general
   correlated values.

    Moving to the $k$-GSAPV setting, let
    $\mathcal{R}=\{(\vec{R^1},w_1),\ldots,(\vec{R^\ell},w_\ell)\}$ be the
    succinct representation of the joint distribution $F$. In this case, we can
    rewrite the $H$ functions that express the winning probability using the
    succinct representation as follows:
    \begin{equation}\label{eq:cfpa-utility-h-group-symmetric}
    H_{n}(b,\vec{\beta_{-n}};v_n)=\sum_{r=0}^{n-1} \frac{1}{r+1} \cdot \sum_{\substack{(\vec{R^j},w_j)\in \mathcal{R}: \\\vec{R^j_{-n}}\in \support{F_{n \mid v_n}} }} f_{n \mid v_n}(\vec{R^j_{-n}}) \cdot m_j \cdot T_n(b,n-1,r,\vec{R^j_{-n}}), 
    \end{equation} 
    where $m_j$ counts the number of valid permutations (with respect to the
    groups). To compute $m_j$, assume, without loss of generality, that the bidder $n$ belongs in the
    last group (the $k$-th). Then, $m_j = n_1! n_2!\ldots n_{k-1}!(n_k-1)!$.

    To derive the above, we have used the fact that the bidders are symmetric to
    guarantee that $T_n(b,n-1,r,\vec{v})=T_n(b,n-1,r,\vec{v'})$ for any
    $\vec{v'}$ that is a group-valid permutation of $\vec{v}$, and instead of summing over
    the whole support of the conditional, we have only summed over the elements
    that appear in the succinct representation. To prove that the RHS
    of~\eqref{eq:cfpa-utility-h-group-symmetric} (and thus the utility, when the
    other bidders play according to a symmetric strategy $\vec{\beta_{-n}}$) is
    efficiently computable, we show the following facts:
    \begin{itemize}[leftmargin=*]
        \item[-] First of all, notice that it is easy to check whether
        $\vec{R^j_{-n}}\in \support{F_{n \mid v_n}}$, by iterating through the
        intervals representing $\vec{R^j}$ and checking if $v_n$ is in any of
        them (out of the ones corresponding to bidder $n$'s group). 
        \item[-] $T_n(b,n-1,r,\vec{R^j_{-n}})$ is also efficiently computable,
        using the same dynamic approach as in the case of general correlated
        priors.
        \item[-] It remains to show that we can compute $f_{n \mid v_n}(\vec{R^j_{-n}})$ for every $\vec{R^j_{-n}}$.
        To see this, we will express it as follows:
        \begin{equation}\label{eq:cfpa-conditional-symmetric}
            f_{n \mid v_n}(\vec{R^j_{-n}}) = \frac{w_j}{f_n(v_n)} = \frac{w_j}{\int_{\vec{v_{-n}}\in \vec{V_{-n}}} f(v_n,\vec{v_{-n}})\, \mathrm{d}\vec{v_{-n}}} = \frac{w_j}{\sum_{j=1}^{\ell}w_j \cdot \sum_{\pi \in \perm{n_1,n_2,\ldots,n_k}} \mathbbm{1}_{\pi(\vec{R^j})}(v_n,\vec{v_{-n}})} 
        \end{equation}
        where the last step follows from the definition of the representation of
        the CFPA with SAPV. Finally, we need to reason that the denominator in
        the expression of the conditional is efficiently computable. Notice that
        if we naively try to compute it, there is an exponential blow up in the
        computation of all group-valid permutations. Instead, we will describe how to
        efficiently compute it using our succinct representation. To see this,
        notice that for every hyperrectangle $\vec{R^j}$ in the representation
        we can keep a count of the number of times each interval appears in the entries corresponding to $n$'s group.
        Then, we can also efficiently compute $S_n$, which we define to be the set of intervals of $\vec{R^j}$ that correspond to $n$'s group, in which $v_n$ is contained. 
        We can now express the sum over the valid permutations to be equal to $n_1!n_2!\dots n_{k-1}!(n_k-1)! \sum_{s \in S_n}c_s$, where we denote by $c_s$ the number of times interval $s$ appears in $\vec{R^j}$ and we have assumed, without loss of generality, that $n$ belongs to group $k$.
    \end{itemize}
    Using the above properties, we have demonstrated how to efficiently compute
    the RHS of~\eqref{eq:cfpa-utility-h-group-symmetric}, and therefore the
    utility $u_n(b,\vec{\beta_{-n}};v_n)$ for symmetric strategy profiles
    $\vec{\beta_{-n}}$.
\end{proof}


\section{Omitted Proofs from \texorpdfstring{\cref{sec:densification}}{Section \ref*{sec:densification}}}
\label{app:densification-proofs}

\subsection{Proof of~\texorpdfstring{\cref{lemma:inverter-poly-time-oracle-beta-MW}}{Lemma~\ref*{lemma:inverter-poly-time-oracle-beta-MW}}}

    We start with the IID setting. We will use the same notation for the IID
    value distribution representation, as we did in the proof of
    \cref{lemma:Lipschitz-bounds-beta-SAPV-bounded-IID} (see
    Page~\pageref{page:IID-represent-internal-lemma}). Recall that the density
    of the marginal distribution is given by $f_1(x)=p_{j}$ for all
    $x\in(a_{j-1},a_{j})$, $j\in[k]$, and thus its cdf, on any value $x\in
    [\underline{v},1]$, can be recursively computed, in polynomial time, by:
    \begin{equation}
        \label{eq:marginal-cdf-iid-recursive}
    F_1(x)=
    \begin{cases}
        xp_1,&\text{for}\;\; x\in[a_0,a_1],\\
        (x-a_{j-1})p_{j}+F(a_{j-1}), &\text{for}\;\; x\in[a_{j-1},a_{j}],\; j=2,3,\dots,k.
    \end{cases}
    \end{equation}
    In the following, it would also be convenient to have direct access to the
    intervals of $F_1$'s support, so we define $J^*\coloneqq
    \ssets{j\in[k]\fwh{p_k>0}}$ and $\bar{J}^*:=[k]\setminus J^*$. Note that
    sets $J^*$ and $\bar{J}^*$ can be computed in polynomial time from our
    representation of $F_1$.

    Now, to compute the canonical equilibrium strategy $\beta$, on any value
    $x\in[\underline{v},1]$, we first observe that by~\eqref{eq:MW-CCFPA-PBNE-beta-IID}:
    $$
    \beta(x) 
    = x-\int_{0}^x \frac{F_1^{n-1}(t)}{F_1^{n-1}(x)} \,\mathrm{d} t
    = x-\frac{1}{F_1^{n-1}(x)}\int_{0}^x F_1^{n-1}(t) \,\mathrm{d} t.
    $$
    Therefore, for any value $x\in V_1$ in the support of the marginal, i.e.,
    such that $x\in[a_\xi,a_{\xi+1}]$ with $\xi+1\in J^*$, we can compute the
    above integral as:
    \begin{align}
    \beta(x) &=x-\frac{1}{F_1^{n-1}(x)}\int_{\underline{v}}^x [F_1(t)]^{n-1} \,\mathrm{d} t \notag\\
        &=x-\frac{1}{F_1^{n-1}(x)}\left[\sum_{j=1}^\xi\int_{a_{j-1}}^{a_j} \left[F_1(a_{j-1})+(t-a_{j-1})p_j\right]^{n-1} \,\mathrm{d} t +\int_{a_{\xi}}^x \left[F(a_\xi)+(t-a_\xi)p_{\xi+1}\right]^{n-1} \,\mathrm{d} t\right] \notag\\
        &=x-\frac{1}{F_1^{n-1}(x)}\left[\sum_{j\in[\xi]\inters J^*}\int_{a_{j-1}}^{a_j} \left[F_1(a_{j-1})+(t-a_{j-1})p_j\right]^{n-1} \,\mathrm{d} t +\int_{a_{\xi}}^x \left[F_1(a_\xi)+(t-a_\xi)p_{\xi+1}\right]^{n-1} \,\mathrm{d} t\right. \notag\\
        &\qquad\qquad\qquad\left.+\sum_{j\in[\xi]\inters \bar{J}^*}\int_{a_{j-1}}^{a_j} \left[F_1(a_{j-1})+(t-a_{j-1})p_j\right]^{n-1} \,\mathrm{d} t \right] \notag\\
        &=x-\frac{1}{F_1^{n-1}(x)}\left[\sum_{j\in[\xi]\inters J^*}\frac{1}{np_{j}}\int_{a_{j-1}}^{a_j} \frac{\mathrm{d}}{\mathrm{d}t}\left[F_1(a_{j-1})+(t-a_{j-1})p_j\right]^{n} \,\mathrm{d} t\right. \notag\\
        &\qquad\qquad\qquad\left.+\frac{1}{np_{\xi+1}}\int_{a_{\xi}}^x \frac{\mathrm{d}}{\mathrm{d}t}\left[F_1(a_\xi)+(t-a_\xi)p_{\xi+1}\right]^{n} \,\mathrm{d} t+\sum_{j\in[\xi]\inters \bar{J}^*}\int_{a_{j-1}}^{a_j} F_1^{n-1}(a_{j-1}) \,\mathrm{d} t \right] \notag\\
        &=x-\frac{1}{F_1^{n-1}(x)}\left[\sum_{j\in[\xi]\inters J^*}\frac{1}{np_{j}}\left[\left(F_1(a_{j-1})+(a_j-a_{j-1})p_j\right)^{n}-F_1^n(a_{j-1})\right] \right.\notag\\ 
        &\qquad\qquad\qquad\left.+\frac{1}{np_{\xi+1}} \left[\left(F_1(a_{\xi})+(x-a_{\xi})p_{\xi+1}\right)^{n}-F_1^n(a_{\xi})\right] +\sum_{j\in[\xi]\inters \bar{J}^*}(a_j-a_{j-1}) F_1^{n-1}(a_{j-1}) \right] \notag\\
        &=x-\frac{1}{F_1^{n-1}(x)}\left[\sum_{j\in[\xi]\inters J^*}\frac{1}{np_{j}}\left[F_1^n(a_{j})-F_1^n(a_{j-1})\right] +\frac{1}{np_{\xi+1}} \left[F_1^n(x)-F_1^n(a_{\xi})\right] \right.\notag\\
        &\qquad\qquad\qquad\left.+\sum_{j\in[\xi]\inters \bar{J}^*}(a_j-a_{j-1}) F_1^{n-1}(a_{j-1}) \right] \label{eq:beta-explicit-iid-piecewise} 
    \end{align}
    Given that, by~\eqref{eq:marginal-cdf-iid-recursive}, we have
    polynomial-time oracle access to the values of the cdf $F_1$, it is not hard
    to see that the expression~\eqref{eq:beta-explicit-iid-piecewise} can be
    (exactly) computed in polynomial time as well (with respect to the binary
    representation of the input value $x$ and the auction's description).

    Finally, note that for the remaining values $x\in [\underline{v},1]\setminus
    V_1$, which are outside the marginal's support, computation is
    straightforward: since $\beta$ is constant in the intervals outside of
    $F_1$'s support, we can simply query the value of $\beta$ on the last point,
    before $x$, in the support. That is, we can compute (in polynomial time)
    index $\xi^*=\max\ssets{j\in J\fwh{a_j\leq x}}$ and then use
    $\beta(x)=\beta(a_{\xi^*})$, where $\beta(a_{\xi^*})$ can be computed, in
    polynomial time, as described above
    (in~\eqref{eq:beta-explicit-iid-piecewise}, by using $x\gets
    \alpha_{\xi^*}$).

    \bigskip
    We now move to the SAPV setting, under our standard assumption that the
    joint value $F$ has full support. Similar to our proof
    of~\cref{lemma:Lipschitz-bounds-beta-SAPV-bounded-IID}, we need to now use
    our hyperrectangle representation for $F$ (see~\cref{sec:CFPA-represent}).
    Our proof is split into a series of observations/steps, each of which we
    make sure that can be executed in polynomial time.
    \begin{enumerate}
    \item\label{item:SAPV-marginal-induced-representation} Due to the
    hyperrectangle representation of $F$ in our input, the marginal distribution
    $F_1$ is piecewise constant. That is, there exist pairs
    $\sset{(a_1,p_1),\dots,(a_k,p_k)}\in(0,1]^2$ with
    $0=a_0<a_1<a_2<\dots<a_{k-1}<a_k= 1$ and $\sum_{j=1}^kp_j=1$, such that the
    density $f_1$ of the marginal (which has full-support) is given by
    $f_1(x)=p_j$ if $x\in(a_{j-1},a_j)$ for $j\in[k]$. Furthermore, this
    representation can be constructed in polynomial time (with respect to the
    initial binary representation of $F$ in our input).

    \item\label{item:SAPV-marginal-order-statistics-induced-representation}
    Given a value $v\in [0,1]$, the distribution of the maximum value of all
    other players, namely $G_v$, has also piecewise constant density. Again, we
    can construct in polynomial time a list of value-density pairs
    $\sset{(c^v_1,q^v_1),\dots,(c^v_\ell,q^v_\ell)}\in(0,1]^2$ such that
    $g_v(y)=g^v_j$ if $y\in[c^v_{j-1},c^v_j]$. This can be done in two steps:
    \begin{enumerate}
    \item First, we find a succinct, hyperrectangle representation\footnote{That
    is, our standard representation for symmetric priors,
    see~\eqref{eq:represent-CFPA-density-permutations}
    in~\cref{sec:CFPA-represent}.} for the conditional distribution $F_{1|v}$ of
    all other bidders' values $\vec{v}_{-1}$, when the value of bidder $1$ (or
    any other bidder, due to symmetry) is fixed at $v$;
    see~\eqref{eq:cfpa-conditional-symmetric}, for more details about why this
    can be efficiently computed.
    \item Secondly, given a value $y\in [0,1]$, the computation of the density
    $g_v(y)$ boils down to identifying (up to symmetry) all the hyperrectangles
    in $F_{1|v}$'s representation from the first step, that are intersecting the
    outer faces of the hypercube $[0,y]^{n-1}$; i.e., we check for all
    hyperrectangles that, in any of their coordinates, include $y$, and we take
    the sum of their weight/densities, taking all their permutations into
    consideration (due to the symmetric representation;
    see~\eqref{eq:represent-CFPA-density-permutations}). The reason for this is
    that the corresponding cdf of the maximum order statistic $G_v(y)$ of
    $\vec{v}_{-1}$ is equal to the probability $\prob{Y_1 \leq y
    \fwh{X_1=y}}$.\footnote{This is conceptually similar to our arguments for
    the bodies $S_x$ in Page~\pageref{page:max-order-stat-(n-1)hypercubes} in
    the proof of~\cref{lemma:bounds-inverse-bidding}.} Finally, recall that, as
    we have argued multiple times within our proofs in~\cref{sec:densification},
    $\support{G_v}\subseteq \support{F_1}$, and therefore it is enough to only
    consider one value of $y$ for each interval $(a_{j-1},a_j)$ of $F_1$'s
    representation (see Step~\ref{item:SAPV-marginal-induced-representation}
    above). 
    \end{enumerate}
    %
    Then, the corresponding cdf can also be efficiently computed, by
    observing that
    \begin{equation}
        \label{eq:oracle-beta-general-computation-G}
        G_v(y)=(y-c^v_{j-1})q_j^v+\sum_{l=1}^{j-1}(c^v_{l}-c^v_{l-1})q^v_l.
    \end{equation}
    \item\label{item:SAPV-marginal-order-statistics-constant-interval-induced-representation}
    Given a fixed value $y\in [0,1]$, functions $G_v(y), g_v(y)$ are constant,
    with respect to the conditional $v$, within the different intervals in the
    support of the marginal. That is, for any $j\in[k]$ and $v,v'\in
    [a_{j-1},a_j]$, it is $g_v(y)=g_{v'}(y)$ for all $y\in [0,1]$.
    \end{enumerate}

    Now we are ready to show how the values of the canonical bidding strategy
    $\beta$ (given in~\eqref{eq:MW-CCFPA-PBNE-beta}), can be (exactly) computed
    in polynomial time. Fix some $v\in [0,1]$ and let $v\in[a_{k_v-1},a_{k_v}]$
    be the interval of the marginal distribution representation (see
    Point~\ref{item:SAPV-marginal-induced-representation} above) in which it
    lies in. We will now show that function $L_v(y)$, given
    in~\eqref{eq:MW-CCFPA-PBNE-L}, is piecewise constant with respect to $y
    \in[0,v]$, across the intervals of the representation of $G_v$ (see
    Point~\ref{item:SAPV-marginal-order-statistics-induced-representation}
    above). Indeed $L_v(y)$ can be computed in the following recursive way:
    \begin{itemize}
        \item For $y\in[a_{k_v-1},v]$, it is
        \begin{align*}
            L_v(y)&= \exp\left(-\int_{y}^v\frac{g_t(t)}{G_t(t)}\,\mathrm{d}t\right)\\
            &= \exp\left(-\int_{y}^v\frac{g_{a_{k_v}}(t)}{G_{a_{k_v}}(t)}\,\mathrm{d}t\right), &&\text{due Point~\ref{item:SAPV-marginal-order-statistics-constant-interval-induced-representation} above, since}\;\; t\in[a_{k_v-1},a_{k_v}],\\
            &= \exp\left(-\int_{y}^v\left[\frac{\mathrm{d}}{\mathrm{d}t}\ln G_{a_{k_v}}(t)\right]\,\mathrm{d}t\right)\\
            &= \exp\left(\ln G_{a_{k_v}}(y)-\ln G_{a_{k_v}}(v)\right)\\
            &=\frac{G_{a_{k_v}}(y)}{G_{a_{k_v}}(v)},
        \end{align*}
        which can be computed in polynomial time, via~\eqref{eq:oracle-beta-general-computation-G}.
        %
        \item For $y\in[a_{\kappa-1},a_{\kappa}]$, where $1\leq\kappa\leq k_v-1$, it is
        \begin{align*}
            L_v(y)&= \exp\left(-\int_{y}^{a_\kappa}\frac{g_t(t)}{G_t(t)}\,\mathrm{d}t -\int_{a_\kappa}^v\frac{g_t(t)}{G_t(t)}\,\mathrm{d}t\right)\\
            &= \exp\left(-\int_{y}^{a_\kappa}\frac{g_t(t)}{G_t(t)}\,\mathrm{d}t\right)\cdot\exp\left(-\int_{a_\kappa}^v\frac{g_t(t)}{G_t(t)}\,\mathrm{d}t\right)\\
            &= \exp\left(-\int_{y}^{a_\kappa}\frac{g_t(t)}{G_t(t)}\,\mathrm{d}t\right)\cdot L_v(a_\kappa)\\
            &= \exp\left(-\int_{y}^{a_\kappa}\frac{g_{a_\kappa}(t)}{G_{a_\kappa}(t)}\,\mathrm{d}t\right)\cdot L_v(a_\kappa),&&\text{since}\;\; t\in[a_{\kappa-1},a_\kappa],\\
            &= \frac{G_{a_\kappa}(y)}{G_{a_\kappa}(a_\kappa)}\cdot L_v(a_\kappa).
        \end{align*}
    \end{itemize}


\subsection{Proof of~\texorpdfstring{\cref{lemma:Lipschitz-bounds-beta-SAPV-bounded-IID}}{Lemma~\ref*{lemma:Lipschitz-bounds-beta-SAPV-bounded-IID}}}

Recall (see~\cref{sec:canonical-equilibrium-MW},
    page~\pageref{page:beta-absolutely-continuous}) that the canonical
    equilibrium strategy $\beta$ is absolutely continuous and almost everywhere
    differentiable (see~\eqref{eq:MW-beta-differential-equation-def}).
    Therefore, in order to bound its Lipschitz constant, it is enough to bound
    its derivative $\card{\beta'}$.\footnote{More precisely, here we are using
    the fact that, if for an absolutely continuous function $f:[a,b]\map\R$ it
    holds that $\card{f'}\leq c$ a.e. on $[a,b]$, for some $c>0$, then $\beta$
    is Lipschitz continuous with constant at most $c$. This is a direct
    consequence of the fundamental theorem of calculus: for any $x,y\in[a,b]$ we
    get that $\card{f(x)-f(y)}=\card{\int_x^y f'(t)\,\mathrm{d}t} \leq \int_x^y
    \card{f'(t)} \,\mathrm{d}t \leq \int_x^y c \,\mathrm{d}t = c\card{x-y}$.}
    Also recall that $\beta$ is nondecreasing (and thus, its derivative is
    nonnegative) and constant outside the marginals' support $V_1$. Therefore,
    it is enough to simply upper-bound $\beta'$ on $V_1$.

    We start first with the SAPV setting. Then, the value distribution is
    $(\priorlowerbound,\priorupperbound)$-bounded for $\priorlowerbound\geq
    w_{\min}$ and $\priorupperbound\leq \ell n! w_{\max}$
    (see~\eqref{eq:represent-CFPA-density-permutations}), where here we are
    using the parameters of the hyperrectangle representation
    from~\cref{sec:CFPA-represent}, with $w_{\min}\coloneqq\min_{j\in[\ell]}
    w_j$,  $w_{\max}\coloneqq\max_{j\in[\ell]} w_j$, and $\ell$ being the number
    of hyperrectangles in the input. Then, at any $y\in V_1$ we can bound
    $\beta$'s derivative by:
    \begin{align}
    \beta'(y) 
    &= \frac{g_y(y)}{G_y(y)}\int_{\underline{v}}^yL_y(t)\, \mathrm{d} t, &&\text{from~\eqref{eq:bounds-density-max-conditional-helper5},}\\
        &\leq \frac{g_y(y)}{G_y(y)}\int_{\underline{v}}^y 1\, \mathrm{d} t,&&\text{from Property~\ref{item:affiliation-property-measure-L} of~\cref{prop:affiliation-properties},}\label{eq:bounds-density-max-conditional-helper8}\\
        &\leq \frac{g_y(y)}{G_y(y)} y\notag\\
        &= \frac{g_y(y)}{\int_{0}^y g_y(t)\,\mathrm{d}t} y\notag, &&\text{since $G_y$ has full support $[0,1]$,}\\
        &\leq \frac{\frac{n-1}{f_1(y)}\priorupperbound y^{n-2}}{\int_{0}^y\frac{n-1}{f_1(y)}\priorlowerbound t^{n-2}}y\notag, &&\text{from~\eqref{eq:bounds-density-max-conditional-helper3},}\\
        &=\frac{\priorupperbound}{\priorlowerbound}\frac{(n-1)y^{n-2}}{y^{n-1}}y\notag\\
        &=(n-1)(\priorupperbound/\priorlowerbound)\notag\\
        &\leq (n-1)\frac{\ell n! w_{\max}}{w_{\min}}\notag\\
        &= 2^{\Theta(n\log n)}\ell\frac{w_{\max}}{w_{\min}}.\notag
    \end{align}

    We next consider IID values. We will make use that now the marginal $F_1$ is
    given to us (see also the representation in
    p.~\pageref{page:IID-represent-internal-lemma}) in the input by a set of
    possible values $0=a_0<a_1<a_2<\dots<a_{k-1}<a_{k}=1$ together with their
    corresponding probabilities $\ssets{p_j}_{j\in[k]}\in [0,1]$, such that
    $\sum_{j=1}^k(a_j-a_{j-1})p_j=1$. Then, the marginal's density is given by
    $f_1(x)=p_{j}$ for all $x\in(a_{j-1},a_{j})$, $j\in[k]$. Clearly, the value
    distribution is $\priorupperbound$-bounded, with
    $\priorupperbound=p_{\max}\coloneq \max_{j\in[k]} p_j>0$. Let us also denote
    $p_{\min}\coloneq \min_{j\in[k]}\ssets{p_j\fwh{p_j>0}}>0$,
    $\bar{a}_{\min}\coloneqq \min_{j\in[k]} (a_j-a_{j-1})>0$ and
    $\bar{a}_{\max}\coloneqq \max_{j\in[k]} (a_j-a_{j-1})>0$. Observe that all
    these quantities have polynomial binary representation.

    From~\eqref{eq:bounds-density-max-conditional-helper8}, for the IID setting
    we can bound the derivative of the canonical equilibrium strategy, at any
    value $x\in V_1$ in the support, by
    \begin{align}
    \beta'(x) &\leq \frac{g(x)}{G(x)}\int_{\underline{v}}^x 1\, \mathrm{d} t \notag\\
    &=\frac{g(x)}{G(x)}(x-\underline{v}) \notag\\
    &=\frac{(n-1)f_1(x)F_1^{n-2}(x)}{F_1^{n-1}(x)}(x-\underline{v})\notag\\
    &=(n-1)\priorupperbound\frac{x-\underline{v}}{F_1(x)}\label{eq:bound-Lipschit-beta-IID-helper1},
    \end{align}
    where, recall that, $\underline{v}=\inf V_1$ denotes the leftmost point in
    the support of the marginal value distribution. Taking our input
    representation into consideration, clearly it must be that
    $\underline{v}\in\ssets{a_0,a_1,\dots,a_{k-1}}$. Let $\xi\in[k]$ such that
    $\underline{v}=a_{\xi-1}$. Notice that it must be that $p_\xi>0$. Then, we
    observe that: 
    \begin{itemize}
    \item If $x\in[a_{\xi-1},a_\xi]$, then $F_1(x)=p_\xi(x-a_{\xi-1})=p_\xi(x-\underline{v})$ and therefore $\frac{x-\underline{v}}{F_1(x)}= \frac{1}{p_{\xi}}\leq\frac{1}{p_{\min}}\leq\frac{\bar{a}_{\max}}{\bar{a}_{\min}}\frac{1}{p_{\min}}$.
    \item If $x\in[a_{l-1},a_l]$ for some $\xi<l\leq k$, then it must be that
    $F(x) \geq (a_\xi-a_{\xi-1})p_\xi\geq \bar{a}_{\min}p_{\min} $ and
    $x-\underline{v}=x-a_{\xi-1}\leq a_{l}-a_{\xi-1}\leq \bar{a}_{\max}$.
    Therefore,
    $\frac{x-\underline{v}}{F_1(x)}\leq\frac{\bar{a}_{\max}}{\bar{a}_{\min}}\frac{1}{p_{\min}}$.
    \end{itemize}
    Using this bounds, we can finally upper-bound the derivative of $\beta$
    from~\eqref{eq:bound-Lipschit-beta-IID-helper1} by
    $$\beta'(x) \leq (n-1)\cdot p_{\max} \cdot \frac{\bar{a}_{\max}}{\bar{a}_{\min}}\frac{1}{p_{\min}}\leq n \frac{\bar{a}_{\max}}{\bar{a}_{\min}}\frac{p_{\max}}{p_{\min}}.$$





\section{Technical Lemmas}
\label{app:technical}

\begin{lemma}
\label{lemma:lower-bound-integral-derivative} Let $g:[a,b]\to\R_{\geq 0}$ be a
nondecreasing, absolutely continuous function, whose derivative is at most $L>0$
(almost everywhere). Then,
$$
\int_{a}^b F(t)\, dt \geq \frac{F^2(b)-F^2(a)}{2\cdot L}.
$$
\end{lemma}
\begin{proof}
Since $F$ is absolutely continuous and nondecreasing, its derivative $F'$ exists
almost everywhere and is nonnegative, thus 
$$
\int_{a}^b F(t)\, dt 
\geq \int_{a}^b \frac{F'(t)}{L}F(t)\, dt
= \frac{1}{2L}\int_{a}^b 2 F(t)F'(t)\, dt
= \frac{1}{2L}\int_{a}^b [F^2(t)]'\, dt
= \frac{1}{2L} \left[F^2(b)-F^2(a)\right].
$$
\end{proof}


\begin{lemma}
    \label{lemma:bounds-difference-of-powers} 
    Let $n$ be a positive integer, and $0\leq x \leq y$ reals. Then,
    $$
    n(y-x)x^{n-1}
    \leq
    y^n-x^n
    \leq 
    n(y-x)y^{n-1}.
    $$
\end{lemma}
\begin{proof}
Immediate from the convexity of the function $f(x)=x^n$ and the fact that its
derivative is $f'(x)=n x^{n-1}$.
\end{proof}




