\subsection{Tiled Matrix Multiplication}
\subsubsection{Runtime}
\begin{figure}[h]
    \centering
    \includegraphics[width=\columnwidth]{figures/matmul_time_tile1.png}
    \caption{The runtime of tiled matrix multiplication for different matrix sizes with tile=1}
\label{fig:matmul_time_tile1}
