We consider that the jobs of a task $\tau_i$ must be executed one
after another in a FIFO manner. If a job $\tau_{i,j}$ of task
$\tau_i$ does not finish execution before the next job
$\tau_{i,j+1}$ of $\tau_i$ is released, job $\tau_{i,j+1}$
cannot be executed even if the processor idles. That is, the
EL scheduling algorithm has to handle this situation as
follows: 1) It sets the priority of the job $\tau_{i,j+1}$ to
$r_{i,j+1} + \Pi_i$ when it arrives at $r_{i,j+1}$, but 2) this
job is only eligible for execution (i.e., ready to be executed) after
all jobs of $\tau_i$ released prior to $\tau_{i,j+1}$ finish execution.


\section{Capabilities and Limitations of EL Scheduling}
\label{sec:capabilities_and_limitations}

EDF-Like (EL) scheduling algorithms are Job-Level Fixed-Priority (JFP) scheduling algorithms, i.e., if one job has higher priority than another job, then it has higher priority at all times.
This is due to the priority definition by comparison of priority points.
Since the priority point of a job does not change once it is assigned, the priorities of jobs are fixed after they are released.
%
However, EL scheduling covers many of those JFP scheduling algorithms.
These are for example: 
\begin{itemize}
	\item Earliest-Deadline-First (EDF)~\cite{liu73scheduling} ($\Pi_i = D_i$)
	\item Earliest-Quasi-Deadline-First (EQDF)~\cite{DBLP:conf/rtas/BackCS12} \\($\Pi_i = D_i + \lambda C_i$ for some predefined $\lambda \in \Rbb$) 
	\item Suspension-aware variations of EDF (SAEDF)\\($\Pi_i = D_i + \lambda S_i$ for some predefined $\lambda \in \Rbb$) 
	\item First-In-First-Out (FIFO) ($\Pi_i = 0$)
\end{itemize}
As a result, the schedulability test that we present in Section~\ref{sec:test} is applicable to all these scheduling algorithms by configuring the relative priority points $\Pi_i$ accordingly.

Moreover, Task-Level Fixed-Priority (TFP) algorithms can be treated as EL scheduling algorithms as well.
For this purpose, we assume that the tasks are ordered by their priorities, i.e., $\tau_k$ has higher priority than $\tau_{k'}$ if and only if $k<k'$, and $\tau_1$ has the highest priority.
Furthermore, we assume that a worst-case response time upper bound $K_j$ for each task either for the schedule under EL scheduling or under TFP scheduling is given.
If we set the relative priority point of each task $\tau_i$ to $\Pi_i = \sum_{j=1}^{i} K_j$, then EL and TFP coincide.
Please note that the response time 
of tasks may be unbounded and that for such cases a TFP algorithm cannot be treated as EL scheduling algorithm.
However, these cases do not apply in practical scenarios since in real-time systems it is required that the jobs of all tasks finish until their deadline.

\begin{prop}[TFP as EL.]\label{prop:TFPasEL}
	Let $K_1, \dots, K_n \in \Rbb_{\geq 0}$ and $\Pi_i := \sum_{j=1}^{i} K_j$ for $i=1,\dots, n$.
	If for all $j=1,\dots, n$ the value $K_j$ is an upper bound on the worst-case response time of $\tau_j$ in EL or in TFP, then the schedule of $\Tbb$ under EL and the schedule of $\Tbb$ under TFP coincide.
\end{prop}

\begin{proof}
	For an indirect proof we assume that the schedule of $\Tbb$ under EL and TFP does not coincide.
	Let $\tau_{k,\ell}$ be the job with the highest priority in the EL schedule, such that the schedule of $\tau_{k,\ell}$ does not coincide under EL and TFP.
	We define the interval 
	\begin{equation}
		I := [r_{k,\ell}, r_{k,\ell} + K_k).
	\end{equation}
	Let $\Jbb_{\TFP}$ and $\Jbb_{\EL}$ be the set of jobs with higher priority than $\tau_{k,\ell}$ under TFP and under EL that are executed during $I$.
	We will reach a contradiction by showing that $\Jbb_{\TFP}=\Jbb_{\EL}$ and that further the schedule of the jobs in $\Jbb_{\TFP}=\Jbb_{\TFP}$ coincides under TFP and under EL scheduling.
	For that purpose we partition the job sets into three subsets
	$\Jbb_{\TFP} = \coprod_{i \in \setof{+, -, 0}} \Jbb_{\TFP}^i$ and
	$\Jbb_{\EL} = \coprod_{i \in \setof{+, -, 0}} \Jbb_{\EL}^i$,
%	\begin{align}
%		\Jbb_{\TFP} = \coprod_{i \in \setof{+, -, 0}} \Jbb_{\TFP}^i
%		&&\Jbb_{\EL} = \coprod_{i \in \setof{+, -, 0}} \Jbb_{\EL}^i
%	\end{align}
	where each of them denotes the subset of jobs released by tasks of $\Tbb_{+} = \setof{\tau_{k+1}, \dots, \tau_n}$, $\Tbb_{-} = \setof{\tau_1, \dots, \tau_{k-1}}$ or $\Tbb_{0} = \setof{\tau_k}$.
	In the following we show that $\Jbb_{\TFP}^i = \Jbb_{\EL}^i$ for all $i \in \setof{+,-,0}$.

	\paragraph{$\Jbb_{\TFP}^+ = \Jbb_{\EL}^+$}
%	We start with the jobs released by tasks $\Tbb_{+} = \setof{\tau_{k+1}, \dots, \tau_n}$.
	Under TFP, there are no jobs of $\Tbb_{+}$ with higher priority than $\tau_{k,\ell}$, i.e., $\Jbb_{\TFP}^+ = \emptyset$.
%	 since all of those jobs have lower priority than $\tau_{k,\ell}$.
	Under EL, we choose any job $\tau_{i,j}$, with $\tau_i \in \Tbb_{+}$, that has higher priority than $\tau_{k,\ell}$, i.e., $\pi_{i,j}=r_{i,j} + \Pi_i \leq \pi_{k,\ell} = r_{k,\ell} + \Pi_k$ holds.
	By subtracting $\Pi_k$ we obtain
	\begin{equation}\label{eq:pf_prop_TFPasEL_1}
	 	r_{i,j} + K_i \leq r_{i,j} + (\Pi_i-\Pi_k) \leq r_{k,\ell}.
	\end{equation}
 	Since $\tau_{i,j}$ has higher priority than $\tau_{k,\ell}$, by assumption the schedule of $\tau_{i,j}$ coincides under EL and TFP, and we have $f_{i,j} \leq r_{i,j} + K_i$.
 	With Equation~\eqref{eq:pf_prop_TFPasEL_1} we conclude $f_{i,j} \leq r_{k,\ell}$.
 	In particular, the job $\tau_{i,j}$ is not executed during $I$.
 	Since $\tau_{i,j}$ was chosen arbitrarily, this means that $\Jbb_{\EL}^+ = \emptyset$ as well.

 	\paragraph{$\Jbb_{\TFP}^- = \Jbb_{\EL}^-$}
 	Under TFP and under EL, jobs of the tasks in $\Tbb_{-}$ %= \setof{\tau_1, \dots, \tau_{k-1}}$ 
 	can only be executed during $I$ if they are released before $r_{k,\ell} + K_k$, 
 	i.e., let $\tilde{\Jbb}^-$ be the set of jobs released before $r_{k,\ell} + K_k$ by tasks of $\Tbb_{-}$ then 
 	$\Jbb_{\TFP}^-, \Jbb_{\EL}^- \subseteq \tilde{\Jbb}^-$.
 	Under TFP, all jobs in $\tilde{\Jbb}^-$ have higher priority than $\tau_{k,\ell}$ since they are released by the tasks of $\Tbb_{-}$.
 	Under EL, we show the same:
% 	need to show that all jobs in $\tilde{\Jbb}^-$ have higher priority than $\tau_{k,\ell}$ as well since in that case by assumption the schedule of these jobs coincides and the same jobs are executed during $I$ under EL and TFP.
 	Let $\tau_{i,j} \in \tilde{\Jbb}^-$, i.e., $r_{i,j} < r_{k,\ell} + K_k$.
 	It directly follows that
 	\begin{equation}
 		\pi_{i,j} = r_{i,j} + \Pi_i 
 		< r_{k,\ell} + K_k + \Pi_i
 		\leq r_{k,\ell} + \Pi_k = \pi_{k,\ell}.
 	\end{equation}
	In particular, $\tau_{i,j}$ has higher priority than $\tau_{k,\ell}$.
	We have shown that all jobs in $\tilde{\Jbb}^-$ have higher priority than $\tau_{k,\ell}$ under EL and under TFP scheduling.
	By assumption the schedule of the jobs in $\tilde{\Jbb}^-$ coincides under TFP and EL.
	Therefore the same jobs of $\tilde{\Jbb}^-$ executed during $I$ under TFP and EL, i.e., $\Jbb_{\TFP}^- = \Jbb_{\EL}^-$.

	\paragraph{$\Jbb_{\TFP}^0 = \Jbb_{\EL}^0$}
	Under TFP and under EL, $\tilde{\Jbb}^0 := \setof{\tau_{k,1}, \dots, \tau_{k,\ell-1}}$ are the jobs of $\tau_k$ that have higher priority than $\tau_{k,\ell}$, i.e., $\Jbb_{\TFP}^0, \Jbb_{\EL}^0 \subseteq \tilde{\Jbb}^0$.
	By assumption, the schedule of the jobs in $\tilde{\Jbb}^0$ coincides.
	Therefore the same jobs of $\tilde{\Jbb}^0$ are executed during $I$, i.e., we have $\Jbb_{\TFP}^0 = \Jbb_{\EL}^0$.

	We have shown that $\Jbb_{\TFP}=\Jbb_{\EL}$ by the above discussion.
	Since the schedule of the jobs $\Jbb_{\TFP}=\Jbb_{\EL}$ coincides during $I$, $\tau_{k,\ell}$ is preempted/blocked during the same time intervals under TFP and EL scheduling during $I$.
	Hence, the schedule of $\tau_{k,\ell}$ during $I$ coincides.
	Furthermore, since by assumption $K_k$ is an upper bound on the response time under EL or TFP scheduling, the job $\tau_{k,\ell}$ finishes during $I$.
	This proves that the whole schedule of $\tau_{k,\ell}$ coincides.
