	\begin{defn}\label{def:B_interferences}
		Let $[c,d)$ be any half opened interval with $c<d$.
		\begin{itemize}
			\item $\Btilde_k(c,d)$ denotes the amount of time during $[c,d)$ where the processor is in state \textbf{PS~1}.
			\item $B_k(c,d)$ is the amount of time during $[c,d)$ in \textbf{PS~2}.
			\item For $i \neq k$, $B_k^i(c,d)$ is the amount of time during $[c,d)$ where the processor is in \textbf{PS~3} working on $\tau_i$.
			More specifically, $\sum_{i\neq k}B_k^i(c,d)$ is the total time during $[c,d)$ in \textbf{PS~3}.
		\end{itemize}
		If $c\geq d$, we set all of them, $\Btilde_k(c,d), B_k(c,d), B_k^i(c,d)$, to $0$.
	\end{defn}

	The definitions are collected in Table~\ref{table:summary_notation}.
	In the following Lemma, the result from Lemma~\ref{lem:processor_states} is formalized using the previous notation.
	The time in PS~1, PS~2 and PS~3 during some interval $[c,d)$ adds up to the whole interval length.

	\begin{lem}\label{lem:distribution_ps_with_b}
		For any half opened interval $[c,d)$ with $c<d$ we have
		\begin{equation}
			\Btilde_k(c,d) + B_k(c,d) + \sum_{i \neq k} B^i_k(c,d) =(d-c).
		\end{equation}
	\end{lem}

	\begin{proof}
		This follows from Lemma~\ref{lem:processor_states}.
	\end{proof}


	For analysis of the worst-case response time, the terms $B_k(c,d)$ and $B^i_k(c,d)$ are inconvenient because at each time, the \emph{current} job of $\tau_k$ has to be determined to calculate those values.
	In the following, we prove that they can be expressed by the more convenient terms $B_{k,\ell}^i(c,d)$ and $B_{k,\ell}(c,d)$ which take a specific job $\tau_{k,\ell}$ as current job into consideration.

	\begin{defn}\label{def:B_interferences_refinement}
		Let $[c,d)$ with $c<d$ be any half opened interval.
		\begin{itemize}
			\item $B_{k,\ell}^i(c,d)$ is the amount of time during $[c,d)$ that the processor is working on jobs of $\tau_i$ with higher priority than $\tau_{k,\ell}$.
			\item $B_{k,\ell}(c,d)$ is the amount of time during $[c,d)$ that the processor is working on or suspended by $\tau_{k,\ell}$ while it is not working on a higher-priority job.
		\end{itemize}
		If $c\geq d$, we set all of them to $0$ for simplicity.
	\end{defn}

