	Again, the definition is summarized in Table~\ref{table:summary_notation}.
	In Lemma~\ref{lem:refinement_Bk} and~\ref{lem:refinement_Bik} we will prove the relations between the terms from Definition~\ref{def:B_interferences_refinement} and Definition~\ref{def:B_interferences} as summarized in Figure~\ref{fig:relations_from_lemmas}.

	Intuitively, the following lemma states that we can compute the total time in PS~2, by adding up the time in PS~2 for all possible current jobs $\tau_{k,j}$.

	\begin{lem}\label{lem:refinement_Bk}
		For any half opened interval $[c,d)$ we have
		\begin{equation}
			B_k(c,d) = \sum_{j \in \Nbb} B_{k,j}(c,d).
		\end{equation}
	\end{lem}
	\begin{proof}
		The lemma follows from the equivalence between: 1)~the processor is in PS~2 and 
		2)~the processor is \emph{working on or suspended by some job of $\tau_k$ while it is not working on higher-priority jobs}.

		Since the processor is work-conserving, we obtain an equivalence between 1) and \emph{the processor is working on or suspended by the current job of $\tau_k$ while it is not working on a higher-priority job}.
		%
		By the definition of the current job, if the processor is working on or suspended by a job, then this is the current job by default. 
		This concludes the equivalence between 1) and 2).

		By definition, the time of 1) during $[c,d)$ is $B_k(c,d)$, and the time of 2) during $[c,d)$ is $\sum_{j \in \Nbb} B_{k,j}(c,d)$.
	\end{proof}

	In the subsequent lemma, we approximate the time in PS~3 by determining the current job of $\tau_k$ at the end of the analysis window $[c,d)$.
	More specifically, we use that if a job of $\tau_i$ has higher priority than the current job of $\tau_k$ in the analysis window, then it has higher priority than the last current job in the analysis window as well.

	\begin{lem}\label{lem:refinement_Bik}
		Consider any half opened interval $[c,d)$.
		If $\tau_{k,\ell}$ is the current job of $\tau_k$ during the whole interval $[c,d)$, then
		\begin{equation}
			B^i_k(c,d) = B^i_{k,\ell}(c,d).
		\end{equation}
		If $\tau_{k,\ell}$ is the current job of $\tau_k$ during $[d-\eps, d)$ for some $\eps >0$, then
		\begin{equation}
			B^i_k(c,d) \leq B^i_{k,\ell}(c,d).
		\end{equation}
	\end{lem}
	\begin{proof}
		By definition, $B^i_k(c,d)$ is the amount of time during $[c,d)$ that the processor is working on a job of $\tau_i$ with higher priority than the current job of $\tau_k$.
		If $\tau_{k,\ell}$ is the current job of $\tau_k$ during the whole interval, then $B^i_k(c,d) = B^i_{k,\ell}(c,d)$.
		If $\tau_{k,\ell}$ is current during $[d-\eps,d)$, then any job of $\tau_k$ which is current at some time during $[c,d)$ has a priority higher than or equal to the priority of $\tau_{k,\ell}$.
		If the processor is working on a job of $\tau_i$ with higher priority than the current job of $\tau_k$ at that time, then that job of $\tau_i$ has also higher priority than $\tau_{k,\ell}$.
		As a result, $B^i_k(c,d) \leq B^i_{k,\ell}(c,d)$. 
	\end{proof}

	By definition, $B_k^i$, $B_k$, $\widetilde{B}_k$, $B_{k,\ell}^i$ and $B_{k,\ell}$ are \emph{non-negative} and \emph{additive}, in the sense that $B(c,d)\geq 0$ and $B(c, d) + B(d,e) = B(c,e)$ for all $B \in \{B_k^i, B_{k}, \widetilde{B}_k, B_{k,\ell}^i, B_{k, \ell}\}$ and $c\leq d \leq e$.
	%
	The following two lemmas build a bridge between the processor state formulation and the ability of a job $\tau_{k,\ell}$ to be finished by the end of the analysis window $[c,d)$.

	\begin{lem}\label{lem:Bkl_finished}
%		Consider an interval $[c,d)$.
		If $B_{k,\ell}(c,d) \geq C_k + S_k$, then the job $\tau_{k,\ell}$ is finished by time $d$.
	\end{lem}
	\begin{proof}
		Since $B_{k,\ell}(c,d) \geq C_k + S_k$, the processor is working on the job $\tau_{k,\ell}$ for at least $C_k$ time units during $[c,d)$.
		As a result, the job finishes no later than at time $d$.
	\end{proof}

	\begin{lem}\label{lem:non-sched}
		Consider some interval $[c,d)$ with $c\leq d$.
		If $\tau_{k,\ell}$ is not finished by time d and the task $\tau_k$ is active during (the whole interval) $[c,d)$, then 
		\begin{equation}
			(C_k+S_k) + \sum_{i \neq k} B^i_{k,\ell}(c,d) + \sum_{j < \ell} B_{k,j}(c,d) > (d-c).
		\end{equation}
	\end{lem}

	\begin{proof}
		Since $\tau_k$ is active during $[c,d)$, we have $\Btilde_k(c,d) = 0$.
		Using this together with Lemma~\ref{lem:distribution_ps_with_b} and Lemma~\ref{lem:refinement_Bk} leads to $\sum_{i\neq k} B^i_k(c,d) + \sum_{j\in\Nbb} B_{k,j}(c,d) = (d-c)$.
%		\begin{equation}
%			 \sum_{i\neq k} B^i_k(c,d) + \sum_{j\in\Nbb} B_{k,j}(c,d) = (d-c).
%		\end{equation}
		We prove the lemma by showing that 
%		1) $\sum_{j \in \Nbb} B_{k,j}(c,d) < C_k+S_k + \sum_{j < \ell} B_{k,j}(c,d)$ and 2) $B^i_k(c,d)\leq B^i_{k,\ell}(c,d)$ for all $i\neq k$.
		\begin{enumerate}
			\item $\sum_{j \in \Nbb} B_{k,j}(c,d) < C_k+S_k + \sum_{j < \ell} B_{k,j}(c,d)$ and
			\item $B^i_k(c,d)\leq B^i_{k,\ell}(c,d)$ for all $i\neq k$.
		\end{enumerate}

		First, we prove 1). 
		Since $\tau_{k,\ell}$ is not finished by time $d$, we know that all $\tau_{k,j}$ with $j>\ell$ are not current before $d$.
		Hence, $B_{k,j}(c,d) = 0$ for all $j > \ell$ and $\sum_{j \in \Nbb} B_{k,j}(c,d) = \sum_{j \leq \ell} B_{k,j}(c,d)$.
		Moreover, due to Lemma~\ref{lem:Bkl_finished}, we have $B_{k,\ell}(c,d) < C_k+S_k$.
		This proves 1).

		Second, we prove 2).
		Since $\tau_{k}$ is active during $[c,d)$, by definition, at any time instant $t \in [c, d)$, there is always a job of $\tau_k$, which is current. Let the last job of $\tau_k$ that is current in this interval be $\tau_{k,\ell'}$. That is, there exists some $\eps >0$ such that $\tau_{k,\ell'}$ is current during $[d-\eps,d)$.  By Lemma~\ref{lem:refinement_Bik}, we have $B^i_k(c,d) \leq B^i_{k,\ell'}(c,d)$ for all $i\neq k$.

        According to the handling mechanism to deal with multiple
        active jobs of $\tau_k$ (for arbitrary-deadline task systems) at the end of Section~\ref{sec:system_model}, the jobs of
        $\tau_k$ are executed one after another. Since
        $\tau_{k,\ell'}$ is current in $[d-\eps,d)$, the job
        $\tau_{k,\ell}$ can not have higher priority than
        $\tau_{k, \ell'}$, i.e., $\ell' \leq \ell$ holds.
        Otherwise,
        $\tau_{k,\ell}$ has to be finished by time $d-\eps$.
        Therefore, $B^i_{k,\ell'}(c,d) \leq B^i_{k,\ell}(c,d)$ for all
        $i\neq k$. 
        We conclude that 2) holds.
	\end{proof}

	The negation of this lemma leads to a response-time upper bound of $\tau_{k,\ell}$ introduced by Proposition~\ref{prop:backbone_prep} and Corollary~\ref{cor:backbone}.

	\begin{prop}\label{prop:backbone_prep}
      Let $c\leq d \in \Rbb$ such that either 1) $\tau_{k,\ell}$ is
      released before $c$, i.e., $c \geq r_{k,\ell}$, or 2)~$c < r_{k,\ell}$ and task $\tau_k$ is active during
        $[c,r_{k,\ell})$. If
		\begin{equation}\label{eq:prop:backbone_prep}
			(C_k+ S_k) + \sum_{i \neq k} B^i_{k,\ell}(c,d) + \sum_{j < \ell} B_{k,j}(c,d) \leq (d-c),
		\end{equation}
		then $\tau_{k,\ell}$ is finished by time $d$, i.e., $d \geq f_{k,\ell}$.
	\end{prop}

	\begin{proof}
		We use an indirect proof strategy and assume that $\tau_{k,\ell}$ is not finished by time $d$.
		In this case, $\tau_{k,\ell}$ is active during $[r_{k,\ell},d)$.
		Since $r_{k,\ell}\leq c$ or $\tau_k$ is active during $[c,r_{k,\ell})$, we conclude that $\tau_k$ is also active during $[c,d)$.
		Lemma~\ref{lem:non-sched} states that Equation~\eqref{eq:prop:backbone_prep} does not hold.
		This contradicts our assumption.
	\end{proof}

	In Section~\ref{sec:estimation_B} we obtain the upper bounds for $B^i_{k,\ell}(c,d)$ and $B_{k,j}(c,d)$ by enlarging the window of interest to $[c, d_{k,\ell})$.
	To apply these upper bounds we formulate the response-time upper bound using $B^i_{k,\ell}(c, d_{k,\ell})$ and $B_{k,j}(c, d_{k,\ell})$ in the following corollary.

	\begin{cor}[Analysis Backbone]\label{cor:backbone}
    Let $c\leq d_{k,\ell} \in \Rbb$ such that either 1)~$\tau_{k,\ell}$ is
    released before $c$, i.e., $c \geq r_{k,\ell}$ or 2)~$c < r_{k,\ell}$ and task $\tau_k$ is active during
        $[c,r_{k,\ell})$.
		If 
		\begin{equation}\label{eq:cor_sched_test}
			\Rtilde_{k,\ell} \!:=\!
			(C_k+ S_k) + \!\sum_{i \neq k}\! B^i_{k,\ell}(c,d_{k,\ell}) + \!\sum_{j < \ell}\! B_{k,j}(c,d_{k,\ell}) + c - r_{k,\ell},
		\end{equation}
		is at most $D_k$, then $\Rtilde_{k,\ell}$ is an upper bound on the response time of $\tau_{k,\ell}$.
	\end{cor}

	\begin{proof}
		This corollary follows from Proposition~\ref{prop:backbone_prep} by setting $d:=r_{k,\ell} + \Rtilde_{k,\ell}$.
		The case $c>d$ does not occur since otherwise $\Rtilde_{k,\ell} \geq  c-r_{k,\ell} > \Rtilde_{k,\ell}$ would hold by definition of $\Rtilde_{k,\ell}$ and $d$.
		We only consider $c \leq d$.

		Since $\Rtilde_{k,\ell} \leq D_k$ by assumption, we have $d\leq d_{k,\ell}$.
		Hence, $B^i_{k,\ell}(c,d)\leq B^i_{k,\ell}(c,d_{k,\ell})$ and $B_{k,j}(c,d) \leq B_{k,j}(c,d_{k,\ell})$ for all $i$ and all $j$.
		As a result, the left hand side of Equation~\eqref{eq:prop:backbone_prep} is less than or equal to $(C_k+ S_k) + \sum_{i \neq k} B^i_{k,\ell}(c,d_{k,\ell}) + \sum_{j < \ell} B_{k,j}(c,d_{k,\ell})$, which is the same as $\Rtilde_{k,\ell} + r_{k,\ell} - c = d-c$ by definition.

		Since all assumptions from Proposition~\ref{prop:backbone_prep} hold, the job $\tau_{k,\ell}$ is finished by time $d=\Rtilde_{k,\ell} + r_{k,\ell}$.
		Hence, $\Rtilde_{k,\ell}$ is an upper bound on the response time of $\tau_{k,\ell}$.
	\end{proof}

	To apply the response time upper bound from Equation~\eqref{eq:cor_sched_test} we need to answer the following two questions:
	\begin{itemize}
		\item \textbf{Question~1:} What are the values of $B^i_{k,\ell}(c,d_{k,\ell})$ and $B_{k,j}(c,d_{k,\ell})$?
		Since computing the values directly has high complexity, we use overapproximation to deal with this issue.
		In Section~\ref{sec:estimation_B} we derive upper bounds for $B^i_{k,\ell}(c,d_{k,\ell})$ and $B_{k,j}(c,d_{k,\ell})$ with $i\neq k$ and $j<\ell$.
		\item \textbf{Question~2:} Which are good values for $c$?
		Trying out all possible $c$ for the estimation would lead to very high complexity of our method.
		Therefore, we discuss two strategies to choose $c$ in Sections~\ref{sec:test_fixed} and~\ref{sec:test_arb}.
		More precisely, with the first procedure we restrict $c$ to be in the interval $[r_{k\ell}, d_{k,\ell})$, which has benefits on the runtime of our analysis due to the \emph{fixed analysis windows}.
		For the second strategy, we examine \emph{active intervals} for $\tau_k$, and gradually increase the analysis window.
		In Section~\ref{sec:dominance} we discuss that both methods do not dominate each other.
	\end{itemize}

	\subsection{Upper Bounds of $B^i_{k,\ell}(c,d_{k,\ell})$ and $B_{k,j}(c,d_{k,\ell})$}
	\label{sec:estimation_B}

	In this section, we bound the interference of higher-priority jobs during the interval $[c,d_{k,\ell})$ to provide upper bounds
	for $\sum_{j < \ell} B_{k,j}(c,d_{k,\ell})$ in Lemma~\ref{lem:upper_bound_sum_Bkj} and for $B_{k,\ell}^i(c, d_{k,\ell})$ in Lemma~\ref{lem:total_bound_interference}.
	We do this under the assumption that all jobs with higher priority than $\tau_{k,\ell}$ meet their deadline, since this is our induction hypothesis later used in Theorem~\ref{thm:suff_sched_test_fixed} and Lemma~\ref{lem:suff_sched_test_var_prep}.
	As mentioned earlier, the decision of $c$ will be further discussed in Sections~\ref{sec:test_fixed}~and~\ref{sec:test_arb}.
	%
	For each task $\tau_i \neq \tau_k$ let $\Rtilde_i$ be an upper bound on the worst-case response time (WCRT) of jobs of $\tau_i$ with higher priority than $\tau_{k,\ell}$.
	If there is no upper bound available yet, we set $\Rtilde_i := D_i$, as all jobs with higher priority than $\tau_{k,\ell}$ meet their deadline.

	With arbitrary deadlines, there might be several active jobs of one task at the same time, which makes the analysis in general more complicated.
	Note that, according to the mechanism introduced in the end of Section~\ref{sec:system_model}, the jobs of $\tau_k$ must be executed one after another, i.e., even if the processor idles, a job of $\tau_k$ cannot start its execution unless all jobs of $\tau_k$ released prior to it are finished.

	\begin{lem}\label{lem:number_active_jobs}
		The number of jobs of $\tau_k$ with higher priority than $\tau_{k,\ell}$ which can be executed during $[c,d_{k,\ell})$ is upper bounded by $\ceiling{\frac{d_{k,\ell}-c}{T_k}}-1$.
	\end{lem}

	\begin{proof}
		The formula $\ceiling{\frac{d_{k,\ell}-c}{T_k}}$ counts the maximal number of deadlines of $\tau_k$ in $(c,d_{k,\ell}]$. Since $\tau_{k,\ell}$ has deadline at the end of the analysis window but it has no higher priority than itself, we remove one job.
	\end{proof}

	We use the previous lemma to conclude an upper bound for $\sum_{j < \ell} B_{k,j}(c,d_{k,\ell})$ as follows.

	\begin{lem}[Bound~B1]\label{lem:upper_bound_sum_Bkj}
		The total amount of time that the processor is working on or suspended by higher-priority jobs of $\tau_k$ while not working on higher priority jobs of other tasks is upper bounded by
		\begin{equation}
			\sum_{j < \ell} B_{k,j}(c,d_{k,\ell}) \leq \left(\ceiling{\frac{d_{k,\ell}-c}{T_k}}-1\right) \cdot (C_k+S_k).
		\end{equation}
	\end{lem}
	\begin{proof}
		This follows from Lemma~\ref{lem:number_active_jobs} and the upper bounds $C_k$ for execution and $S_k$ for suspension. 
	\end{proof}

