	For $B^i_{k,\ell}$, we bound the interference by estimating the number of job releases during a certain interval under analysis, as depicted by the gray boxes in Figure~\ref{fig:intuition}.

	\begin{lem}\label{lem:ineqk_1}
		There are at most $\max\left(\ceiling{\frac{\Pi_k-\Pi_i+\Rtilde_i+r_{k,\ell}-c}{T_i}}, 0\right)$ jobs of $\tau_i,~i\neq k$ with higher priority than $\tau_{k,\ell}$ that are executed during the interval $[c, d_{k,\ell})$.
	\end{lem}

	\begin{proof}
		A job of $\tau_i$ can only be executed during $[c,d_{k,\ell})$, if it is released after $c-\Rtilde_i$.
		Moreover, it can have higher priority than $\tau_{k,\ell}$, if it is released no later than $r_{k,\ell} + \Pi_k - \Pi_i$.
		We count the maximal number of releases of $\tau_i$ during $(c-\Rtilde_i, r_{k,\ell} + \Pi_k - \Pi_i)$ by $\ceiling{\frac{r_{k,\ell} + \Pi_k - \Pi_i - c + \Rtilde_i}{T_i}}$ if the interval has non-negative length.
		Otherwise, the number of releases is $0$.
	\end{proof}

	The processor is working on each job of $\tau_i$ for at most $C_i$ time units.
	Hence, we have an upper bound of $B_{k,\ell}^i(c,d_{k,\ell}) \leq \max\left(\ceiling{\frac{\Pi_k-\Pi_i+\Rtilde_i+r_{k,\ell}-c}{T_i}}, 0\right) \cdot C_i$.
	In the above proof we only compare if the job can work \emph{after} $c$.
	We do not check if the job can work \emph{before} $d_{k,\ell}$.
	As a result, the estimation can become very loose if $\Pi_k$ is very high compared to $\Pi_i$, e.g., when applying the schedulability test to TFP scheduling.
	Therefore, we combine the estimation with a second approach.

	\begin{lem}\label{lem:ineqk_2}
		For $i\neq k$,  $B_{k,\ell}^i(c,d_{k,\ell})$ is upper bounded
        by
        $\max\left\{\ceiling{\frac{D_k-C_i+r_{k,\ell}-c+\Rtilde_i}{T_i}}C_i, 0\right\}$.
	\end{lem}

	Intuitively, the maximal interference from task $\tau_i$ is obtained when the \emph{last} interfering job of $\tau_i$ is released at $d_{k,\ell}-C_i$ and executed for $C_i$ time units during $[d_{k,\ell}-C_i, d_{k,\ell})$.
	The maximum interference is then calculated by the number of releases during $(c-\Rtilde_i, d_{k,\ell}-C_i]$ multiplied with $C_i$.
	In the following, we provide a formal proof as well.

	\begin{proof}
		If there is no job of $\tau_i$ executed during $[c,d_{k,\ell})$, then $B^i_{k,\ell}(c,d_{k,\ell})=0$ and the lemma is proven.

		Otherwise, let $\tau_{i,j'}$ be the last job of $\tau_i$ being executed during $[c,d_{k,\ell})$.
		We isolate that job in the following way.
		Let $r_{i,j'}$ be the release time of $\tau_{i,j'}$ and let $C^*$ be the amount of time that the processor is working on $\tau_{i,j'}$ during the interval $[c,d_{k,\ell})$.
		We have $B(c,d_{k,\ell}) \leq B(c,r_{i,j'}) + C^*.$
%		\begin{equation}
%			B(c,d_{k,\ell}) \leq B(c,r_{i,j'}) + C^*.
%		\end{equation}

		If $r_{i,j'}-c < (C-C^*)$, then $B(c,r_{i,j'}) + C^* \leq C$.
		Moreover, $\ceiling{\frac{D_k-C_i+r_{k,\ell}-c+\Rtilde_i}{T_i}}C_i \geq \ceiling{\frac{D_k+r_{k,\ell}-c}{T_i}}C_i \geq C_i$ since there is a job being executed during $[c, d_{k,\ell})$, i.e., $c < D_k+r_{k,\ell}$.
		In this case the lemma is proven.

		If $r_{i,j'}-c \geq (C-C^*)$, then $B(c,r_{i,j'}) + C^* \leq B(c + (C_i-C^*),r_{i,j'}) + C_i$, i.e., we over approximate be replacing $(C_i-C^*)$ time units at the beginning by execution time.
		Next we compute $B(c + (C_i-C^*),r_{i,j'})$ by counting the number of releases during the interval $(c+(C_i-C^*)-\Rtilde_i, r_{i,j'}-T_i]$.
		It is 
%		\begin{equation}
		$
			\ceiling{\frac{r_{i,j'}-T_i-c-C_i+C*+\Rtilde_i}{T_i}} 
			\leq \ceiling{\frac{r_{k,\ell}-T_i-c-C_i+D_k+\Rtilde_i}{T_i}}
			= \ceiling{\frac{r_{k,\ell}-c-C_i+D_k+\Rtilde_i}{T_i}} -1
		$
%		\end{equation}
		where we use that $r_{i,j'} + C^* \leq r_{k,\ell} + D_k$.
		In total, the value of $B(c,d_{k,\ell})$ is then upper bounded by $\ceiling{\frac{r_{k,\ell}-c-C_i+D_k+\Rtilde_i}{T_i}} \cdot C_i$ in this case.
	\end{proof}

	We combine the above two lemmas, to obtain the following bound for $B_{k,\ell}^i(c,d_{k,\ell})$.

	\begin{lem}[Bound~B2]\label{lem:total_bound_interference}
		For $i\neq k$ the value of  $B_{k,\ell}^i(c,d_{k,\ell})$ is upper bounded by
		\begin{equation}\label{eq:total_bound_interference}
			B_{k,\ell}^i (c,d_{k,\ell}) \leq
				\max\left(\ceiling{\frac{G_{k}^i+\Rtilde_i+r_{k,\ell}-c}{T_i}}, 0\right)C_i
		\end{equation}
		where $G_k^i:= \min(D_k-C_i, \Pi_k-\Pi_i)$.
	\end{lem}

	\begin{proof}
		This is a combination of the results from Lemma~\ref{lem:ineqk_1} and Lemma~\ref{lem:ineqk_2}.
	\end{proof}

	\subsection{Fixed Analysis Window}
\label{sec:test_fixed}	
	\begin{algorithm}[t]
		\small
		%\footnotesize
		%\scriptsize
		\caption{Schedulability test with fixed analysis window.}
		\label{alg:sched_test_fixed}
		\begin{algorithmic}[1]
			\item[] \textbf{Input:} $\Tbb = \{\tau_1,\dots,\tau_n\}$, $(\Pi_1,\dots,\Pi_n)$, $\eta$, $depth$
			\item[] \textbf{Output:} True: schedulable, False: no decision
			\item[]

			\State Order $\tau_1 ,\dots,\tau_n$, s.th. $D_1\geq \dots \geq D_n$.
			\State Set $\Rtilde_i := D_i$ for all $i$.

			\For{$i=1, 2, \dots, depth$}
			\State $solved := True$
			\For{$k = 1, 2, \dots,n$}
			\State $cand := [~]$; $step := \eta \cdot {D_k}$
			\Comment{Preparation.}
			\For{$b = 0, step, 2\cdot step, \cdots < D_k$}
			\Comment{Compute.}
%			\Comment{Compute candidate.}
			\State $cand.append(\Rtilde_k(b))$ using Equation~\eqref{eq:suff_sched_test_fixed}.
			\EndFor
			\State $\Rtilde_k := \min\limits (cand)$
			\Comment{Compare candidates.}
			\If{$\Rtilde_k>D_k$} 
			\Comment{Check condition.}
%			\Comment{Check schedulability condition.}
			\State $solved := False$; $\Rtilde_k := D_k$; \textbf{break}
			\EndIf
			\EndFor
			\EndFor
			\State \Return $solved$
		\end{algorithmic}
	\end{algorithm}

	In this section, we fix the analysis window, i.e., the possible range of $c$ from the previous sections, to the interval $[r_{k,\ell}, d_{k,\ell})$.
	First, we utilize the upper bounds on $B^i_{k,\ell}(c,d_{k,\ell})$ and $B_{k,j}(c,d_{k,\ell})$ provided in the previous section, to obtain the following schedulability test for this scenario with fixed analysis interval.

	\begin{thm}[Sufficient Schedulability Test]\label{thm:suff_sched_test_fixed}
		Let $\Tbb = \{\tau_1,\dots.\tau_n\}$ be an arbitrary-deadline task set with relative priority points $(\Pi_1, \dots, \Pi_n)$.
		If for all $k=1, \dots, n$ there exists some $b_k \in [0,D_k)$ such that
		\begin{equation}\label{eq:suff_sched_test_fixed}
%			\footnotesize{}
			\Rtilde_k(b_k)
%			:=\ceiling{\frac{D_k-b_k}{T_k}}(C_k + S_k) + b_k + \sum\limits_{i\neq k} \max\left(\ceiling{\frac{G_k^i+ \Rtilde_i-b_k}{T_i}}, 0\right) C_i 
			\leq D_k,
		\end{equation}
		where $\Rtilde_k(b_k):=\ceiling{\frac{D_k-b_k}{T_k}}(C_k + S_k) + b_k + \sum\limits_{i\neq k} \max\left(\ceiling{\frac{G_k^i+ \Rtilde_i-b_k}{T_i}}, 0\right) C_i$
		and 
%		where $\Rtilde_k(b_k)$ is computed by  $\ceiling{\frac{D_k-b_k}{T_k}}(C_k + S_k) + b_k + \sum\limits_{i\neq k} \max\left(\ceiling{\frac{G_k^i+ \Rtilde_i-b_k}{T_i}}, 0\right) C_i$ and 
%		where
		$G^i_k = \min(D_k-C_i, \Pi_k-\Pi_i)$,
		then the task set is schedulable by EL scheduling with the given relative priority points and the worst-case response time of $\tau_k$ is upper bounded by $\Rtilde_k := \Rtilde_k(b_k)$.
	\end{thm}

	\begin{proof}
		Assume we have found $b_k,~k=1,\dots,n$ such that Equation~\eqref{eq:suff_sched_test_fixed} holds.
		We consider some schedule obtained by this task set and denote by $Seq$ the sequence of all jobs in the schedule ordered by their priority.
		Via induction, we prove that the first $\xi$ jobs in $Seq$ have the required response time upper bound, for all $\xi \in \Nbb_0$.
		Consequently, $\Rtilde_k$ is an upper bound on the worst-case response time of $\tau_k$ for all $k$ and the task set is schedulable.

		\textbf{Initial case:} $\xi = 0$.
		In this case, the set of the first $\xi$ jobs in $Seq$ is $\{\}$ the empty set.
		Trivially, all of them have the required response time upper bound.

		\textbf{Induction step:} $\xi \to \xi+1$.
		By assumption, the first $\xi$ jobs in $Seq$ have the required response time upper bound.
		We denote the $(\xi+1)$-th job in $Seq$ by $\tau_{k,\ell}$.
		We aim to use Corollary~\ref{cor:backbone} to prove that the response time of $\tau_{k,\ell}$ is upper bounded by $\Rtilde_k$.
		%
		By definition, we have $\Rtilde_{k,\ell} = (C_k+ S_k) + \sum_{i \neq k} B^i_{k,\ell}(c,d_{k,\ell}) + \sum_{j < \ell} B_{k,j}(c,d_{k,\ell}) + c - r_{k,\ell}$.
		Since all higher priority jobs have the required response time upper bound, we can use the estimation from Section~\ref{sec:estimation_B}.
		Using Lemma~\ref{lem:upper_bound_sum_Bkj} and Lemma~\ref{lem:total_bound_interference}, we obtain $\Rtilde_{k,\ell} \leq \Rtilde_k$ when choosing $c:= b_k+r_{k,\ell}$.
		Due to Equation~\eqref{eq:suff_sched_test_fixed}, even
		$\Rtilde_{k,\ell} \leq \Rtilde_k \leq D_k$.
%		\begin{equation}
%			\Rtilde_{k,\ell} \leq \Rtilde_k \leq D_k.
%		\end{equation}
		We use Corollary~\ref{cor:backbone} to conclude that $\Rtilde_{k,\ell}$ is an upper bound on the response time of $\tau_{k,\ell}$ and therefore $\Rtilde_k$ is an upper bound on the response time of $\tau_{k,\ell}$ as well.
	\end{proof}
    %
    Although the test in Theorem~\ref{thm:suff_sched_test_fixed} looks like a classical mechanism extended from time demand analysis (TDA)~\cite{joseph86responsetimes,lehoczky89}, implementing an efficient schedulability test based on it requires some efforts since the values of $\Rtilde_k$ for every task $\tau_k$ are dependent on each other. The critical part to apply this schedulability is two folded:
	\begin{enumerate}
		\item Find good values for $b_k$ with low complexity. Without an efficient mechanism, there are $D_k$ options for $b_k$, provided that all input parameters are integers, and infinitely many options in general.
		\item Compute the dependent values of $\Rtilde_k$ for every task $\tau_k$ correctly and efficiently.
	\end{enumerate}
    For $b_k$, we discretize the search space into $\frac{1}{\eta}$ values with a step size $\eta \cdot D_k$, for a user-specified parameter $\eta$. For computing $\Rtilde_k$, we go through the task set several times to compute upper bounds for the values of $\Rtilde_k$.
	%
	Improvement of the search algorithm will be part of future work and is out of scope for this paper.


	The search algorithm is depicted in pseudocode in Algorithm~\ref{alg:sched_test_fixed}.
	It takes as input the task set $\Tbb$, the relative priority points $(\Pi_1, \dots, \Pi_n)$, a step size parameter $\eta \in (0,1]$ and $depth$ to indicate the number improving runs of the search algorithm.
	It returns \emph{True} if the task set is schedulable by EL scheduling with the given relative priority points.
	We start by setting $\Rtilde_k = D_k$ for all $k=1, \dots, n$, and go $depth$-times through the task set ordered by the relative deadline, as we obtained the best results with this ordering.
	With  a step size of $step = \eta \cdot D_k$, i.e., a certain share of $D_k$ like $1$ percent, we compute $\Rtilde_k(b_k)$ for $b_k=0,step,2\cdot step, 3\cdot step, \dots$ until $b \geq D_k$ is reached.
	We then take the minimal value of all these candidates and define it as the new $\Rtilde_k$.
    The time complexity of Algorithm~\ref{alg:sched_test_fixed} is $\mathcal{O}\left(\frac{depth\cdot n^2}{\eta}\right)$.

	Please note that the computed values of $\Rtilde_k$ are in fact only upper bounds of $\Rtilde_k$ from Theorem~\ref{thm:suff_sched_test_fixed}.
	A reduction of $\Rtilde_i,~i\neq k$ in subsequent iterations reduces the actual value of $\Rtilde_k$ as well, since $\Rtilde_k$ is monotonically increasing with respect to $\Rtilde_i,$ for all $i\neq k$.


\subsection{Variable Analysis Window}
	\label{sec:test_arb}



	In the following, we show a different approach based on \emph{active intervals}.
	More specifically, if all jobs finish until the next job release is reached, i.e., $R_k \leq T_k$, then no previous jobs contribute interference to the job under analysis and they can be safely removed from the computation of the worst-case response-time upper bound.
	However, if $R_k > T_k$ then interference from previous jobs has to be considered in the following way.
	We utilize that a job $\tau_{k,\ell-a}$ can only interfere with $\tau_{k,\ell}$, if $\tau_k$ is active during $[r_{k,\ell-a}, r_{k,\ell})$.
	For the schedulability test with variable analysis window, we gradually increase the length of the active interval, i.e., $a = 0,1,2,\dots$ and analyze the window $[c,d_{k,\ell})$ with $c \in [r_{k,\ell-a}, d_{k,\ell})$.

	With this approach, the pessimism of the interference estimation from higher-priority jobs of the same task is reduced in some cases.
	Please note that this approach only differs from the case with fixed analysis window when considering arbitrary deadline tasks.
	For constrained deadline task sets, the variable analysis window approach coincides with the fixed analysis window approach, as the algorithm stops at $a=0$ without enlarging the analysis window.
	We start be formally defining active intervals.

	\begin{defn}\label{def:active_int}
		Let $a\in \Nbb_0$.
		A job $\tau_{k,\ell}$ is the $(a+1)$-th job in an \emph{active interval} of $\tau_k$, if the following two conditions hold.
		\begin{itemize}
			\item $\tau_k$ is active during $[r_{k,\ell-a},f_{k,\ell})$.
			\item At time $r_{k,\ell-a}$ there is no active job which is released \emph{before} $r_{k,\ell-a}$.
		\end{itemize}
	\end{defn}

	If $\tau_{k,\ell}$ is the $(a+1)$-th job in an active interval of $\tau_k$, then only $\tau_{k,\ell-a}, \dots, \tau_{k,\ell}$ are current jobs of $\tau_k$ during $[r_{k,\ell-a},f_{k,\ell})$.
	More specifically, in this case the value of $B_{k,j}(c,d_{k,\ell})$ is $0$ if $c \geq r_{k,\ell-a}$ and $j<\ell-a$. 
	We formalize this by the following lemma.

	\begin{lem}\label{lem:suff_sched_test_var_prep}
		Let $\tau_{k,\ell}$ be the $(a+1)$-th job in an active interval of $\tau_k$ and let all higher-priority jobs meet their deadline.
		Let $\Rtilde_i,~i\neq k$ be an upper bound on the response time of all higher-priority jobs of $\tau_i$.
		If there exists some $c \in [r_{k,\ell-a},d_{k,\ell})$ such that 
		\begin{equation}\label{eq:lem_var_window}
			\begin{aligned}
				&\min \left( a+1, \ceiling{\frac{d_{k,\ell}-c}{T_k}} \right) (C_k+S_k)
				\\&+ \sum_{i \neq k} \max\left( \ceiling{\frac{G^i_k+\Rtilde_i+r_{k,\ell}-c}{T_i}}, 0 \right) C_i
				+ c - r_{k,\ell}
			\end{aligned}
		\end{equation}
		is at most $D_k$,
		with $G^i_k := \min(D_k-C_i, \Pi_k-\Pi_i)$, then \eqref{eq:lem_var_window} is an upper bound on the response time of $\tau_{k,\ell}$.
	\end{lem}
	\begin{proof}
		For the proof, we apply Corollary~\ref{cor:backbone}.
		Since $\tau_{k,\ell}$ is the $(a+1)$-th job in an active interval, $\tau_k$ is active during $[r_{k,\ell-a}, r_{k,\ell})$.
		Hence, the restriction on $c$ in Corollary~\ref{cor:backbone} are fulfilled by default, when $c$ is chosen from $[r_{k,\ell-a}, d_{k,\ell})$.
		Moreover, since $\tau_{k,\ell}$ is the $(a+1)$-th job in an active interval, the jobs $\tau_{k,1}, \dots, \tau_{k,\ell-a-1}$ are finished by time $r_{k,\ell-a}$.
		We obtain $\sum_{j < \ell-a} B_{k,j} (c,d_{k,\ell}) \leq \sum_{j < \ell-a} B_{k,j} (r_{k,\ell-a},d_{k,\ell}) = 0$.
		Hence, 
%		\begin{equation}
		$
			\sum_{j < \ell} B_{k,j} (c,d_{k,\ell}) 
			= \sum_{j = \ell-a}^{\ell-1} B_{k,j} (c,d_{k,\ell})
			\leq \sum_{j = \ell-a}^{\ell-1} (C_k+S_k)
			= a\cdot (C_k+S_k).
%		\end{equation}
		$
		We combine this with the results from Lemma~\ref{lem:upper_bound_sum_Bkj} and Lemma~\ref{lem:total_bound_interference}, and obtain that $\Rtilde_{k,\ell}$ from Equation~\eqref{eq:cor_sched_test} is less than or equal to the value in Equation~\eqref{eq:lem_var_window}.
		If \eqref{eq:lem_var_window} is at most $D_k$, then $\Rtilde_{k,\ell}\leq D_k$.
		Corollary~\ref{cor:backbone} states that $\Rtilde_{k,\ell}$ is an upper bound on the response time of $r_{k,\ell}$ and therefore, also \eqref{eq:lem_var_window} is an upper bound on the response time.
	\end{proof}

	In the following theorem, we replace $r_{k,\ell}-c$ by $aT_k-x$.

	\begin{thm}[Sufficient Schedulability Test]\label{thm:suff_sched_test_var}
		Let $\Tbb=\{\tau_1, \dots, \tau_n\}$ be an arbitrary-deadline task set with relative priority points $(\Pi_1, \dots, \Pi_n)$.
		We define the function $\Rtilde^a_k : \Rbb_{\geq 0} \to \Rbb_{\geq 0}$ by the assignment 
		\begin{equation}\label{eq:thm:suff_sched_test_var}
		\begin{aligned}
		x \mapsto &\min\left(a+1, \ceiling{\frac{D_k-x+aT_k}{T_k}}\right)(C_k+S_k)
		\\&+ \sum_{i \neq k} \max \left( \ceiling{\frac{G^k_i + \Rtilde_i-x+aT_k}{T_i}},0 \right) C_i
		+ x-aT_k.
		\end{aligned}
		\end{equation}
		If for all $k=1,\dots,n$ there exists $\tilde a_k \in \Nbb_0$, such that for all $a = 0,\dots,\tilde a_k$ there exists $b^a_k \in [0,a T_k + D_k)$, such that 
		\begin{equation}
			\Rtilde^a_k(b^a_k) \leq D_k,
			\text{ and furthermore }
			\Rtilde^{\tilde a_k}_k(b^{\tilde a_k}_k) \leq T_k,
		\end{equation}
		then the task set is schedulable by EL scheduling with the given relative priority points and $\Rtilde_k := \max_{a = 0, \dots, \tilde a} \Rtilde^a_k(b^a_k)$ is an upper bound on the WCRT of $\tau_k$ for all $k$. 
	\end{thm}

	\begin{proof}
		The proof is similar to the one of Theorem~\ref{thm:suff_sched_test_fixed}.
		Let $Seq$ be the sequence of all jobs in the schedule ordered by their priority.
		By induction we show that the following response time upper bound holds for the first $\xi \in \Nbb_0$ jobs in $Seq$:
		\begin{enumerate}
			\item $\Rtilde_k$ for all jobs of $\tau_k$ for each task $\tau_k$.
			\item $T_k$ for all $\tilde a_k$-th jobs in an active interval of $\tau_k$ for each task $\tau_k$.
		\end{enumerate}

		\textbf{Initial case:} $\xi_0$. The initial case is again trivially fulfilled, since there has nothing to be checked when there are no jobs.

		\textbf{Induction step:} $\xi \to \xi+1$.
		The first $\xi$ jobs in $Seq$ have the required response time upper bounds 1) and 2) by induction.
		We denote by $\tau_{k,\ell}$ the $(\xi+1)$-th job of $Seq$.
		Let $a$ be the lowest value in $\Nbb_0$, such that $\tau_{k,\ell}$ is the $(a+1)$-th job in an active interval of $\tau_k$.
		We first show that $a\leq \tilde a_k$ by contraposition.
		If $a > \tilde a$, then we consider the job $\tau_{k,\ell-(a-\tilde a)}$.
		This is the $(\tilde a+1)$-th job in an active interval of $\tau_k$.
		Moreover, this job is one of the first $\xi$ jobs in $Seq$ and therefore has a response time of at most $T_k$ due to 2).
		Hence, $\tau_{k,\ell-(a-\tilde a)}$ is finished by time $r_{k,\ell-(a-\tilde a)+1}$.
		We conclude that $\tau_{k,\ell}$ is the $(a-\tilde a_k)$-th job in an active interval of $\tau_k$, which contradicts the minimality of $a$.
		We now choose $c:=b^a_k-a\cdot T_k + r_{k,\ell}$.
		Applying Lemma~\ref{lem:suff_sched_test_var_prep} with this $c$ shows that $\Rtilde^a_k(b^a_k)$ is a response time upper bound of $\tau_{k,\ell}$ as required.
	\end{proof}

We apply a similar search strategy as for the case with fixed analysis window. 
However, the values of $\Rtilde_k$ are computed through an additional loop over the values of $a$ until $\Rtilde^a_k \leq T_k$.
Algorithm~\ref{alg:sched_test_var} depicts an implementation of the schedulability test in pseudocode.
As the value of $\Rtilde^a_k$ can be between $T_k$ and $D_k$ for all iterations of $a$, the program may never return a result. 
To make the schedulability test deterministic, we introduce an additional parameter $max\_a$ which aborts the loop when even $a=max\_a$ gives no result.

\begin{algorithm}[t]
			\small
%			\footnotesize{}
			%\scriptsize
			\caption{Schedulability test with var.\@ analysis window.}
			\label{alg:sched_test_var}
			\begin{algorithmic}[1]
				\item[] \textbf{Input:} $\Tbb = \{\tau_1,\dots,\tau_n\}$, $(\Pi_1,\dots,\Pi_n)$, $\eta$, $max\_a$, $depth$
				\item[] \textbf{Output:} True: schedulable, False: no decision
				\item[]

				\State Order $\tau_1 ,\dots,\tau_n$, s.th. $D_1\geq \dots \geq D_n$.
				\State Set $\Rtilde_i := D_i$ for all $i$.

				\For{$i=1,2, \dots, depth$}
				\State $solved := True$
				\For{$k = 1, 2, \dots,n$}
				%			\State $\Phi = \floor{\frac{D_i}{\eta}}$
				\For{$a=0,1, \dots, max\_a$} \Comment{Different $a$.}
				\State $cand := [~]$; $step := \eta \cdot D_k$
				\Comment{Preparation.}
				\For{$b=0,step, 2\cdot step, \dots <aT_k + D_k$}
				\State $\triangleright$ Compute candidate:
%				\Comment{Compute candidate.}
				\State $cand.append(\Rtilde^a_k(b))$ from Equation~\eqref{eq:thm:suff_sched_test_var}
				\EndFor
				\State $\Rtilde^a_k := \min\limits (cand)$
				\Comment{Compare candidates.}
				\If{$\Rtilde^a_k\leq T_k$}\Comment{Check~cond.~1.}
				\State $\triangleright$ WCRT upper bound:
				\State $\tilde{a} := a$; $\Rtilde_k := \min_{a=0,\dots,\tilde a} \Rtilde^a_k$; 
				\textbf{break} 
%				\Comment{WCRT upper bound.}
				\EndIf
				\If{$\Rtilde^a_k>D_k$ or $a=max\_a$} \Comment{Check cond.~2.}
				\State $solved:=False$; $\Rtilde_k := D_k$; \textbf{break}
				\EndIf
				\EndFor
				\EndFor
				\EndFor
				\State \Return $solved$
			\end{algorithmic}
		\end{algorithm}


\subsection{Dominance of Fixed and Variable Analysis Window}
\label{sec:dominance}

At first glance, the analysis derived in Section~\ref{sec:test_arb} with the variable analysis window seems to improve the analysis from Section~\ref{sec:test_fixed} with fixed analysis window in all cases:
When setting $x = b_k + a\cdot T_k$ in Theorem~\ref{thm:suff_sched_test_var}, then the result is lower bounded by $\Rtilde_k(b_k)$ from Theorem~\ref{thm:suff_sched_test_fixed}.
However, both methods do not dominate each other, as demonstrated in the discussion of Figure~\ref{fig:eval_arbdl_dm} in Section~\ref{sec:evaluation}, due to the following reasons.
%
First, the analysis with variable analysis window can only analyze schedules where the length of active intervals is bounded.
More specifically, if the response-time upper bound $\Rtilde^a_k$ is in the interval $(T_k, D_k)$ for all $a$, then the schedulability test with the variable analysis window never deems the task schedulable.
Second, by setting $max\_a$ this effect is even intensified:
The analysis with variable analysis window has to find $\Rtilde^a_k \leq T_k$ even for some $a \leq max\_a$.
Third, the discretization using $\eta$ in Algorithm~\ref{alg:sched_test_fixed} and~\ref{alg:sched_test_var} ensures the same number of points for each analysis interval.
As a result, not all points $b+aT_k$ with $b$ from Algorithm~\ref{alg:sched_test_fixed} are checked during Algorithm~\ref{alg:sched_test_var} as well.



\section{Realization of EL Scheduling}
\label{sec:remark+realization}

To implement EDF-Like (EL) scheduling algorithms, we can exploit the existing EDF scheduling mechanisms to integrate the proposed relative priority points.
	Here we demonstrate the integration on two well-known real-time operating systems (RTOSes), i.e., RTEMS \cite{rtems} and {$\text{LITMUS}^{\text{RT}}$} \cite{litmusrt}, which officially support EDF scheduling.
	In general, the workflow of an EDF mechanism can be abstracted as follows:
	\begin{enumerate}
		\item At each job release, its priority should be identified with its absolute deadline, and necessary priority mapping operations should be performed. 
		\item The job context is placed into the ready queue according to its priority, which is commonly realized by a dedicated data structure, e.g., a red-black tree in RTEMS and a binomial heap in {$\text{LITMUS}^{\text{RT}}$}.
		\item One highest priority job should be executed. In case there are deadline ties, a regulation should be performed. This step also takes place if a job finishes its execution.
	\end{enumerate}
	Since EL scheduling only affects the job priority, the realization can be achieved by performing the priority mapping with the \emph{priority point} instead of the absolute deadline. This implies that  any underlying data structure for EDF scheduling, which sorts the jobs according to their absolute deadlines, can be directly adapted.
	Suppose the relative priority point for each task is given, we demonstrate the integration of these relative priority points for RTEMS (version 5.1) and {$\text{LITMUS}^{\text{RT}}$}:

	\paragraph{RTEMS} 
	In \texttt{Thread\_Configuration} we add a field \texttt{rel\_pp} to hold the given relative priority point.
	Two new fields \texttt{rel\_pp} and \texttt{release\_time} are added in \texttt{Thread\_Control} structure to keep the relevant modification minimal.
	To avoid corrupting the dependency of original priority mapping, we reuse the original mapping macro \texttt{SCHEDULER\_PRIORITY\_MAP()} and replace the original input \emph{deadline} by the priority point.

	\paragraph{{$\text{LITMUS}^{\text{RT}}$}} We add a new field \texttt{priority\_point} in \texttt{rt\_job} structure and a new field \texttt{rel\_pp} in \texttt{rt\_task} structure. 
	The calculation of \texttt{priority\_point} is performed at \texttt{setup\_release()}. 
	A new macro \texttt{higher\_priority\_point} is used to compare \texttt{priority\_point} over jobs.
	To ensure that the light-weight event tracing toolkit~\cite{Brandenburg07feather-trace:a} still functions correctly, we did not touch any relevant functions and macros for the absolute deadline.

	The functionality of both realizations are validated successfully on real platforms. The corresponding patches will be publicly available once the paper is accepted.
	Since the realization on both RTOSes only requires slight modifications,
	we conjecture that every RTOS supporting EDF scheduling can also realize EL scheduling. 
	Please note that the discussion is to demonstrate the applicability, and we do not recommend to replace TFP or FIFO with EL scheduling because of unnecessary operation overhead.


