\subsection{Timed Automata}
%
%
%
A TA is a finite automaton extended with a finite set of real-valued clocks. %
We also add to the standard definition of TAs a special private locations set, which is then used to define the subsequent opacity concepts.

%
\begin{definition}[TA~\cite{AD94}]\label{def:TA}
	A TA~$\TA$ is a tuple \mbox{$\TA = \TAprivextend$}, where:
	\begin{oneenumerate}%
		\item $\ActionSet$ is a finite set of actions,
		\item $\LocSet$ is a finite set of locations,
		\LongVersion{\item} $\locinit \in \LocSet$ is the initial location,
		\item $\PrivSet \subseteq \LocSet$ is a set of private locations,
		\LongVersion{\item} $\FinalSet \subseteq \LocSet$ is a set of final locations,
		\item $\ClockSet$ is a finite set of clocks,
		\item $\invariant$ is the invariant, assigning to every $\loc\in \LocSet$ a constraint $\invariant(\loc)$ over $\ClockSet$ (called \emph{invariant}),
		\item $\EdgeSet$ is a finite set of edges  $\edge = (\loc,\guard,\action,\resets,\loc')$
		where~$\loc,\loc'\in \LocSet$ are the source and target locations, $\action \in \ActionSet \cup \{ \silentaction \}$ (where $\silentaction$ denotes an unobservable action),
		$\resets\subseteq \ClockSet$ is a set of clocks to be reset, and $\guard$ is a constraint over $\ClockSet$ (called \emph{guard}).
	\end{oneenumerate}%
\end{definition}
