\begin{definition}[Semantics of a TA]\label{def:semantics}
	Given a TA $\TA = \TAprivextend$,
	the semantics of $\TA$ is given by the timed transition system $\semantics{\TA} = \semanticsextend$, with
	\begin{enumerate}
		\item $\StateSet = \big\{ (\loc, \clockval) \in \LocSet \times \setRgeqzero^\ClockSet \mid \clockval \models \invariant(\loc) \big\}$,
		\LongVersion{\item }$\concstateinit = (\locinit, \ClocksZero) $,
		\item  $\transition \subseteq \StateSet \times \EdgeSet \times \StateSet \cup \StateSet \times \setRgeqzero \times \StateSet$ consists of the discrete and (continuous) delay transition relations:
		\begin{enumerate}
			\item discrete transitions: 
$((\loc,\clockval), \edge, (\loc',\clockval'))\in \transition$, and we write	
$(\loc,\clockval) \transitionWith{\edge} (\loc',\clockval')$, if $(\loc, \clockval) , (\loc',\clockval') \in \StateSet$, $\edge = (\loc,\guard,\action,\resets,\loc') \in \EdgeSet$, $\clockval'= \reset{\clockval}{\resets}$, and $\clockval\models \guard$.
			\item delay transitions: 
$((\loc,\clockval), d, (\loc,\clockval +d))\in \transition$, and we write	
$(\loc,\clockval) \transitionWith{d} (\loc, \clockval+d)$, if $d \in \setRgeqzero$ and 
$\forall d' \in [0, d], (\loc, \clockval+d') \in \StateSet$.
		\end{enumerate}
	\end{enumerate}
\end{definition}
%

Moreover we write $(\loc, \clockval)\longuefleche{(d, \edge)} (\loc',\clockval')$ for a combination of a delay and discrete transition if
$\exists  \clockval'' :  (\loc,\clockval) \transitionWith{d} (\loc,\clockval'') \transitionWith{\edge} (\loc',\clockval')$.

Given a TA~$\TA$ with semantics $\semanticsextend$, we refer to the elements of~$\StateSet$ as the \emph{configurations} of~$\TA$.
A (finite) \emph{run} of~$\TA$ is an alternating sequence of configurations of~$\TA$ and pairs of delays and edges starting from the initial configuration $\concstateinit$ and ending in a final configuration (\ie{} whose location is final),
%
of the form
$(\loci{0}, \clockval_{0}), (d_0, \edge_0), (\loci{1}, \clockval_{1}), \ldots (\loci{n}, \clockval_{n})$ for some $n \in \setN$,
with
$\loci{n} \in \FinalSet$ and for $i = 0, 1, \dots n-1$, $\loci{i} \notin \FinalSet$, $\edge_i \in \EdgeSet$, $d_i \in \setRgeqzero, $ and
$(\loci{i}, \clockval_{i}) \longuefleche{(d_i, \edge_i)} (\loci{i+1}, \clockval_{i+1})$.
A \emph{path} of $\TA$ is a prefix of a run ending with a configuration.
%


