\subsection{Region Automaton}\label{section:tools:RA}
%


We recall that the region automaton is obtained by quotienting the set of clock valuations out by an equivalence relation $\simeq$ recalled below.
\LongVersion{%
	The definitions we present here are inspired by those from \cite{ALM23}.
}


%
Given a TA~$\TA$ and its set of clocks $\ClockSet$, we define $M : \ClockSet \rightarrow \setN$ the map that associates to a clock $\clock$ the greatest value to which the interpretations of $\clock$ are compared within the guards and invariants; if $\clock$ appears in no constraint, we set $M(\clock) = 0$.

Given $\alpha \in \setR$, we write $\lfloor \alpha \rfloor$ and $\fract{\alpha}$ respectively for the integral and fractional parts of $\alpha$.



%
\begin{definition}[Equivalence relation $\simeq$ for valuations~\cite{AD94}]
Let $\mu$, $\mu'$ be two clock valuations (with values in $\setRgeqzero$). We say that $\mu$ and $\mu'$ are equivalent, denoted by $\mu \simeq \mu'$ when, for each $\clock \in \ClockSet$, either $	\mu (\clock) > M(\clock)$ and $\mu' (\clock) > M(\clock)$ or the three following conditions hold:

\begin{enumerate}
\item $\lfloor \mu (\clock) \rfloor = \lfloor \mu' (\clock) \rfloor$;
\item $\fract{\mu(\clock)} = 0 \text{ if and only if }  \fract{\mu'(\clock)} = 0$;
\item for each $y \in \ClockSet$, $\fract{\mu(\clock)} \leq  \fract{\mu(y)} \text{ if and only if } \fract{\mu'(\clock)} \leq  \fract{\mu'(y)}$.
\end{enumerate}
\end{definition}

The equivalence relation is extended to the configurations of $\TA$: let $\concstate = (\loc, \mu)$ and $\concstate' = (\loc', \mu')$ be two configurations in $\TA$, then
\(\concstate \simeq \concstate' \text{ if and only if } \loc = \loc' \text{ and } \mu \simeq \mu'. \)

The equivalence class of a valuation $\mu$ is denoted $[ \mu ]$ and is called a \emph{clock region}, and the equivalence class of a configuration $\concstate = (\loc, \mu)$ is denoted $[ \concstate ]$ and called a \emph{region} of~$\TA$.
\LongVersion{%
	In other words, a region is a pair made of a location and of a clock region.
}%
Clock regions are denoted by the enumeration of the constraints defining the equivalence class. Thus, values of a clock $\clock$ that go beyond $M(\clock)$ are merged and described in the regions by \LongVersion{the inequality }``$\clock > M(\clock)$''.

The set of regions of $\TA$ is denoted by~$\Regions{\TA}$.
These regions are of finite number: this allows us to construct a finite ``untimed'' regular automaton, the region automaton~$\RegionAutomaton{\TA}$.
Locations of $\RegionAutomaton{\TA}$ are regions of~$\TA$, and the transitions of $\RegionAutomaton{\TA}$ convey the reachable valuations associated with each configuration in~$\TA$.

To formalize the construction, we need to transform discrete and time-elapsing transitions of $\TA$ into transitions between the regions of $\TA$. To do that, we define a ``time-successor'' relation that corresponds to time-elapsing transitions.

\begin{definition}[Time-successor relation \cite{ALM23}]
Let $r = (\loc, [\mu]), r' = (\loc', [\mu']) \in \Regions{\TA}$. We say that $r'$ is a time-successor of $r$ when $r \neq r'$, $\loc = \loc'$ and for each configuration $(\loc, \mu)$ in $r$, there exists $d \in \setRgeqzero$ such that $(\loc, \mu + d)$ is in $r'$ and for all $d' < d, (\loc, \mu + d') \in r \cup r'$.
\end{definition}

A region $r = (\loc, [\mu])$ is \emph{unbounded} when, for all $\clock$ in $\ClockSet$ and all $\clockval' \in [\clockval]$, $\clockval'(\clock) > M(\clock)$.

\begin{definition}[Region automaton \cite{AD94}\label{definition:region-automaton}]
Given a TA $\TA = \TAprivextend$, the region automaton is the
%
tuple $\RegionAutomaton{\TA} = (\ActionSet_{\Regions{}}, \Regions{}, r_0, {\Regions{}}_f, \EdgeSet_{\Regions{}})$ where
\begin{oneenumerate}%
\item $\ActionSet_{\Regions{}} = \ActionSet \cup \lbrace \silentaction \rbrace$;
\item ${\Regions{}} = \Regions{\TA}$;
\item $r_0 = [\concstateinit]$;
\item ${\Regions{}}_f$ is the set of regions whose first component is a final location $\locfinal \in \FinalSet$;
\item
\begin{ienumerate}%
	\item \emph{(discrete transitions)} For every $r = (\loc, [\mu])$ with $\loc\notin \FinalSet$, $r' = (\loc', [\mu']) \in \Regions{\TA}$ and $a \in \ActionSet \cup \lbrace \silentaction \rbrace$:
\[ (r, a, r') \in \EdgeSet_{\Regions{}} \text{ if } \exists \mu'' \in [\mu], \exists \mu''' \in [\mu'], (\loc, \mu'') \transitionWith{\edge} (\loc', \mu''') \]
%
\noindent{}with $e = (\loc, g, a, \resets, \loc') \in \EdgeSet$\LongVersion{ for some guard $g$ and some clock set~$R$}.\\
\item \emph{(delay transitions)}
	For every $r = (\loc, [\mu])$ with $\loc\notin \FinalSet$, $r' \in \Regions{\TA}$:
\[ (r, \silentaction, r') \in \EdgeSet_{\Regions{}} \text{ if } r' \text{ is a time-successor of } r \text{ or if } r=r'\text{ is unbounded.}\]
\end{ienumerate}%
\end{oneenumerate}%
\end{definition}

As in TAs, a \emph{run} of~$\RegionAutomaton{\TA}$ is an alternating sequence of regions of~$\RegionAutomaton{\TA}$ and actions starting from the initial region $\regioni{0}$ and ending in a final region, of the form
$\regioni{0}, a_0, \regioni{1}, a_1, \ldots \regioni{n-1}, a_{n-1}, \regioni{n}$ for some $n \in \setN$,
with $\regioni{n} \in R_f$ and for $i \in \interval{0}{n-1}$, $\regioni{i} \notin R_f$, and $(\regioni{i},a_i, \regioni{i+1}) \in \EdgeSet_{\Regions{}}$.
A \emph{path} of $\RegionAutomaton{\TA}$ is a prefix of a run ending with a region and the
trace of a path of $\RegionAutomaton{\TA}$ is the sequence of actions ($\silentaction$ excluded) contained in this path.

