Based on \cite[Lemma 1 and 2]{caire2018ergodic}, the upper bound and lower bound (known as the use-and-then-forget (UatF) bound) to the ergodic achievable rate for user $k$ at a generic subcarrier are respectively given by 
\begin{align}
    R_k^{{\rm ub}} &= \bE\left[\log\left(1 + \frac{
    |\hv_k^\herm \vv_k|^2}{ \sum_{j \neq k}  |\hv_k^\herm \vv_j|^2 + 1}\right)\right], \label{eq:R_ub}\\
    R_k^{{\rm UatF}} &= \log\left(1 + \frac{|\mathbb{E}[\hv_k^\herm \vv_k]|^2}{ {\rm Var}(\hv_k^\herm \vv_k) + \sum_{j \neq k} \mathbb{E}[|\hv_k^\herm \vv_j|^2] + 1}\right).\label{eq:R_hard}
\end{align}
It is noticed that in all feedback schemes, for a fixed pilot matrix $\Xm$, the DL CSI for user $k$ can be derived from the channel estimate $\widehat{\hv}_k$ as
\begin{align}\label{eq:h_hat}
    \hv_k = \widehat{\hv}_k + \ev_k, 
\end{align}
where $\widehat{\hv}_k$ and $\ev_k$ are independent with $\widehat{\hv}_k \sim \Cc\Nc(\mathbf{0}, \Cm_{\widehat{\hv}_k})$ and $\ev_k \sim \Cc\Nc(\mathbf{0}, \Cm_{\ev_k} = \Cm_{\hv_k} - \Cm_{\widehat{\hv}_k})$. 
In the following lemmas, we provide closed-form expressions of the UatF  ergodic rate for the considered MRT and ZF precoders, respectively.  

\begin{lemma}[$R_k^{{\rm UatF}}$ under MRT precoder] \label{lemma: MRT}
Using MRT precoding, we have $\Vm = \sqrt{\eta}\widehat{\Hm}$, where the power scaling factor $\eta$ is obtained based on \eqref{eq: V_power} as 
\begin{align}
    \eta = \frac{\mathsf{snr}_{\rm dl}}{\tr\left(\mathbb{E}[\widehat{\Hm}^\herm \widehat{\Hm}]\right)} 
    = \frac{\mathsf{snr}_{\rm dl}}{\tr\left(\sum_{k=1}^K \Cm_{\widehat{\hv}_k}\right)}. \label{eq:eta_MRT}
\end{align}
The UatF ergodic rate under MRT precoder in closed-form is 
\begin{align}
    R^{{\rm MRT}}_{k} &= \log\left(1 +\frac{\eta\trace^2(\Cm_{\widehat{\hv}_k})}{\eta\tr(\Cm_{\widehat{\hv}_k} \Cm_{{\hv}_k})+ \eta \sum_{j \neq k} \trace( \Cm_{\widehat{\hv}_j} \Cm_{\hv_k})+ 1}\right), \\
    &=\log\left(1 +\frac{\trace^2(\Cm_{\widehat{\hv}_k})}{  \tr\left(\left(\sum_{k=1}^K \Cm_{\widehat{\hv}_k}\right) \Cm_{\hv_k}\right)+ \frac{1}{\eta}}\right).\label{eq:R_hard_MRT}
\end{align}
\end{lemma}
\begin{proof}
    See Appendix \ref{sec:MRT_lemma}.
\end{proof}

\begin{lemma}[$R_k^{{\rm UatF}}$ under ZF precoder]\label{lemma: ZF}
    Using ZF precoding, the precoder matrix is a power normalized pseudo-inverse of the estimated channel matrix, i.e., $\Vm =  \sqrt{\widetilde{\eta}} \widehat{\Hm} (\widehat{\Hm}^{\herm} \widehat{\Hm})^{-1}$, where the power scaling factor $\widetilde{\eta}$ is obtained based on \eqref{eq: V_power} as 
\begin{align}
    \widetilde{\eta} &= \frac{\mathsf{snr}_{\rm dl}}{\tr\left(\mathbb{E}\left[\left(\widehat{\Hm}^\herm \widehat{\Hm}\right)^{-1}\right]\right)}. \label{eq:V_eta_ZF}
\end{align}
The UatF ergodic rate under ZF precoder can be written as  
\begin{align}
    {R}^{{\rm ZF}}_{k} &= \log\left(1 + \frac{1}{  \tr\left(\mathbb{E}\left[\widehat{\Hm} (\widehat{\Hm}^{\herm} \widehat{\Hm})^{-2} \widehat{\Hm}^{\herm}\right]\Cm_{\ev_k}\right) + \frac{1}{\widetilde{\eta}}}\right).  \label{eq:R_hard_ZF} 
\end{align} 
% \begin{align}
%     {R}^{{\rm ZF}}_{k} &= \log\left(1 + \frac{1}{  \trace\left(\mathbb{E}\left[\widehat{\Hm} (\widehat{\Hm}^{\herm} \widehat{\Hm})^{-2} \widehat{\Hm}^{\herm}\right]\Cm_{\ev_k}\right) + \frac{1}{\widetilde{\eta}}}\right)  \label{eq:R_hard_ZF} \\
%     &\geq  \log\left(1 + \frac{1}{ \|\Cm_{\ev_k}\|_2 \trace\left(\mathbb{E}\left[(\widehat{\Hm}^{\herm} \widehat{\Hm})^{-1}\right]\right) + \frac{1}{\widetilde{\eta}}}\right) \triangleq \check{R}_k^{\rm ZF} \label{eq:R_ZF_low}.
% \end{align} 
\end{lemma}
\begin{proof}
    See Appendix \ref{sec:proof_ZF}.
\end{proof}
\begin{remark}
    Note that the expression in \eqref{eq:R_hard_ZF} is not in closed-form, since the terms $\mathbb{E}[(\widehat{\Hm}^\herm \widehat{\Hm})^{-1}]$ in \eqref{eq:V_eta_ZF} and $\mathbb{E}[\widehat{\Hm} (\widehat{\Hm}^{\herm} \widehat{\Hm})^{-2} \widehat{\Hm}^{\herm}]$ in \eqref{eq:R_hard_ZF} are required to be numerically calculated via Monte Carlo method. 
    It is still an open problem to obtain the closed-form expressions for both terms based on the corresponding covariance knowledge, i.e., $\{\Cm_{\widehat{\hv}_k}\}_{k=1}^K$.  \hfill $\lozenge$
\end{remark}

