\section{The solution of \eqref{eq:opt_ppp}}
\label{sec:lemma_TKL}
To solve \eqref{eq:opt_ppp}, we first rewrite the objective more simply. Noticing that the objective can be written as $\trace(\Cm_{\hv_k}) - \trace(\Cm_{\widehat{\hv}_k^{\rm tkl}})$ and the first term is constant to the variable $\alphav_k$, we thus focus on the second term $-\trace(\Cm_{\widehat{\hv}_k^{\rm tkl}}) = -\trace(\Cm_{\hv_k \widehat{\yv}^{\rm fb}_k} \Cm_{\widehat{\yv}^{\rm fb}_k}^{-1} \Cm_{\hv_k \widehat{\yv}^{\rm fb}_k}^{\herm})$. Further noticing that $\Cm_{\widehat{\yv}^{\rm fb}_k} = \diag({\alphav_k})\Sm_k(\widebar{\Lambdam}_k + \Id_{\beta_{\rm tr}})\Sm_k^\herm  +\Id_{\beta_{\rm fb}}
    = \diag\left({\alpha_{k, 1}(\widebar{\lambda}_{k, 1} + 1) + 1}, ..., {\alpha_{k, \beta_{\rm fb}}(\widebar{\lambda}_{k, \beta_{\rm fb}} + 1) + 1}\right)$
and defining $\boldsymbol{\nu}_k = [\nu_{k,1},\dots,\nu_{k,\beta_{\rm fb}}]$ with $\nu_{k,j} \triangleq \frac{\alpha_{k, j} }{\alpha_{k, j}(\widebar{\lambda}_{k, j} + 1) + 1}$ and  $\Deltam_k \triangleq \Sm_k^\herm \diag\left(\boldsymbol{\nu}\right)\Sm_k =
    \diag(\nu_{k,1}, \dots, \nu_{k, \beta_{\rm fb}}, \underbrace{0,\dots, 0}_{\betatr - \beta_{\rm fb}})$,
we have 
\begin{align}
    &\trace(\Cm_{\hv_k \widehat{\yv}^{\rm fb}_k} \Cm_{\widehat{\yv}^{\rm fb}_k}^{-1} \Cm_{\hv_k \widehat{\yv}^{\rm fb}_k}^{\herm})\\ 
        =\;&\trace(\Cm_{\hv_k}\Xm^\herm \Um_k \Deltam_k \Um_k^\herm \Xm \Cm_{\hv_k}) \\
        =\;&\trace(\Cm_{\hv_k}^{\frac{1}{2}}\Cm_{\hv_k}^{\frac{1}{2}}\Xm^\herm \Um_k \Deltam_k \Um_k^\herm \Xm \Cm_{\hv_k}^{\frac{1}{2}}\Cm_{\hv_k}^{\frac{1}{2}}) \\
        =\;& \trace\left(\Cm_{\hv_k}^{\frac{1}{2}} \Vm_k \Sigmam_k^\herm \Deltam_k  \Sigmam_k  \Vm_k^\herm \Cm_{\hv_k}^{\frac{1}{2}}\right) \\
        =\;& \trace\left(  \Vm_k^\herm \Cm_{\hv_k} \Vm_k \Sigmam_k^\herm \Deltam_k  \Sigmam_k \right) \\
        \stackrel{(a)}{=}& \sum_{i=1}^{\beta_{\rm fb}} \frac{\rho_{k,i} \alpha_{k, i} \widebar{\lambda}_{k,i}}{\alpha_{k, i}(\widebar{\lambda}_{k, i} + 1) + 1} \triangleq f(\alphav_k),
\end{align} 
where in (a) we denote $\rho_{k,i} \triangleq \vv_{k, i}^\herm \Cm_{\hv_k} \vv_{k, i}$ with $\vv_{k, i}$ as the $i$-th column of $\Vm_k$ and noting that $[\Vm_k^\herm \Cm_{\hv_k} \Vm_k]_{i,i} = \vv_{k, i}^\herm \Cm_{\hv_k} \vv_{k, i}$. Then, the optimization problem can be equivalently rewritten as
\begin{subequations}\label{eq:opt_new}
\begin{align}
    \underset{\alphav_k\geq0}{\text{minimize}} \;\;\;\;\quad \quad &  -f(\alphav_k) \\
    \text{subject to} \quad \qquad&  \eqref{eq:power_constraint}.
\end{align}
\end{subequations}
The constraints are obviously convex. We show the convexity of the objective by showing that its Hessian matrix is positive semi-definite. It is clear that $\frac{\partial^2 -f(\alphav_k)}{\partial \alpha_{k,i}\alpha_{k,j}} = 0, \forall i \neq j$, and  
\begin{equation}
    \frac{\partial^2 -f(\alphav_k)}{\partial \alpha_{k,i}^2} = \frac{2\rho_{k,i}\bar{\lambda}_{k,i}(\bar{\lambda}_{k,i}+1)(\alpha_{k,i}(\bar{\lambda}_{k,i}+1)+1)}{(\alpha_{k,i}(\bar{\lambda}_{k,i} + 1) + 1)^4}\geq 0.
\end{equation}
Therefore, the Hessian matrix is a diagonal matrix with all non-negative diagonal elements and thus a positive semi-definite matrix. In total, the problem in \eqref{eq:opt_new} is a convex problem. Then, we solve the problem using the Lagrangian method.
Given Lagrangian multiplier $\gamma$, the corresponding Lagrangian function is given as 
\begin{align}\label{eq:lag_func}
    L = -\sum_{i=1}^{\betafb}\frac{\rho_{k,i} \alpha_{k, i}\widebar{\lambda}_{k, i} }{\alpha_{k,i}(\widebar{\lambda}_{k, i} + 1) + 1} + \gamma\left( \sum_{i=1}^{\beta_{\rm fb}} \alpha_{k, i}(\widebar{\lambda}_{k, i} + 1) - P_{\rm ul}\right).
\end{align}

Letting the derivative of $L$ regarding $\alpha_{k,i}$ be zero  
\begin{align}
    \frac{\partial L}{\partial \alpha_{k,i}} = \frac{ - \rho_{k,i}\widebar{\lambda}_{k, i}}{(\alpha_{k,i}(\widebar{\lambda}_{k, i}+ 1)+1)^2} + \gamma(\widebar{\lambda}_{k, i} + 1) \overset{!}{=} 0,
\end{align}
we have 
\begin{align}\label{eq:alpha_star}
    \alpha^\star_{k, i} = \frac{\left[\sqrt{ \frac{\rho_{k,i}\widebar{\lambda}_{k, i}}{\gamma^\star(\widebar{\lambda}_{k, i} + 1)}} -1 \right]_+ }{1 + \widebar{\lambda}_{k, i}}, 
\end{align}
where $\gamma^\star$ is chosen such that 
\begin{align}\label{eq:gamma_results}
    \sum_{i=1}^{\beta_{\rm fb}} \left[ \sqrt{ \frac{\rho_{k,i} \widebar{\lambda}_{k, i}}{\gamma^\star(\widebar{\lambda}_{k, i} + 1)}} -1\right]_+ =P_{\rm ul}.
\end{align}
We obtain the optimal $\gamma^\star$ by solving \eqref{eq:gamma_results} using a binary search. Finally, given the optimal $\gamma^\star$, the optimal power allocation $\alphav_k^\star$ is obtained by \eqref{eq:alpha_star}.

\section{The proof of {{Theorem}} \ref{theorem:QSE}}
\label{sec:QSE_proof}
We first denote the eigen-decomposition of the channel covariance as $\Cm_{\hv_k} = \Um_{\hv_k} \Lambdam_{\hv_k} \Um_{\hv_k}^\herm $, where $\Um_{\hv_k} \in \bC^{MN\times r_k}$ is the tall matrix with eigenvectors and $\Lambdam_{\hv_k}\in \bR^{r_k\times r_k}$ is a diagonal matrix with $r_k$ non-zero eigenvalues $\lambda^{\hv_k}_1 \geq \lambda^{\hv_k}_2\geq\dots \geq \lambda^{\hv_k}_{r_k} $ in descending order on its diagonal. By further denoting $\Psim\triangleq\Um_k\Sm_k^\herm {\rm diag}(\sqrt{\alphav_k})$, we find that the resulting terms of $\Cm_{\hv_k \widehat{\yv}^{\rm fb}_k}$ and $ \Cm_{\widehat{\yv}^{\rm fb}_k}$ have the same formulations as the corresponding terms of the ``analog feedback'' scheme in \cite{khalilsarai2023fdd}. Therefore, following the similar steps in \cite[Appendix B]{khalilsarai2023fdd}, the MSE of channel estimation can be derived as 
\begin{align}\label{eq:MSE_TKL}
    D_k^{\rm tkl}(R) &= \mathbb{E}[\|\hv_k - \widehat{\hv}_k^{\rm tkl}\|^2] \nonumber \\
    &=  \tr\left(\Lambdam_{\hv_k} \left(\Id - \Gm_k + \Gm_k(\Id + \Gm_k)^{-1} \Gm_k\right)\right),
\end{align}
where $\Gm_k$ is defined as 
\begin{align}
    \Gm_k &\triangleq \Lambdam_{\hv_k}^{\frac{1}{2}} \Um_{\hv_k}^\herm \Xm^\herm \Psim (\Psim^\herm \Psim + \Id)^{-1} \Psim^\herm \Xm \Um_{\hv_k}\Lambdam_{\hv_k}^{\frac{1}{2}}.
\end{align}   
Using the same trace inequality on \eqref{eq:MSE_TKL} as in \cite[(29) in Appendix A]{khalilsarai2023fdd}, one can show that 
\begin{align}\label{eq:trace_inequality}
   \lambda^{\hv_k}_{r_k} g({\mathsf{snr}}_{\rm dl}) \leq  D_k^{\rm tkl}(R) \leq \lambda^{\hv_k}_1 g({\mathsf{snr}}_{\rm dl}),
\end{align}
where $g({\mathsf{snr}}_{\rm dl}) \triangleq \tr\left( \Id - \Gm_k + \Gm_k(\Id+ \Gm_k)^{-1} \Gm_k\right)$. 
Then, we show the trend of $g(\cdot)$ in large $\snrdl$.
For a given pilot matrix $\Xm$, denote the eigenvalues of $ \Gm_k$ by $u_k^i, i=[r_k]$, $ g({\mathsf{snr}}_{\rm dl})$ is given by
\begin{align}
    g({\mathsf{snr}}_{\rm dl}) &= r_k - \sum_{i=1}^{r_k} u^i_k + \sum_{i=1}^{r_k} \frac{{u^i_k}^2}{u^i_k + 1} \\
    &=\sum_{i=1}^{r_k} \frac{1}{u^i_k + 1}. \label{eq:gu}
\end{align}
We now derive an approximation of $\Gm_k$ in large $\snrdl$ for further analysis, given as
\begin{align}
    \Gm_k &=  \Lambdam_{\hv_k}^{\frac{1}{2}} \Um_{\hv_k}^\herm \Xm^\herm \Um_k\Sm_k^\herm {\rm diag}(\sqrt{\alphav_k}) ({\rm diag}({\alphav_k})+ \Id)^{-1}  \nonumber \\
    & \quad \quad \quad \quad  {\rm diag}(\sqrt{\alphav_k}) \Sm_k \Um_k^\herm \Xm \Um_{\hv_k}\Lambdam_{\hv_k}^{\frac{1}{2}}   \\
    & \approx \Lambdam_{\hv_k}^{\frac{1}{2}} \Um_{\hv_k}^\herm \Xm^\herm \Um_k\Sm_k^\herm \Sm_k \Um_k^\herm  \Xm  \Um_{\hv_k}\Lambdam_{\hv_k}^{\frac{1}{2}}, \label{eq:G_value}
\end{align}
where the approximation in \eqref{eq:G_value} holds when ${\mathsf{snr}}_{\rm dl} \rightarrow \infty$, which results in $\alphav_k \rightarrow \infty$ based on \eqref{eq:gamma_results}, and $({\rm diag}({\alphav_k})+ \Id)^{-1} \approx {\rm diag}({\alphav_k})^{-1}$. 
Checking the items in \eqref{eq:G_value}, we find out: (a) $\Lambdam_{\hv_k}$ and $ \Um_{\hv_k}$ are independent of ${\mathsf{snr}}_{\rm dl}$; (b) the training matrix can be written as $\Xm = \sqrt{{\mathsf{snr}}_{\rm dl}} \Xm^o$, where $\Xm^o$ is randomly generated and independently from ${\mathsf{snr}}_{\rm dl}$; and (c) $\Sm_k^\herm\Sm_k$ is a diagonal matrix with first $\betafb$ diagonal elements as ones and all other elements as zeros. Therefore, the behavior of the non-zero eigenvalues of $\Gm_k$ in high $\snrdl$ is  
\begin{equation}\label{eq:uk}
    u_k^i = \Theta({\mathsf{snr}}_{\rm dl}), \quad \forall u_k^i \neq 0. 
\end{equation}
Using \eqref{eq:gu} and \eqref{eq:uk}, we deduce that if $\Gm_k$ is full rank, i.e., $u_k^i \neq 0, \forall i \in [r_k]$, we have $g(\snrdl)=\Theta(\snrdl^{-1})$ and then $D_k^{\rm tkl}(R) = \Theta(\snrdl^{-1})$ using \eqref{eq:trace_inequality}. Conversely, if $\Gm_k$ has at least one zero eigenvalue, i.e., $\exists u_k^i = 0$, we have $g(\snrdl) = \Theta(1)$ from \eqref{eq:gu} and then $D_k^{\rm tkl}(R) = \Theta(1)$ using \eqref{eq:trace_inequality}. In short:
\begin{equation}
    D_k^{\rm tkl}(R) = \begin{cases}
        \Theta(\snrdl^{-1}), & u_k^i \neq 0, \forall i \in [r_k],\\
        \Theta(1), & \text{otherwise}.
    \end{cases}
\end{equation}

Finally, we check the rank of $\Gm_k$. It is clear from \eqref{eq:G_value} that when $\betafb \geq r_k$, $\Gm_k$ is full rank with probability one, and thus $D_k^{\rm tkl}(R) = \Theta(\snrdl^{-1})$. Conversely, if $\betafb < r_k$, $\Gm_k$ has a rank at most equal to $\betafb$ for any realization of the training matrix $\Xm$, leading to  $u_k^i=0$ for some $i$ and thus $D_k^{\rm tkl}(R) = \Theta(1)$. This completes the proof.


\section{The proof of Lemma \ref{lemma: MRT}}
\label{sec:MRT_lemma}
Given $\vv_k = \sqrt{\eta} \widehat{\hv}_k, ~\forall k \in [K]$ in MRT precoding, in order to satisfy the power constraint in \eqref{eq: V_power}, it is evident that the power scaling factor $\eta$ can be obtained from \eqref{eq:eta_MRT}.
Next, we derive the three terms $\mathbb{E}[\hv_k^\herm \vv_k]$, ${\rm Var}(\hv_k^\herm \vv_k)$ and $\mathbb{E}[|\hv_k^\herm \vv_j|^2]$ for $j \neq k$ in \eqref{eq:R_hard} as follows. First, we have
\begin{align}
        \mathbb{E}[\hv_k^\herm \vv_k] &= \sqrt{\eta} \mathbb{E}[{\hv_k^\herm \widehat{\hv}_k}] \nonumber \\
        &= \sqrt{\eta} \mathbb{E}[{(\widehat{\hv}_k + \ev_k)^\herm\widehat{\hv}_k}] \label{eq:h_v_k_0} \\
        &= \sqrt{\eta}\mathbb{E}[\widehat{\hv}_k^\herm \widehat{\hv}_k]\nonumber \\
        &=\sqrt{\eta} \trace(\Cm_{\widehat{\hv}_k}), \label{eq:h_v}
\end{align}
where \eqref{eq:h_v_k_0} holds due to \eqref{eq:h_hat}. Then, we have
\begin{align}
        &{\rm Var}(\hv_k^\herm \vv_k)\nonumber \\
        &= \mathbb{E}[(\hv_k^\herm \vv_k -\mathbb{E}[\hv_k^\herm \vv_k])(\hv_k^\herm \vv_k -\mathbb{E}[\hv_k^\herm \vv_k])^\herm] \nonumber \\
        &= \mathbb{E}[{\hv_k^\herm \vv_k\vv_k^\herm \hv_k}] - \eta \trace^2(\Cm_{\widehat{\hv}_k} ) \nonumber \\
        &=\eta \left(\mathbb{E}[{(\widehat{\hv}_k + \ev_k)^\herm \widehat{\hv}_k \widehat{\hv}_k^\herm (\widehat{\hv}_k + \ev_k)}] - \trace^2(\Cm_{\widehat{\hv}_k} ) \right)\nonumber \\
        &= \eta \left(\mathbb{E}[{\widehat{\hv}_k^\herm \widehat{\hv}_k \widehat{\hv}_k^\herm \widehat{\hv}_k}] + \mathbb{E}[{\ev_k^\herm \widehat{\hv}_k \widehat{\hv}_k^\herm \ev_k}] -  \trace^2(\Cm_{\widehat{\hv}_k} )\right) \label{eq:var_hv_0} \\
        &= \eta\left( \trace(\Cm_{\widehat{\hv}_k}^2) +\trace^2(\Cm_{\widehat{\hv}_k}) + \trace(\Cm_{\widehat{\hv}_k}  \Cm_{\ev_k})  - \trace^2(\Cm_{\widehat{\hv}_k} )\right) \label{eq:var_hv_1}\\
        &=\eta \left(\trace(\Cm^2_{\widehat{\hv}_k}) + \trace(\Cm_{\widehat{\hv}_k}  \Cm_{\ev_k})\right)\nonumber \\
        &= \eta \trace(\Cm_{\widehat{\hv}_k} \Cm_{{\hv}_k}),\label{eq:var_h_v}
\end{align}
where \eqref{eq:var_hv_0} holds since $\ev_k$ and $\widehat{\hv}_k$ are uncorrelated, and where the term $ \mathbb{E}[{\widehat{\hv}_k^\herm \widehat{\hv}_k \widehat{\hv}_k^\herm \widehat{\hv}_k}]$  from \eqref{eq:var_hv_0} to \eqref{eq:var_hv_1} is derived as follows. Let $\Cm_{\widehat{\hv}_k} = \Um_{\widehat{\hv}_k} \Lambdam_{\widehat{\hv}_k} \Um_{\widehat{\hv}_k}^{\herm}$ be the eigenvalue decomposition and denote $\widetilde{\hv}_k \triangleq \Um_{\widehat{\hv}_k}^{\herm} \widehat{\hv}_k$, we have $\widetilde{\hv}_k \sim \Cc\Nc(\mathbf{0}, \Lambdam_{\widehat{\hv}_k})$.
Further denoting $\widetilde{h}_{k, i}$ as the $i$-th element of $\widetilde{\hv}_{k}$ and $\lambda_{\widehat{\hv}_k, i}$ as the $i$-th eigenvalue of $\Cm_{\widehat{\hv}_k}$, we have 
\begin{align}
        &\mathbb{E}[{\widehat{\hv}_k^\herm \widehat{\hv}_k \widehat{\hv}_k^\herm \widehat{\hv}_k}]\nonumber \\ 
        &=\mathbb{E}[\|\widetilde{\hv}_k\|^2 \|\widetilde{\hv}_k\|^2] \nonumber \\
        &= \mathbb{E}\left[\left(\sum_{i=1}^{MN} |\widetilde{h}_{k, i}|^2\right)^2\right] \label{eq:4_h_1} \\
        &= \sum_{i=1}^{MN} \mathbb{E}[|\widetilde{h}_{k, i}|^4] + \sum_{i=1}^{MN} \sum_{j=1, j\neq i}^{MN} \mathbb{E}[|\widetilde{h}_{k, i}|^2|\widetilde{h}_{k, j}|^2] \nonumber \\
        &= \sum_{i=1}^{MN} 2 \lambda_{\widehat{\hv}_k, i}^2 + \sum_{i=1}^{MN} \sum_{j=1, j\neq i}^{MN} \lambda_{\widehat{\hv}_k, i} \lambda_{\widehat{\hv}_k, j} \label{eq:4_h_0} \\
        &= \sum_{i=1}^{MN} 2 \lambda_{\widehat{\hv}_k, i}^2 + \sum_{i=1}^{MN} \lambda_{\widehat{\hv}_k, i} \left(\left(\sum_{j=1}^{MN}  \lambda_{\widehat{\hv}_k, j}\right) - \lambda_{\widehat{\hv}_k, i}\right) \nonumber \\
        &= \sum_{i=1}^{MN} 2 \lambda_{\widehat{\hv}_k, i}^2 + \sum_{i=1}^{MN} \lambda_{\widehat{\hv}_k, i} \sum_{j=1}^{MN}  \lambda_{\widehat{\hv}_k, j} - \sum_{i=1}^{MN} \lambda_{\widehat{\hv}_k, i}^2 \nonumber \\
        &= \trace(\Cm_{\widehat{\hv}_k}^2) + \trace^2(\Cm_{\widehat{\hv}_k}),
\end{align}
where \eqref{eq:4_h_0} holds based on [Appendix A.2.4]\cite{mimo2016marzetta}, which states that given a random variable $z \sim \Cc\Nc(0, \lambda)$, the fourth-order moment is given as $\mathbb{E}[|z|^4] = 2\lambda^2$.
Finally, we have
\begin{align}
        \mathbb{E}[|\hv_k^\herm \vv_j|^2] &= \eta\mathbb{E}[|(\widehat{\hv}_k + \ev_k)^\herm \widehat{\hv}_j|^2] \nonumber \\
        &=\eta \mathbb{E}[\widehat{\hv}_j^\herm ( \widehat{\hv}_k + \ev_k) (\widehat{\hv}_k + \ev_k)^\herm \widehat{\hv}_j] \nonumber \\
        &= \eta \left(\mathbb{E}[\widehat{\hv}_j^\herm \widehat{\hv}_k \widehat{\hv}_k^\herm \widehat{\hv}_j] + \mathbb{E}[\widehat{\hv}_j^\herm \ev_k \ev_k^\herm \widehat{\hv}_j] \right)\nonumber \\
        &= \eta\trace(\Cm_{\widehat{\hv}_j} \Cm_{\widehat{\hv}_k} + \Cm_{\widehat{\hv}_j}\Cm_{\ev_k} ) \nonumber \\
        &= \eta\trace( \Cm_{\widehat{\hv}_j} \Cm_{\hv_k}), \label{eq: h_v_j}
\end{align}
where \eqref{eq: h_v_j} holds due to the fact that $\Cm_{\hv_k} = \Cm_{\widehat{\hv}_k} + \Cm_{\ev_k}$.
Combining \eqref{eq:h_v}, \eqref{eq:var_h_v} and \eqref{eq: h_v_j}, the closed-form expression of the UatF rate under MRT precoding is given as \eqref{eq:R_hard_MRT}.

\section{the proof of Lemma \ref{lemma: ZF}}\label{sec:proof_ZF}
Given $\Vm  = \sqrt{\widetilde{\eta}}  \widehat{\Hm} (\widehat{\Hm}^{\herm} \widehat{\Hm})^{-1}$ in ZF precoding, according to the power constraint in \eqref{eq: V_power}, it is evident to obtain the result in \eqref{eq:V_eta_ZF}. 
Next, we derive three terms $\mathbb{E}[\hv_k^\herm \vv_k]$, ${\rm Var}(\hv_k^\herm \vv_k)$ and $\mathbb{E}[|\hv_k^{\herm} \vv_j|^2]$ for $j \neq k$ in \eqref{eq:R_hard}.
Based on the properties of ZF precoding, the inner product of $\widehat{\hv}_i$ and $\vv_j$ is given by 
\begin{equation}\label{eq:prop_ZF}
\widehat{\hv}_i^{\herm} \vv_j =
    \begin{cases}
        \sqrt{\widetilde{\eta}} & \text{if } i = j,\\
        0 & \text{if } i \neq j,
    \end{cases} ~\forall~ i, j \in [K].
\end{equation}
First, we have
\begin{align}
        \mathbb{E}[\hv_k^\herm \vv_k] &= \mathbb{E}[ (\widehat{\hv}_k + \ev_k)^{\herm} \vv_k] \nonumber \\
        &= \mathbb{E}[ \widehat{\hv}_k^{\herm} \vv_k] + \mathbb{E}[ \ev_k^{\herm} \vv_k] \nonumber \\
        &= \sqrt{\widetilde{\eta}}, \label{eq:h_v_zf}
\end{align}
where \eqref{eq:h_v_zf} holds according to \eqref{eq:prop_ZF}. Then, we have
\begin{align}
        &{\rm Var}(\hv_k^\herm \vv_k) = \mathbb{E}[(\hv_k^\herm \vv_k -\mathbb{E}[\hv_k^\herm \vv_k])(\hv_k^\herm \vv_k -\mathbb{E}[\hv_k^\herm \vv_k])^\herm] \nonumber \\
        &= \mathbb{E}[{\hv_k^\herm \vv_k\vv_k^\herm \hv_k}] - (\mathbb{E}[\hv_k^\herm \vv_k])^2 \nonumber \\
        &=  \mathbb{E}[{(\widehat{\hv}_k + \ev_k)^\herm \vv_k\vv_k^\herm (\widehat{\hv}_k + \ev_k)}] - \widetilde{\eta} \nonumber \\
        &= \mathbb{E}[{\ev_k^\herm \vv_k\vv_k^\herm \ev_k}]  +  \mathbb{E}[{\widehat{\hv}_k^\herm \vv_k\vv_k^\herm \widehat{\hv}_k}] - \widetilde{\eta} \label{eq:var_h_v_zf_0} \\
        &=  \mathbb{E}[{\ev_k^\herm \vv_k\vv_k^\herm \ev_k}] \nonumber \\
        &= \tr(\Cm_{\vv_k} \Cm_{\ev_k}), \label{eq:var_h_v_zf}
\end{align}
where $\Cm_{\vv_k} \triangleq \bE[\vv_k\vv_k^\herm]$ and  \eqref{eq:var_h_v_zf_0} holds since $\ev_k$ and $\vv_k$ are uncorrelated. Finally, we have
\begin{align}
        \mathbb{E}[|\hv_k^{\herm} \vv_j|^2] &= \mathbb{E}[|( \widehat{\hv}_k + \ev_k)^{\herm} \vv_j|^2] \nonumber \\
        &= \trace\left(\mathbb{E}[( \widehat{\hv}_k + \ev_k)^{\herm} \vv_j \vv_j^{\herm}( \widehat{\hv}_k + \ev_k)]\right)  \nonumber \\
        % &= \trace\left(\mathbb{E}[\widehat{\hv}_k^{\herm} \vv_j \vv_j^{\herm}(\widehat{\hv}_k + \ev_k)] + \mathbb{E}[\ev_k^{\herm} \vv_j \vv_j^{\herm}(\widehat{\hv}_k + \ev_k)]\right)  \nonumber \\
        &= \trace\left(\mathbb{E}[\ev_k^{\herm} \vv_j \vv_j^{\herm}\ev_k]\right) \label{eq:h_k_v_j_zf_0} \\
        &= \trace(\Cm_{\vv_j} \Cm_{\ev_k}), \label{eq:h_k_v_j_zf}
\end{align}
where \eqref{eq:h_k_v_j_zf_0} holds based on \eqref{eq:prop_ZF}.
Combing \eqref{eq:h_v_zf}, \eqref{eq:var_h_v_zf} and \eqref{eq:h_k_v_j_zf}, the UatF rate under ZF precoding is given by
\begin{align}\label{eq:R_zf_org}
    R_k^{{\rm ZF}} = \log\left(1 + \frac{\widetilde{\eta} }{\tr(\Cm_{\vv_k} \Cm_{\ev_k}) + \sum_{j \neq k} \trace(\Cm_{\vv_j} \Cm_{\ev_k}) + 1}\right),
\end{align}
where the denominator in \eqref{eq:R_zf_org} can be further simplified as  
\begin{align}
     &\tr(\Cm_{\vv_k} \Cm_{\ev_k}) + \sum_{j \neq k} \trace(\Cm_{\vv_j} \Cm_{\ev_k}) = \trace\left(\left(\sum_{k=1}^K \Cm_{\vv_k}\right) \Cm_{\ev_k}\right) \nonumber \\
    &=  \trace\left(\left(\sum_{k=1}^K \mathbb{E}[\vv_k \vv_k^{\herm}]\right)\Cm_{\ev_k}\right) \nonumber \\
     &=  \trace\left(\mathbb{E}\left[\Vm \Vm^{\herm}\right]\Cm_{\ev_k}\right) \nonumber \\
     &=\widetilde{\eta} \trace\left(\mathbb{E}\left[\widehat{\Hm} (\widehat{\Hm}^{\herm} \widehat{\Hm})^{-1}(\widehat{\Hm}^{\herm} \widehat{\Hm})^{-1} \widehat{\Hm}^{\herm}\right]\Cm_{\ev_k}\right) \nonumber \\
     &=\widetilde{\eta} \trace\left(\mathbb{E}\left[\widehat{\Hm} (\widehat{\Hm}^{\herm} \widehat{\Hm})^{-2} \widehat{\Hm}^{\herm}\right]\Cm_{\ev_k}\right) \label{eq:denominator}.
\end{align}
Putting \eqref{eq:denominator} back to \eqref{eq:R_zf_org}, we have the UatF rate expressions under ZF precoding as in  \eqref{eq:R_hard_ZF}.



