\title{\begin{center} An AI Approach for Learning the Spectrum of the Laplace-Beltrami Operator \end{center}}

\author{
\begin{center}
\name{Yulin An\textsuperscript{$\ast$}\thanks{Y.A. e-mail: yba5115@psu.edu} and Enrique del Castillo\textsuperscript{$\ast,\dagger$}\thanks{E.D.C., corresponding author, e-mail: exd13@psu.edu}}
