\section{Parallel Sparse LQR} \label{sec:parallel_lqr}

\subsection{Connection to Parallel Scan}
We now fit an LQR problem $\mathcal{P}_1^i$ into the parallel scan framework to achieve temporal parallelism. 
Let us consider a time-varying finite horizon LQR problem without tree structures:
\begin{equation} \label{eq:LQR}
    \begin{split} 
    \min _{\boldsymbol{x}, \boldsymbol{u}} &\sum _{k=0}^{N-1}\begin{bmatrix}
        q_{k} \\  r_{k} 
    \end{bmatrix} ^\top 
    \begin{bmatrix} x_k \\ u_k \end{bmatrix} + \frac{1}{2}
    \begin{bmatrix} x_k \\ u_k \end{bmatrix} ^\top 
    \begin{bmatrix}
        Q_{k} &  M_{k}^\top\\ M_{k} & R_{k}
    \end{bmatrix} 
    \begin{bmatrix} x_k \\ u_k \end{bmatrix} \\ 
    &\quad\quad + q_N^\top x_N + \frac{1}{2} x_N^\top Q_N x_N \\
    \text{s.t.} &\; x_{k+1} = A_kx_k + B_ku_k + c_k,\; \forall k \in [0, N-1],
    \end{split} 
\end{equation}
where $\boldsymbol{x} := (x_k)_{k \in [0, N]}$, $\boldsymbol{u} := (u_k)_{k \in [0, N-1]}$, and $N$ is the horizon length.
% \bluetext{Note that this problem does not have a tree structure. We postpone the discussion of the LQR-Tree problem to Section \ref{sec:parallel_bmpc}.}
% \bluetext{The problem in \ref{eq:LQR} can be formulated in either sparse or dense form \cite{Borrelli2017PredictiveCF}. We first introduce the sparse formulation, which can be efficiently solved using dynamic programming (DP) through backward and forward passes.}
We denote the optimal state and input sequences by $\boldsymbol{x}^*$ and $\boldsymbol{u}^*$, respectively.
\subsubsection{Backward Pass}
We recursively solve the Bellman equations, starting from the final step and working backward to the initial step.
The Bellman equation is expressed as: 
\begin{equation*}
\begin{split} 
    V_{k}(x_{k}) =\min _{u_{k}} &\;\; \ell_{k}(x_{k},u_{k}) + V_{k+1}(x_{k+1})\\
    \text{s.t.} &\;\; x_{k+1} = A_kx_k+ B_ku_k + c_k,
\end{split} 
\end{equation*}
with $V_N(x_N) = q_N^\top x_N + \frac{1}{2} x_N^\top Q_N x_N$. It is known that the value function $V_k: \mathbb{R}^{n_x} \to \mathbb{R}$ has a quadratic form:
\begin{equation}
    V_k(x_k) = z + p_k^\top x_k + \frac{1}{2} x_k^\top P_k x_k,
\end{equation}
where $z$ denotes an arbitrary constant. 
Using the value functions, we can compute the optimal control laws and subsequently recover the optimal state and input trajectories through the forward rollout. 
This dynamic programming (DP)-based algorithm is an inherently sequential approach, since the value function at the next step $V_{k+1}$ needs to be computed before $V_{k}$ can be determined.
To parallelize the DP process, the entire prediction horizon is divided into smaller segments that can be processed in parallel.
This motivates us to define the conditional value function \cite{SarkkaTemporal2023}, $V_{k\to i}: \mathbb{R}^{n_x}\times \mathbb{R}^{n_x} \to \mathbb{R}$, which represents the cost of the optimal trajectory starting from $x_k$ and ending at $x_i$. 
The conditional value function is related to the fixed-end LQR problem, which is formulated as
\begin{equation} \label{eq:con_value_fun} 
\begin{split} 
     \min_{u_{k:i-1}} &\sum_{n=k}^{i-1}\ell_{n}(x_{n},u_{n}) := V_{k\to i}(x_{k},x_{i}) \\
    \text{s.t.} &\; x_{n+1} = A_nx_n + B_nu_n + c_n,\; \forall n \in [k, i-1].
\end{split} 
\end{equation} 
If the state $x_i$ is not reachable from $x_k$, indicating an infeasible problem, then the corresponding conditional value function becomes infinite.

Next, we decompose the computation of $V_{k\to i}$ into two subproblems: $V_{k\to j}: \mathbb{R}^{n_x}\times \mathbb{R}^{n_x} \to \mathbb{R}$ and  $V_{j\to i}: \mathbb{R}^{n_x}\times \mathbb{R}^{n_x} \to \mathbb{R}$. 
The optimal trajectories for the two subproblems are linked by the intermediate state $x_j$. To recover $V_{k\to i}$, as derived in \cite{SarkkaTemporal2023}, we minimize the sum of two conditional value functions over the intermediate state:
\begin{align}
    V_{k\to i}(x_k, x_i) &= V_{k\to j}(x_k, x_j) \oplus V_{j\to i}(x_j, x_i) \\
    &= \min_{x_j}\; V_{k\to j}(x_k, x_j) + V_{j\to i}(x_j, x_i), \label{eq:V_ki_min} \\ \nonumber 
    &\; \quad \quad \quad \quad \quad \quad \quad \quad \quad k < j < i \leq N. \nonumber
\end{align}
Similarly, the value function decomposition is expressed as
\begin{align}
     V_{k}(x_k) &= V_{k\to i}(x_k, x_i) \oplus V_{i}(x_i)\\
     &= \min_{x_i}\; V_{k\to i}(x_k,x_i) + V_i(x_i),\; k < i \leq N. \label{eq:V_k_min} 
\end{align}
In the case of LQR problems, the closed-form solutions to \eqref{eq:V_ki_min} and \eqref{eq:V_k_min} can be derived, which is critical for efficient computation. 
For clarity, we now focus on the connection between the parallel scan and the LQR problem, postponing the discussion of the analytical forms for later.
In an LQR problem, we can interpret the one-step conditional value function $V_{k\to k+1}$ as the input array element $a_k$ in \eqref{eq:array_element}. 
In this setting, the input to the parallel scan algorithm is the array of the one-step conditional value functions, $\left[ V_{0\to 1}, V_{1\to 2}, \dots, V_{N} \right]$, and the corresponding output is the collection of the value functions, $\left[ V_{0}, V_{1}, \dots, V_{N} \right]$.
The associative operator $\oplus$ used to combine two elements is defined by equations \eqref{eq:V_ki_min} and \eqref{eq:V_k_min}.
After completing the parallel scan, we can determine the affine control law in parallel, with a time complexity of $O(1)$: 
\begin{equation} \label{eq:feedback_laws}
\begin{aligned}
    K_k &= -\left(R_k + B_k^\top P_{k+1} B_k\right)^{-1} \left( M_k + B_k^\top P_{k+1} A_k \right), \\
    k_k &= -\left(R_k + B_k^\top P_{k+1} B_k\right)^{-1} \left[ r_k + B_k^\top \left( p_{k+1} + P_{k+1}c_k \right) \right].
\end{aligned}
\end{equation}

\subsubsection{Forward Pass} \label{subsubsec:par_lin_rollout}
We conduct a linear rollout to obtain the optimal state and input trajectories using all the feedback gains and affine terms derived in \eqref{eq:feedback_laws}:
\begin{align*}
    u_k^* &= K_k x_k^* + k_k, \\
    x_{k+1}^* &= A_k x_k^* + B_k u_k^* + c_k \\
    &= (A_k + B_k K_k) x_k^* + c_k+ B_k k_k \\
    &= \tilde{A}_k x_k^* + \tilde{c}_k := f_k^{\text{lin}}(x_k^*),
\end{align*} 
where $\tilde{A}_k = A_k + B_k K_k$ and $\tilde{c}_k = c_k+ B_k k_k $.
Due to the affine structure, the parallel scan can also be applied to accelerate this process.
Let us figure out the combination rule.
We express $x_i^*$ in terms of $x_k^*$ for $i > k$, yielding $x_i^* = f_{k\to i}^{\text{lin}}(x_k^*) = \tilde{A}_{k,i} x_k^* + \tilde{c}_{k,i}$.
The computation of $\tilde{A}_{k,i}$ and $\tilde{c}_{k,i}$ can be split into two parts, forming the combination rule for the forward pass:
\begin{align}
    x_i^* &= f_{k\to j}^{\text{lin}}(x_k^*) \oplus f_{j\to i}^{\text{lin}}(x_j^*) \\
    &= \tilde{A}_{j,i} ( \tilde{A}_{k,j} x_k^* + \tilde{c}_{k,j}) + \tilde{c}_{j,i} \nonumber, \\
    \implies \tilde{A}_{k,i} &= \tilde{A}_{j,i}\tilde{A}_{k,j},\;  
    \tilde{c}_{k,i} = \tilde{A}_{j,i} \tilde{c}_{k,j} + \tilde{c}_{j,i}.
\end{align}
Next, we define the input array for the parallel scan using the one-step dynamics $f_{k\to k+1}^{\text{lin}}(\cdot)$:
\begin{equation}
    \left[f_{0\to 1}^{\text{lin}}, f_{1\to 2}^{\text{lin}}, \dots, f_{N-1\to N}^{\text{lin}} \right],
\end{equation}
where for $k \in [0,N-1]$, the dynamics matrices in $f_{k\to k+1}^{\text{lin}}$ are
\begin{equation}
    \tilde{A}_{k\to k+1} = \tilde{A}_k, \; \tilde{c}_{k\to k+1} = \tilde{c}_k.
\end{equation}
The output array, resulting from the parallel scan, is then expressed as
\begin{equation}
    [f_{0\to 1}^{\text{lin}}, f_{0\to 2}^{\text{lin}}, \dots, f_{0\to N}^{\text{lin}}], \label{eq:forward_output}
\end{equation}
where each element is given by:
\begin{align}
    f_{0\to i}^{\text{lin}}(x) &= f_{0\to 1}^{\text{lin}} \oplus f_{1\to 2}^{\text{lin}} \dots \oplus f_{i-1\to i}^{\text{lin}} 
    = \tilde{A}_{0,i}x + \tilde{c}_{0,i}.
\end{align}
Finally, the optimal state trajectory $[x^*_1, x^*_2, \dots, x^*_{N}]$ can be obtained by evaluating \eqref{eq:forward_output} at the initial state $x_0$. 


