\subsection{Conditional Value Function} \label{subsec:dual_value_function}
The optimization problem \eqref{eq:con_val_fun_dense} can be reformulated as
\begin{equation}
\begin{aligned}
    V_{k\to i}(x_k, x_i) \\ = \min_{\boldsymbol{u}_k} \max_{\lambda} & 
    \begin{bmatrix}
        g_{q,k} \\  g_{r,k} 
    \end{bmatrix} ^\top 
    \begin{bmatrix} x_k \\ \boldsymbol{u}_k \end{bmatrix} + \frac{1}{2}
    \begin{bmatrix} x_k \\ \boldsymbol{u}_k \end{bmatrix} ^\top 
    \begin{bmatrix}
        H_{Q,k} &  H_{M,k}^\top\\ H_{M,k} & H_{R,k}
    \end{bmatrix} 
    \begin{bmatrix} x_k \\ \boldsymbol{u}_k \end{bmatrix}
    \\ 
    &\quad + \lambda^\top \left( x_i - \bar{A}_k x_k - \bar{B}_k\boldsymbol{u}_k - \bar{c}_k \right).
\end{aligned}
\end{equation}
By applying the duality theorem, we interchange the order of the max and min operators, resulting in
\begin{equation*}
    \begin{aligned}
        V_{k\to i}(x_k, x_i) = \max_{\lambda}\; g_{k\rightarrow i}(\lambda;x_k,x_i),
    \end{aligned}
\end{equation*}
where the inner optimization is expressed as
\begin{equation}
    \begin{aligned}
        & g_{k\rightarrow i}(\lambda;x_k,x_i) \\
        =& \min_{\boldsymbol{u}_k} \frac{1}{2} \boldsymbol{u}_k^\top H_{R,k} \boldsymbol{u}_k 
        - (\lambda^\top \bar{B}_k - g_{r,k}^\top - x_k^\top H_{M,k}^\top) \boldsymbol{u}_k  \\
        & + g_{q,k}^\top x_k + \frac{1}{2} x_k^\top H_{Q,k} x_k + \lambda^\top (x_i- \bar{A}_k x_k - \bar{c}_k) \\
        = & \min_{\boldsymbol{u}_k}\; \mathcal{E}( \lambda, u_k, x_k, x_i )
    \end{aligned}
\end{equation}
By setting $\frac{\partial \mathcal{E}}{\partial \boldsymbol{u}_k} = 0$, we obtain the optimal control input
\begin{equation}
    \boldsymbol{u}_k^* = H_{R,k}^{-1} ( \bar{B}_k^\top \lambda  - g_{r,k} -  H_{M,k} x_k ) = H_{R,k}^{-1} \chi_k. \label{eq:control_condensed}
\end{equation}
Substituting \eqref{eq:control_condensed} into $\mathcal{E}( \lambda, u_k, x_k, x_i )$, we have
\begin{equation}
    \begin{aligned}
    & g_{k\rightarrow i}(\lambda;x_k,x_i)  \\
    =& -\frac{1}{2} \chi_k^\top H_{R,k}^{-1} \chi_k + \lambda^\top (x_i - \bar{A}_k x_k - \bar{c}_k) \\
     &+ g_{q,k}^\top x_k  + \frac{1}{2} x_k^\top H_{Q,k} x_k\\
    =& \frac{1}{2} x_k^\top \left(H_{Q,k} -H_{M,k}^\top H_{R,k}^{-1} H_{M,k}\right) x_k \\
     & + \left(g_{q,k}^\top - g_{r,k}^\top H_{R,k}^{-1} H_{M,k} \right) x_k \\
     & - \frac{1}{2} \lambda^\top \bar{B}_k H_{R,k}^{-1} \bar{B}_k^\top \lambda  -\frac{1}{2} g_{r,k}^\top H_{R,k}^{-1} g_{r,k} \\
     & + \lambda^\top \left( x_i - \left(\bar{A}_k - \bar{B}_k H_{R,k}^{-1} H_{M,k} \right) x_k - \left(\bar{c}_k - \bar{B}_k H_{R,k}^{-1} g_{r,k}\right) \right).
     % & + \lambda^T \bar{B}_k H_{R,k}^{-1} g_{r,k} + \lambda^T \bar{B}_k H_{R,k}^{-1} H_{M,k} x_k  \\
    \end{aligned}
\end{equation}
This expression aligns with \eqref{eq:sol_min}.

\subsection{Combination Rule} \label{subsec:comb_rule}
We express the combination of the two conditional value functions, $V_{k\to j}(x_k, x_j)$ and $V_{j\to i}(x_j, x_i)$ as
\begin{align}
    &V_{k\to i}(x_k, x_i) \nonumber \\ & = \min_{x_j}\, \left\{ \max_{\lambda_1 }\,g_{k\to j}(\lambda_1;x_{k}, x_{j}) + \max_{\lambda_2 }\,g_{j\to i}(\lambda_2;x_{j},x_{i}) \right\} \nonumber \\
    &= \max_{\lambda_1, \lambda_2} \min_{x_j} g_{k\to j}(\lambda_1;x_{k}, x_{j}) + g_{j\to i}(\lambda_2;x_{j},x_{i}) \nonumber \\
    &= z + \max_{\lambda_2, \lambda_1} \min_{x_j}  
    \left\lbrace \frac{1}{2}x_{k}^{\top}P_{k,j}x_{k} + p_{k,j}^{\top} x_{k} -\frac{1}{2}\lambda_1 ^{\top }C_{k,j}\lambda_1 \right. \nonumber \\
    & \quad \left. + \lambda_1^{\top }\left(x_{j} - A_{k,j}x_{k} - c_{k,j}\right) + 
    \frac{1}{2}x_{j}^{\top}P_{j,i}x_{j} + p_{j,i}^{\top} x_{j} \right. \nonumber \\ 
    & \quad \left. -\frac{1}{2}\lambda_2 ^{\top }C_{j,i}\lambda_2 + \lambda_2^{\top }\left(x_{i} - A_{j,i}x_{j} - c_{j,i}\right)
    \right\rbrace \nonumber \\ 
    &= z + \max_{\lambda_2, \lambda_1} \min_{x_j}\; \Omega\left( x_j, \lambda_1; x_k, x_i, \lambda_2 \right), \label{eq:min-max}
\end{align}
where $z$ is a constant. 
We derive the solution of the min-max problem in \eqref{eq:min-max} over $x_j$ and $\lambda_1$ by setting the gradients of $\Omega$ with respect to the two variables to zero:
\begin{align}
    P_{j,i} x_j &= -\lambda_1 - p_{j,i} + A^\top_{j,i}\lambda_2, \label{eq:grad_x} \\
    x_j &= C_{k,j}\lambda_1 + A_{k,j}x_k + c_{k,j}. \label{eq:grad_lambda}
\end{align}
Combing \eqref{eq:grad_x} and \eqref{eq:grad_lambda}, we obtain the expression for $\lambda_1$:
\begin{equation}
    \lambda_1 = (I + P_{j,i}C_{k,j})^{-1}\left[ - p_{j,i} + A^\top_{j,i}\lambda_2 - P_{j,i}\left( A_{k,j}x_k + c_{k,j}\right) \right]. \label{eq:lambda1}
\end{equation}
Substituting \eqref{eq:grad_lambda} into $\Omega$ in \eqref{eq:min-max}, we obtain
\begin{align*}
    \Omega = 
    \frac{1}{2} c_{k,j}^\top p_{j,i} + 
    \frac{1}{2}x_{k}^{\top}P_{k,j}x_{k} + \left( p_{k,j} + \frac{1}{2}A_{k,j}^\top p_{j,i} \right)^{\top} x_{k} \\
    -\frac{1}{2}\lambda_2 ^{\top }C_{j,i}\lambda_2 + \lambda_2^\top \left( x_i - \frac{1}{2} A_{j,i}A_{k,j}x_k - c_{j,i} - \frac{1}{2}A_{j,i} c_{k,j} \right) \\
    + \frac{1}{2} \Big(  
    \lambda_1^\top C_{k,j} p_{j,i} 
    - \lambda_1^\top C_{k,j} A^\top_{j,i} \lambda_2
    - x_k^\top A_{k,j}^\top \lambda_1  
    - c_{k,j}^\top \lambda_1 
    \Big).
\end{align*}
Next, we eliminate $\lambda_1$ using \eqref{eq:lambda1}. The resulting expression includes quadratic terms in \( x_k \) and \( \lambda_2 \), 
linear terms in \( x_k \) and \( \lambda_2 \), as well as a cross term involving \( x_k \) and \( \lambda_2 \). 
By matching these terms with those in \eqref{eq:sol_min}, we obtain
\begin{equation}    
\begin{aligned} \label{eq:p_ki}
    P_{k,i} &= P_{k,j} + A_{k,j}^\top (I + P_{j,i}C_{k,j})^{-1} P_{j,i} A_{k,j}, \\
    p_{k,i} &= p_{k,j} + \frac{1}{2}\left[-A_{k,j}^\top P_{j,i} \left( I + C_{k,j}P_{j,i} \right)^{-1} C_{k,j}p_{j,i} + A_{k,j}^\top p_{j,i} \right. \\
    &\quad \left. + A_{k,j}^\top P_{j,i} \left(I + C_{k,j}P_{j,i} \right)^{-1} c_{k,j} \right. \\
    &\quad \left. + A_{k,j}^\top (I + P_{j,i}C_{k,j})^{-1} \left( P_{j,i}c_{k,j} + p_{j,i} \right)
    \right] 
\end{aligned} 
\end{equation}
We can further simplify the expression for $p_{k,i}$ in \eqref{eq:p_ki} using the Woodbury matrix identity, yielding
\begin{align*}
    p_{k,i}
    &= p_{k,j} + \frac{1}{2}\left[A_{k,j}^\top \left( I - P_{j,i} \left( I + C_{k,j}P_{j,i} \right)^{-1} C_{k,j} \right) p_{j,i}  \right. \\
    &\quad \left. + A_{k,j}^\top \left(I + P_{j,i}C_{k,j} \right)^{-1} P_{j,i} c_{k,j} \right. \\
    &\quad \left. + A_{k,j}^\top (I + P_{j,i}C_{k,j})^{-1} \left( P_{j,i}c_{k,j} + p_{j,i} \right) \right] \\
    &= p_{k,j} + \frac{1}{2}\left[A_{k,j}^\top \left(I + P_{j,i}C_{k,j} \right)^{-1} p_{j,i}  \right. \\
    &\quad \left. + A_{k,j}^\top \left(I + P_{j,i}C_{k,j} \right)^{-1} P_{j,i} c_{k,j} \right. \\
    &\quad \left. + A_{k,j}^\top (I + P_{j,i}C_{k,j})^{-1} \left( P_{j,i}c_{k,j} + p_{j,i} \right)
    \right] \\
    &= p_{k,j} + A_{k,j}^\top (I + P_{j,i}C_{k,j})^{-1} \left( P_{j,i}c_{k,j} + p_{j,i} \right)
\end{align*}
Similarly, we can derive $C_{k,i}$, $A_{k,i}$ and $c_{k,i}$ as follows:
\begin{align*}
    C_{k,i} &= C_{j,i} + A_{j,i} \left( I + C_{k,j}P_{j,i} \right)^{-1} C_{k,j} A^\top_{j,i}, \\
     A_{k,i} &= \frac{1}{2}\left[ A_{j,i} C_{k,j} \left( I + P_{j,i}C_{k,j} \right)^{-1} P_{j,i} A_{k,j} - A_{j,i}A_{k,j} \right. \\ 
    &\quad \quad \quad - \left. A_{j,i} \left( I + C_{k,j}P_{j,i} \right)^{-1} A_{k,j}  
    \right] \\
    &= -A_{j,i} \left( I + C_{k,j}P_{j,i} \right)^{-1} A_{k,j}, \\
    c_{k,i} &= c_{j,i} + \frac{1}{2} \left[ A_{j,i} \left( I + C_{k,j}P_{j,i} \right)^{-1} \left( C_{k,j} p_{j,i} - c_{k,j}  \right) \right. \\
    & \left. + A_{j,i} C_{k,j} \left( I + P_{j,i}C_{k,j} \right)^{-1}p_{j,i} \right. \\
    & \left. - A_{j,i}c_{k,j} + A_{j,i} C_{k,j} \left( I + P_{j,i}C_{k,j} \right)^{-1} P_{j,i}c_{k,j} \right] \\
    &= c_{j,i} + A_{j,i} \left( I + C_{k,j}P_{j,i} \right)^{-1} \left( C_{k,j} p_{j,i} - c_{k,j}  \right).
\end{align*}

