\section*{Appendix}

This appendix contains the proofs of selected results from the main body of the paper.

\paragraph*{Energy-positional Determinacy}

\begingroup
\def\thelemma{\ref{lem:pos-determinacy}}
\begin{lemma}
    Let $\mathcal{G}$ be an energy game over $(\E, \leq)$.
    For all positions $g\in G$ and energies $e \in \E$ either the defender or the attacker wins $\mathcal{G}[g,e]$. Then, there exists an energy-positional winning strategy, i.e.\ a winning strategy that depends only on the current position and energy level. 
\end{lemma}
\addtocounter{lemma}{-1}
\endgroup

\begin{proof}
The (energy-positional) determinacy follows from the positional determinacy of parity games. We define a parity game $\mathcal{P_G} := (G_{\mathcal{G}},G_{\mathcal{G} 0}, E_{\mathcal{G}}, r_{\mathcal{G}})$ where 
    \begin{itemize}
        \item $G_{\mathcal{G}} := \lbrace (g,e) \ | \ g\in G, e \in \E\uplus \lbrace \bot \rbrace \rbrace$,
        \item $G_{\mathcal{G} 0} := G_{\mathcal{G}} \setminus G_{\mathcal{G} 1}$ with $ G_{\mathcal{G} 1} := \lbrace (g,e) \in G_{\mathcal{G}} \ | \ g\in G_a \lor e = \bot \rbrace$,
        \item $E_{\mathcal{G}} := \lbrace \left( (g,e) , (g', e') \right) \in G_{\mathcal{G}} \times G_{\mathcal{G}} \ | \ g \move{u} g' \land e \neq \bot \land u(e) = e' \rbrace$ and
        \item $r_{\mathcal{G}} : G_{\mathcal{G}} \rightarrow \mathbb{N} ,(g,e)\mapsto 0$.
    \end{itemize}  
This construction is similar to that of a configuration graph. Thereby, a play in $\mathcal{P_G}$ corresponds to a play in $\mathcal{G}$ and vice versa. 
Note that player~0 wins all infinite plays in $\mathcal{P_G}$ while the defender wins all infinite plays in $\mathcal{G}$.
By construction a position $(g,e)$ is a deadend in $\mathcal{P_G}$ if and only if $g$ is a deadend in $\mathcal{G}$ or $e=\bot$.
Hence, a play is won by the defender (resp. attacker) in $\mathcal{G}$ if and only if the corresponding play is won by player~0 (resp. player~1) in $\mathcal{P_G}$. 


Let $e\in \E$ and $g \in G$.
Since parity games are positionally determined, there exists a positional winning strategy $s$ for player~0 or player~1 when starting in  $(g,e)$. Define $s_p: G^* G_p \rightarrow G$ by setting $s_p (g_0 ... g_n) := g'$ with $s  \left( g_n, EL(g_0 ... g_n, e) \right) = (g',e')$ if $g_n \in G_p$, where $G_p = G_d $ if player~0 wins and $G_p = G_a$ else. Note that this strategy is an energy-positional winning strategy.\qedhere

\end{proof}

\paragraph*{Complexity}

\begingroup
\def\thetheorem{\ref{thm:complexity}}
\begin{theorem}[Complexity]
    Let $\mathcal{G}=(G, G_a, \move{ \ } )$ be a Galois energy game over $(\E, \leq)$. Further, let
    \begin{itemize}
        \item $o$ be the branching degree of the underlying graph,
        \item $t_{\sup}$ be an upper bound of the time to compute the supremum of two energies,
        \item $t_{\leq}$ be an upper bound of the time to compute the comparison of two energies,
        \item $t_{{\circlearrowleft}}$ be an upper bound of the time to compute $u^{\circlearrowleft} (e)$ for any update $u$ in $\mathcal{G}$ and $e \in \E$, and
        \item $e_\mathit{worst} := \sup \lbrace u_1^{\circlearrowleft} \circ ... \circ u_i^{\circlearrowleft} (\min \E) \ | \ i \in \lbrace 0, ..., \relSize{G} -1 \rbrace \  \land \ u_1, ..., u_i \text{ are updates in } \mathcal{G} \rbrace$ be the highest energy obtainable using up to $\relSize{G} -1$ reverse updates applied to the least element of $\E$.
    \end{itemize}   
    Then, \autoref{alg:game-algorithm} on input $\mathcal{G}$ terminates in a time in 
    \begin{align*}
        &\mathcal{O}\left(\relSize{G}^2 \cdot o \cdot \h(e_\mathit{worst}) \cdot \w(e_\mathit{worst})^2 \cdot (t_\circlearrowleft + t_{sup} + \w(e_\mathit{worst}) \cdot t_{\leq} )\right),\\
        &\text{and in }\mathcal{O}\left(\relSize{G}^2 \cdot o \cdot \w(e_\mathit{worst})^2 \cdot (t_\circlearrowleft + t_{sup} + \w(e_\mathit{worst}) \cdot t_{\leq} )\right) \text{, if }\mathcal{G} \text{ is declining.}
    \end{align*}
    In both cases, the output is calculated using space in $\mathcal{O} \left( \relSize{G} \cdot \w(e_\mathit{worst}) \cdot s_\E \right)$ where $s_\E$ is an upper bound for the space needed to store any energy.
\end{theorem}
\addtocounter{theorem}{-1}
\endgroup

\begin{proof}
\begin{sloppypar}
    If all successors of a defender position $g_d$ were previously assigned a non-empty set, then $g_d$ will be assigned a non-empty set in the next iteration. Similarly, if any successor of an attacker position $g_a$ was assigned a non-empty set, then $g_a$ will be assigned a non-empty set next. 
    After $\relSize{G}$ iterations the information, which positions are winnable for the attacker, has traveled from defender deadlocks to all other winnable positions, i.e.\ $\forall g \in G. \ \wina (g) \neq \varnothing \longleftrightarrow \mathsf{Iteration}^{\relSize{G}}(\mathbf{0})(g)  \neq \varnothing$. 
    This allows us to calculate an upper bound for the energies being assigned to positions during the run of the algorithm, i.e.\ $e_\mathit{worst}$. 

    If  $\mathcal{G}$ is declining, then cycles do not benefit the attacker and a fixed point is reached in $\mathcal{O}(\relSize{G})$ iterations. In both, declining and non-declining games, only sets in $\mathsf{antichain}_{\leq e_\mathit{worst}}$ are assigned to positions as candidates for minimal attacker winning budgets. 
    Each set in $\mathsf{antichain}_{\leq e_\mathit{worst}}$ can only truly be updated at most as many times as the maximal length of chains in $\mathsf{antichain}_{\leq e_\mathit{worst}}$ w.r.t.\ inclusion of upward-closures is long, i.e.\ at most ${\textstyle{\sup_\N} \lbrace i \in \N \ | \ \exists A_1,... ,A_{i} \in \mathsf{antichain}_{\leq e_\mathit{worst}}. \ \forall j \in \lbrace 1, ..., i-1 \rbrace. \  A_j \subsetneq \ \uparrow A_{j+1}\rbrace =\h (e_\mathit{worst})}$ times.
    Thus, in non-declining energy games the algorithm terminates after at most $1+\relSize{G} + \relSize{G} \cdot \h (e_\mathit{worst}) \in \mathcal{O} (\relSize{G} \cdot \h (e_\mathit{worst}) ) $ iterations of the while-loop. 

    The computing time needed for operations outside the while-loop is negligible. We now focus on the time needed to execute one iteration, where \autoref{code:attacker-pos-update}'s time is dominated by that of \autoref{code:defender-pos-update}.     
    The following procedure inspired by Brihaye and Goeminne~\cite{mult-reach-games} calculates  \autoref{code:defender-pos-update}, i.e.\ $\varname{win} [\varname{g}]$ for a defender position $\varname{g}$. 

    \begin{algorithm}[H]
  \Fn{$\varname{compute\_new\_win}(\mathcal{G}, \varname{old\_win}, \varname{g})$}{
    $\varname{new}[\varname{g}]:= \Min \E$

    \For{$g'$ with $\varname{g} \move{u} g'$\ \label{code:branching}}
    {

    $\varname{new}[\varname{g}] := \Min \lbrace \sup \lbrace e', u^{\circlearrowleft}(e_{g'}) \rbrace \ | \ e' \in \varname{new}[\varname{g}]\land  e_{g'} \in \varname{old\_win}[g'] \rbrace $\label{code:defender-one-pos}

    }

    \KwRet{$\varname{new}[\varname{g}]$}
  }
  \end{algorithm}

    Note that the repeated application of $\Min$ ensures that $\w(e_\mathit{worst})$ is an upper bound for the size of $\varname{new}[\varname{g}]$ as well as $\varname{old\_win}[g']$ for all $g'\in G$. Therefore, \autoref{code:defender-one-pos} in the procedure can be calculated in $\mathcal{O} \left( \w(e_\mathit{worst})^2 \cdot (t_{\circlearrowleft} + t_{\sup} + \w(e_\mathit{worst}) \cdot t_{\leq}) \right) $. 
    The for-loop in \autoref{code:branching} adds a factor of the branching degree $o$, while \autoref{code:begin-iteration} adds $\relSize{G}$.
    This yields a running time of \autoref{alg:game-algorithm} in $ \mathcal{O}\left(\relSize{G}^2 \cdot o  \cdot \h(e_\mathit{worst}) \cdot \w(e_\mathit{worst})^2 \cdot (t_\circlearrowleft + t_{sup} + \w(e_\mathit{worst}) \cdot t_{\leq} )\right)$ where $\h(e_\mathit{worst})$ may be omitted in the case of declining energy games.

    Since each $\varname{win}[g]$ calculated contains at most $\w(e_\mathit{worst})$ elements, the space needed to compute the output is proportional the space of $ \relSize{G} \cdot \w(e_\mathit{worst})$ energies. \qedhere
\end{sloppypar}
\end{proof}


