    \begin{definition}[Volume sampling] 
		\label{vs}
		Let \( A \) be an \( m \times n \) matrix and suppose the integer \( s \) satisfies \( 1 \leq s \leq \operatorname{rank}(A) \). Consider a random variable \( \mathcal{S}_0 \) that takes values in \( \binom{[m]}{s} \). We define \( \mathcal{S}_0 \) as being generated according to \( s \)-element volume sampling with respect to \( AA^\top \), denoted by \( \mathcal{S}_0 \sim \operatorname{Vol}_s(AA^\top) \), if for all \( \mathcal{S} \in \binom{[m]}{s} \), the probability that \( \mathcal{S}_0 \) equals \( \mathcal{S} \) is given by
		\[
		\mathbb{P}(\mathcal{S}_0 = \mathcal{S}) = \frac{\operatorname{det}(A_{\mathcal{S}} A_{\mathcal{S}}^\top)}{\sum_{\mathcal{J} \in \binom{[m]}{s}} \operatorname{det}(A_{\mathcal{J}} A_{\mathcal{J}}^\top)}.
		\]
	\end{definition}


\subsection{The randomized Douglas-Rachford method}

Consider the consistent linear system
\begin{equation}
	\label{linear system}
	Ax = b, \ \ A\in\mathbb{R}^{m\times n}, \ b\in\mathbb{R}^m,
\end{equation}
where each row defines a hyperplane 
\(\mathcal{H}_i := \{ x \in \mathbb{R}^n \mid  \langle a_i, x \rangle = b_i \}.\)
We use \( \mathcal{P}_{\mathcal{H}_i} \) and \( \mathcal{R}_{\mathcal{H}_i} \) to denote the orthogonal projection and reflection operators with respect to \( \mathcal{H}_i \), respectively. Specifically, for any \( x \in \mathbb{R}^n \), these operators are given by
\[
\mathcal{P}_{\mathcal{H}_i}(x) = x - \frac{\langle a_i, x \rangle - b_i}{\|a_i\|_2^2} a_i \ \ \text{and} \ \
\mathcal{R}_{\mathcal{H}_i}(x) = x - 2\frac{\langle a_i, x \rangle - b_i}{\|a_i\|_2^2} a_i.
\]
Starting from an initial point \( x^0 \in \mathbb{R}^n \), the randomized Kaczmarz (RK) method \cite{strohmer2009randomized} updates the iterates via
\[
x^{k+1} = \mathcal{P}_{\mathcal{H}_{i_k}}(x^k) = x^k - \frac{\langle a_{i_k}, x^k \rangle - b_{i_k}}{\|a_{i_k}\|_2^2} a_{i_k},
\]
where \( \mathbb{P}(i_k = i) = \frac{\|a_i\|_2^2}{\|A\|_F^2} \). This procedure is illustrated in Figure~\ref{figueRK}.
In contrast, the randomized Douglas–Rachford (RDR) method \cite{han2024randomized} generates iterates via
\[
x^{k+1} = \frac{1}{2} \left(I + \mathcal{R}_{\mathcal{H}_{i_{k_2}}} \mathcal{R}_{\mathcal{H}_{i_{k_1}}} \right)(x^k),
\]
where the indices \( i_{k_1} \) and \( i_{k_2} \) are independently sampled from the same distribution, i.e.,
$
\mathbb{P}(i_{k_1} = i) = \mathbb{P}(i_{k_2} = i) = \frac{\|a_i\|_2^2}{\|A\|_F^2}.
$
The Douglas–Rachford (DR) method is illustrated in Figure~\ref{figueRDR}.




