     The canonical DR algorithm has inspired numerous modifications and relaxations in the literature. One particularly important and widely used variant is the generalized Douglas-Rachford method, introduced by Eckstein and Bertsekas~\cite{Eck92}, which incorporates a relaxation parameter $\alpha \in (0,1)$:
    \[
    x^{k+1} = \left((1 - \alpha) I + \alpha \mathcal{R}_{\mathcal{H}_{i_{k_2}}} \mathcal{R}_{\mathcal{H}_{i_{k_1}}} \right)(x^k).
    \]
    This formulation reduces to the standard DR method when $\alpha = \frac{1}{2}$. The introduction of the relaxation parameter $\alpha$ is significant, as it can lead to practical acceleration of convergence, especially when $\alpha > \frac{1}{2}$~\cite{strohmer2009randomized,han2024randomized}. In this paper, we also consider the use of relaxation, and we present our practical RDR method in Algorithm~\ref{alg:PRDR}.


    % $x^{k+1} =\left((1-\alpha)I+\alpha\mathcal{R}_{\mathcal{H}_{i_{k_2}} }  \mathcal{R}_{\mathcal{H}_{i_{k_1}}  }\right)(x^k)$

	%算法3：PRDR
	\begin{algorithm}[htpb]
		\caption{Practical randomized Douglas-Rachford (PRDR) method}
		\label{alg:PRDR}
		\begin{algorithmic}
			\Require % 算法的输入参数：Input
			$A \in \mathbb{R}^{m\times n}, b \in \mathbb{R}^{m}, k=0, $
			 relaxation parameter $\alpha \in (0,1)$, and initial vector $x^0 \in \mathbb{R}^{m}$.
			\begin{enumerate}
			%\item[1:] Choose a rule between Probability Criterion 1 and Probability Criterion 2.
			\item[1:] Select $\{i_{k_1},i_{k_2}\}$ according to strategy I or strategy II. % with the probability criterion chosen in Step 1.

			\item[2:] Compute 
			$$
			\left\{
			\begin{array}{l}
				y^k =\mathcal{R}_{\mathcal{H}_{i_{k_1}} }(x^k)  
					=x^k - 2\frac{\langle a_{i_{k_1}}, x^k \rangle - b_{i_{k_1}}}{\Vert a_{i_{k_1}} \Vert_2^2} a_{i_{k_1}},\\
				 z^k =\mathcal{R}_{\mathcal{H}_{i_{k_2}} }(y^k)  = y^k - 2\frac{\langle a_{i_{k_2}}, y^k \rangle - b_{i_{k_2}}}{\Vert a_{i_{k_2}} \Vert_2^2} a_{i_{k_2}}.
			\end{array}\right.
			$$

			\item[3:] Update $$ 
			x^{k+1} =(1-\alpha)x^k+\alpha z^k.
			%x^{k+1} =\left((1-\alpha)I+\alpha\mathcal{R}_{\mathcal{H}_{i_{k_2}} }  \mathcal{R}_{\mathcal{H}_{i_{k_1}}  }\right)(x^k)%\coloneqq (1-\alpha) x^k + \alpha z^k.
			$$

			\item[4:] If the stopping rule is satisfied, stop, and go to output. Otherwise, set $k = k + 1$, and return to step 1.

            \end{enumerate}

			\Ensure  
			The approximate solution $x^k$.
		\end{algorithmic}
	\end{algorithm}

\subsection{Convergence Analysis}

To establish the convergence of Algorithm~\ref{alg:PRDR}, we begin by introducing some notations.   Define the constant
\(
\Delta \coloneqq \sum_{j=1}^m \frac{\|a_j\|_2^2}{\|A\|_F^2 - \|a_j\|_2^2},
\)
and consider the matrix \( M \in \mathbb{R}^{m \times m} \) defined as
\begin{equation}\label{definition-M}
M := (\Delta + 1)I - 
\begin{bmatrix}
	\frac{\|a_1\|_2^2}{\|A\|_F^2 - \|a_1\|_2^2} & \frac{2\langle a_1, a_2 \rangle}{\|A\|_F^2 - \|a_2\|_2^2} & \cdots & \frac{2\langle a_1, a_m \rangle}{\|A\|_F^2 - \|a_m\|_2^2} \\
	\frac{2\langle a_1, a_2 \rangle}{\|A\|_F^2 - \|a_1\|_2^2} & \frac{\|a_2\|_2^2}{\|A\|_F^2 - \|a_2\|_2^2} & \cdots & \frac{2\langle a_2, a_m \rangle}{\|A\|_F^2 - \|a_m\|_2^2} \\
	\vdots & \vdots & \ddots & \vdots \\
	\frac{2\langle a_1, a_m \rangle}{\|A\|_F^2 - \|a_1\|_2^2} & \frac{2\langle a_2, a_m \rangle}{\|A\|_F^2 - \|a_2\|_2^2} & \cdots & \frac{\|a_m\|_2^2}{\|A\|_F^2 - \|a_m\|_2^2}
\end{bmatrix}.
\end{equation}
For any \( i, j \in [m] \), we define
$
g_{i,j} := 1 - \frac{\langle a_i, a_j \rangle^2}{\|a_i\|_2^2 \|a_j\|_2^2},
$
and construct the matrix \( N \in \mathbb{R}^{m \times m} \) as
\begin{equation}\label{definition-N}
N := 
\begin{bmatrix}
	\sum\limits_{j=1}^m g_{1,j} \|a_j\|_2^2 & -g_{1,2} \langle a_1, a_2 \rangle & \cdots & -g_{1,m} \langle a_1, a_m \rangle \\
	-g_{2,1} \langle a_2, a_1 \rangle & \sum\limits_{j=1}^m g_{2,j} \|a_j\|_2^2 & \cdots & -g_{2,m} \langle a_2, a_m \rangle \\
	\vdots & \vdots & \ddots & \vdots \\
	-g_{m,1} \langle a_m, a_1 \rangle & -g_{m,2} \langle a_m, a_2 \rangle & \cdots & \sum\limits_{j=1}^m g_{m,j} \|a_j\|_2^2
\end{bmatrix}.
\end{equation}


We now state a key property of the matrices \( M \) and \( N \) defined above. All proofs in this section are deferred to Appendix~\ref{appendix-P}.

\begin{proposition}\label{propMN}
	Suppose that \( \operatorname{rank}(A) \geq 2 \), and let \( M \) and \( N \) be defined as in \eqref{definition-M} and \eqref{definition-N}, respectively. Then both \( M \) and \( N \) are positive definite. %In particular, if $A$ is row normalized, i.e. $\|a_i\|_2=1,i=1,\ldots,m$, then $\lambda_{\min}(M)$
\end{proposition}


We present the convergence result for Algorithm~\ref{alg:PRDR}.

	\begin{theorem}\label{main-PRDR}
		Suppose that  the linear system $Ax=b$ is consistent, $\alpha\in(0,1)$, $\operatorname{rank}\left(A\right)\geq2$, and $x^0\in\mathbb{R}^n$ is an arbitrary initial vector.
		Let $x_*^0=A^{\dagger}b+(I-A^\dagger A)x^0$.
		Then the iteration sequence $\{x^k\}_{k\geq0}$ generated by Algorithm \ref{alg:PRDR} using strategy I satisfies
		$$\mathbb{E} [ \|x^k-x^{0}_*\|^2_2]
		\leq
		\left(1-4\alpha(1-\alpha)\frac{\sigma_{\min}^2(M^{\frac{1}{2}}A)}{\|A\|^2_F}
		\right)^k\|x^0-x^{0}_*\|^2_2,
		$$
		and the iteration sequence $\{x^k\}_{k\geq0}$ generated by Algorithm \ref{alg:PRDR} using strategy II satisfies
		$$
		\mathop{\mathbb{E}}\big[\|x^{k}-x^{0}_*\|^2_2] 
		\leq
		\left(
		1-8\alpha(1-\alpha)
		\frac{\sigma_{\min}^2(N^{\frac{1}{2}}A)} 
		{ \Vert A \Vert_F^4 -\Vert AA^{\top} \Vert_F^2} 
		\right)^{k}
		\|x^0-x^{0}_*\|^2_2,
		$$
		where $M$ and $N$ are given by \eqref{definition-M} and \eqref{definition-N}, respectively.
	\end{theorem}

We now compare the convergence upper bound established in Theorem~\ref{main-PRDR} with the one given in \eqref{xie-RDR-rate}. Due to the structure of the matrices \( M \) and $N$, it is only feasible to analyze the convergence bound for certain special forms of \( A \).
To begin, we assume that the matrix \( A \) is row-normalized so that \( \|a_i\|_2 = 1 \) for all \( i \in [m] \). Under this assumption, the matrix \( M \) becomes
\[
M = \frac{2\|A\|_F^2}{\|A\|_F^2 - 1}I - \frac{2}{\|A\|_F^2 - 1}AA^{\top}.
\]
To estimate \( \sigma_{\min}(M^{1/2}A) \), we consider the matrix \( A^\top M A \). Suppose that \( A = U \Sigma V^\top \) is the singular value decomposition of \( A \), where the singular values satisfy \( \sigma_1(A) \geq \cdots \geq \sigma_r(A) = \sigma_{\min}(A) > 0 \), and \( r = \operatorname{rank}(A) \). Then we have
\[
A^\top M A = \frac{2}{\|A\|_F^2 - 1} \left( \|A\|_F^2 V \Sigma^\top \Sigma V^\top - V \Sigma^\top \Sigma \Sigma^\top \Sigma V^\top \right).
\]
It follows that the nonzero eigenvalues of \( A^\top M A \) are given by
\[
\frac{2}{\|A\|_F^2 - 1} \left( \|A\|_F^2 \sigma_1^2(A) - \sigma_1^4(A) \right), \ldots, \frac{2}{\|A\|_F^2 - 1} \left( \|A\|_F^2 \sigma_r^2(A) - \sigma_r^4(A) \right).
\]
We conclude that the smallest nonzero eigenvalue of \( A^\top M A \) is
$
\frac{2}{\|A\|_F^2 - 1} \left( \|A\|_F^2 \sigma_r^2(A) - \sigma_r^4(A) \right).
$
To verify this, consider any \( i \in [r] \), then
\[
\begin{aligned}
	& \frac{2}{\|A\|_F^2 - 1} \left( \|A\|_F^2 \sigma_r^2(A) - \sigma_r^4(A) \right) - \frac{2}{\|A\|_F^2 - 1} \left( \|A\|_F^2 \sigma_i^2(A) - \sigma_i^4(A) \right) \\
	=\, & \frac{2}{\|A\|_F^2 - 1} \left( \sigma_r^2(A) - \sigma_i^2(A) \right) \left( \|A\|_F^2 - \sigma_r^2(A) - \sigma_i^2(A) \right) \\
	\leq\, & 0,
\end{aligned}
\]
where the inequality holds because \( \sigma_r^2(A) \leq \sigma_i^2(A) \) and
$
\|A\|_F^2 - \sigma_r^2(A) - \sigma_i^2(A) \geq 0.
$
Hence, under the assumption that \( A \) is row-normalized and the relaxation parameter is set to \( \alpha = \frac{1}{2} \), Theorem~\ref{main-PRDR} implies that Algorithm~\ref{alg:PRDR} with strategy I satisfies
\[
\mathbb{E} \left[ \|x^k - x_*^0\|_2^2 \right]
\leq
\left(1 - 2\frac{\sigma_{\min}^2(A)}{\|A\|_F^2 - 1} \left(1 - \frac{\sigma_{\min}^2(A)}{\|A\|_F^2} \right) \right)^k \|x^0 - x_*^0\|_2^2.
\]
Comparing this upper bound to that in \eqref{xie-RDR-rate}, we obtain
\[
1 - 2\frac{\sigma_{\min}^2(A)}{\|A\|_F^2 - 1} \left(1 - \frac{\sigma_{\min}^2(A)}{\|A\|_F^2} \right)
\leq
1 - 2\frac{\sigma_{\min}^2(A)}{\|A\|_F^2}\left(1 - \frac{\sigma_{\min}^2(A)}{\|A\|_F^2} \right).
\]
This confirms that Algorithm~\ref{alg:PRDR} with strategy I achieves a sharper convergence upper bound under the given assumption.

Next, suppose that \( A \) is row-normalized and, in addition, the rows are orthogonal, i.e., \( \langle a_i, a_j \rangle = 0 \) for any \( i, j \in [m] \) with \( i \neq j \). In this case, the matrix \( N \) becomes
\[
N = (m - 1) I,
\]
and we have \( \|A\|_F^4 = m^2 \), \( \|AA^\top\|_F^2 = m \), and \( \|A\|_F^2 = m \). Under this assumption and with relaxation parameter \( \alpha = \frac{1}{2} \), Theorem~\ref{main-PRDR} implies that Algorithm~\ref{alg:PRDR} with strategy II satisfies
\[
\mathbb{E} \left[ \|x^k - x_*^0\|_2^2 \right]
\leq
\left(1 - 2\frac{\sigma_{\min}^2(A)}{\|A\|_F^2} \right)^k \|x^0 - x_*^0\|_2^2.
\]
Comparing this bound to that in \eqref{xie-RDR-rate}, we conclude that Algorithm~\ref{alg:PRDR} with strategy II also achieves a tighter convergence upper bound under the specified conditions.



