In this section, building on the momentum variant of the RDR (mRDR) method \cite{han2024randomized}, we address its key limitations by developing an adaptive scheme that automatically tunes both the relaxation parameter and the momentum coefficient. At the \(k\)-th iteration (\(k \geq 1\)), the original mRDR method updates according to
\[
x^{k+1} = \left((1 - \alpha) I + \alpha \mathcal{R}_{\mathcal{H}_{i_{k_2}}} \mathcal{R}_{\mathcal{H}_{i_{k_1}}} \right)(x^k) + \beta(x^k - x^{k-1}),
\]
where \(\alpha\) and \(\beta\) are fixed hyperparameters. While this scheme can achieve linear convergence under suitable choices of \(\alpha\) and \(\beta\) \cite[Theorem 4.1]{han2024randomized}, its performance is highly sensitive to these parameters, which are often problem-specific and require manual tuning.

It follows from Theorem~\ref{main-PRDR} that Algorithm~\ref{alg:PRDR} converges linearly in expectation to the solution  
$
x_*^0 = A^{\dagger}b + (I - A^\dagger A)x^0.
$
Based on this result, we aim to choose the parameters \(\alpha_k\) and \(\beta_k\) at each iteration so as to minimize the error \(\|x^{k+1} - x_*^0\|_2\). This leads to the following constrained optimization problem:
\begin{equation}\label{AS-pro1}
	\begin{aligned}
		&\min_{\alpha, \beta \in \mathbb{R}} \quad  \|x - x_*^0\|_2^2 \\
		\text{subject to} \quad & x = \left((1 - \alpha) I + \alpha \mathcal{R}_{\mathcal{H}_{i_{k_2}}} \mathcal{R}_{\mathcal{H}_{i_{k_1}}} \right)(x^k) + \beta(x^k - x^{k-1})\\
		&\ \ =x^k-\alpha(x^k-z^k)+ \beta(x^k - x^{k-1}),
	\end{aligned}
\end{equation}
where $z^k= \mathcal{R}_{\mathcal{H}_{i_{k_2}}} \mathcal{R}_{\mathcal{H}_{i_{k_1}}} (x^k) $. 
Define
$$	
u_k := \frac{\langle a_{i_{k_1}}, x^k \rangle - b_{i_{k_1}}}{\|a_{i_{k_1}}\|_2^2} \ \ \text{and} \ \	v_k := \frac{\langle a_{i_{k_2}}, x^k \rangle - b_{i_{k_2}} - 2 \langle a_{i_{k_2}}, a_{i_{k_1}} \rangle u_k}{\|a_{i_{k_2}}\|_2^2}.
$$
Then we have 
$$z^k = x^k - 2 u_ka_{i_{k_1}} - 2 v_ka_{i_{k_2}}.$$
Hence, \eqref{AS-pro1} can be rewritten as
	\begin{equation}\label{AS-pro2}
		\begin{aligned}
			\min\limits_{ \alpha,\beta\in\mathbb{R}}& \ \ \|x-x_*^0\|_2^2\\
			\text{subject to} \ \ x = x^k - & 2\alpha(u_k a_{i_{k_1}} + v_k a_{i_{k_2}} )  
			+ \beta (x^k - x^{k-1}).
		\end{aligned}
	\end{equation}
If $\|x^k - x^{k-1}\|_2^2  \|u_k a_{i_{k_1}} + v_k a_{i_{k_2}}\|_2^2 -  \langle u_k a_{i_{k_1}} + v_k a_{i_{k_2}}, x^k - x^{k-1} \rangle^2 \neq 0$, then the minimizers of \eqref{AS-pro2} are given by
	\begin{equation}\label{Parameter1}
		\left\{\begin{array}{ll}
			\alpha_k
			=
			\frac{ \|x^k - x^{k-1}\|_2^2 \left( u_k \langle x^k - x_*^0, a_{i_{k_1}} \rangle + v_k \langle x^k - x_*^0, a_{i_{k_2}} \rangle\right) -  \langle x^k - x_*^0, x^k - x^{k-1} \rangle \langle u_k a_{i_{k_1}} + v_k a_{i_{k_2}}, x^k - x^{k-1} \rangle} % 分子
			{2\left( \|x^k - x^{k-1}\|_2^2  \|u_k a_{i_{k_1}} + v_k a_{i_{k_2}}\|_2^2 -  \langle u_k a_{i_{k_1}} + v_k a_{i_{k_2}}, x^k - x^{k-1} \rangle^2 \right)},
			\\
			\beta_k
			=
			\frac{\langle u_k a_{i_{k_1}} + v_k a_{i_{k_2}}, x^k - x^{k-1} \rangle \left( u_k \langle x^k - x_*^0,  a_{i_{k_1}}\rangle + v_k \langle x^k - x_*^0,  a_{i_{k_2}}\rangle \right)
				-   
				\langle x^k - x_*^0, x^k - x^{k-1} \rangle \|u_k a_{i_{k_1}} + v_k a_{i_{k_2}}\|_2^2} %分子
			{ \|x^k - x^{k-1}\|_2^2  \|u_k a_{i_{k_1}} + v_k a_{i_{k_2}}\|_2^2 -  \langle u_k a_{i_{k_1}} + v_k a_{i_{k_2}}, x^k - x^{k-1} \rangle^2}, %分母
		\end{array}
		\right.
	\end{equation}
	which seem to be intractable since $  \langle x^k - x_*^0,  a_{i_{k_1}}\rangle$, $ \langle x^k - x_*^0,  a_{i_{k_2}}\rangle$ and $\langle x^k-x_*^0 ,x^k - x^{k-1} \rangle$ include an unknown vector $x_*^0$.  In fact, we can calculate the three terms directly to get rid of $x_*^0$.
	Noting that $AA^\dagger b = b$ and $x_*^0=A^\dagger b+(I-A^\dagger A)x^0$, so we have $Ax_*^0 = b$.
	Thus, for every $i\in [m]$,\  $\langle a_i,x_*^0 \rangle = a_i^{\top}x_*^0 =  b_i$. Then we know that
	\begin{equation}\label{kill-unknown}
		\langle x^k - x_*^0,  a_{i}\rangle 
		= \langle x^k,  a_{i}\rangle - \langle x_*^0,a_{i} \rangle
		= \langle x^k,  a_{i}\rangle - b_{i}.
        \nonumber
	\end{equation}
	On the other hand, we can discern from the problem \eqref{AS-pro2} that $x^k$ is the orthogonal projection of $x_*^0$ onto the affine set
	$$
\begin{aligned}
	\Pi_{k-1}&:=x^{k-1}+\mbox{Span}\{ u_{k-1} a_{i_{(k-1)_1}} + v_{k-1} a_{i_{(k-1)_2}}, x^{k-1} - x^{k-2} \}\\
	&=x^{k-1}+\operatorname{Span}\{ x^{k-1}-z^{k-1}, x^{k-1} - x^{k-2} \},
\end{aligned}
	$$
	hence we have
	$$\langle x^k-x_*^0 , x^k - x^{k-1} \rangle=0.$$
	A geometric interpretation is presented in Figure \ref{GI1}. Therefore,  \eqref{Parameter1} can be simplified to
	\begin{equation}\label{Parameter2}
		\left\{\begin{array}{ll}
			\alpha_k
			=
			\frac{ \|x^k - x^{k-1}\|_2^2 \left( \langle  u_k a_{i_{k_1}} + v_k a_{i_{k_2}} , x^k \rangle  -  \left( u_k b_{i_{k_1}}+ v_k b_{i_{k_2}}\right) \right) } 
			{2\left( \|x^k - x^{k-1}\|_2^2  \|u_k a_{i_{k_1}} + v_k a_{i_{k_2}}\|_2^2 -  \langle u_k a_{i_{k_1}}+ v_k a_{i_{k_2}}, x^k - x^{k-1} \rangle^2 \right)}, 
			\\
			\beta_k
			=
			\frac{\langle u_k a_{i_{k_1}} + v_k a_{i_{k_2}}, x^k - x^{k-1} \rangle\left( \langle  u_k a_{i_{k_1}} + v_k a_{i_{k_2}} , x^k \rangle  -  \left( u_k b_{i_{k_1}} + v_k b_{i_{k_2}} \right) \right) } %分子
			{ \|x^k - x^{k-1}\|_2^2  \|u_k a_{i_{k_1}} + v_k a_{i_{k_2}}\|_2^2 -  \langle u_k a_{i_{k_1}} + v_k a_{i_{k_2}}, x^k - x^{k-1} \rangle^2}. 
		\end{array}
		\right.
	\end{equation}
	To sum up, for any $k\geq1$, if $\|x^k - x^{k-1}\|_2^2  \|u_k a_{i_{k_1}} + v_k a_{i_{k_2}}\|_2^2 -  \langle u_k a_{i_{k_1}} + v_k a_{i_{k_2}}, x^k - x^{k-1} \rangle^2\neq 0$, i.e. $\text{dim}(\Pi_k)=2$, can be guaranteed, then the minimizers of \eqref{AS-pro2} can be computed by \eqref{Parameter2}.


