	\begin{algorithm}[htpb]
		\caption{\small{PRDR with adaptive momentum (AmPRDR)} }
		\label{alg:AmPRDR}
		\begin{algorithmic}
			\Require
			$A\in \mathbb{R}^{m\times n}$, $b\in \mathbb{R}^m$, $k=1$, and initial vector $x^0\in \mathbb{R}^{n}$.
			\begin{enumerate}

				\item[1:]  Select $\{i_{0_1},i_{0_2}\}$ according to strategy I or strategy II and compute 
				$$z^0= \mathcal{R}_{\mathcal{H}_{i_{0_2}}} \mathcal{R}_{\mathcal{H}_{i_{0_1}}} (x^0). $$

				\item[2:] If $z^0=x^0$, return to Step 1. Otherwise, set $x^1=\frac{1}{2} x^0+\frac{1}{2} z^0$. % by Algorithm \ref{alg:PRDR} with the probability criterion chosen in Step 1.

				\item[3:]  Select $\{i_{k_1},i_{k_2}\}$ according to strategy I or strategy II and 
				 compute $$z^k= \mathcal{R}_{\mathcal{H}_{i_{k_2}}} \mathcal{R}_{\mathcal{H}_{i_{k_1}}} (x^k). $$

				\item[4:] If $z^k=x^k$, return to Step 3. Otherwise, compute the parameters $\alpha_k$ and $\beta_k$ according to \eqref{Parameter2}.

				\item[5:] Update
				$$
				x^{k+1}:=(1-\alpha_k) x^k+\alpha_k z^k+\beta_k(x^k-x^{k-1}).
				$$
				\item[6:] If the stopping rule is satisfied, stop and go to output. Otherwise, set $k=k+1$ and return to Step 3.
			\end{enumerate}

			\Ensure
			The approximate solution $ x^k $.
		\end{algorithmic}
	\end{algorithm}

	\subsection{Convergence analysis}

We begin by introducing some auxiliary variables. Define
\[
\tilde{x}^{k+1} \coloneqq \frac{1}{2} x^k + \frac{1}{2} z^k.
\]
It is evident that \(\tilde{x}^{k+1}\) corresponds to the next iterate generated by Algorithm~\ref{alg:PRDR} with a fixed parameter \(\alpha = \frac{1}{2}\), when starting from \(x^k\). Moreover, it is clear that \(\tilde{x}^{k+1} \in \Pi_k\).
Next, we define the index set
\[
\mathcal{Q}_k := \left\{ (i, j) \mid z^k = \mathcal{R}_{\mathcal{H}_j} \mathcal{R}_{\mathcal{H}_i}(x^k) \neq x^k \right\},
\]
which collects all index pairs that yield a nontrivial reflection at iteration \(k\).
We also define the auxiliary vector
\[
\zeta_k := \langle z^k - x^k,\, x^k - x^{k-1} \rangle (z^k - x^k) - \|z^k - x^k\|_2^2 (x^k - x^{k-1}),
\]
and denote by \(\theta_k\) the angle between \(\tilde{x}^{k+1} - x_*^0\) and \(\zeta_k\).
We further define the scalar
\begin{equation}\label{gamma_k}
	\gamma_k \coloneqq \inf_{(i, j) \in \mathcal{Q}_k} \left\{ \cos^2 \theta_k \right\}.
\end{equation}
Based on the above definitions, we now present the convergence result for Algorithm~\ref{alg:AmPRDR}. It can be observed that the AmPRDR method exhibits convergence bound that is at least as that of the PDRD method.

	% AmPRDR的收敛定理
	\begin{theorem}\label{main-AmPRDR}
		Suppose that the linear system $Ax=b$ is consistent, $\operatorname{rank}(A)\geq2$, and $x^0\in\mathbb{R}^n $ is the arbitrary initial vector. Let $x_*^0=A^{\dagger}b+(I-A^\dagger A)x^0$. 
		Then the iteration sequence $\{x^k\}_{k\geq0}$ generated by Algorithm \ref{alg:AmPRDR} using strategy I satisfies
		$$
		\mathbb{E} \left[ \|x^{k+1} - x_*^0\|_2^2 \mid x^k \right] \leq (1 - \gamma_k) 
		\left(1-\frac{ \sigma_{\min}^2(M^{\frac{1}{2}}A)}{\|A\|^2_F}
		\right)
		\|x^k - x_*^0\|_2^2,
		$$
			and the iteration sequence $\{x^k\}_{k\geq0}$ generated by Algorithm \ref{alg:AmPRDR} using strategy II satisfies
		%the iteration sequence $\{x^k\}_{k=0}^{\infty}$ generated by Algorithm with Probability Criterion 2 satisfies
		$$
		\mathbb{E} \left[ \|x^{k+1} - x_*^0\|_2^2 \mid x^k \right] \leq (1 - \gamma_k) 
		\left(
		1-2
		\frac{\sigma_{\min}^2(N^\frac{1}{2}A)}%分子
		{ \Vert A \Vert_F^4 -\Vert AA^{\top} \Vert_F^2}%分母
		\right)
		\|x^k - x_*^0\|_2^2,
		$$
		where $\gamma_k$ is given by \eqref{gamma_k}, and $M$ and $N$ are given by \eqref{definition-M} and \eqref{definition-N}, respectively.
	\end{theorem}


