	\begin{proof}[Proof of Proposition \ref{propMN}]
		We first prove that the matrix \( M \) is positive definite. That is, for any nonzero vector \( x = (x_1, x_2, \dots, x_m)^\top \in \mathbb{R}^m \), we need to show that
		$
		x^\top Mx>0
		$.
		Let \( x = (x_1, x_2, \dots, x_m)^\top \in \mathbb{R}^m \). Then we have
		$$
		\begin{aligned}
			x^{\top}M x
			=&(\Delta+1)x^{\top}x+
			x^\top
			% 矩阵D+(q+1)I-2AA^{\top}C
			\begin{bmatrix}
				-\frac{\Vert a_1 \Vert_2^2}{\Vert A \Vert_F^2 -\Vert a_1 \Vert_2^2}  & -\frac{2\left\langle a_1,a_2\right\rangle}{\Vert A \Vert_F^2 -\Vert a_2 \Vert_2^2}   & \cdots & -\frac{2\left\langle a_1,a_m\right\rangle}{\Vert A \Vert_F^2 -\Vert a_m \Vert_2^2} \\
				-\frac{2\left\langle a_1,a_2\right\rangle}{\Vert A \Vert_F^2 -\Vert a_1 \Vert_2^2}   & -\frac{\Vert a_2 \Vert_2^2}{\Vert A \Vert_F^2 -\Vert a_2 \Vert_2^2}   & \cdots & -\frac{2\left\langle a_2,a_m\right\rangle}{\Vert A \Vert_F^2 -\Vert a_m \Vert_2^2} \\
				\vdots & \vdots & \ddots & \vdots \\
				-\frac{2\left\langle a_1,a_m\right\rangle}{\Vert A \Vert_F^2 -\Vert a_1 \Vert_2^2}   & -\frac{2\left\langle a_2,a_m\right\rangle}{\Vert A \Vert_F^2 -\Vert a_2 \Vert_2^2}   & \cdots & -\frac{\Vert a_m \Vert_2^2}{\Vert A \Vert_F^2 -\Vert a_m \Vert_2^2}  
			\end{bmatrix}x\\
			=& 
			(\Delta+1)x^{\top}x-\sum_{i=1}^{m}\frac{\Vert a_i \Vert_2^2}{\Vert A \Vert_F^2 -\Vert a_i \Vert_2^2} x_i^2-\sum_{i=1}^{m}\sum\limits_{\substack{ j=1\\j\neq i}}^m\frac{2\left\langle a_i,a_j\right\rangle}{\Vert A \Vert_F^2 -\Vert a_j \Vert_2^2}x_ix_j
			\\
			\overset{(a)}{=}&\sum_{i=1}^{m}\left( \sum_{j=1}^m \frac{\|a_j\|_2^2}{\|A\|_F^2 - \|a_j\|_2^2} +1-\frac{\Vert a_i \Vert_2^2}{\Vert A \Vert_F^2 -\Vert a_i \Vert_2^2} \right)x_i^2-\sum_{i=1}^{m}\sum\limits_{\substack{ j=1\\j\neq i}}^m\frac{2\left\langle a_i,a_j\right\rangle}{\Vert A \Vert_F^2 -\Vert a_j \Vert_2^2}x_ix_j
			\\
			\overset{(b)}{=}&\sum_{i=1}^{m} \sum\limits_{\substack{ j=1\\j\neq i}}^m \left(\frac{\|a_j\|_2^2}{\|A\|_F^2 - \|a_j\|_2^2} +\frac{\Vert a_j \Vert_2^2}{\Vert A \Vert_F^2 -\Vert a_i \Vert_2^2} \right)x_i^2-\sum_{i=1}^{m}\sum\limits_{\substack{ j=1\\j\neq i}}^m\frac{2\left\langle a_i,a_j\right\rangle}{\Vert A \Vert_F^2 -\Vert a_j \Vert_2^2}x_ix_j
			\\
			=&\sum_{1\leq i<j\leq m}  \left(\frac{1}{\|A\|_F^2 - \|a_j\|_2^2} +\frac{1}{\Vert A \Vert_F^2 -\Vert a_i \Vert_2^2} \right)\left(\|a_j\|^2_2x_i^2+\|a_i\|^2_2x_j^2-2\langle a_i,a_j\rangle x_ix_j\right),
		\end{aligned}
		$$
		where $(a)$ follows from the definition of $\Delta= \sum_{j=1}^m \frac{\|a_j\|_2^2}{\|A\|_F^2 - \|a_j\|_2^2}$ and $(b)$ follows from  $1=\sum\limits_{\substack{ j=1\\j\neq i}}^m \frac{\Vert a_j \Vert_2^2 }{\Vert A \Vert_F^2 -\Vert a_i \Vert_2^2}$, $i=1,\dots,m$.

		We define 
		$$
		\mathcal{I}:=\{i\mid x_i\neq0\}, \ \mathcal{I}^c:=[m]\setminus \mathcal{I},
		$$
		and the pair sets
		$$
		\mathcal{J}_{+}:=\{(i,j)\mid x_ix_j>0, i\neq j, i,j\in\mathcal{I}\}, \ \mathcal{J}_{-}:=\{(i,j)\mid x_ix_j<0, i\neq j , i,j\in\mathcal{I}\}.
		$$
		Without loss of generality, assume \( \mathcal{I} = \{1, \dots, \ell\} \). Then,
		\[
		\begin{aligned}
			x^\top M x
			=&\ \sum_{\substack{i,j \in \mathcal{I}\\ i<j}} \left( \frac{1}{\|A\|_F^2 - \|a_j\|_2^2} + \frac{1}{\|A\|_F^2 - \|a_i\|_2^2} \right) \left( \|a_j\|_2^2 x_i^2 + \|a_i\|_2^2 x_j^2 - 2\langle a_i,a_j\rangle x_i x_j \right) \\
			&+ \sum_{\substack{i \in \mathcal{I},\, j \in \mathcal{I}^c}} \left( \frac{1}{\|A\|_F^2 - \|a_j\|_2^2} + \frac{1}{\|A\|_F^2 - \|a_i\|_2^2} \right) \left( \|a_j\|_2^2 x_i^2 + \|a_i\|_2^2 x_j^2 - 2\langle a_i,a_j\rangle x_i x_j \right) \\
			&+ \sum_{\substack{i,j \in \mathcal{I}^c\\ i<j}} \left( \frac{1}{\|A\|_F^2 - \|a_j\|_2^2} + \frac{1}{\|A\|_F^2 - \|a_i\|_2^2} \right) \left( \|a_j\|_2^2 x_i^2 + \|a_i\|_2^2 x_j^2 - 2\langle a_i,a_j\rangle x_i x_j \right).
		\end{aligned}
		\]
		Note that all terms involving \( x_j = 0 \) for \( j \in \mathcal{I}^c \) vanish. Thus, we obtain
		\[
		\begin{aligned}
			x^\top M x =&\sum_{\substack{i,j \in \mathcal{I}\\ i<j}} \left( \frac{1}{\|A\|_F^2 - \|a_j\|_2^2} + \frac{1}{\|A\|_F^2 - \|a_i\|_2^2} \right) \left( \|a_j\|_2^2 x_i^2 + \|a_i\|_2^2 x_j^2 - 2\langle a_i,a_j\rangle x_i x_j \right) \\
			&+ \sum_{\substack{i \in \mathcal{I},\, j \in \mathcal{I}^c}} \left( \frac{1}{\|A\|_F^2 - \|a_j\|_2^2} + \frac{1}{\|A\|_F^2 - \|a_i\|_2^2} \right)\|a_j\|_2^2 x_i^2
			\\
			\geq&\ \sum_{(i,j)\in \mathcal{J}_+} \left( \frac{1}{\|A\|_F^2 - \|a_j\|_2^2} + \frac{1}{\|A\|_F^2 - \|a_i\|_2^2} \right) \left( \|a_j\|_2 x_i - \|a_i\|_2 x_j \right)^2 \\
			&+ \sum_{(i,j)\in \mathcal{J}_-} \left( \frac{1}{\|A\|_F^2 - \|a_j\|_2^2} + \frac{1}{\|A\|_F^2 - \|a_i\|_2^2} \right) \left( \|a_j\|_2 x_i + \|a_i\|_2 x_j \right)^2 \\
			&+ \sum_{\substack{i \in \mathcal{I},\, j \in \mathcal{I}^c}} \left( \frac{1}{\|A\|_F^2 - \|a_j\|_2^2} + \frac{1}{\|A\|_F^2 - \|a_i\|_2^2} \right) \|a_j\|_2^2 x_i^2 \\
			\geq&\ 0.
		\end{aligned}
		\]
		The first inequality follows from the Cauchy–Schwarz inequality, and equality holds if and only if \( \langle a_i, a_j \rangle^2 = \|a_i\|_2^2 \|a_j\|_2^2 \) for all \( i \ne j \in \mathcal{I} \), i.e., the vectors \( a_i \) (for \( i \in \mathcal{I} \)) are colinear. The last inequality becomes equality only if \( a_j = 0 \) for all \( j \in \mathcal{I}^c \).
		Therefore, \( x^\top M x = 0 \) if and only if all \( a_i \) (for \( i \in \mathcal{I} \)) are colinear and \( a_j = 0 \) for all \( j \in \mathcal{I}^c \), which implies \( \operatorname{rank}(A) \leq 1 \). Since we assume \( \operatorname{rank}(A) \geq 2 \), it follows that \( x^\top M x > 0 \) for all \( x \ne 0 \), and hence \( M \) is positive definite.

