				\vdots & \vdots & \ddots & \vdots \\
				-g_{m,1} \langle a_m, a_1 \rangle & -g_{m,2} \langle a_m, a_2 \rangle & \cdots & \sum\limits_{j=1}^m g_{m,j} \|a_j\|_2^2
