	Next, we will prove Theorem \ref{main-PRDR}. First, we introduce some useful lemmas. For any $i\in[m]$, we define
	\begin{equation}\label{reflection operator}
		T_{\mathcal{H}_i}:=I-2\frac{a_{i}a_i^{\top}}{\|a_i\|^2_2}.
	\end{equation}
	It is easy to verify that $T_{\mathcal{H}_i}T_{\mathcal{H}_i}=I$, and thus for any $y\in \mathbb{R}^n$, $\|T_{\mathcal{H}_i}y\|_2=\|y\|_2$.

	\begin{lemma}\label{exp-reflection-operator}
		Let \( T_{\mathcal{H}_i} \) be defined in \eqref{reflection operator}. 
		If indices \( i, j \in [m] \) are selected according to Strategy I, then 
		\[
		\mathbb{E}\left[ T_{\mathcal{H}_j} T_{\mathcal{H}_i} \right] = I - \frac{2}{\|A\|_F^2} A^\top M A,
		\]
		where the matrix \( M \) is defined in \eqref{definition-M}.
		If indices \( i, j \in [m] \) are selected according to Strategy II, then we have
		\[
		\mathbb{E}\left[ T_{\mathcal{H}_j} T_{\mathcal{H}_i} \right] = I - \frac{4}{\|A\|_F^4 - \|A A^\top\|_F^2} A^\top N A,
		\]
		where the matrix \( N \) is defined in \eqref{definition-N}.
	\end{lemma}


	\begin{proof}
		We begin by computing the expected composition \( \mathbb{E}\left[ T_{\mathcal{H}_j} T_{\mathcal{H}_i} \right] \) under Strategy I. We have
		\begin{equation}\label{exp-2.4}
			\begin{aligned}
				&\mathop{\mathbb{E}}\left[T_{\mathcal{H}_j}T_{\mathcal{H}_i}\right]
				=\sum\limits_{i=1}^m \frac{\Vert a_i \Vert_2^2}{\Vert A \Vert_F^2} \ \sum\limits_{\substack{ j=1\\j\neq i}}^m \frac{\Vert a_j \Vert_2^2}{\Vert A \Vert_F^2 -\Vert a_i \Vert_2^2} 
				\left(I-2\frac{a_ja_j^{\top}}{\|a_j\|^2_2}\right)
				\left(I-2\frac{a_ia_i^{\top}}{\|a_i\|^2_2}\right)\\
				=&I-\underbrace{2\sum\limits_{i=1}^m \frac{\Vert a_i \Vert_2^2}{\Vert A \Vert_F^2}\  \sum\limits_{\substack{ j=1\\j\neq i}}^m \frac{\Vert a_j \Vert_2^2}{\Vert A \Vert_F^2 -\Vert a_i \Vert_2^2}\ \frac{a_ja_j^{\top}}{\|a_j\|^2_2}}_{\textcircled{a}}
				-\underbrace{2\sum\limits_{i=1}^m \frac{\Vert a_i \Vert_2^2}{\Vert A \Vert_F^2}\  \sum\limits_{\substack{ j=1\\j\neq i}}^m \frac{\Vert a_j \Vert_2^2}{\Vert A \Vert_F^2 -\Vert a_i \Vert_2^2}\ \frac{a_ia_i^{\top}}{\|a_i\|^2_2}}_{\textcircled{b}}\\
				&+\underbrace{4\sum\limits_{i=1}^m \frac{\Vert a_i \Vert_2^2}{\Vert A \Vert_F^2}\  \sum\limits_{\substack{ j=1\\j\neq i}}^m \frac{\Vert a_j \Vert_2^2}{\Vert A \Vert_F^2 -\Vert a_i \Vert_2^2}\ \frac{a_ja_j^{\top}}{\|a_j\|^2_2}\ \frac{a_ia_i^{\top}}{\|a_i\|^2_2}}_{\textcircled{c}}
			\end{aligned}
		\end{equation}
		We now analyze the three expressions $\textcircled{a},\textcircled{b}$, and $\textcircled{c}$ separately. For term \( \textcircled{a} \), we have
		$$
		\begin{aligned}
			%第一行
			\textcircled{a}=&2\sum\limits_{i=1}^m \frac{\Vert a_i \Vert_2^2}{\Vert A \Vert_F^2}\  \sum\limits_{\substack{ j=1\\j\neq i}}^m \frac{\Vert a_j \Vert_2^2}{\Vert A \Vert_F^2 -\Vert a_i \Vert_2^2}\ \frac{a_ja_j^{\top}}{\|a_j\|^2_2}
			=\frac{2}{\Vert A \Vert_F^2}
			\sum\limits_{i=1}^m \left(\frac{\Vert a_i \Vert_2^2 }{\Vert A \Vert_F^2 -\Vert a_i \Vert_2^2}\ \sum\limits_{\substack{ j=1\\j\neq i}}^m a_ja_j^{\top}\right)\\
			%第二行
			=&\frac{2}{\Vert A \Vert_F^2}
			\sum\limits_{i=1}^m \left(\sum\limits_{\substack{ j=1\\j\neq i}}^m \frac{\Vert a_j \Vert_2^2 }{\Vert A \Vert_F^2 -\Vert a_j \Vert_2^2}\right)a_ia_i^{\top}=2\frac{A^{\top}\hat{D}A}{\Vert A \Vert_F^2},
		\end{aligned}
		$$
		where the third equality follows by regrouping terms based on the coefficients of \( a_i a_i^\top \), and the last equality uses the definition
		$
		\hat{D} \coloneqq \operatorname{diag}(\hat{d}_1, \ldots, \hat{d}_m)$ with $ \hat{d}_i = \sum_{\substack{j=1 \\ j \neq i}}^m \frac{\|a_j\|_2^2}{\|A\|_F^2 - \|a_j\|_2^2}.
		$
		For term $\textcircled{b}$, we have
		$$
		\begin{aligned}
			\textcircled{b}=&2\sum\limits_{i=1}^m \frac{\Vert a_i \Vert_2^2}{\Vert A \Vert_F^2}\  \sum\limits_{\substack{ j=1\\j\neq i}}^m \frac{\Vert a_j \Vert_2^2}{\Vert A \Vert_F^2 -\Vert a_i \Vert_2^2}\ \frac{a_ia_i^{\top}}{\|a_i\|^2_2}
			%
			=2\sum\limits_{i=1}^m \frac{a_ia_i^{\top}}{\Vert A \Vert_F^2}\  \sum\limits_{\substack{ j=1\\j\neq i}}^m \frac{\Vert a_j \Vert_2^2}{\Vert A \Vert_F^2 -\Vert a_i \Vert_2^2}\\
			% 第二行
			=&2\sum\limits_{i=1}^m \frac{a_ia_i^{\top}}{\Vert A \Vert_F^2}\
			=\ 2\frac{A^{\top}A}{\Vert A \Vert_F^2}.
		\end{aligned}
		$$   
		For term $\textcircled{c}$, we have
		%分析c式
		\begin{equation}
			\begin{aligned}
				\textcircled{c}=&4\sum\limits_{i=1}^m \frac{\Vert a_i \Vert_2^2}{\Vert A \Vert_F^2}\  \sum\limits_{\substack{ j=1\\j\neq i}}^m \frac{\Vert a_j \Vert_2^2}{\Vert A \Vert_F^2 -\Vert a_i \Vert_2^2}\ \frac{a_ja_j^{\top}}{\|a_j\|^2_2}\ \frac{a_ia_i^{\top}}{\|a_i\|^2_2}\\
				=&4\sum\limits_{i=1}^m   \sum\limits_{\substack{ j=1\\j\neq i}}^m\ 
				\frac{a_ja_j^{\top}}{\Vert A \Vert_F^2 -\Vert a_i \Vert_2^2}\ \frac{a_ia_i^{\top}}{\Vert A \Vert_F^2}\\
				%第二行
				=&4\sum\limits_{i=1}^m  \frac{A^{\top}A-a_ia_i^{\top}}{\Vert A \Vert_F^2 -\Vert a_i \Vert_2^2}\frac{a_ia_i^{\top}}{\Vert A \Vert_F^2}
				\\
				=&\frac{4}{\Vert A \Vert_F^2} \left(A^{\top}A \sum\limits_{i=1}^m  \frac{a_ia_i^{\top}}{\Vert A \Vert_F^2 -\Vert a_i \Vert_2^2} \     -      \sum\limits_{i=1}^m  \frac{a_ia_i^{\top}a_ia_i^{\top}}{\Vert A \Vert_F^2 -\Vert a_i \Vert_2^2}\right)\\
				%第三行
				=&\frac{4}{\Vert A \Vert_F^2} \left(A^{\top}A\sum\limits_{i=1}^m  \frac{1}{\Vert A \Vert_F^2 -\Vert a_i \Vert_2^2}a_ia_i^{\top} \     -      \sum\limits_{i=1}^m  \frac{\Vert a_i \Vert_2^2}{\Vert A \Vert_F^2 -\Vert a_i \Vert_2^2}\ a_ia_i^{\top}\right)\\
				%第四行
				=&4\frac{A^{\top}AA^{\top} \bar{D}  A  - A^{\top}DA }{\Vert A \Vert_F^2},
			\end{aligned}
			\nonumber
		\end{equation}
		where $D\coloneqq \operatorname{diag}(d_1,\ldots,d_m)$ with $d_i=\frac{\Vert a_i \Vert_2^2}{\Vert A \Vert_F^2 -\Vert a_i \Vert_2^2}$, and  $\bar{D} \coloneqq \operatorname{diag}(\bar{d_1},\ldots,\bar{d_m})$ with $\bar{d_i}=\frac{1}{\Vert A \Vert_F^2 -\Vert a_i \Vert_2^2}$.
		By substituting all these equations into \eqref{exp-2.4}, we obtain
		$$\label{exp-result}
		\begin{aligned}
			\mathop{\mathbb{E}}\left[T_{\mathcal{H}_j}T_{\mathcal{H}_i}\right]
			%第二行公式
			=&I-2\frac{A^{\top} \left(\hat{D}+2D\right)A}{\Vert A \Vert_F^2}
			-2\frac{A^{\top}A}{\Vert A \Vert_F^2}
			+4\frac{A^{\top}AA^{\top}\bar{D}A }{\Vert A \Vert_F^2}\\
			%第三行公式
			=&I-2\frac{A^{\top} \left(\Delta I+D\right)A}{\Vert A \Vert_F^2}
			-2\frac{A^{\top}A}{\Vert A \Vert_F^2}
			+4\frac{A^{\top}AA^{\top}\bar{D}A }{\Vert A \Vert_F^2}
			\\
			=&I-\frac{2}{\|A\|^2_F}A^{\top}
			M A,
		\end{aligned}
		$$
		where the second equality comes from the reality that $\hat{d_i}+d_i =\Delta   =  \sum\limits_{j=1}^m \frac{\Vert a_j \Vert_2^2}{\Vert A \Vert_F^2 -\Vert a_j \Vert_2^2}$.





		Next we compute the expected composition \( \mathbb{E}\left[ T_{\mathcal{H}_j} T_{\mathcal{H}_i} \right] \) under Strategy II. Since for any $\mathcal{S}_k=\{i,j\}$, 
		$$
		\frac{\operatorname{det}(A_{\mathcal{S}_k} A_{\mathcal{S}_k}^\top)}{\sum_{\mathcal{J} \in \binom{[m]}{2}} \operatorname{det}(A_{\mathcal{J}} A_{\mathcal{J}}^\top)}=\frac{2\left(\Vert a_{j}\Vert_2^2 \Vert a_{i} \Vert_2^2   -   \left\langle a_{i},a_{j} \right\rangle^2 \right)}%分子
		{ \Vert A \Vert_F^4 -\Vert AA^{\top} \Vert_F^2 }.%分母
		$$
		Hence, we have
		%期望内积的展开式1
		\begin{equation}
			\label{exp-zhankaishi}
			\begin{aligned}
				\mathop{\mathbb{E}}\left[ T_{\mathcal{H}_{j}}T_{\mathcal{H}_{i}}\right]
				%第二个等式
				=&
				\sum_{\{i,j\}\in \binom{[m]}{2}} 
				\frac{2\left(\Vert a_{j}\Vert_2^2 \Vert a_{i} \Vert_2^2   -   \left\langle a_{i},a_{j} \right\rangle^2 \right)}%分子
				{ \Vert A \Vert_F^4 -\Vert AA^{\top} \Vert_F^2 }%分母
				\left(I-2\frac{a_{j}a_{j}^{\top}}{\|a_{j}\|^2_2}\right)
				\left(I-2\frac{a_{i}a_{i}^{\top}}{\|a_{i}\|^2_2}\right)\\
				%第三个等式
				=&
				\sum\limits_{i=1}^m \ 
				\sum\limits_{j=1}^m 
				\frac{\Vert a_j\Vert_2^2 \Vert a_i \Vert_2^2   -   \left\langle a_i,a_j \right\rangle^2}%分子
				{ \Vert A \Vert_F^4 -\Vert AA^{\top} \Vert_F^2 }%分母
				\left(I-2\frac{a_ja_j^{\top}}{\|a_j\|^2_2}\right)
				\left(I-2\frac{a_ia_i^{\top}}{\|a_i\|^2_2}\right)\\
				%第四个等式-前两个部分
				=& I
				\underbrace{-2 \sum\limits_{i=1}^m \ 
					\sum\limits_{j=1}^m 
					\frac{\Vert a_j\Vert_2^2 \Vert a_i \Vert_2^2   -   \left\langle a_i,a_j \right\rangle^2}%分子
					{ \Vert A \Vert_F^4 -\Vert AA^{\top} \Vert_F^2}%分母
