	Now, we are ready to prove Theorem \ref{main-PRDR}.


	\begin{proof}[Proof of Theorem \ref{main-PRDR}]
		By taking the conditional expectation, we obtain
		\begin{equation}
			\begin{aligned}\label{exp-inner product}
				%第一行公式
				&\mathop{\mathbb{E}}\big[\|x^{k+1}-x^{0}_*\|^2_2 \mid x^k\big]=
				\mathop{\mathbb{E}}\big[\|(1-\alpha)x^{k}+\alpha z^k-x^{0}_*\|^2_2|x^k\big]\\
				=&\left(\alpha^2+(1-\alpha)^2\right)\|x^k-x^{0}_*\|^2_2
				+2\alpha(1-\alpha)
				\mathop{\mathbb{E}}\left[\left\langle T_{\mathcal{H}_{i_{k_2}}}T_{\mathcal{H}_{i_{k_1}}}(x^k-x^{0}_*),x^k-x^{0}_*\right\rangle\right]\\
				%第二行公式
				=&\left(\alpha^2+(1-\alpha)^2\right)\|x^k-x^{0}_*\|^2_2
				+2\alpha(1-\alpha)
				\left\langle \mathop{\mathbb{E}}\left[ T_{\mathcal{H}_{i_{k_2}}}T_{\mathcal{H}_{i_{k_1}}}\right](x^k-x^{0}_*),x^k-x^{0}_*\right\rangle ,
			\end{aligned}
		\end{equation}
		where the first equality follows from Step $3$ in Algorithm \ref{alg:PRDR}, the second equality follows from Lemma \ref{lemma-22}, and the last equality follows from the  linearity of the expectation.

		First, we consider Algorithm \ref{alg:PRDR} with  Strategy I.
		According to Lemma \ref{exp-reflection-operator} and  Proposition~\ref{propMN}, we have
		\begin{equation}
			\begin{aligned}
				\label{thm-qyz-1}
				\langle \mathop{\mathbb{E}}[ T_{\mathcal{H}_{i_{k_2}}}T_{\mathcal{H}_{i_{k_1}}}](x^k-x_*^0),x^k-x_*^0\rangle 
				= \|x^k-x_*^0\|^2_2-\frac{2}{\|A\|^2_F} 
				\|	M^{\frac{1}{2}}
				A(x^k-x_*^0 )\|^2_2.
			\end{aligned}
		\end{equation}
		Moreover, by Lemma~\ref{lemma-23}, we know that \( x^k - x^0_* \in \operatorname{Range}(A^\top) \). Since \( M \) is positive definite, it follows that \( x^k - x^0_* \in \operatorname{Range}(A^\top M^{1/2}) \). Therefore, we have the inequality
		$$		\|	M^{\frac{1}{2}}
		A(x^k-x_*^0 )\|^2_2
		\geq 
		\sigma_{\min}^2(M^{\frac{1}{2}}A)\|x^k-x_*^0\|^2_2.$$
		Substituting this bound and \eqref{thm-qyz-1} into \eqref{exp-inner product}, we obtain
		%公式
		\begin{equation}
			\begin{aligned}
				\mathop{\mathbb{E}}[\|x^{k+1}-x_*^0\|^2_2\mid x^k] 
				\leq \left(1-4\alpha(1-\alpha)\frac{\sigma_{\min}^2(M^{\frac{1}{2}}A)}{\|A\|^2_F}\right)
				\|x^k-x_*^0\|^2_2.
			\end{aligned}
			\nonumber
		\end{equation}
		Taking the expectation over the entire history yields the desired linear convergence result. %we can get the desired result.

		The proof under Strategy II follows analogously by replacing the matrix \( M \) with the corresponding matrix \( N \) for Strategy II. The same argument yields the desired result.
	\end{proof}


