	\begin{proof}[Proof of Proposition \ref{prob-full}]
		We prove the result by contradiction. Suppose \( \dim(\Pi_k) < 2 \). Then there exists a scalar \( \lambda \in \mathbb{R} \) such that
		$
		x^k - z^k = \lambda (x^k - x^{k-1}).
		$
		If \( \lambda = 0 \), then \( x^k = z^k \), which contradicts the assumption \( z^k \neq x^k \). Hence, we must have \( \lambda \neq 0 \).
		Since the algorithm ensures that
		$
		\langle x^{k}-x^{k-1}, x^k-x^0_{*}\rangle=0,
		$
		it follows that
		$$
		\langle x^{k}-z^{k}, x^k-x^0_{*}\rangle=0.
		$$
		Recall  that $z^k = x^k - 2 u_ka_{i_{k_1}} - 2 v_ka_{i_{k_2}}$, we get
		$$
		\begin{aligned}
			0=\langle  u_ka_{i_{k_1}} + v_ka_{i_{k_2}}, x^k-x^0_{*}\rangle=u_k \langle  a_{i_{k_1}}, x^k-x^0_{*}\rangle+v_k \langle  a_{i_{k_2}}, x^k-x^0_{*}\rangle.
		\end{aligned}
		$$
		Without loss of generality,   we assume that  
		$
		 \frac{ \langle a_{i_{k_2}}, x^k \rangle - b_{i_{k_2}} }{ \|a_{i_{k_2}}\|_2 }$ and $\frac{ \langle a_{i_{k_1}}, x^k \rangle - b_{i_{k_1}} }{ \|a_{i_{k_1}}\|_2 }
		$ 
		 have the same sign.
		Using the fact that \( \langle a_i, x^0_* \rangle = b_i \) for any $i\in[m]$, and the definitions
		$
		u_k = \frac{\langle a_{i_{k_1}}, x^k \rangle - b_{i_{k_1}}}{\|a_{i_{k_1}}\|_2^2} $ and $
		v_k = \frac{\langle a_{i_{k_2}}, x^k \rangle - b_{i_{k_2}} - 2 \langle a_{i_{k_2}}, a_{i_{k_1}} \rangle u_k}{\|a_{i_{k_2}}\|_2^2},
		$ we can rewrite the above as
		$$
		\begin{aligned}
			0=&\frac{(\langle a_{i_{k_1}}, x^k \rangle - b_{i_{k_1}})^2}{\|a_{i_{k_1}}\|_2^2}+\frac{(\langle a_{i_{k_2}}, x^k \rangle - b_{i_{k_2}})^2}{\|a_{i_{k_2}}\|_2^2}\\
			&-2\frac{ \langle a_{i_{k_2}}, a_{i_{k_1}} \rangle  }{\|a_{i_{k_1}}\|_2\|a_{i_{k_2}}\|_2}\cdot\frac{ \langle a_{i_{k_2}}, x^k \rangle - b_{i_{k_2}}}{\|a_{i_{k_2}}\|_2}\cdot\frac{\langle a_{i_{k_1}}, x^k \rangle - b_{i_{k_1}}}{\|a_{i_{k_1}}\|_2}
			\\
			\geq &\frac{(\langle a_{i_{k_1}}, x^k \rangle - b_{i_{k_1}})^2}{\|a_{i_{k_1}}\|_2^2}+\frac{(\langle a_{i_{k_2}}, x^k \rangle - b_{i_{k_2}})^2}{\|a_{i_{k_2}}\|_2^2}-2 \frac{ \langle a_{i_{k_2}}, x^k \rangle - b_{i_{k_2}}}{\|a_{i_{k_2}}\|_2}\cdot\frac{\langle a_{i_{k_1}}, x^k \rangle - b_{i_{k_1}}}{\|a_{i_{k_1}}\|_2}\\
			=&\left(\frac{\langle a_{i_{k_1}}, x^k \rangle - b_{i_{k_1}}}{\|a_{i_{k_1}}\|_2}-\frac{\langle a_{i_{k_2}}, x^k \rangle - b_{i_{k_2}}}{\|a_{i_{k_2}}\|_2} \right)^2,
		\end{aligned}
		$$
		where the inequality follows from the Cauchy-Schwarz inequality. Hence, we have 
		\begin{equation}\label{xie-proof-0604-1}
			\frac{\langle a_{i_{k_1}}, x^k \rangle - b_{i_{k_1}}}{\|a_{i_{k_1}}\|_2}=\frac{\langle a_{i_{k_2}}, x^k \rangle - b_{i_{k_2}}}{\|a_{i_{k_2}}\|_2}.
		\end{equation}
		Substituting this back, we find
		%\begin{equation}\label{xie-proof-0604-2}
		$$	0=2\frac{(\langle a_{i_{k_1}}, x^k \rangle - b_{i_{k_1}})^2}{\|a_{i_{k_1}}\|_2^2}-2\frac{ \langle a_{i_{k_2}}, a_{i_{k_1}} \rangle  }{\|a_{i_{k_1}}\|_2\|a_{i_{k_2}}\|_2}\cdot\frac{(\langle a_{i_{k_1}}, x^k \rangle - b_{i_{k_1}})^2}{\|a_{i_{k_1}}\|_2^2}.$$
		%\end{equation}
		This leads to $\frac{(\langle a_{i_{k_1}}, x^k \rangle - b_{i_{k_1}})^2}{\|a_{i_{k_1}}\|_2^2}=0$ or $\frac{ \langle a_{i_{k_2}}, a_{i_{k_1}} \rangle  }{\|a_{i_{k_1}}\|_2\|a_{i_{k_2}}\|_2}=1$. 
		If 
		$
		\frac{(\langle a_{i_{k_1}}, x^k \rangle - b_{i_{k_1}})^2}{\|a_{i_{k_1}}\|_2^2} = 0,
		$
		then it follows from \eqref{xie-proof-0604-1} that
		$
		\frac{(\langle a_{i_{k_2}}, x^k \rangle - b_{i_{k_2}})^2}{\|a_{i_{k_2}}\|_2^2} = 0
		$. Consequently, we have \( u_k = v_k = 0 \), which implies \( z^k = x^k \), contradicting the assumption \( z^k \neq x^k \).
		On the other hand, if
		$
		\frac{\langle a_{i_{k_2}}, a_{i_{k_1}} \rangle}{\|a_{i_{k_1}}\|_2 \|a_{i_{k_2}}\|_2} = 1,
		$
		then the vectors \( a_{i_{k_1}} \) and \( a_{i_{k_2}} \) are colinear, meaning the corresponding hyperplanes \( \mathcal{H}_{i_{k_1}} \) and \( \mathcal{H}_{i_{k_2}} \) coincide. In this case, the reflection step yields \( z^k = x^k \), again contradicting the assumption \( z^k \neq x^k \).
		Therefore, our initial assumption that \( \dim(\Pi_k) < 2 \) must be false. Hence, \( \dim(\Pi_k) = 2 \).
	\end{proof}


	\begin{proof}[Proof of Proposition \ref{xie-0604-p}]
		Without loss of generality, assume that \(a_1 \neq 0\), and define the index set
		\[
		\mathcal{I} := \{ i \in [m] \mid a_i \text{ is linearly independent of } a_1 \}.
		\]
		Since \(\operatorname{rank}(A) \geq 2\), the set \(\mathcal{I}\) is nonempty.
		For any \(i \in \mathcal{I}\), using the same argument as in the proof of Proposition~\ref{prob-full}, we obtain the following two identities:
		$$
		\frac{\langle a_{1}, \tilde{x} \rangle - b_{1}}{\|a_{1}\|_2}=\frac{\langle a_{i}, \tilde{x} \rangle - b_{i}}{\|a_{i}\|_2}
		$$
		and
		$$
		0=2\frac{(\langle a_{1}, \tilde{x} \rangle - b_1)^2}{\|a_1\|_2^2}-2\frac{ \langle a_{1}, a_{i} \rangle  }{\|a_{1}\|_2\|a_{i}\|_2}\cdot\frac{(\langle a_{1}, \tilde{x} \rangle - b_{1})^2}{\|a_{1}\|_2^2}.
		$$
		Since \(a_1\) and \(a_i\) are linearly independent, it follows that \(\frac{\langle a_1, a_i \rangle}{\|a_1\|_2 \|a_i\|_2} < 1\).  Hence we know that $\frac{\langle a_{1}, \tilde{x} \rangle - b_{1}}{\|a_{1}\|_2}=\frac{\langle a_{i}, \tilde{x} \rangle - b_{i}}{\|a_{i}\|_2}=0$, i.e., $\langle a_{1}, \tilde{x} \rangle = b_{1}$ and  $\langle a_{i}, \tilde{x} \rangle = b_{i}$ for all $i\in\mathcal{I}$. 
		Now consider any \(j \in [m] \setminus \mathcal{I}\). Since \(a_j\) is linearly dependent on \(a_1\), there exists a scalar \(\lambda_j \in \mathbb{R}\) such that \(a_j = \lambda_j a_1\). Then
		$
		\langle a_j, \tilde{x} \rangle = \lambda_j \langle a_1, \tilde{x} \rangle = \lambda_j b_1 = b_j,
		$
		where the last equality follows from the consistency of the system \(Ax = b\). Hence, \(\langle a_j, \tilde{x} \rangle = b_j\) for all \(j \in [m] \setminus \mathcal{I}\).
		Combining the above, we conclude that \(\langle a_i, \tilde{x} \rangle = b_i\) for all \(i \in [m]\), i.e., \(\tilde{x}\) is a solution to the linear system \(Ax = b\).
	\end{proof}


		Next, we will prove Theorem \ref{main-AmPRDR}. First, we introduce a useful lemma.
	\begin{lemma} \label{tilde}
		Let $\{x^k\}_{k\geq0}$ and $\{z^k\}_{k\geq0}$ be the sequence generated by Algorithm \ref{alg:AmPRDR} and $x_*^0=A^{\dagger}b+(I-A^\dagger A)x^0$. Then 
		$$
		\|x^{k+1} - \tilde{x}^{k+1}\|_2^2 =\cos^2 \theta_k \|\tilde{x}^{k+1} - x_*^0\|_2^2,
		$$ 
		where $\tilde{x}^{k+1}=\frac{1}{2}x^k+\frac{1}{2}z^k$, and \(\theta_k\) is the angle between the vectors \(\tilde{x}^{k+1} - x_*^0\) and \(\zeta_k= \langle z^k - x^k,\, x^k - x^{k-1} \rangle (z^k - x^k) - \|z^k - x^k\|_2^2 (x^k - x^{k-1})\).
	\end{lemma}
	\begin{proof}
		Since $\Vert \zeta_k\Vert^2_2 =\Vert z^k-x^k\Vert_2^2(\Vert z^k-x^k\Vert_2^2\Vert x^k-x^{k-1}\Vert_2^2-\langle z^k-x^k,x^k-x^{k-1}\rangle^2) $ and $\text{dim}(\Pi_k)=2 (k\geq 1)$, we know that $\zeta_k\neq 0$. Let $l_k\coloneqq \frac{\langle \tilde{x}^{k+1} - x_*^0,\zeta_k\rangle}{\Vert \zeta_k\Vert^2_2}$ and note that $\tilde{x}^{k+1}=\frac{1}{2}x^k+\frac{1}{2}z^k$, then we have 
		\begin{equation*}
			\begin{aligned}
				l_k\zeta_k
				&=\frac{\langle x^k - x_*^0,\zeta_k\rangle+\frac{1}{2}\langle z^k - x^k,\zeta_k\rangle}{\Vert \zeta_k\Vert^2_2}\zeta_k\\
				&=\frac{\langle x^k - x_*^0,\zeta_k\rangle}
				{\Vert \zeta_k\Vert^2_2}\zeta_k\\
				&=\frac{\langle x^k - x_*^0,\langle z^k-x^k,x^k-x^{k-1}\rangle (z^k-x^k)-\Vert z^k-x^k\Vert_2^2 (x^k-x^{k-1})\rangle}
				{\Vert z^k-x^k\Vert_2^2(\Vert z^k-x^k\Vert_2^2\Vert x^k-x^{k-1}\Vert_2^2-\langle z^k-x^k,x^k-x^{k-1}\rangle^2)}\zeta_k\\
				%&\quad\ \left(\langle z^k-x^k,x^k-x^{k-1}\rangle (z^k-x^k)-\Vert z^k-x^k\Vert_2^2 (x^k-x^{k-1})\right)\\
				&\overset{(a)}{=}\frac{\langle z^k-x^k,x^k-x^{k-1}\rangle\langle x^k - x_*^0, z^k-x^k\rangle}
				{\Vert z^k-x^k\Vert_2^2(\Vert z^k-x^k\Vert_2^2\Vert x^k-x^{k-1}\Vert_2^2-\langle z^k-x^k,x^k-x^{k-1}\rangle^2)}\zeta_k\\
				%&\quad\ \left(\langle z^k-x^k,x^k-x^{k-1}\rangle (z^k-x^k)-\Vert z^k-x^k\Vert_2^2 (x^k-x^{k-1})\right)\\
				&=\frac{\langle z^k-x^k,x^k-x^{k-1}\rangle^2\langle x^k - x_*^0, z^k-x^k\rangle}
				{\Vert z^k-x^k\Vert_2^2(\Vert z^k-x^k\Vert_2^2\Vert x^k-x^{k-1}\Vert_2^2-\langle z^k-x^k,x^k-x^{k-1}\rangle^2)} (z^k-x^k)\\
				&\quad\ -\underbrace{\frac{\langle z^k-x^k,x^k-x^{k-1}\rangle\langle x^k - x_*^0, z^k-x^k\rangle}
					{\Vert z^k-x^k\Vert_2^2\Vert x^k-x^{k-1}\Vert_2^2-\langle z^k-x^k,x^k-x^{k-1}\rangle^2}}_{\beta_k}(x^k-x^{k-1}),
			\end{aligned}
		\end{equation*}
		where $(a)$ follows from $\langle x^k-x^0_*,x^k-x^{k-1}\rangle=0$ and the last equality follows from the definition of $\zeta_k$.	
		Since 
		\begin{equation*}
			\frac{\langle x^k-z^k,x^k-x^0_*\rangle}{\Vert z^k-x^k\Vert_2^2} 
			=\frac{\frac{1}{2}(\Vert z^k-x^k\Vert_2^2+\Vert x^k-x^0_*\Vert_2^2-\Vert z^k-x^0_*\Vert_2^2)}{\Vert z^k-x^k\Vert_2^2}
			= \frac{1}{2},
		\end{equation*}
		we can obtain that 

		\begin{equation*}
			\begin{aligned}
				&\tilde{x}^{k+1}-l_k\zeta_k \\
				&= x^k+\left(\frac{1}{2} -\frac{\langle z^k-x^k,x^k-x^{k-1}\rangle^2\langle x^k - x_*^0, z^k-x^k\rangle}
				{\Vert z^k-x^k\Vert_2^2(\Vert z^k-x^k\Vert_2^2\Vert x^k-x^{k-1}\Vert_2^2-\langle z^k-x^k,x^k-x^{k-1}\rangle^2)}\right) (z^k-x^k)
				\\
				&\quad \ +\beta_k(x^k-x^{k-1})\\
				&=x^k+\left(\frac{1}{2} -\frac{\langle z^k-x^k,x^k-x^{k-1}\rangle^2(-\frac{1}{2}\Vert z^k-x^k\Vert_2^2)}
				{\Vert z^k-x^k\Vert_2^2(\Vert z^k-x^k\Vert_2^2\Vert x^k-x^{k-1}\Vert_2^2-\langle z^k-x^k,x^k-x^{k-1}\rangle^2)}\right) (z^k-x^k)
				\\
				&\quad \ +\beta_k(x^k-x^{k-1})\\
				&=x^k+\frac{1}{2} \frac{\Vert z^k-x^k\Vert_2^2\Vert x^k-x^{k-1}\Vert_2^2}
				{\Vert z^k-x^k\Vert_2^2\Vert x^k-x^{k-1}\Vert_2^2-\langle z^k-x^k,x^k-x^{k-1}\rangle^2} (z^k-x^k)
				+\beta_k(x^k-x^{k-1})\\
				&=x^k+\frac{\Vert x^k-x^{k-1}\Vert_2^2 \langle x^k-z^k,x^k-x^0_*\rangle}
				{\Vert z^k-x^k\Vert_2^2\Vert x^k-x^{k-1}\Vert_2^2-\langle z^k-x^k,x^k-x^{k-1}\rangle^2} (z^k-x^k)
				+\beta_k(x^k-x^{k-1})\\
				&=x^k+\alpha_k(z^k-x^k)
				+\beta_k(x^k-x^{k-1}) \\
				&= x^{k+1}.
			\end{aligned}
		\end{equation*}
		Thus we have 
		$$
		\|x^{k+1} - \tilde{x}^{k+1}\|_2^2 =l_k^2\|\zeta_k\|_2^2 = \frac{\langle \tilde{x}^{k+1} - x_*^0,\zeta_k\rangle^2}{\Vert \zeta_k\Vert^2_2}=\cos^2 \theta_k \|\tilde{x}^{k+1} - x_*^0\|_2^2
		$$
		as desired.
	\end{proof}

	Now, we are ready to prove Theorem \ref{main-AmPRDR}.
	\begin{proof}[Proof of Theorem \ref{main-AmPRDR}]
		Since $x^{k+1} - x_*^0$ is orthogonal to $\Pi_k$ and $x^{k+1}, \tilde{x}^{k+1} \in \Pi_k$, the Pythagorean Theorem implies that
		\begin{equation*}
			\|x^{k+1} - x_*^0\|_2^2 = \|\tilde{x}^{k+1} - x_*^0\|_2^2 - \|x^{k+1} - \tilde{x}^{k+1}\|_2^2.
		\end{equation*}
		From Lemma \ref{tilde}, we know that 
		$$
		\|x^{k+1} - \tilde{x}^{k+1}\|_2^2  = \cos^2 \theta_k \|\tilde{x}^{k+1} - x_*^0\|_2^2,
		$$
		where $\theta_k$ denotes the angle between $\tilde{x}^{k+1} - x_*^0$ and $\zeta_k$.
		%	In the case that $\zeta_k = 0$, we stipulate that $\theta_k=\frac{\pi}{2}$, so
		%	$$
		%	\|x^{k+1} - \tilde{x}^{k+1}\|_2^2 = 0 = \cos^2 \theta_k \|\tilde{x}^{k+1} - x_*^0\|_2^2.
		%	$$
		%	Thus, regardless of whether $\zeta_k = 0$, there holds 
		%	$$
		%	\|x^{k+1} - \tilde{x}^{k+1}\|_2^2 = \cos^2 \theta_k \|\tilde{x}^{k+1} - x_*^0\|_2^2.
		%	$$
		Hence we have 
		$$
		\begin{aligned}
			\mathbb{E}\left[\|x^{k+1}-x_*^0\|_2^2 \mid  x^k\right]&=\mathbb{E}_{(i,j)\in \mathcal{Q}_k}\left[\|x^{k+1}-x_*^0\|_2^2 \mid  x^k\right]
			\\&=\mathbb{E}_{(i,j)\in \mathcal{Q}_k}\left[\|\tilde{x}^{k+1}-x_*^0\|_2^2  \mid x^k\right]-\mathbb{E}_{(i,j)\in \mathcal{Q}_k}\left[\|x^{k+1}-\tilde{x}^{k+1}\|_2^2 \mid x^k\right]
			\\
			&=\mathbb{E}_{(i,j)\in \mathcal{Q}_k}\left[(1-\cos^2\theta_k)\|\tilde{x}^{k+1}-x_*^0\|_2^2 \mid  x^k\right]
			\\
			&\leq
			\left( 1-\gamma_k \right) \mathbb{E}_{(i,j)\in \mathcal{Q}_k}\left[\|\tilde{x}^{k+1}-x_*^0\|_2^2 \mid  x^k\right]\\
			&\leq \left( 1-\gamma_k \right)\mathbb{E}\left[\|\tilde{x}^{k+1}-x_*^0\|_2^2 \mid  x^k\right],
		\end{aligned}
		$$
		where the first inequality follows from the definition of $\gamma_k$.
		From Theorem \ref{main-PRDR} we can get that when the iteration sequence $\{x^k\}_{k\geq0}$ generated by Algorithm \ref{alg:AmPRDR} using strategy I, we have
		$$
		\mathbb{E}\left[\|\tilde{x}^{k+1}-x_*^0\|_2^2 \mid  x^k\right]
		\leq
		\left( 1-\gamma_k \right)
		\left(1-\frac{\sigma_{\min}^2(M^{\frac{1}{2}}A)}{\|A\|^2_F}
		\right)
		\|x^k - x_*^0\|_2^2 ,
		$$
		and when the iteration sequence $\{x^k\}_{k\geq 0}$ generated by Algorithm \ref{alg:AmPRDR} using strategy II, we have
		$$
		\mathbb{E}\left[\|x^{k+1}-x_*^0\|_2^2 \mid  x^k\right]
		\leq
		\left( 1-\gamma_k \right)
		\left(
		1-2
		\frac{\sigma_{\min}^2(N^{\frac{1}{2}}A)}%分子
		{ \Vert A \Vert_F^4 -\Vert AA^{\top} \Vert_F^2}%分母
		\right)
		\|x^k - x_*^0\|_2^2 ,
		$$
		where $M$ and $N$ are given by \eqref{definition-M} and \eqref{definition-N}, respectively.
	\end{proof}





