\end{align*}
\end{lemma}
\begin{proof} Assume that ${\mathcal B}=\{b_0,b_1,\ldots,b_{t-1}\}\subseteq [\bar{s}]$ with $b_0<b_1<\ldots<b_{t-1}$,  and ${\mathcal G}_{\mathcal B}=\{{\mathcal G}_{b_0},{\mathcal G}_{b_1},\ldots,{\mathcal G}_{b_{t-1}}\}$ with ${\mathcal G}_{b_j}=\{g_{b_j,0},g_{b_j,1},\ldots,g_{b_j,m_j-1}\}\subseteq [u], j\in [t]$ such that $m_0+m_1+\ldots+m_{t-1}=\delta$. From \eqref{eqA-1}, $f_{\mathcal B}(\mathbf{x}_{{\mathcal B}\bar{s}+[\bar{s}]})$ is the product of some determinants $\text{det}(\boldsymbol{\varphi}_{\mathcal B}^{(\delta)}(\theta^{{\mathcal G}_{\mathcal B}}\odot \mathbf{x}_{{\mathcal B}\bar{s}+[\bar{s}]}))$.  For a given determnant $\text{det}(\boldsymbol{\varphi}_{\mathcal B}^{(\delta)}(\theta^{{\mathcal G}_{\mathcal B}}\odot \mathbf{x}_{{\mathcal B}\bar{s}+[\bar{s}]}))$, all the elements that are non-zero and located in the same row share the same degree. More precisely, for $e\in[\bar{s}]$  and $j\in[\delta]$, all the nonzero entries in the $(e\delta+j)$-th row of $\boldsymbol{\varphi}_{\mathcal B}^{(\delta)}(\theta^{{\mathcal G}_{\mathcal B}}\odot \mathbf{x}_{{\mathcal B}\bar{s}+[\bar{s}]})$  have the same degree $j$, it follow that $\text{det}(\boldsymbol{\varphi}_{\mathcal B}^{(\delta)}(\theta^{{\mathcal G}_{\mathcal B}}\odot \mathbf{x}_{{\mathcal B}\bar{s}+[\bar{s}]}))$ is a homogeneous polynomial. So, $f_{\mathcal B}(\mathbf{x}_{{\mathcal B}\bar{s}+[\bar{s}]})$ is also a homogeneous polynomial.

Note that the following term 
\begin{align}\label{eqA-3-1}
(\prod_{j\in[m_0]}\prod_{e\in[\bar{s}]}(\theta^{g_{b_0,j}}x_{b_0\bar{s}+e})^{j})\cdot(\prod_{j\in[m_1]}\prod_{e\in[\bar{s}]}(\theta^{g_{b_1,j}}x_{b_1\bar{s}+e})^{m_0+j})\cdots (\prod_{j\in[m_{t-1}]}\prod_{e\in[\bar{s}]}(\theta^{g_{b_{t-1},j}}x_{b_{t-1}\bar{s}+e})^{m_0+\ldots+m_{t-2}+j})
\end{align}
appears in the expansion of $\text{det}(\boldsymbol{\varphi}_{\mathcal B}^{(\delta)}(\theta^{{\mathcal G}_{\mathcal B}}\odot \mathbf{x}_{{\mathcal B}\bar{s}+[\bar{s}]}))$, and can only be obtained by picking constant entries from 
$\varphi_{b_0}^{(\delta)}(\theta^{g_{b_0,0}}\odot \mathbf{x}_{b_0\bar{s}+[\bar{s}]})$, degree-1 entries from $\varphi_{b_0}^{(\delta)}(\theta^{g_{b_0,1}}\odot \mathbf{x}_{b_0\bar{s}+[\bar{s}]})$, $\ldots$, degree-$(m_0-1)$ entries from $\varphi_{b_0}^{(\delta)}(\theta^{g_{b_0,m_0-1}}\odot \mathbf{x}_{b_0\bar{s}+[\bar{s}]})$,  degree-$m_0$ entries from $\varphi_{b_1}^{(\delta)}(\theta^{g_{b_1,0}}\odot \mathbf{x}_{b_1\bar{s}+[\bar{s}]})$, and so on. Then,  we can calculate that $\text{det}(\boldsymbol{\varphi}_{\mathcal B}^{(\delta)}(\theta^{{\mathcal G}_{\mathcal B}}\odot \mathbf{x}_{{\mathcal B}\bar{s}+[\bar{s}]}))$ is a nonzero homogeneous polynomial of degree $(0+1+\ldots+m_0-1+\ldots+(m_0+\ldots+m_{t-1}-1))\bar{s}=\bar{s}\delta(\delta-1)/2$. Moreover, for each $i\in{\mathcal B}\bar{s}+[\bar{s}]$, the largest power of $x_i$ occurring in $\text{det}(\boldsymbol{\varphi}_{\mathcal B}^{(\delta)}(\theta^{{\mathcal G}_{\mathcal B}}\odot \mathbf{x}_{{\mathcal B}\bar{s}+[\bar{s}]}))$ is 
\begin{align*}
(\delta-1)+(\delta-2)+\ldots+(\delta-m_{\lfloor i/\bar{s} \rfloor})=m_{\lfloor i/\bar{s} \rfloor}\delta-\dfrac{m_{\lfloor i/\bar{s} \rfloor}(m_{\lfloor i/\bar{s} \rfloor}+1)}{2}.
\end{align*}
Therefore, the largest power of $x_i$ occurring in $f_{\mathcal B}(\mathbf{x}_{{\mathcal B}\bar{s}+[\bar{s}]})$ is 
\begin{align*}
	\sum_{\delta=t}^{ut}\sum_{m_j\in[1,u], j\in[t], \atop m_0+\ldots+m_{t-1}=\delta}{u\choose m_0}\dots{u\choose m_{t-1}}(m_{\lfloor i/\bar{s} \rfloor}\delta-\dfrac{m_{\lfloor i/\bar{s} \rfloor}(m_{\lfloor i/\bar{s} \rfloor}+1)}{2}).
\end{align*}
\end{proof}
\begin{corollary}\label{lmA-2}
The polynomial $f(\mathbf{x}_{[\bar{s}^2]})$ defined in \eqref{eqA-2} is a nonzero homogeneous polynomial in $\mathbb{F}_q[x_0,x_1,\ldots,x_{\bar{s}^2-1}]$, and the largest power of $x_i$, $i\in[\bar{s}^2]$ is 
\begin{align*}
\text{deg}_{x_i}=\sum_{t=1}^{\bar{s}}{\bar{s}-1\choose t-1}\sum_{\delta=t}^{ut}\sum_{m_j\in[1,u], j\in[t], \atop m_0+\ldots+m_{t-1}=\delta}{u\choose m_0}\dots{u\choose m_{t-1}}(m_{\lfloor i/\bar{s} \rfloor}\delta-\dfrac{m_{\lfloor i/\bar{s} \rfloor}(m_{\lfloor i/\bar{s} \rfloor}+1)}{2}).
\end{align*}
\end{corollary}
\begin{remark}
Notice that the status of each $m_j$ in $m_0+\ldots+m_{t - 1}=\delta$ is the same. Therefore, for any two distinct elements $i$ and $i'$ in $[\bar{s}^2]$, we have $\text{deg}_{x_i}=\text{deg}_{x_{i'}}$.  
\end{remark}

Note that  $m_0+\ldots+m_{t-1}=\delta$ with $m_j\in[1,u]$, $j\in[u]$, for any $i\in[\bar{s}^2]$ we know that 
\begin{align*}
	m_{\lfloor i/\bar{s}\rfloor}=\delta-\sum_{j\in[t],\atop j\not=\lfloor i/\bar{s}\rfloor}m_j\leq \delta-t+1,
\end{align*}
then
\begin{align*}
m_{\lfloor i/\bar{s} \rfloor}\delta-\dfrac{m_{\lfloor i/\bar{s} \rfloor}(m_{\lfloor i/\bar{s} \rfloor}+1)}{2}&\leq(\delta-t+1)\delta-\frac{(\delta-t+1)(\delta-t+2)}{2}\\
&=\frac{(\delta-t+1)(\delta+t-2)}{2}.
\end{align*}
Since ${u\choose m_0}\dots{u\choose m_{t-1}}\leq {ut\choose \delta}$, then 
\begin{align}\label{eqA-4}
\nonumber	\text{deg}_{x_i}&=\sum_{t=1}^{\bar{s}}{\bar{s}-1\choose t-1}\sum_{\delta=t}^{ut}\sum_{m_j\in[1,u], j\in[t], \atop m_0+\ldots+m_{t-1}=\delta}{u\choose m_0}\dots{u\choose m_{t-1}}(m_{\lfloor i/\bar{s} \rfloor}\delta-\dfrac{m_{\lfloor i/\bar{s} \rfloor}(m_{\lfloor i/\bar{s} \rfloor}+1)}{2})\\
\nonumber	&\leq\frac{1}{2} \sum_{t=1}^{\bar{s}}{\bar{s}-1\choose t-1}\sum_{\delta=t}^{ut}\sum_{m_j\in[1,u], j\in[t], \atop m_0+\ldots+m_{t-1}=\delta}{ut\choose \delta}(\delta-t+1)(\delta+t-2)\\
	&\leq\frac{1}{2} \sum_{t=1}^{\bar{s}}\sum_{\delta=t}^{ut}{\bar{s}-1\choose t-1}{ut\choose \delta}{\delta-1\choose t-1}(\delta-t+1)(\delta+t-2).
	 \end{align}
\subsection{The proof of Lemma \ref{lm6}}
\begin{lemma}\label{lmA-3}(\cite{LWHY})
Let $f=
f(x_1,\ldots, x_n)$ be a nonzero polynomial in $\mathbb{F}_q[x_1, . . . , x_n]$. Let
$d_i = \text{deg}_{x_i}(f)$ be the largest power of $x_i$ occurring in any
monomial of $f$, and $d=max(d_1,\ldots,d_n)$. Let ${\mathcal S}$ be a subset
of  $\mathbb{F}_q$ with $|{\mathcal S}|\geq n+d$. Then there exist $n$ distinct elements
$s_1, s_2,\ldots, s_n\in S$ such that $f(s_1,\ldots,s_n)\not=0$.
\end{lemma}

Recall that we need to choose $\bar{n}\bar{s}$ distinct elements $\boldsymbol{\lambda}_{[\bar{n}\bar{s}]}$ from $\mathbb{F}_q$ such that $\theta^{[u]}\boldsymbol{\lambda}_{[\bar{n}\bar{s}]}$ are $n\bar{s}$ distinct elements, and satisfy \eqref{eqA-3}, i,e, $f(\boldsymbol{\lambda}_{a\bar{s}^2+[\bar{s}^2]})\not=0$, $a\in [\tilde{n}]$. According to
Corollary \ref{lmA-2} and \eqref{eqA-4}, $f(\mathbf{x}_{[\bar{s}^
2]})$ is a nonzero polynomial in $\mathbb{F}_q[\mathbf{x}_{[\bar{s}^2]}]$, and
its degree of each variable $x_i$, $i\in[\bar{s}^2]$ does not exceed $\Omega(\bar{s},u)$, it follow that $\Omega(\bar{s},u)\geq max(d_0,\ldots,d_{\bar{s}^2-1})$ where $d_i=\text{deg}_{x_i}(f(\mathbf{x}_{[\bar{s}^2]}))$. Then by
Lemma \ref{lmA-3}, for each $a\in[\tilde{n}]$, we can choose $\boldsymbol{\lambda}_{a\bar{s}^2+[\bar{s}^2]}$ from a
subset ${\mathcal S}\subseteq Q$ with size $|{\mathcal S}|\geq\bar{s}^2+\Omega(\bar{s},u)\geq\bar{s}^2+max(d_1,\ldots,d_{\bar{s}^2-1})$ 
satisfying that
$f(\boldsymbol{\lambda}_{a\bar{s}^2+[\bar{s}^2]})\not=0$. As $q/u\geq \bar{n}\bar{s}+\Omega(\bar{s},u)$, we can repeat
this process $\bar{n}/\bar{s}$ times, and the total complexity is $O_{\bar{s}}(n)$.
Since $\bar{n}\bar{s}$ distinct elements $\boldsymbol{\lambda}_{[\bar{n}\bar{s}]}\subset Q$, then it is easy to see that $\theta^{[u]}\boldsymbol{\lambda}_{[\bar{n}\bar{s}]}$ are $n\bar{s}$ distinct elements in $\mathbb{F}_q$. This
concludes the proof of Lemma \ref{lm6}. 
\subsection{The proof of Lemma \ref{lm7}}
Since $f(\mathbf{x}_{[\bar{s}^2]})$ is a nonzero homogeneous polynomial, it follows that
\begin{align*}
	f(x^{a\bar{s}^2},x^{a\bar{s}^2+1},\ldots,x^{a\bar{s}^2+\bar{s}^2-1})=x^{a\bar{s}^2deg(f)}f(1,x,\ldots,x^{\bar{s}-1}).
\end{align*}
Consider the polynomial
\begin{align*}
	h(x)=f(1,x,\ldots,x^{\bar{s}-1}),
\end{align*}
that is,  we set the value of $x_i$ to be $x^i$  in the polynomial $f(\mathbf{x}_{[\bar{s}^2]})$. If $h(\xi)\not=0$, then the $\bar{n}\bar{s}$ values $\lambda_i=\xi^i$, where $i\in[\bar{n}\bar{s}]$, are all distinct and satisfy the the local constraints \eqref{eq3-5} and \eqref{eq3-6}.	

Given any non-empty subset ${\mathcal B}\subseteq[\bar{s}]$, we set 
\begin{align*}
	h_{{\mathcal B}}(x)=f_{{\mathcal B}}(x^i:i\in{\mathcal B}\bar{s}+[\bar{s}])\in\mathbb{F}_p[x].
\end{align*}
Let ${\mathcal B}=\{b_0,b_1,\ldots,b_{t-1}\}\subseteq [\bar{s}]$ with $b_0<b_1<\ldots<b_{t-1}$. By applying the same approach as \eqref{eqA-3-1}, we can check that the term 
\begin{align*}
\prod_{z\in[t]}\prod_{j\in[m_z]}\prod_{e\in[\bar{s}]}(\theta^{g_{b_z,j}}x^{b_z\bar{s}+e})^{m_0+\ldots+m_{z-1}+j}
\end{align*}
uniquely has the highest degree in the polynomial $h_{{\mathcal B}}(x)$. In the same way, the term 
\begin{align*}
	\prod_{z\in[t]}\prod_{j\in[m_z]}\prod_{e\in[\bar{s}]}(\theta^{g_{b_z,j}}x^{b_z\bar{s}+e})^{\delta-1-(m_0+\ldots+m_{z-1}+j)}
\end{align*}
uniquely has the lowest degree in the polynomial $h_{{\mathcal B}}(x)$. Set
\begin{align*}
	M_{\mathcal B}=\sum_{z\in[t]}\sum_{j\in[m_z]}\sum_{e\in[\bar{s}]}({b_z\bar{s}+e})(m_0+\ldots+m_{z-1}+j),
\end{align*}
\begin{align*}
	m_{\mathcal B}=\sum_{z\in[t]}\sum_{j\in[m_z]}\sum_{e\in[\bar{s}]}({b_z\bar{s}+e})(\delta-1-m_0-\ldots-m_{z-1}-j),
\end{align*}
we have $h_{\mathcal B}(x)=x^{m_{\mathcal B}}\bar{h}_{\mathcal B}(x)$, where $\bar{h}_{\mathcal B}(x)$ is a polynomial with degree $deg(\bar{h}_{\mathcal B})=M_{\mathcal B}-m_{\mathcal B}$.
We can verify that 
\begin{align*}
	deg(\bar{h}_{\mathcal B})&=M_{\mathcal B}-m_{\mathcal B}\\
	&=\sum_{z\in[t]}\sum_{j\in[m_z]}\sum_{e\in[\bar{s}]}({b_z\bar{s}+e})(2(m_0+\ldots+m_{z-1}+j)-\delta+1)\\
	&=\sum_{z\in[t]}\sum_{j\in[m_z]}(2(m_0+\ldots+m_{z-1}+j)-\delta+1)(b_z\bar{s}^2+\frac{\bar{s}(\bar{s}-1)}{2})\\
	&=\bar{s}^2\sum_{z\in[t]}\sum_{j\in[m_z]}(2(m_0+\ldots+m_{z-1}+j)-\delta+1)b_z\\
	&\leq \bar{s}^2\sum_{z\in[t]}\sum_{j\in[m_z]}(m_0+\ldots+m_{z-1}+j)b_z\\
	&\leq \bar{s}^2\sum_{z\in[t]}u^2(z+1)b_z
	\leq u^2\bar{s}^2\sum_{z\in[\bar{s}]}(z+1)z
	\leq u^2\bar{s}^2\sum_{z\in[\bar{s}]}\bar{s}^2=u^2\bar{s}^5.
\end{align*}
Let $q=p^m$. If $m>u^2\bar{s}^5$, then the primitive element $\xi$ satisfies $\bar{h}_{\mathcal B}(\xi)\not=0$.  Consequently, for every subset ${\mathcal B}\subseteq[\bar{s}]$, we have $h_{\mathcal B}(\xi)\not=0$. Furthermore, we impose the condition that the field size  $q>n\bar{s}$ to ensure that the $\bar{n}\bar{s}$ elements $\lambda_i=\xi^i$ for $i\in[\bar{n}\bar{s}]$ are distinct, and that the $n\bar{s}$ elements $\theta^{[u]}\boldsymbol{\lambda}_{[\bar{n}\bar{s}]}$ are also  distinct. This concludes our proof of Lemma \ref{lm7}.

\section{The proof of Lemma \ref{lm10}} \label{app-B}

Let $\mathbf{x}_{[\bar{s}^2]}$ be $\bar{s}^2$ unknown variables in $\mathbb{F}_q$.
For a non-empty subset ${\mathcal B}=\{b_0,b_1,\ldots,b_{t-1}\}\subseteq [\bar{s}]$ with $b_0<b_1<\ldots<b_{t-1}$, let
\begin{align*}
	\mathbf{x}_{{\mathcal B}\bar{s}+[\bar{s}]}=(x_{b\bar{s}+j}:b\in{\mathcal B},j\in[\bar{s}])
\end{align*} be a sub-vector of $\mathbf{x}_{[\bar{s}^2]}$.
Recall the definition of $\boldsymbol{\varphi}_{\mathcal B}^{(m)}(\mathbf{x}_{[\bar{s}t]})$ in \eqref{eq501}. We define 
\begin{align} \label{eqA-5}
	f'_{\mathcal B}(\mathbf{x}_{{\mathcal B}\bar{s}+[\bar{s}]})=\text{det}(\boldsymbol{\varphi}_{\mathcal B}(\mathbf{x}_{{\mathcal B}\bar{s}+[\bar{s}]}))
\end{align}
and
\begin{align}\label{eqA-6}
	f'(\mathbf{x}_{[\bar{s}^2]})=\prod_{{\mathcal B}\subseteq [\bar{s}]}f_{\mathcal B}(\mathbf{x}_{{\mathcal B}\bar{s}+[\bar{s}]}). 
\end{align}
Therefore, the local constraints specified in \eqref{eq3-18} are able to be reformulated as
\begin{align}\label{eqA-7}
	f'(\boldsymbol{\lambda}_{a\bar{s}^2+[\bar{s}^2]}^u)\not=0, a\in[\tilde{n}].
\end{align}
\begin{lemma}\label{lmA-4}
	For each non-empty ${\mathcal B}\subseteq [\bar{s}]$ of size $|{\mathcal B}|=t$,
	the polynomial $f'_{\mathcal B}(\mathbf{x}_{{\mathcal B}\bar{s}+[\bar{s}]})$ defined in \eqref{eqA-1} is a nonzero homogeneous
	polynomial of degree $\bar{s}t(t-1)/2$. In addition, the largest
	power of $x_i$, $i\in{\mathcal B}\bar{s}+[\bar{s}]$ in $f'_{\mathcal B}(\mathbf{x}_{{\mathcal B}\bar{s}+[\bar{s}]})$ is $t-1$.
\end{lemma}
We omit the proof of Lemma \ref{lmA-4}, as it is almost the same as the proof of Lemma 12 in \cite{LWHY}.

\begin{corollary}\label{lmA-5}
	The polynomial $f'(\mathbf{x}_{[\bar{s}^2]})$ defined in \eqref{eqA-2} is a nonzero homogeneous polynomial in $\mathbb{F}_q[x_0,x_1,\ldots,x_{\bar{s}^2-1}]$, and the largest power of $x_i$, $i\in[\bar{s}^2]$ is 
	\begin{align*}
		\text{deg}_{x_i}=\sum_{t=1}^{\bar{s}}{\bar{s}-1\choose t-1}(t-1)=(\bar{s}-1)2^{\bar{s}-2}.
	\end{align*}
\end{corollary}

Recall that we need to choose $\bar{n}\bar{s}$ distinct elements $\boldsymbol{\lambda}_{[\bar{n}\bar{s}]}$ from $\mathbb{F}_q$ such that $\boldsymbol{\lambda}_{[\bar{n}\bar{s}]}^u$ are also $\bar{n}\bar{s}$ distinct elements, and satisfy \eqref{eqA-7}, i,e, $f'(\boldsymbol{\lambda}_{a\bar{s}^2+[\bar{s}^2]})\not=0$, $a\in [\tilde{n}]$. According to
Corollary \ref{lmA-5}, $f(\mathbf{x}_{[\bar{s}^2]})$ is a nonzero polynomial in $\mathbb{F}_q[\mathbf{x}_{[\bar{s}^2]}]$, and
its degree of each variable $x_i$, $i\in[\bar{s}^2]$ is $(\bar{s}-1)2^{\bar{s}-2}$. Then by
Lemma \ref{lmA-3}, for each $a\in[\tilde{n}]$, we can choose $\boldsymbol{\lambda}_{a\bar{s}^2+[\bar{s}^2]}$ from a
subset ${\mathcal S}\subseteq Q\subset \mathbb{F}_q$ with size $|{\mathcal S}|\geq\bar{s}^2+(\bar{s}-1)2^{\bar{s}-2}$ 
satisfying that
$f(\boldsymbol{\lambda}_{a\bar{s}^2+[\bar{s}^2]})\not=0$. As $q/u\geq \bar{n}\bar{s}+(\bar{s}-1)2^{\bar{s}-2}$, we can repeat
this process $\bar{n}/\bar{s}$ times, and the total complexity is $O_{\bar{s}}(n)$.
Since the $\bar{n}\bar{s}$  elements $\boldsymbol{\lambda}_{[\bar{n}\bar{s}]}\subseteq Q$ are distinct, then it is easy to see that $\boldsymbol{\lambda}_{[\bar{n}\bar{s}]}^u$ are also the $\bar{n}\bar{s}$ distinct elements in $\mathbb{F}_q$. This
concludes the proof of Lemma \ref{lm10}. 



