\section{Diameter in graphs with bounded treewidth}
\label{sec:diamtreewidth}

%\fabian{Repeat the setup here and state high-level overview. How do the lemmas/theorems interact.}
In this section, we discuss the computation of the diameter of a continuous graph with treewidth $k$.
Note that computing the diameter of continuous trees (i.e., treewidth $1$) can be reduced to the discrete setting, 
because in trees the diameter is always attained by two vertices. 
Thus, we restrict our attention to $k>1$.
As in~\cite{Abboudetal2016,BHM20,Cabello19,CABELLO2009815}, we use orthogonal range searching to work with distance-related problems in graphs of bounded treewidth. However, because we consider continuous graphs, we have to consider pairs of edges instead of pairs of vertices, and the interaction between edges is more complex. We handle this by using more dimensions in the range searching space. 

Sometimes we need to consider an orientation for each edge of $G$,
to distinguish its vertices. We orient the edges of $G$ arbitrarily, but 
keep track of the orientation.
We use $uv$ when the orientation is not relevant and $(u,v)$ or $(v,u)$,
depending on the orientation, when we consider it oriented.
We use $E(G)$ in both cases.
%\antonia{Up to here, I didn't understand why edges will be oriented, when we consider undirected graphs. Maybe specify "sometimes" [we need...]? }

\subsection{Characterization of the diameter via walks}

e start with a characterization of the diameter in the continuous setting that uses the length of walks (compare to \cref{fig:cases}).
For each $aa',bb' \in E(G)$, let \emph{$W(aa',bb')$} be a shortest closed walk 
passing through all the interior points of $aa'$ and $bb'$.

%\rodrigo{Anyone knows what the star means?}

\begin{restatable}{lemmastar}{LemClosedWalks}\label{lem:closed_walks}
For each $aa',bb' \in E(G)$, 
    ${\max}_{p\in aa', \, q\in bb'} d_{\GG}(p,q)=\frac{\ell(W(aa',bb'))}{2}.$
\end{restatable}

\begin{proof}
     Let $p\in aa'$ and $q\in bb'$ be two points such that $d_{\GG}(p,q)= \underset{p'\in aa', \, q'\in bb'}{\max} d_{\GG}(p',q')$. 
     Let $P=au_1\ldots u_kb$ be a shortest $ab$-path. Consider \cref{fig:closed_walks}.
     Exchanging the roles of $a$ and $a'$, if needed, and the roles of $b$ and $b'$, if needed, 
     we assume without loss of generality that $\ell(pa)+\ell(P)+\ell(bq)=d_{\GG}(p,q)$. 
     This also covers the cases where $p$ or $q$ are vertices.
     Let $P'=a'u'_1\ldots u'_{k'}b'$ be a shortest $a'b'$-path. 
     If $\ell(pa')+\ell(P')+\ell(b'q)<d_{\GG}(p,q)$, then there is a $pq$-path shorter than $d_{\GG}(p,q)$, which is not possible.
     If $\ell(pa')+\ell(P')+\ell(b'q)>d_{\GG}(p,q)$, then there is a pair $p'\in aa'$ and $q'\in bb'$ with $d_{\GG}(p',q')>d_{\GG}(p,q)$. 
     This contradicts that $d_{\GG}(p,q)$ is the maximal distance of all pairs with one point in the interior of $aa'$ and one in the interior of $bb'$. 
     Therefore, it holds 
     \[
        \ell(pa')+\ell(P')+\ell(b'q) ~=~ d_{\GG}(p,q) ~=~ \ell(pa)+\ell(P)+\ell(bq).
     \]
     The sequence $pa,au_1\ldots u_kb,bq,qb',b'u'_{k'}\ldots u'_1a',a'p$ defines a shortest closed walk $W'$
     passing through all the interior points of $aa'$ and $bb'$ and has length $2 d_{\GG}(p,q)$.
     Therefore, 
     \[
        d_{\GG}(p,q) ~=~ \frac{\ell(W')}{2} ~\le~ \frac{\ell(W(aa',bb'))}{2},
     \]
     because $W(aa',bb')$ is a shortest closed walk passing through all the points in the interior of $aa'$ and $bb'$.
     On the other hand, any closest walk passing through $p$ and $q$ has length at least $2 d_{\GG}(p,q)$,
     and therefore $\ell(W(aa',bb'))\le 2 d_{\GG}(p,q)$.
\end{proof}



