The following corollary is an immediate consequence of \cref{lem:closed_walks}.

\begin{corollary}\label{theo:diam-walks}
    If $H\subseteq G$ defines the continuous subgraph $\HH$ of $\GG$,
    then $\diam(\HH,\GG) = \tfrac{1}{2}\cdot \max \{ \ell(W(aa',bb'))\mid aa',bb'\in E(H)\}$.
    %\[ \diam(\GG) = \max_{ aa', \, bb'\in E(G)} \frac{\ell(W(aa',bb'))}{2}.\]
\end{corollary}

For our computation, we use the following closed formula.

\begin{restatable}{lemmastar}{LemLengthW}\label{lem:lengthW}
    For each $aa', bb'\in E(G)$, it holds that
    \[
        \ell(W(aa',bb')) = \ell(aa')+\ell(bb') + 
            \min\{ d_G(a,b)+ d_G(a',b') , \, d_G(a,b')+ d_G(a',b)\}.
    \]
\end{restatable}

\begin{proof}
    Set $R_1= \ell(aa')+ d_G(a',b')+ \ell(b'b) + d_G(b,a)$
    and $R_2= \ell(aa')+ d_G(a',b) +\ell(bb') + d_G(b',a)$.
    Both quantities are the length of some closed walk passing through
    the interior of $aa'$ and $bb'$.
    Therefore $\ell(W(aa',bb')) \le \min \{ R_1,R_2\}$.

    Consider now the optimal walk $W(aa',bb')$ and orient it
    such that we go along $aa'$ from $a$ to $a'$. In this direction, 
    we may walk $bb'$ from $b$ to $b'$ or in the opposite direction. 
    In the first case the length of $W(aa',bb')$ is at least $R_2$, 
    while in the second case the length is at least $R_1$.
    In either case, we have $\ell(W(aa',bb')) \ge \min\{ R_1,R_2\}$.
\end{proof}

For each pair of oriented edges $(a_0,a_1),(b_0,b_1)\in E(G)$,
\cref{lem:lengthW} implies that there are two possible values for
$\ell(W(a_0a_1,b_0b_1))$. 
We say that $(a_0,a_1,b_0,b_1)$ is of \emph{type $1$} if
\[
    \ell(W(a_0a_1,b_0b_1)) = \ell(a_0a_1)+\ell(b_0b_1) + 
        d_G(a_0,b_0)+ d_G(a_1,b_1),
\]    
and of \emph{type $2$} otherwise. 
For each oriented edge $(b_0,b_1)\in E(G)$ and type $\tau\in \{1,2\}$, we define 
\begin{align*}
    \Type_\tau(b_0,b_1) &= \{ (a_0,a_1)\in E(G)\mid (a_0,a_1,b_0,b_1) \text{ is of type $\tau$}\}.
\end{align*}
Therefore, 
$
    (a_0,a_1)\in \Type_1(b_0,b_1) ~~\Longleftrightarrow~~
    d_G(a_0,b_0)+ d_G(a_1,b_1) \le d_G(a_0,b_1)+ d_G(a_1,b_0)
$.


\subsection{Diameter across the portals}
\label{sec:diam-across}
%Recall that $G$ is a graph with $n$ vertices and $m$ edges.
Let $(A,B,S)$ be a separation in $G$ with $k$ portals. We fix an enumeration $s_1,\dots,s_k$ of them. 
% Let $(A,B,S)$ be a separation in $G$ where $S$ has at most $k$ portals. 
% For simplicity, we assume that $S$ contains exactly $k$ portals 
% (it may well happen that is has fewer) and fix an enumeration 
% $s_1,\dots,s_k$ of them. 
% Recall that each path from $a\in A$ to $b\in B$ must go through a vertex of $S$.
Let $E_A\subseteq E(G[A])$ be the edge sets of the subgraph of $G$ induced by $A$ and $E_B\subseteq E(G[B])$, respectively;
%$E_A$ and $E_B$ are 
not necessarily disjoint.
%
For each index $i\in [k]$, each vertex $a\in A$, and each vertex $b\in B$,
let $\varphi(i;a,b)$ be the logic predicate that holds whenever 
$s_i$ is the first portal in the enumeration that lies in some shortest path from $a$ to $b$.
Formally, 
\begin{align*}
    \varphi(i;a,b) ~=~ &\bigwedge_{j<i}
            \big[ d_G(a,b) < d_G(a,s_j) + d_G(s_j,b)\big] 
            ~\wedge~ \big[d_G(a,b) = d_G(a,s_i) + d_G(s_i,b)\big] \wedge \\ 
            &\bigwedge_{j>i}\big[d_G(a,b) \le d_G(a,s_j) + d_G(s_j,b)\big].
\end{align*}
It is easy to see that, for each $(a,b)\in A\times B$, 
there exists a unique index $i\in [k]$ where $\varphi(i;a,b)$ holds (in other words, $|\{ i\in [k] \mid \varphi(i;a,b) \}|=1$).

We extend this to the four shortest paths defined by two 
vertices $a_0,a_1\in A$ and two vertices $b_0,b_1\in B$, by defining the following predicate for all
$\kappa=(i_{0,0},i_{0,1},i_{1,0},i_{1,1})\in [k]^4$:
%all $a_0,a_1\in A$, and all $b_0,b_1\in B$:
\begin{align*}
\Phi(\kappa; a_0,a_1,b_0,b_1) =
    \Phi((i_{0,0},i_{0,1},i_{1,0},i_{1,1}); a_0,a_1,b_0,b_1) =
    \bigwedge_{(\alpha,\beta)\in \{0,1\}^2}
    \varphi(i_{\alpha,\beta}; a_\alpha,b_\beta).
\end{align*}
Therefore, this predicate holds if and only if,
for each $\alpha,\beta \in \{ 0,1\}$, the index $i_{\alpha,\beta}$
is the smallest index $i$ with the property that $s_i$
lies on some shortest path from $a_\alpha$ to $b_\beta$.
As before, for each $(a_0,a_1,b_0,b_1)\in A^2\times B^2$, 
there exists a unique $4$-tuple
$\kappa\in [k]^4$ where $\Phi(\kappa; a_0,a_1,b_0,b_1)$ holds.
%\rodrigo{Not sure what $R$ is here}\sergio{corrected}
%
For each $\kappa\in [k]^4$, each $(b_0,b_1)\in E_B$,
and each type $\tau$ 
%$\tau\in \{1,2 \}$ 
we define
\begin{align*}
    \hspace{-3mm}\Lambda_\tau(\kappa;b_0,b_1)= \max \{ \ell(W(a_0a_1,b_0b_1)) \mid (a_0,a_1)\in E_A\cap \Type_\tau(b_0,b_1) \wedge \Phi(\kappa;a_0,a_1,b_0,b_1)  \}.
\end{align*}
This represents the maximum length over all edges $(a_0, a_1)$  of a type-$\tau$ walk between $(b_0, b_1)$ and $(a_0, a_1)$, consistent with the portals in $\kappa$.
%\rodrigo{Add some words explaining what $\Lambda_\tau(\kappa;b_0,b_1)$ is? E.g., represents the maximum length over all edges $(a_0, a_1)$  of a type-$\tau$ walk between $(b_0, b_1)$ and $(a_0, a_1)$, consistent with the portals in $\kappa$.} \sergio{Sounds good and I added it.}
