\begin{restatable}{lemma}{ABcompute}
\label{lem:AB}
    We can compute $\displaystyle\max_{p\in \GG(E_A), q\in \GG(E_B)} d_{\GG}(p,q)$ in 
    $O(m 2^{4k-3} k^4 B(m,4k-3))$ time.
\end{restatable}

\begin{proof}
    We use \cref{le:accross} to compute for each type $\tau\in \{1,2\}$ and indices $\kappa\in [k]^4$ the values $\Lambda_\tau(\kappa;b_0,b_1)$ for all $(b_0,b_1)\in E_B$.
    This requires applying \cref{le:accross} a total of $O(k^4)$ times, and therefore we spend 
    $O(m 2^{4k-3} k^4 B(m,4k-3))$ time.

    Because for each $(a_0,a_1)\in E_A$ and each $(b_0,b_1)\in E_B$,  there
    is one $\kappa\in [k]^4$ such that $\Phi(\kappa;a_0,a_1,b_0,b_1)$,
    and because the types complement each other,
    we have 
    \[
        \forall (b_0,b_1)\in E_B:~~~ \max_{(a_0,a_1)\in E_A} \ell(W(a_0a_1,b_0b_1))  = \max \big\{ \Lambda_\tau(\kappa;b_0,b_1)\mid \kappa\in [k]^4, ~\tau\in \{1,2\} \big\}.
    \]
    Using \cref{lem:lengthW}, we note that 
    \begin{align*}
    \max_{p\in \GG(E_A), q\in \GG(E_B) } d_{\GG}(p,q) 
    &= \max_{(a_0 a_1)\in E_A,~ (b_0 b_1)\in E_B}~~ \max_{p\in \GG(a_0a_1), q\in \GG(b_0b_1)} d_{\GG}(p,q) \\
    &= \max_{(a_0 a_1)\in E_A,~ (b_0 b_1)\in E_B}~~\frac{\ell(W(a_0a_1,b_0b_1))}{2} \\
    &= \tfrac{1}{2} \cdot\max_{(b_0, b_1)\in E_B}~~ \max_{ (a_0,a_1)\in E_A}{\ell(Wa_0a_1,b_0b_1))} \\
    &= \tfrac{1}{2} \cdot \max_{(b_0, b_1)\in E_B}~~ \max \big\{ \Lambda_\tau(\kappa;b_0,b_1)\mid \kappa\in [k]^4, ~\tau\in \{1,2\} \big\}\\
     &= \tfrac{1}{2} \cdot \max \big\{ \Lambda_\tau(\kappa;b_0,b_1)\mid 
     (b_0,b_1)\in E_B,~\kappa\in [k]^4, ~\tau\in \{1,2\} \big\} .
    \end{align*}
    With this expression, it is clear we can obtain the result in
    $O(|E_B|\cdot k^4\cdot 2)$ additional time.
\end{proof}

\textbf{Remark:} We are aware that some log factors can
be shaved off, and that for small $k$ one can improve the analysis slightly. 
