\begin{theorem}[Cabello, Chambers and Erickson~\cite{CabelloCE13}, 
Erickson, Fox and Lkhamsuren~\cite{EricksonFL18}]
\label{thm:pivoting}
	Let $G=(V,E)$ be a plane graph with $n$ vertices and non-negative edge lengths.
%	embedded in an orientable surface of genus $g$.
	Let $f$ be any fixed face of $G$ such that the facial walk of $f$ is a cycle, 
	let $s_0$ be any vertex on the boundary of $f$ 
	and let $T_0$ be the shortest-path tree rooted at $s_0$.
	A sequence 
	of triples $(s_1,e_1,e'_1),\dots,(s_k,e_k,e'_k)\in \GG_f\times E\times E$ can be computed in $O(n\log n)$ time such that:
	\begin{itemize}
	\item $k=O(n)$; %$k=O((1+g)n)$;
	\item $s_i\in [s_0,s_{i+1}]$ for all $i\in [k-1]$;
	\item $T_0$ is a shortest-path tree for all sources $s\in [s_0,s_1]_f$;
	\item the tree $T_i$ (for $i\in [k]$),
		obtained inductively from $T_{i-1}$ by pivoting $e_i$ in and pivoting $e'_i$ out,
		is a shortest-path tree for all sources $s\in [s_i,s_{i+1}]_f$ (where $s_{k+1}=s_0$).
	\end{itemize}
%	Moreover, such a sequence can be computed in 
%$O((g+1) n \log n)$ time with high probability,
%	in $O((g+1) n \log^2 n)$ worst-case time, or in $O((g+1)^2 n \log n)$ worst-case time.
\end{theorem}


\subsection{Eccentricity from a face}

%Let $G$ be a fixed embedded graph on an orientable surface of genus $g$.
We keep assuming that the boundary of $f$ is a cycle.
Consider any source $s$ on $\GG_f$ and let $T_s$ be the shortest-path tree from $s$. %to the vertices of $G$. 
Let $C_s=E(G)\setminus E(T_s)$, that is, the set of edges 
not in the shortest-path tree.
For each edge $xy\in C_s$, there is one point $m_s(xy)$ on the continuous edge $xy\subset \GG$
with two shortest paths from $s$, one through $x$ and one through $y$.
See \cref{fig:slides} for a schema.
For each edge $xy\in C_s$, we define the weight $\omega_s(xy)$ as
the distance from $s$ to $m_s(xy)$, thus
$\omega_s(xy) = d_{\GG}(s,m_s(xy)) = (d_{T_s}(s,x)+ \ell(xy) + d_{T_s}(s,y))/2$.
%\[
%	\omega_s(xy) ~=~ d_{T_s}(s,m_s(xy)) ~= ~(d_{T_s}(s,x)+ \ell(xy) + d_{T_s}(s,y))/2. 
%\]
\antonia{Since we are not in the context of (arbitrary) weighted graphs ("weight" of an edge is its length?), $\omega_s(xy)$ is confusing.}
