     \caption{The dual tree $C_s^*$ for the examples in  \cref{fig:red-blue}. The vertices $a$ and $b$ are added artificially as segments of the dual edge $f^*g^*$.}
	\label{fig:dual}
\end{figure}


\begin{restatable}{theorem}{thmecc}
    \label{thm:oneface}
    For a continuous plane graph $\GG$ with $n$ vertices and a face $f$ of $\GG$,
    we can compute the maximum eccentricity over all points  on the boundary of $f$  in $O(n\log n)$ time.
% 
	% Let $G$ be a continuous plane graph with $n$ vertices, let $f$ be a face of $G$, and let
	% $\GG_f$ be the points on the boundary of the face $f$. 
	% We can compute in $O(n\log n)$ time the maximum of $\ecc(p,G)$ over all $p\in \GG_f$.
\end{restatable}
\begin{proof}
	We change the embedding of $G$, if needed, to assume that $f$
	is the outer face of $G$ and we traverse the face of $f$ counterclockwise.
	As mentioned before, %cutting open some parts of the embedding and adding some zero-length edges, 
    we may assume that the boundary of $f$ is a cycle.

	We compute and store the embedded dual graph $G^*$ of $G$.
	We maintain pointers between the edges in the dual and the primal.
	Since the embedding is going to be static,
	for each vertex of $G$ or $G^*$, we store explicitly 
	the cyclic order of the edges incident to it and rank them so
	that, given a sequence of three edges incident to the same vertex, we can
	identify in $O(1)$ time whether they are clockwise or counterclockwise. 

	For a fixed vertex $s_0$ from $f$, we compute the shortest-path tree $T_0=T_{s_0}$
	from $s_0$ to the vertices of $G$. 
	Computing the sequence $(s_1,e_1,e'_1),\dots,(s_k,e_k,e'_k)\in \GG_f\times E\times E$
	of \cref{thm:pivoting} takes $O(n \log n)$ time.

	For $i\in [k]$, we write $d_i$, $T_i$, $C_i^*$, $m_i$ and $\omega_i$
	instead of $d_{s_i}$, $T_{s_i}$, $C_{s_i}^*$, $m_{s_i}$ and $\omega_{s_i}$.

	We store $T_0$ using the data structure of \cref{sec:dynamicforests} where,
	for each vertex $u$ of $G$, the associated value is $d_{T_0}(s_0,u)$.
	We construct the embedded dual tree $C^*_0$ and store it using 
	the edge-weighted embedded forest of \cref{lem:embeddedtree},
	where, for all $xy\in C_0$, the edge associated with the edge $(xy)^*$ is 
	$\omega_{0}(xy)$. %$=\omega_{s_0}(xy)$. 
    This initialization of $T_0$ and $C^*_0$ takes $O(n\log n)$ time.

	%Consider now any $i\in [k]$ and assume that we have a representation of $T_{i-1}$, 	where each vertex $x$ of $G$ has label $d_{i-1}(s_{i-1},x)$, 	and a representation of the embedded dual tree $C_{i-1}^*$ where  	each edge $xy\in C_{i-1}$ has value $\omega_{i-1}(xy)$.
	Now, we explain how to construct $T_i$ and $C_i^*$ for any $i\in [k]$, given a representation of $T_{i-1}$,
	where each vertex $x$ of $G$ has label $d_{i-1}(s_{i-1},x)$,
	and a representation of the embedded dual tree $C_{i-1}^*$ where 
	each edge $xy\in C_{i-1}$ has value $\omega_{i-1}(xy)$. 
	Let $\lambda_i$ be the length of the $f$-interval 
	$[s_{i-1},s_i]_f$. As we move from $s_{i-1}$ to $s_i$, we note the following
	(see \cref{fig:red-blue,fig:slides}):
	\begin{itemize}
		\item For each vertex $x$ in the red tree $T_u$, the distance
			from $s$ to $x$ increases by $\lambda_i$.  For each vertex in the blue tree $T_v$, it decreases  by $\lambda_i$.
		\item For each green edge $xy$, the distance from $s$ to $m_s(xy)$ does not
			change because $m_s(xy)$ moves also by $\lambda_i$ towards the blue edge.
			Thus, $\omega_s(xy)$ remains constant.
		\item For each red edge $xy$ of $C_s$, the point $m_s(xy)$ does not move,
			but the distance from $s$ to $m_s(xy)$ increases by $\lambda_i$.
		\item For each blue edge $xy$ of $C_s$, the point $m_s(xy)$ does not move,
			but the distance from $s$ to $m_s(xy)$ decreases by $\lambda_i$.			
	\end{itemize}
	Therefore, we obtain $T_i$ from $T_{i-1}$ performing the following
	operations in the dynamic tree: if $su$ belongs to $T_{i-1}$,
	we perform $\Cut(su)$, $\AddTree(\lambda_i,u)$ and $\Link(s,u)$; 
	if $sv$ belongs to $T_{i-1}$, we perform 
	$\Cut(sv)$, $\AddTree(-\lambda_i,v)$ and $\Link(s,v)$;
	then we perform the pivot operation of cutting $e_i$ and linking $e'_i$.

	To obtain $C^*_i$ from $C^*_{i-1}$, we perform the following
	operations in the dynamic tree storing $C^*_{i-1}$.
	Since the blue edges of $C_s$ are precisely those to the left of
	the path from $a$ to $b$, we perform $\AddLeftPath(-\lambda_i,a,b)$.
	Since the red edges of $C_s$ are precisely those to the right of
	the path from $a$ to $b$, we perform $\AddLeftPath(\lambda_i,b,a)$.
	The value of the green edges did not change.
	Now, we have to perform the pivot operation of deleting $(e'_i)^*$ 
	and inserting $e^*_i=(xy)^*$ in $C_i$; note the reverse order
	of operations with respect to the primal tree.
	For this, we $\Cut(e'_i)$, use the data structure for the primal $T_i$
    to obtain $\GetNodeValue(x)=d_i(s_i,x)$ and $\GetNodeValue(y)=d_i(s_i,y)$,
	and compute $\omega_i(xy)$.
	Using the precomputed circular order of $(xy)^*$, we identify
	where to insert the dual edge $(xy)^*$, and call $\Link$ to insert it.

	This finishes the description of how to obtain $T_i$ and $C^*_i$
	from $T_{i-1}$ and $C^*_{i-1}$. At the end of each iteration,
	we can compute $\max_{x\in V} d_{T_s}(s,x)$ by performing
	$\MaxTree(s)$ in the data structure storing $T_i$,
	and we can compute $\max_{e\in C_i} \omega_i(e)$ using 
	$\MaxTree(f^*)$ in the data structure storing $C^*_i$.
	From this, due to \cref{lem:ecc-onestep}, we obtain $\ecc(s_i,\GG)$.

    When $s$ slides over a vertex of the face, we also need to 
    make a small update and the concept of red and blue has
    to be updated; we skip the easy details.

	At each $i\in [k]$, we spend $O(\log n)$ amortised time for $O(1)$
	operations in dynamic forests and $O(1)$ additional work. 
	Thus, the eccentricity
	from each $s_i$ is computed in $O(n\log n)$ time. Finally, note that the eccentricity has to be attained 
	either at $s_0$ or at some point where the shortest-path tree 
	changes. Therefore $\max_{p\in \GG_f}\ecc(p,\GG)=\max_i \ecc(s_i,\GG)$.	
 % \antonia[]{Review 3: The authors omit a minor detail on the time needed to re-embed a planar graph in such a way that the considered face f is the outer face.}\sergio{I would ignore this.}
\end{proof}

Applying \cref{thm:oneface} to each face of an embedding of an $n$-vertex graph $\GG$ with $F$ faces, we can compute its diameter in $O(nF\log n)$ time (compare to \cref{thm:planar}).


\subsection{Mean from a face}

The approach used to compute the diameter of planar graphs can be easily adapted to compute the mean distance.
As we move the source $s$, with edge $e$ we maintain the value 
$\nu(e)=\int_{p\in \GG(e)} d_\GG(s,p) \, dp$.
When we slide $s$ by $\lambda>0$ without pivoting,
the new value $\nu(e)$ is increased by $\lambda$ for the red edges, 
decreased by $\lambda$ for the blue edges, and remains constant for 
the green edges.
When we slide the source $s$ along $uv$ by $\lambda>0$ without pivoting,
for each red edge we have
\[
    \int_{\lambda'\in [0,\lambda]} \int_{p\in \GG(e)} 
        \big( d_\GG(s,p)+\lambda'\big) 
    \, dp \, d\lambda' =
    \lambda \cdot \nu(e) + \ell(e)\cdot \lambda^2/2.
\]
Therefore, it holds
\[
    \int_{\lambda'\in [0,\lambda]} \int_{p\in \GG(T_u)} 
        \big( d_\GG(s,p)+\lambda'\big) 
    \, dp \, d\lambda' =
    \lambda \cdot \sum_{e\in E(T_u)}\nu(e) + (\lambda^2/2)\cdot \sum_{e\in E(T_u)}\ell(e).
\]
Similarly, for each blue edge $e$, we have
\[
    \int_{\lambda'\in [0,\lambda]} \int_{p\in \GG(T_v)} 
        \big( d_\GG(s,p)-\lambda'\big) 
    \, dp \, d\lambda' =
    \lambda \cdot \sum_{e\in E(T_v)}\nu(e) - (\lambda^2/2)\cdot \sum_{e\in E(T_u)}\ell(e).
\]
Finally, for the each green edge $e$, we have
\[
    \int_{\lambda'\in [0,\lambda]} \int_{p\in \GG(e)} 
        \big( d_\GG(s,p)+\lambda'\big) 
    \, dp \, d\lambda' =
    \lambda \cdot \nu(e).
\]

In a dynamic forest we can maintain edge weights and return
the sum of the weights in a subtree. A simple option is 
to assign weight $0$ to all vertices and maintain it constant, 
subdivide each edge $e$ with a vertex $v_e$, 
and attach the weight of $e$ to $v_e$. Then, we can use
a dynamic forest with vertex weights, where only some vertices
have active weights. The operation $\SumTree$ returns the answer. Both values $\sum_{e\in E(T_v)}\nu(e)$
and $\sum_{e\in E(T_u)}\ell(e)$ can be maintained this way.

Finally, for the red edges $e$ outside $T_u$, that is,
those red edges in $C_s$, we can also obtain the sum
of the values $\nu(e)$ and update $\nu(e)$ for those 
edges. This requires an update operation in the embedded
forest, where we add a weight to all the edges to
one side of a path, and obtain the sum of the 
weights on one side of a path. The dynamic forest
we presented can be extended to have these operations.
Sliding the source along the boundary of a face and 
adding the values obtained over each part, we
obtain the following.

\begin{theorem}
    Let $G$ be a graph planar with $n$ vertices, 
    positive edge-lengths, and let $\GG$ be the corresponding continuous graph.
    Let $H$ be a subgraph of $G$ and let $\HH\subseteq \GG$
    be the corresponding continuous subgraph.
    Let $f$ be a face in some given embedding of $G$.
    In  $O(n\log n)$ time, we can compute  the value
    \[
        \int_{s\in \HH\cap f} \int_{q\in \HH} 
            d_\GG(s,p) \, dq \, ds.
    \]
\end{theorem}

Fix an embedding of a planar graph $G$.
By adding over all faces $f$ of the embedding the value
$\int_{s\in \HH\cap f} \int_{q\in \HH} d_\GG(s,p) \, dq \, ds$, we can compute  $\mean(\HH,\GG)$ in $O(nF\log n)$ time (compare to \cref{thm:planar}).

