\subsection{Pruning Loss}

Following the magnitude-based pruning criterion~\cite{zhu2017prune}, we use the weight magnitude (WM) to approximate the relative accuracy loss resulting from the pruning of a group of weights. The WM can be expressed in Equation~(\ref{eq:pruning-wm}).
\begin{align} \label{eq:pruning-wm}
\text{WM}_n = \sum_i\frac{\|\mathbf{w}_{n,i}\|_{1}}{N_{n,i}} p_{n,i} 
\end{align}
Here, ${{\|\mathbf{w}_{n,i}\|}_1}/{N_{n,i}}$ represent the average magnitude of weights in a filter. The operator ${\|\cdot\|}_1$ is the $l_1$-norm, and $N_{n,i}$ is the number of elements in the weight group $\mathbf{w}_{n,i}$. We assume that when the WM is increased, i.e., the pruned weight magnitude is greater, the accuracy loss due to pruning these weights would be larger.

To convert the formulation of WM into QUBO form, we square the WM to obtain the pruning loss component, i.e., $L_{p}(\mathcal{P})$, which is expressed in Equation (\ref{eq:pruning-loss}). The coefficients of two qubits $p_{n,i}$ and $p_{n,j}$ are represented by $A_{n, i, j}$ and can be pre-calculated before conducting quantum optimization. Accordingly, the coupling map of qubits is shown in Table~\ref{table:qubo1}, which facilitates the implementation of the QUBO formulation into annealing machines.
\begin{align} \label{eq:pruning-loss}
   L_{p} ( \mathcal{P} ) &= \sum_n \text{WM}_n^2 =\sum_{n} \sum_{i} \sum_{j} A_{n, i, j} \cdot \underline{p_{n, i}} \cdot \underline{p_{n, j}}  
\end{align}
\vspace{-15 px}
\begin{align} 
\text{where}\ A_{n, i, j} = \frac{\|\mathbf{w}_{n,i}\|_{1}  \|\mathbf{w}_{n,j}\|_{1} } {N_{n,i}  N_{n,j}} \nonumber
\end{align}


\subsection{Quantization Loss}

We use local quantization error as a proxy for relative accuracy loss due to quantization. We refer to the root mean square error (RMSE) of weights as the indicator of quantization error. The RMSE can be expressed in Equation~(\ref{eq:RMSE}).
\begin{align} \label{eq:RMSE}
\text{RMSE}_n \approx s_n/\sqrt{12}\approx c_n\cdot 2^{\sum_k 2^k q_{n,k}}
\end{align} 
Here, $s_n$ is the step size. It is approximately proportional to $2^{\sum_k 2^k q_{n,k}}$. We use the coefficient $c_n$, a constant for layer $n$, to denote the ratio.

To convert the formulation of RMSE into QUBO form, we take the logarithm of RMSE$/c_n$ and square the result to obtain the quantization loss component, i.e., $L_{q}(\mathcal{Q})$, which is expressed in Equation~(\ref{eq:quantization-loss}). The coefficients of two qubits, $q_{n,k}$ and $q_{n,l}$, are represented by $B_{n,k,l}$ and can be pre-calculated before decoding quantum optimization. Accordingly, the coupling map of qubits is shown in Table~\ref{table:qubo2}.
\begin{align} \label{eq:quantization-loss}
L_{q} ( \mathcal{Q} ) = &\sum_n \log_2^2 (\text{RMSE}_n/c_n) \nonumber \\
        \approx & \sum_{n} \sum_{k} \sum_{l} \underline{B_{n, k, l}} \cdot q_{n, k} \cdot q_{n, l}
\end{align}
\vspace{-15 px}
\begin{align}
\text{where}\ B_{n, k, l} = 2^{k+l}  \nonumber
\end{align}

\subsection{Compression Rate}

We use the compression rate (CR) to accurately reflect the amount of model size eliminated through pruning and quantization. The CR can be expressed in Equation~(\ref{eq:compression-rate}).
\begin{align}\label{eq:compression-rate}
\text{CR}_n = & \sum_i \bigl( N_{n,i}b_{max}-N_{n,i}b_n (1-p_{n,i})\bigr)/S
\end{align}
Here, $N_{n,i}$ is the number of weights in the $i$-th filter of the $n$-th layer of the model, and $S$ represents the total model size in terms of bits, which can be considered constant for a given target model.

\begin{figure}[t]
\centering
    \includegraphics[width=1\linewidth]{ob}
    \caption{Heat maps of accuracy (left) and model reduction ratio (right) of ResNet-9 as distributions of hyperparameters $\beta$ (x-axis) and $\gamma$ (y-axis). Dark areas represent regions where accuracy is completely lost.}    \label{fig:hyperparameter-space}
\end{figure}

The CR can already be expressed in QUBO form, so we can directly obtain the third component, $R(\mathcal{P},\mathcal{Q})$, which is expressed in Equation~(\ref{eq:compression-layer}). The self-effect coefficients of qubits $p_{n,i}$ and $q_{n,k}$ are represented by $D_{n,i}$ and $E_{n,k}$, respectively. Additionally, the coefficient of interaction between two qubits, $p_{n,i}$ and $q_{n,k}$, is represented by $F_{n,i,k}$. These parameters can all be pre-calculated before coding for quantum optimization. Accordingly, the coupling map of qubits is shown in Table~\ref{table:qubo3}.
\begin{align} \label{eq:compression-layer}
    R ( \mathcal{P} , \mathcal{Q}) = & \sum_n \text{CR}_n \nonumber \\
     = &\sum_{n}\sum_{i}{D}_{n,i} \cdot \underline{p_{n,i}} + \sum_{n}\sum_{k}   {E}_{n,k} \cdot \underline{q_{n,k}} \nonumber \\
    -&\sum_{n}\sum_{i} \sum_{k} {F}_{n,i,k} \cdot \underline{p_{n,i}} \cdot \underline{q_{n,k}}
\end{align}
\vspace{-25 px}
\begin{align}
&\text{where}\nonumber \\
&{D}_{n,i} = \frac{N_{n,i}  b_{max}}{S}  ,\     {E}_{n,k} = \frac{\sum_i2^kN_{n,i}}{S} ,\  {F}_{n,i,k} = \frac{2^kN_{n,i}}{S}\nonumber  
\end{align}
The denominator $S$ in Equation (\ref{eq:compression-rate}) ensures that the model reduction ratio $R(\mathcal{P}, \mathcal{Q})$ is confined to the range $[0,1]$. Consequently, $R$ exhibits a consistent value range across different models, irrespective of their initial sizes.

\begin{algorithm}[t]
\caption{Hyperparameter Search Algorithm} \label{algo:hyperparameter}
\textbf{Input}:  \\
\hspace*{\algorithmicindent} $\mathbf{A}$, $\mathbf{B}$, $\mathbf{E}$, $\mathbf{F}$, $\mathbf{G}$: Hamiltonian coefficients. \\
\hspace*{\algorithmicindent} $a_{th}$: Accuracy threshold. \\
\textbf{Output}: \\
\hspace*{\algorithmicindent} $\gamma_{f},\: \beta_{f}$: Selected $\gamma$, $\beta$ values. \vspace{0.3em} \\
$\mathbf{procedure}$:\:\textsc{HyperparameterSearch}
\vspace{-1.2em}
\begin{algorithmic}[1] 
\STATE{Initialize $\beta \gets {\|\mathbf{A}\|_{1}}/{\|\mathbf{B}\|_{1}} $, $\gamma \gets random()$}.
\STATE{Get initial reduction rate: $\mathcal{P}, \mathcal{Q}, R \gets \mathbf{aqc}(\beta, \gamma)$}
\STATE{Get initial accuracy: $a \gets \mathbf{acc}(\mathcal{P}, \mathcal{Q})$}
\STATE{Initial checkpoint: $R_{f} \gets R$, \, $\beta_{f} \gets \beta$, \, $\gamma_{f} \gets \gamma$}
\FOR{$i = 1$ \TO $N_{iter}$} 
        \IF{$a \ge a_{th}$}
        \STATE{$\gamma_{l} \gets \gamma$}
        \STATE{$\gamma_{u} \gets \textsc{FindUpperGamma}(\gamma, \beta)$}
        \ELSE 
        \STATE{$\gamma_{l} \gets \textsc{FindLowerGamma}(\gamma, \beta)$}
        \STATE{$\gamma_{u} \gets \gamma$}
        \ENDIF
        \STATE{$\gamma \gets \textsc{BinSearchMax}(\gamma_{l}, \,\gamma_{u},\, a_{th})$}
        \STATE{$\beta \gets \textsc{BinSearchMin}(0,\, 2\beta, \,a_{th})$}
        \STATE{\textrm{\\}}
        \STATE{(Checkpoint solution if best compression)}
        \STATE{$\mathcal{P}, \mathcal{Q}, R \gets \mathbf{aqc}(\beta, \gamma)$}
        \STATE{$a \gets \mathbf{acc}(\mathcal{P}, \mathcal{Q})$}
        \STATE{$\textbf{if } R > R_{f} \textbf{ then } R_{f} \gets R, \, \beta_{f} \gets \beta, \, \gamma_{f} \gets \gamma$}
\ENDFOR
\end{algorithmic}
\end{algorithm}


\subsection{Combined QUBO Model} 

We combine the three energy components to yield the system Hamiltonian in QUBO form, shown in Equation~(\ref{eq:final-hamiltonian}):
\begin{align} \label{eq:final-hamiltonian}
    H = \mathbf{x}^T \mathbf{U}\mathbf{x},\ \ \ \textrm{where}\ \ \mathbf{x} = \text{vect}(\mathcal{P}, \mathcal{Q})
\end{align}
The operation $\text{vect}(\mathcal{P}, \mathcal{Q})$ strings together elements $p_{n,i} \in \mathcal{P}$ and $q_{n,k} \in \mathcal{Q}$ into a one-dimensional vector, such that each variable $p_{n,i}$ and $q_{n,k}$ is a unique qubit $x_{i}$. Accordingly, $\mathbf{U}$ is an upper-triangular matrix, in which each element is a linear combination of the three energy components. The coupling map of qubits for the formulation of $H$, and the details of each element in matrix $\mathbf{U}$ are provided in Table~\ref{table:qubo}. Given this coupling map, we can implement the QUBO function onto the quantum annealing machine, perform optimization and obtain the selected parameters for pruning and quantization on the model.

Implicitly, the hyperparameters $\beta$ and $\gamma$ are used to balance among the energy components in $H$. Hyper-parameter $\beta$ balances the weight of pruning loss and quantization loss. If $\beta$ is too large, we find that the system is averse to quantization and may over-prune the network without any quantization in the solution. Similarly, too small values of $\beta$ result in excessive quantization with minimal pruning. Instead, $\gamma$ functions largely as a design knob for us to trade off accuracy and model reduction ratio, as well as prevent over-compression phenomenon (complete loss of predictive power and can not be recovered).


\begin{algorithm} [t]
\caption{Upper/Lower Gamma Search Procedures} \label{algo:gamma}
\textbf{Input}: \\
\hspace*{\algorithmicindent} Current hyperparameter values $\gamma$, $\beta$. \\
\textbf{Output}: \\
\hspace*{\algorithmicindent} \textsc{FindUpperGamma}: $\gamma_{f}$ with invalid solution, $\gamma_{f} > \gamma$. \\ 
\hspace*{\algorithmicindent} \textsc{FindLowerGamma}: $\gamma_{f}$ with valid solution, $\gamma_{f} < \gamma$.  \vspace{0.3em} \\
$\mathbf{procedure}$:\:\textsc{FindUpperGamma} 
\begin{algorithmic}[1]
\STATE{Initialize $a \gets a_{th}$.}
\WHILE{$a \ge a_{th}$}
\STATE{$\gamma_{f} \gets 2 \gamma$}
\STATE{$\mathcal{P}, \mathcal{Q}, R \gets \mathbf{aqc}(\beta, \gamma)$}
\STATE{$a \gets \mathbf{acc}(\mathcal{P}, \mathcal{Q})$}
\ENDWHILE
\RETURN $\gamma_{f}$
\end{algorithmic}  \vspace{0.3em}
$\mathbf{procedure}$:\:\textsc{FindLowerGamma}
\begin{algorithmic}[1]
\STATE{Initialize $a \gets 0$.}
\WHILE{$a < a_{th}$}
\STATE{$\gamma_{f} \gets (\gamma / 2)$}
\STATE{$\mathcal{P}, \mathcal{Q}, R \gets \mathbf{aqc}(\beta, \gamma)$}
\STATE{$a \gets \mathbf{acc}(\mathcal{P}, \mathcal{Q})$}
\ENDWHILE
\RETURN $\gamma_{f}$
\end{algorithmic}
\end{algorithm}


\section{Hyper-Parameter Search} 
\label{section:hyperparameter-search}

From the QUBO Equation~(\ref{eq:hamiltonian-abstracted}), we note that the selection of appropriate hyperparameters is essential for AQC to yield a desirable compression solution. This fact is also observed in Figure~\ref{fig:hyperparameter-space} which shows a representative solution space (grid search on ResNet-9 at CIFAR-10 dataset) as hyperparameters $\gamma$ and $\beta$ are varied. These heat maps of accuracy and model reduction ratio are masked by an accuracy threshold, such that solutions with accuracy below the threshold are considered invalid and hidden. From the figure we observe that the process of determining suitable hyperparameters is itself a search problem and must be navigated efficiently by algorithms. Hence, we propose a simple but effective heuristic to quickly navigate the hyper-parameter space. Our observations on Figure~\ref{fig:hyperparameter-space} can be summarized as follows:
\vspace{-0.5em}
\begin{itemize}
    \setlength\itemsep{-0.2em}
    \item For each $\beta$ value (vertical column), there is a general increase in accuracy as $\gamma$ is reduced. This observation is intuitive as minimizing $\gamma$ reduces the impact of model reduction ratio on energy reduction during AQC.
    \item For each $\gamma$ value (horizontal row), there is an increase in model reduction ratio as $\beta$ is reduced, as the system becomes less averse to quantization.
    \item For each $\gamma$ value, there exists a minimum $\beta$ value above which the solution is valid. Below this $\beta$ value, the solution becomes over-compressed and loses inference ability completely. This region corresponds to the masked out (black/dark blue) region in Figure~\ref{fig:hyperparameter-space}.
\end{itemize}\vspace{-0.5em}


\begin{algorithm}[t]
\caption{Binary Search Procedure for Max/Min Value}  \label{algo:bin-search}
\textbf{Input}:  \\
\hspace*{\algorithmicindent} $x_{l},\: x_{u}$: Variable lower, upper bound. \\
\hspace*{\algorithmicindent} $a_{th}$: Accuracy threshold. \\
\textbf{Output}: \\
\hspace*{\algorithmicindent} $x_{f}$: Variable value after $N_{bin}$ iterations. \vspace{0.45em} \\ 
$\mathbf{procedure}$: \textsc{BinSearchMax}
\begin{algorithmic}[1]
\FOR{$i = 1$ \TO $N_{bin}$}
\STATE{$x_{t} \gets x_{l} + ({x_{u} - x_{l}})/{2}$}
\STATE{Evaluate accuracy $a$ using $\mathbf{aqc}(\cdot)$ and $\mathbf{acc}(\cdot)$. }
\STATE{$\textbf{if} \; a > a_{th} \;\textbf{then} \; x_{l} \gets x_{t}$}
\STATE{$\textbf{else} \; x_{u} \gets x_{t}$}
\ENDFOR
\RETURN $x_{l}$
\end{algorithmic} \vspace{0.3em}
$\mathbf{procedure}$: \textsc{BinSearchMin}
\begin{algorithmic}[1]
\FOR{$i = 1$ \TO $N_{bin}$}
\STATE{$x_{t} \gets x_{l} + ({x_{u} - x_{l}})/{2}$}
\STATE{Evaluate accuracy $a$ using $\mathbf{aqc}(\cdot)$ and $\mathbf{acc}(\cdot)$. }
\STATE{$\textbf{if} \; a > a_{th} \;\textbf{then} \; x_{u} \gets x_{t}$}
\STATE{$\textbf{else} \; x_{l} \gets x_{t}$}
\ENDFOR
\RETURN $x_{u}$
\end{algorithmic}
\end{algorithm} 

On the basis of these observations, we employ an iterative search to find suitable values of $\beta$ and $\gamma$. This iterative search is shown in Algorithm \ref{algo:hyperparameter}. The function call $\mathbf{aqc}(\cdot)$ performs AQC on the Hamiltonian generated using $\beta$ and $\gamma$, returning solution variables $\mathcal{P}$, $\mathcal{Q}$, and model reduction ratio of the solution $R$. Meanwhile, function call $\mathbf{acc}(\cdot)$ generates the compressed model using $\mathcal{P, Q}$, fine-tunes the model for one epoch, and then evaluates the compressed model on the test dataset to yield the resulting accuracy $a$.

Algorithms \ref{algo:gamma} and \ref{algo:bin-search} further detail procedures used in the main algorithm. The procedures $\textsc{FindUpperGamma}$ and $\textsc{FindLowerGamma}$ in Algorithm \ref{algo:gamma} yield appropriate search bounds of hyperparameter $\gamma$. The procudures  $\textsc{BinSearchMax}$ and $\textsc{BinSearchMin}$ in Algorithm \ref{algo:bin-search} presents the binary search processes to maximize or minimize the solution variable respectively.

Refer to Algorithm~\ref{algo:hyperparameter}, we begin with an initial $\beta$ value of ${\|{\mathbf{A}}\|_{1}}/{\|\mathbf{B}\|_{1}}$ and an arbitrary $\gamma$ value (line 1). As coefficients ${A}$ and ${B}$ approximate the severity of pruning loss and quantization error respectively, we hypothesize that the $l1$-norm of these coefficients across the model should be similar in magnitude to balance between pruning and quantization. From our experiments, we find that this initial $\beta$ hypothesis is generally near-optimal, providing a useful starting point for the search.

\begin{figure*}[t]
\centering
    \includegraphics[width=1\linewidth]{combination}
    \caption{Heat maps of accuracy (red, top row) and model reduction ratio (blue, bottom row) of (a) LeNet-5 for MNIST, (b) ResNet-9 for CIFAR-10, and (c) VGG-16 for CIFAR-100. The objective is to select a point that is brightly-colored in both accuracy (top) and model reduction ratio (bottom) heat maps. The red vertical line on each plot indicates the proposed $\beta$ initialization as the starting point for our proposed hyper-parameter search algorithm. The green dot marks the final solution found.}
    \label{fig:plots}
\end{figure*}

Using these initial values as starting hyperparameters, we iteratively perform the following:
\vspace{-0.5em}
\begin{enumerate}

\item Fixing $\beta$, determine an appropriate range of $\gamma$ values in which to search (lines 6-12). Specifically, we aim to search in the range of $[\gamma_{l}, \, \gamma_{u}]$, for which $\gamma_{l}$ has high accuracy above threshold $a_{th}$ while $\gamma_{u}$ has accuracy below threshold $a_{th}$
.
\item Perform binary search for the maximum $\gamma$ in the range $[\gamma_{l}, \, \gamma_{u}]$ that fulfills the accuracy threshold (line 13). Let this value be $\gamma_{n}$

\item Fixing $\gamma$, perform binary search for minimum $\beta$ in the range $(0, 2\beta]$ that fulfills the accuracy threshold (line 14). We increase the upper bound to $2\beta$ in order to explore solutions with less quantization than the current $\beta$ value. Let the $\beta$ found through binary search be $\beta_{n}$.

\item (If necessary) Repeat steps 1 to 3 for $N_{iter}$ times, fixing $\beta = \beta_{n}$.
\end{enumerate}

In each step, we perform quantum optimization using $\mathbf{aqc(\cdot)}$ to yield a pruning-quantization solution (line 17), and then fine-tune the model for one epoch and assess solution accuracy (line 18). Three user-defined search configurations include the accuracy threshold $a_{th}$ for valid solutions, the number of binary search iterations $N_{bin}$, and the number of overall exploration iterations $N_{iter}$ for repeat steps $1$ and $2$. While the proposed procedure is iterative, we find that our initialization of $\beta = {\|\mathbf{A}\|_{1}}/{\|\mathbf{B}\|_{1}}$ provides a good starting point and often yields the near-optimal solution within the first search iteration.

