\subsection{Rod element used for truss modeling}
 \label{sApp:rodElement&discretization}

Adopting the Green-Lagrange strain measure $\epsilon = \epsilon_{0} + u_{x} + \frac{1}{2}(u^{2}_{x} + v^{2}_{x})$, where $\epsilon_{0}$ is a given pre-strain, the strain energy of the rod reads ($d = (u,v)$)
%
\begin{equation}
 \label{eq:APPstrainEnergyRod}
 \begin{aligned}
  \Phi(d) & = \frac{1}{2} \int^{L_{0}}_{0} EA
  \left[\epsilon_{0}+u_{x}+\frac{1}{2}(u^{2}_{x} + v^{2}_{x})\right]^{2}
  {\rm d}x \\ & =
  \frac{1}{2} \int^{L_{0}}_{0}EA\left[
  \epsilon^{2}_{0}+
  2\epsilon_{0}u_{x}+
  u^{2}_{x}+\epsilon_{0}(u^{2}_{x}+v^{2}_{x})+
  u_{x}v^{2}_{x}+u^{3}_{x}+
  \frac{1}{2}u^{2}_{x}v^{2}_{x}+\frac{1}{4}(u^{4}_{x}+v^{4}_{x})
  \right] {\rm d}x
  \end{aligned}
\end{equation}

Introducing the test fields $\delta d$, $\tilde{d}$, $\hat{d}$ and $\bar{d}$, the first four variations of \eqref{eq:APPstrainEnergyRod} read
%
\begin{equation}
 \label{eq:APPstrainEnergyRod_variations}
 \begin{aligned}
  \Phi^{(1)}_{0}[\delta d]
  & = \int^{L_{0}}_{0} \delta u_{x} EA \epsilon_{0} \: {\rm d}x \\
  \Phi^{(2)}_{0}[\tilde{d}, \delta d]
  & = \int^{L_{0}}_{0}\delta u_{x}
  EA (1 + \epsilon_{0})\tilde{u}_{x} +
 \delta v_{x} EA\epsilon_{0}\tilde{v}_{x} \: {\rm d}x \\
 \Phi^{(3)}_{0}[\hat{d}, \tilde{d}, \delta d]
 & = \int^{L_{0}}_{0} EA\left[
 \delta u_{x}
 (3\tilde{u}_{x}\hat{u}_{x} + \tilde{v}_{x} \hat{v}_{x}) + \delta v_{x} (\tilde{u}_{x} \hat{v}_{x} + 
 \tilde{v}_{x} \hat{u}_{x})
 \right] {\rm d}x \\
 \Phi^{(4)}_{0}[\bar{d}, \hat{d}, \tilde{d}, \delta d]
 & = \int^{L_{0}}_{0}
 EA [\delta u_{x}(3\bar{u}_{x}\hat{u}_{x}\tilde{u}_{x} + \bar{v}_{x}\hat{v}_{x}\tilde{v}_{x} + \bar{u}_{x}\hat{v}_{x}\tilde{v}_{x} + \bar{v}_{x}\hat{u}_{x}\tilde{v}_{x}) + \\
 & \qquad\qquad\quad\:
 \delta v_{x} (3\bar{v}_{x}\hat{v}_{x}\tilde{v}_{x} + \bar{v}_{x}\hat{u}_{x}\tilde{u}_{x} + \bar{u}_{x}\hat{u}_{x}\tilde{v}_{x}+\bar{u}_{x}\hat{v}_{x}\tilde{u}_{x})] {\rm d}x
 \end{aligned}
\end{equation}
where we have set $\Phi^{(n)}_{0} := \left. \Phi^{(n)}(d)\right|_{|d|\rightarrow 0}$, as we refer to the current configuration.

In the rods' \emph{local} frame, the DOFs are collected as $\mathbf{d}_{(l)} = \{u_{a(l)}, v_{a(l)}, u_{b(l)}, v_{b(l)}\}$ (see \autoref{fig:APProdandbeamsketch}(a)), and are transformed to the \emph{global} frame by $\mathbf{d} = (I_{2}\otimes R^{T})\mathbf{d}_{(l)}$, where $R = \left[i_{x}, i_{y}\right]$ is the rotation matrix ($i_{x} = \left\{\cos\theta, \sin\theta\right\}^{T}$, $i_{y} = \left\{-\sin\theta, \cos\theta\right\}^{T}$), and $I_{2}$ is the $2\times 2$ identity matrix.

The rods' natural modes are defined as \cite{argyris-etal_79a_naturalModesFEM}
%
\begin{equation}
 \label{eq:APProdNaturalModes}
 \mathbf{d}_{\epsilon} = \left\{
 \begin{array}{c} \varepsilon \\ \phi_{r}
 \end{array} \right\} = \left\{
 \begin{array}{c} u_{x} \\ v_{x}
 \end{array} \right\} =
 L^{-1}_{0}\left[
 \begin{array}{cccc}
 -1 &  0 & 1 & 0 \\
  0 & -1 & 0 & 1
 \end{array}
 \right]
 \mathbf{d}_{(l)}
 = N_{0} (I_{2}\otimes R^{T})\mathbf{d}
 = N_{\theta}\mathbf{d}
\end{equation}
and, introducing $\boldsymbol{\chi}^{T}_{1} = \left\{1, 0\right\}$ and $\boldsymbol{\chi}^{T}_{2} = \left\{0, 1\right\}$, such that $u_{x} = \boldsymbol{\chi}^{T}_{1}\mathbf{d}_{\epsilon}$ and $v_{x} = \boldsymbol{\chi}^{T}_{2}\mathbf{d}_{\epsilon}$, the discretization of the first two expressions in \eqref{eq:APPstrainEnergyRod_variations} gives
%
\begin{equation}
 \label{eq:APPstrainEnergyRod_1&2variations_discretized}
 \begin{aligned}
 \Phi^{(1)}_{0}[\delta\mathbf{d}]
  & = \int^{L_{0}}_{0} (\boldsymbol{\chi}^{T}_{1}N_{\theta}\delta\mathbf{d})^{T}
  EA\epsilon_{0} \: {\rm d}x = \delta\mathbf{d}^{T}N^{T}_{\theta} \boldsymbol{\chi}_{1}\sigma_{0} L_{0} \\
  \Phi^{(2)}_{0}[\tilde{\mathbf{d}}, \delta\mathbf{d}]
  & = \int^{L_{0}}_{0} (\boldsymbol{\chi}^{T}_{1}N_{\theta}\delta\mathbf{d})^{T}EA(1+\epsilon_{0})
  (\boldsymbol{\chi}^{T}_{2}N_{\theta}\tilde{\mathbf{d}}) +
  (\boldsymbol{\chi}^{T}_{2}N_{\theta}\delta\mathbf{d})^{T}EA\epsilon_{0}
  (\boldsymbol{\chi}^{T}_{2}N_{\theta}\tilde{\mathbf{d}}) {\rm d}x \\
  & = \delta\mathbf{d}^{T}N^{T}_{\theta}\left[
  EAL_{0}\boldsymbol{\chi}_{1}\boldsymbol{\chi}^{T}_{1} + 
  \sigma_{0}L_{0}(\boldsymbol{\chi}_{1}\boldsymbol{\chi}^{T}_{1} + \boldsymbol{\chi}_{2}\boldsymbol{\chi}^{T}_{2})
  \right] N_{\theta}\tilde{\mathbf{d}} \\ & = 
  \delta\mathbf{d}^{T} \left[
  N^{T}_{\theta}\mathsf{K_{D}}N_{\theta} + \sigma_{0}
  N^{T}_{\theta}\mathsf{G_{D}}N_{\theta}
 \right]
 \tilde{\mathbf{d}}
 \end{aligned}
\end{equation}
where $\mathsf{K_{D}} := EAL_{0}\boldsymbol{\chi}_{1}\boldsymbol{\chi}^{T}_{1}$, $\mathsf{G_{D}} := L_{0}(\boldsymbol{\chi}_{1}\boldsymbol{\chi}^{T}_{1} + \boldsymbol{\chi}_{2}\boldsymbol{\chi}^{T}_{2})$ are the diagonal stiffness and geometric matrices, referred to the natural coordinates \cite{argyris-etal_79a_naturalModesFEM}. Furthermore, $K := N^{T}_{\theta}\mathsf{K_{D}}N_{\theta}$ and $G := N^{T}_{\theta}\mathsf{G_{D}}N_{\theta}$ give the stiffness and geometric matrices referred to the global coordinates \cite{book:crisfield91}, and we recall that the latter is here independent of the axial stress $\sigma_{0} = EA\epsilon_{0}$, for clarity of the further developments.

With the same formalism, the discretization of the trilinear form in \eqref{eq:APPstrainEnergyRod_variations} reads
%
\begin{equation}
 \label{eq:APPstrainEnergyRod_3variation_discretized}
 \begin{aligned}
  \Phi^{(3)}_{0}[\hat{\mathbf{d}},\tilde{\mathbf{d}},\delta\mathbf{d}]
  & = \delta\mathbf{d}^{T}N^{T}_{\theta}\left[
  \boldsymbol{\chi}_{1}\left(\tilde{\mathbf{d}}^{T}G\hat{\mathbf{d}} + 
  2\tilde{\mathbf{d}}^{T}N^{T}_{\theta}
  \boldsymbol{\chi}_{1}\boldsymbol{\chi}^{T}_{1}
  N_{\theta}\hat{\mathbf{d}}\right) + 
  \boldsymbol{\chi}_{2}\tilde{\mathbf{d}}^{T}G\hat{\mathbf{d}}\right]EA \\
  \Phi^{(3)}_{0}[\hat{\mathbf{d}},\tilde{\mathbf{d}},\dot{\mathbf{d}}]
  & = \hat{\sigma} \tilde{\mathbf{d}}^{T} G\dot{\mathbf{d}} + 
  \tilde{\sigma} \dot{\mathbf{d}}^{T}G\hat{\mathbf{d}} + 
  \dot{\sigma} \hat{\mathbf{d}}^{T}G\tilde{\mathbf{d}} 
 \end{aligned}
\end{equation}
where the top row, containing the virtual field $\delta\mathbf{d}$ can be used to express the right hand side in \eqref{eq:secondOrderDisplacementCorrection}, whereas the bottom row is used to compute the third order contributions in \eqref{eq:asymptoticCoefficients}.

The quadrilinear form in \eqref{eq:APPstrainEnergyRod_variations} gives a lengthy expression, when keeping all the independent fields. However, we see from \autoref{eq:asymptoticCoefficients} that we only need to compute terms of the form $\Phi^{(4)}_{0}\hat{\mathbf{d}}\tilde{\mathbf{d}}^{3}$, $\Phi^{(4)}_{0}\hat{\mathbf{d}}^{2}\tilde{\mathbf{d}}^{2}$ or $\Phi^{(4)}_{0}\hat{\mathbf{v}}^{4}$, the most general of which can be given the following expression
%
\begin{equation}
\label{eq:APPstrainEnergyRod_4variation_discretized}
 \begin{aligned}
  \Phi^{(4)}_{0}[\hat{\mathbf{d}}^{2},\tilde{\mathbf{d}}^{2}] = 
  \hat{\sigma}^{2} \tilde{\mathbf{d}}^{T} G\tilde{\mathbf{d}} + 
  4\hat{\sigma}\tilde{\sigma} \tilde{\mathbf{d}}^{T} G\hat{\mathbf{d}} + 
  \tilde{\sigma}^{2} \hat{\mathbf{d}}^{T} G\hat{\mathbf{d}}
 \end{aligned}
\end{equation}



\subsection{Beam element used for frame modeling}
 \label{sApp:beamElement&discretization}

Truss assemblies are modeled according to the above expression, and the strain energy variations \eqref{eq:APPstrainEnergyRod_variations} are accurate at all orders, as the GL strain measure is geometrically exact for a rod \cite{book:antman}.

This is not the case for beams, for which the so-called technical theories, either based on the Green-Lagrange strain, or on the weakly nonlinear approximation (i.e., $\epsilon = \epsilon_{0} + u_{x} + \frac{1}{2}v^{2}_{x}$) introduce spurious strains (see \autoref{sSec:AsymptoticPBanalysisSimpleCases}). Therefore, the approach outlined above, now including the bending modes $\phi_{s}$ and $\phi_{a}$ (see \autoref{fig:APProdandbeamsketch}(b)), associated with the curvature deformation $\chi = v_{xx}$, would lead to an incorrect evaluation of the II order displacement correction and related quantities \cite{byskov_89a_smoothPostbucklingStresses, silvestre-camotim_05a_asymptoticNumericalPostbuckling, NOTE_garcea-etal_13a_postBucklingAsymptotic}.

Then, we need to restore to more advanced beam models, as those outlined, for example, in \cite{garcea-etal_12a_implicitCoRotationalModel, salerno-lanzo_97a_nonlinearFElockingFree, salerno-23a_koitersWorstImperfection, silvestre-camotim_05a_asymptoticNumericalPostbuckling}, to which we refer for further details.
