        \draw[full] (5*\sz,2*\sz) rectangle ++(\sz,\sz);
        \draw[full] (5*\sz,3*\sz) rectangle ++(\sz,\sz);
        \draw[empty] (5*\sz,4*\sz) rectangle ++(\sz,\sz);
        \draw[empty] (5*\sz,5*\sz) rectangle ++(\sz,\sz);

