        \node at (-1.25*\sz,1.5*\sz) () {$E(Y',W)$};
        \node at (-1.25*\sz,2.5*\sz) () {$E(Y',A)$};
        \node at (-1.25*\sz,3.5*\sz) () {$E(X',W)$};
        \node at (-1.25*\sz,4.5*\sz) () {$E(X',A)$};
        \node at (-1.25*\sz,5.5*\sz) () {$E(X',Y')$};
        \node[rotate=90] at (.5*\sz,7.25*\sz) () {$E(X',Y')$};
        \node[rotate=90] at (1.5*\sz,7.25*\sz) () {$E(X',A)$};
        \node[rotate=90] at (2.5*\sz,7.25*\sz) () {$E(X',W)$};
        \node[rotate=90] at (3.5*\sz,7.25*\sz) () {$E(Y',A)$};
