    \end{tikzpicture}
    \caption{Illustration of the subblocks of $M_E$ participating in the correction term.}
    \label{F:blocks}
\end{figure}

For the second term, we apply \Cref{L:trace} to each term individually and have the bound 
\[ \frac{4\rho_E}{1-\rho_E^2}\paren{\sum_{f \in E(W,\overline{W})} w_f + \sum_{f \in E(\overline{W})} w_f + 2\sum_{f \in E(A)} w_f}.\]
As $2\rho_E(1+\rho_E)^2 \leq 12\rho_E$, the combined error terms can be bounded above by $\frac{12\rho_E}{1-\rho_E^2}\trace(M_E),$ as desired.
\end{proof}


