\section{Proof of Theorem~\ref{thm:ELBO}}\label{app:ELBO_proof}
\begin{proof}
Given the log-likelihood of the global state transition, we have the following:
\begin{align}
    \log P(s_{t+1} | s_t, a_{t}^{1:N}) &= \log \int p(s_{t+1}, s_{t+1}^{(1):(n)} | s_t, a_{t}^{1:n})\,ds_{t+1}^{(1):(n)} \nonumber \\
    &= \log \int \frac{p(s_{t+1}, s_{t+1}^{(1):(n)} | s_t, a_{t}^{(1):(n)}) \hat{q}(s_{t+1}^{(1):(n)} | s_t, a_{t}^{1:n}, s_{t+1})}{\hat{q}(s_{t+1}^{(1):(n)} | s_t, a_{t}^{1:n}, s_{t+1})}\,ds_{t+1}^{(1):(n)} \nonumber \\
    &= \log \mathbb{E}_{\hat{q}(s_{t+1}^{(1):(n)} | s_t, a_{t}^{1:n}, s_{t+1})}\left[  \frac{p(s_{t+1}, s_{t+1}^{(1):(n)} | s_t, a_{t}^{1:n})}{\hat{q}(s_{t+1}^{(1):(n)} | s_t, a_{t}^{1:n}, s_{t+1} )}\right] \nonumber   \\
    &\geq \mathbb{E}_{\hat{q}(s_{t+1}^{(1):(n)} | s_t, a_{t}^{1:n}, s_{t+1})}\left[ \log \frac{p(s_{t+1}, s_{t+1}^{(1):(n)} | s_t, a_{t}^{1:n})}{\hat{q}(s_{t+1}^{(1):(n)} | s_t, a_{t}^{1:n}, s_{t+1} )}\right] \label{equ:app_log_likelihood},
\end{align}
where the last inequality results from Jensen's inequality. Under the definition and property of the conditional Markovian forward diffusion process $\hat{q}$ in Eqs.~\eqref{equ:conditional_diffusion_process}--\eqref{equ:conditional_diffusion_process_1} and Assumption~\ref{assume:diffusion_inspired}, we can rewrite Eq.~\eqref{equ:app_log_likelihood} as follows,
\begin{align}
    \log P(s_{t+1} | s_t, a_{t}^{1:N}) \geq \mathbb{E}_{\hat{q}(s_{t+1}^{(1):(n)} | s_{t+1})}\left[ \log \frac{p(s_{t+1}^{(n)}) \prod_{k=1}^n p( s_{t+1}^{(k-1)} | s_{t+1}^{(k)}, s_t, a_t^k ) )}{ \prod_{k=1}^n \hat{q}( s_{t+1}^{(k)} | s_{t+1}^{(k-1)} ) }\right], \label{equ:app_1}
\end{align}
where we denote $s_{t+1} := s_{t+1}^{(0)}$. Then, RHS of Eq.~\eqref{equ:app_1} can be further simplified,
\begin{align*}
&\mathbb{E}_{\hat{q}(s_{t+1}^{(1):(n)} | s_{t+1})}\left[ \log \frac{p(s_{t+1}^{(n)}) \prod_{k=1}^n p( s_{t+1}^{(k-1)} | s_{t+1}^{(k)}, s_t, a_t^k ) )}{ \prod_{k=1}^n \hat{q}( s_{t+1}^{(k)} | s_{t+1}^{(k-1)} ) }\right] \nonumber \\
=\: & \mathbb{E}_{\hat{q}(s_{t+1}^{(1):(n)} | s_{t+1})} \left[ \log \frac{ p(s_{t+1}^{(n)}) p(s_{t+1}^{(0)} | s_{t+1}^{(1)}, s_t, a_t^1) }{\hat{q}( s_{t+1}^{(1)} | s_{t+1}^{(0)} )} + \log \prod_{k=2}^n \frac{ p(s_{t+1}^{(k-1)} | s_{t+1}^{(k)}, s_t, a_t^k) }{ \hat{q}( s_{t+1}^{(k)} | s_{t+1}^{(k-1)} ) } \right] \nonumber \\
=\: & \mathbb{E}_{\hat{q}(s_{t+1}^{(1):(n)} | s_{t+1})} \left[ \log \frac{ p(s_{t+1}^{(n)}) p(s_{t+1}^{(0)} | s_{t+1}^{(1)}, s_t, a_t^1) }{\hat{q}( s_{t+1}^{(1)} | s_{t+1}^{(0)} )} + \log \prod_{k=2}^n \frac{ p(s_{t+1}^{(k-1)} | s_{t+1}^{(k)}, s_t, a_t^k) }{ \frac{ \hat{q}(s_{t+1}^{(k-1)} | s_{t+1}^{(k)},s_{t+1}^{(0)}) \hat{q}(s_{t+1}^{(k)} | s_{t+1}^{(0)}) }{ q(s_{t+1}^{(k-1)} | s_{t+1}^{(0)})} } \right] \nonumber \\
=\: & \mathbb{E}_{\hat{q}(s_{t+1}^{(1):(n)} | s_{t+1})} \left[ \log \frac{ p(s_{t+1}^{(n)}) p(s_{t+1}^{(0)} | s_{t+1}^{(1)}, s_t, a_t^1) }{\hat{q}( s_{t+1}^{(1)} | s_{t+1}^{(0)} )} + \log \frac{ \hat{q}( s_{t+1}^{(1)} | s_{t+1}^{(0)} ) }{ \hat{q}( s_{t+1}^{(n)} | s_{t+1}^{(0)} ) } + \log \prod_{k=2}^n \frac{ p(s_{t+1}^{(k-1)} | s_{t+1}^{(k)}, s_t, a_t^k) }{ \hat{q}(s_{t+1}^{(k-1)} | s_{t+1}^{(k)},s_{t+1}^{(0)}) } \right] \nonumber \\
=\: & \mathbb{E}_{\hat{q}(s_{t+1}^{(1):(n)} | s_{t+1})} \left[ \log \frac{ p(s_{t+1}^{(n)}) p(s_{t+1}^{(0)} | s_{t+1}^{(1)}, s_t, a_t^1) }{\hat{q}( s_{t+1}^{(n)} | s_{t+1}^{(0)} )} + \sum_{k=2}^n \log \frac{ p(s_{t+1}^{(k-1)} | s_{t+1}^{(k)}, s_t, a_t^k) }{ \hat{q}(s_{t+1}^{(k-1)} | s_{t+1}^{(k)},s_{t+1}^{(0)}) } \right]
\end{align*}
Therefore, the evidence of dynamics transition can be bounded as follows:
\begin{align}
    \log P(s_{t+1} | s_t, a_{t}^{1:N}) &\geq \mathbb{E}_{\hat{q}(s_{t+1}^{(1)} | s_{t+1}^{(0)})} [ \log p(s_{t+1}^{(0)} | s_{t+1}^{(1)}, s_t, a_t^1) ] - {\rm D}_{\rm KL} [\hat{q}(s_{t+1}^{(n)} | s_{t+1}^{(0)}) \| p(s_{t+1}^{n}) ] \nonumber\\
    &- \sum_{k=2}^n \mathbb{E}_{\hat{q}(s_{t+1}^{(k)} | s_{t+1}^{(0)} )} \left[ {\rm D}_{\rm KL}(\hat{q}(s_{t+1}^{(k - 1)} | s_{t+1}^{(k)}, s_{t+1}^{(0)} ) \| p ( s_{t+1}^{(k-1)} | s_{t+1}^{(k)}, a_t^{k}, s_t) ) \right]. \label{equ:app_2}
\end{align}
As shown by \citep{dhariwal2021diffusion}, the conditional forward diffusion process $\hat{q}$ behaves identically to the unconditional one $q$. Therefore, we can substitute the $\hat{q}$ with the $q$ in Eq.~\eqref{equ:app_2}, concluding our proof.
\end{proof}

\section{EDM Preconditioners and Noise Scheduler}\label{app:preconditioners}
To keep input and output signal magnitudes fixed to the same scale and avoid large variance in gradient magnitudes on a per-sample basis, \citet{karras2022edm} introduced the following preconditioners for normalization and re-scaling output to stabilize and improve the training dynamics of the network:
\begin{align}
&c_\text{in}^\tau     = \frac{1}{\sqrt{\sigma(\tau)^2 + \sigma_\text{data}^2}} \\
&c_\text{out}^\tau    = \frac{\sigma(\tau)\sigma_\text{data}}{\sqrt{\sigma(\tau)^2 + \sigma_\text{data}^2}} \\
&c_\text{noise}^\tau  = \frac{1}{4} \log(\sigma(\tau)) \\
&c_\text{skip}^\tau   = \frac{\sigma_\text{data}^2}{\sigma_\text{data}^2 + \sigma(\tau)^2},
\end{align}
where $\sigma_\text{data} = 0.5$ in our experiment hyperparameter setup. The noise scheduler for training the diffusion model follows the same design in \citep{karras2022edm}, described as follows:
\begin{align}
    \sigma(\tau) = \tau,\, \log (\sigma) \sim \mathcal{N}(P_\text{mean}, P_\text{std}^2),
\end{align}
where $P_\text{mean} = -0.4$ and $P_\text{std} = 1.2$.

\section{Behavior Learning Details}\label{app:behaviour_learning}
Inspired by the success of MARIE \citep{zhang2024marie}, we adopt MAPPO \citep{yu2022surprisingeffectivenessppocooperative} to train both the actor and critic inside the imaginations of DIMA.
A key distinction from MARIE is that our model explicitly predicts the global state, enabling seamless integration with CTDE techniques as well as actor–critic architectures commonly used in model-free MARL.
Therefore, we implement both the actor $\psi$ and critic $\xi$ with two 3-layer MLPs together with ReLU activation and Layer Normalization, respectively.
Similar to off-the-shelf CTDE model-free MARL algorithms, we adopt actor parameter sharing across agents.

\paragraph{Critic loss function.} We utilize $\lambda$-return in DreamerV1 \citep{hafner2020Dreamerv1}, which employs an exponentially weighted average of different $k$-steps TD targets to balance bias and variance as the regression target for the critic.
Given an imagined trajectory $\{\hat{s}_t, \hat{o}_{t}^{1:n}, a_{t}^{1:n}, \hat{r}_{t}, \hat{\gamma}_{t} \}^{H}_{t = 1}$ over all agents, $\lambda$-return is calculated recursively as,
\begin{equation}
    V_{\lambda}( \hat{s}_t ) = \hat{r}_{t}^{i} + \hat{\gamma}_{t} \cdot \left\{
    \renewcommand{\arraystretch}{1.5}
    \begin{array}{lcl}
    (1 - \lambda) V_{\xi}(\hat{s}_{t}) + \lambda V_{\lambda}(\hat{s}_{t+1})  &  \text{if}  & t < H \\
    V_{\xi}( \hat{s}_{t} )     &  \text{if}  & t = H
    \end{array}\right.
\end{equation}
The objective of the critic $\xi$ is to minimize the mean squared difference $\mathcal{L}_{\xi}$ with $\lambda$-returns over imagined trajectories, as
\begin{equation}
\label{equ:critic_loss}
    \mathcal{L}_{\xi} = \mathbb{E}_{\pi_{\psi}} \left[ \sum\nolimits_{t = 1}^{H - 1} \Big( V_{\xi}(\hat{s}_{t}) - {\rm sg} \big( V_{\lambda}( {\hat{s}}_{t} ) \big) \Big)^{2} \right],
\end{equation}
where ${\rm sg}(\cdot)$ denotes the stop-gradient operation. We optimize the critic loss with respect to the critic parameters $\xi$ using the Adam optimizer.

\paragraph{Actor loss function.}
The objective for the actor $\pi_{\psi}^{i}(\cdot | \hat{o}_{t}^{i}):= \pi_{\psi}(\cdot | \hat{o}_{t}^{i})$ is to output actions that maximize the prediction of long-term future rewards made by the critic. To incorporate intermediate rewards more directly, we train the actor to maximize the same $\lambda$-return that was computed for training the critic. In terms of the non-stationarity issue in multi-agent scenarios, we adopt PPO updates, which introduce importance sampling for actor learning. The actor loss function for agent $i$ is:
\begin{align}
\label{equ:actor_loss}
    \mathcal{L}_{\psi}^{i} = -\mathbb{E}_{\pi_{\psi_{\rm old}}^{i}} \Big[ \sum_{t=0}^{H - 1} \mathop{\min} \Big(r_{t}^{i}(\psi) A_{t}, {\rm clip}(r_{t}^{i}(\psi), 1 - \epsilon, 1 + \epsilon) A_{t}\Big) + \eta \mathcal{H}(\pi_{\psi}^{i}(\cdot | \hat{o}_{t}^{i})) \Big]
\end{align}
where $r_{t}^{i}(\psi) = \pi_{\psi}^{i} / \pi_{\psi_{\rm old}}^{i}$ is the policy ratio and $A_{t} = {\rm sg}(V_{\lambda}({\hat{s}}_{t}) - V_{\xi} ({\hat{s}}_{t}))$ is the advantage.
Unlike MAPPO, we choose not to design agent-specific global states, as such designs are overly hand-crafted and inject task-specific human priors, which undermines the generality and soundness of the approach.
Instead, we retain the environment’s original agent-agnostic global state shared among all agents, and feed it into the value function $V_\xi$.
As a result, the estimated advantage function $A_t$ is also shared across all agents during actor updates.
We optimize the actor loss with respect to the actor parameters $\psi$ using the Adam optimizer.
Overall hyperparameters are shown in Table~\ref{table:behavior_learning_hyper}.

