\begin{algorithm}[h]
\caption{DIMA paired with learning in imaginations}
\label{alg:DIMA}
% \SetAlgoLined
\SetKwFunction{FMain}{training\_loop()}
\SetKwFunction{FCollect}{collect\_experience($n$)}
\SetKwFunction{FUpdateStateDec}{update\_state\_decoder()}
\SetKwFunction{FUpdateDiff}{update\_diffusion\_model()}
\SetKwFunction{FUpdateRewEnd}{update\_reward\_end\_model()}
\SetKwFunction{FUpdateAC}{update\_actor\_critic()}
\SetKwProg{Fn}{Procedure}{:}{end}
\Fn{\FMain} {
  \For{epochs}{
    % collect\_experience(steps\_collect)\;
    \texttt{collect\_experience(}\textit{steps\_collect}\texttt{)} \\
    \For{steps\_state\_decoder}{
      \FUpdateStateDec
    }
    \For{steps\_diffusion\_model}{
      \FUpdateDiff
    }
    \For{steps\_reward\_end\_model}{
      \FUpdateRewEnd
    }
    \For{steps\_actor\_critic}{
      \FUpdateAC
    }
  }
}

\Fn{\FCollect}{
  $s_0, o_0^{1:n} \gets \texttt{env.reset()}$ \\
  \For{$t = 0$ \KwTo $n-1$}{
    Sample $a_t^i \sim \pi_\psi^i(a_t^i | o_t^i),\, \forall \text{ agent } i$ \\
    $s_{t+1}, o_{t+1}^{1:n}, r_t, \gamma_t \gets \texttt{env.step($a_t^{1:n}$)}$ \\
    $\mathcal{D} \gets \mathcal{D} \cup \{s_{t+1}, o_{t+1}^{1:n}, a_t^{1:n}, r_t, \gamma_t\}$ \\
    \If{$\gamma_t = 1$}{
      $s_{t+1}, o_{t+1}^{1:n} \gets \texttt{env.reset()}$
    }
  }
}

\Fn{\FUpdateStateDec}{
  Sample state-observation pair $(s_t, o_t^{1:n}) \sim \mathcal{D}$ \\
  Compute $\mathcal{L}_\text{FSQ}$ in Eq.~\eqref{equ:fsq_loss} \\
  Update State Decoder $g_\varphi$ \\
}

\Fn{\FUpdateDiff}{
  Sample sequence $\left(s_{t-L+1}, a_{t-L+1}^{1:n}, \dots, s_t, a_t^{1:n}, s_{t+1}\right) \sim \mathcal{D}$ \\
  Sample $\log(\sigma) \sim \mathcal{N}(P_{\text{mean}}, P_{\text{std}}^2)$ and get $\tau = \sigma$ since $\sigma(\tau) := \tau$ \\  %\tcp*[r]{log-normal sigma from EDM}
  % Define $\tau := \sigma$\; \tcp*[r]{default identity schedule}
  Sample $s_{t+1}^\tau \sim \mathcal{N}(x_{t+1}^0, \sigma^2 \mathbf{I})$  \\ %\; \tcp*[r]{Add Gaussian noise}
  Sample a chosen agent id $k \sim \text{Uniform}\{ 1, 2, \dots, n \}$ \\
  Compute $\hat{s}_{t+1}^{(0)} = D_\theta(s_{t+1}^\tau; \tau, a_t^k, \underbrace{s_{t-L+1:t}, a_{t-L+1:t-1}^{1:n}}_{\text{extra temporal context}})$ \\
  Compute loss $\mathcal{L}(\theta) = \|\hat{s}_{t+1}^{(0)} - s_{t+1}\|^2$ in Eq.~\eqref{equ:final_loss} \\
  Update Diffusion Model $D_\theta$ \\
}

\Fn{\FUpdateRewEnd} {
  Sample sequence $\left(s_{t}, a_{t}^{1:n}, r_t, \gamma_t, \dots, s_{t+H-1}, a_{t+H-1}^{1:n}, r_{t+H-1}, \gamma_{t+H-1} \right) \sim \mathcal{D}$ \\
  \For{$i = t$ \KwTo $t+H-1$}{
    Compute $\hat{r}_i \sim f_\phi(\hat{r}_i | s_{\leq i}, a_{\leq i}^{1:n})$ and $\hat{\gamma}_i \sim f_\phi(\hat{\gamma}_i | s_{\leq i}, a_{\leq i}^{1:n})$ \\
  }
  Compute $\mathcal{L}_\phi = \sum_{i=t}^{t+H-1} \text{CrossEntropy}(\hat{\gamma}_{i}, \gamma_i) + \text{SmoothL1}(\hat{r}_i, r_i)$ corresponding to Eq.~\eqref{equ:rew_end_loss} \\
  Update Reward and Termination Model $f_\phi$ \\
}

\Fn{\FUpdateAC} {
  Set the joint action condition order $\rho = (i_1, i_2, \dots, i_n)$ \\
  Sample starting point $\left(s_{t-L+1}, o_{t-L+1}^{1:n}, a_{t-L+1}^{1:n}, \dots, s_t, o_{t}^{1:n}\right) \sim \mathcal{D}$ of the imagination \\
  Let $\hat{o}_t^{1:n} = o_{t}^{1:n}$ \\
  \For{$i = t$ \KwTo $t+H-1$}{
    Sample $a_i^j \sim \pi_\psi^j(a_i^j | \hat{o}_i^j) \,\, \forall \text{  agent  } j$ \\
    Sample the reward $\hat{r}_i$ and the termination $\hat{\gamma}_i$ with $f_\phi$ \\
    Sample the next global state $\hat{s}_{t+1}$ by iteratively denoising with $D_\theta$ and $\rho$ \\
    Sample the next joint observation state $\hat{o}_{t+1}^{1:n}$ with $g_\varphi$ \\
  }
  Update actor $\pi_{\psi}^{i}$ and critic $V_{\xi}$ via $\mathcal{L}_\xi$ and $\mathcal{L}_\psi^i$ over imaginations $\{ \hat{s}_i, \hat{o}_{i}^{1:n}, {a}_{i}^{1:n}, \hat{r}_{i}, \hat{\gamma}_{i} \}^{t+ H - 1}_{i = t}$ \\
}
\end{algorithm}


