    \label{fig:algorithm}
\end{figure*}

\paragraph{Markov Games}
We model agent cooperation as a team-based \emph{Markov game}. A Markov game for $\nagents$ agents consists of a set of states $\statespace$ with initial state distribution $\rho: \statespace \rightarrow [0,1]$, and a set of actions $\allacts$ and observations $\allobs$ (consisting of features correlated with the state) for each agent $i$. The agent set is partitioned into disjoint teams $\team_1, \ldots, \team_L \subseteq [\nagents]$. Each agent chooses actions according to a policy $\pi_\aindex: \agentobsspace \rightarrow \agentactspace$. After agents simultaneously execute actions $\jointact$, the environment produces the next state based on the state transition function $\transitionprob: \statespace \times \actspace_1 \times \ldots \times \actspace_\nagents \rightarrow \statespace$, a joint reward for each team $\team_\ell$ based on $\rewardfunc_\ell : \statespace \times \prod_{\aindex \in \team_\ell} \actspace_\aindex \rightarrow \mathbb{R}$, and private observations $\obsfunc_\aindex : \statespace \rightarrow \agentobsspace$. Each agent maximises its team's return $\return_\ell = \sum_{t=0}^T \gamma^t \rewardfunc_\ell(s_t, \pi(\jointob_t))$ over $T$ timesteps, where $\gamma$ is a discount factor weighting the importance of future rewards.

\paragraph{MARL}
We refer to a policy profile as $\pi=(\pi_1, \ldots, \pi_\nagents)$, a policy profile excluding agent $\aindex$ as $\pi_{-\aindex}$, a joint policy profile for team $\team_\ell$ as $\pi_\ell = (\pi_i, \forall i \in \team_\ell)$, and a joint policy profile excluding all agents in $\team_\ell$ as $\pi_{-\ell} = (\pi_i, \forall i \notin \team_\ell)$. Each agent's \emph{value function} and \emph{state-action value} (or $Q$) \emph{function} characterise its expected returns under a policy profile $\pi$:
\begin{align*}
    &V^{\pi_\aindex} (s) = \agentreward + \gamma\sum_{s' \in \statespace} \transitionprob(\s, \pi_1(\ob_1), \ldots, \pi_{\nagents}(\ob_\nagents), \s')V^{\pi}_\aindex(\s'), \\
    &Q^{\pi_\aindex}(s, \jointact) = \agentreward + \gamma \sum_{s' \in S} \transitionprob(s, a_1, \ldots, a_\nagents,s')V^{\pi_\aindex}(s')
\end{align*}
Our algorithm assumes access to value and $Q$-functions that take the global observations of all agents, not states, as input: $V^{\pi_\aindex}(\jointob)$ and $Q^{\pi_\aindex}(\jointob, \jointact)$. Such $Q$-functions are used by actor-critic MARL algorithms that rely on centralised training with decentralised execution \cite{Lowe2017,Foerster2018}. Lastly, we define \emph{mean} value functions and state-action value functions for each team: $\bar{V}^{\pi_\ell}(\jointob) := \frac{1}{|\team_\ell|} \sum_{\aindex \in \team_\ell} V^{\pi_\aindex} (\jointob), \bar{Q}^{\pi_\ell}(\jointob, \jointact) := \frac{1}{|\team_\ell|} \sum_{\aindex \in \team_\ell} Q^{\pi_\aindex}(\jointob, \jointact)$.

\paragraph{Decision Trees}
A \emph{decision tree} (\dt) recursively partitions an input space $\mathcal{X}$ through functions $f_j: \mathcal{X} \rightarrow \mathbb{R}$ and thresholds $\tau_j$ at each internal node $j$. Each internal node induces a partition of samples, $P_j = {x \in \mathcal{X} : f_j(x) \leq \tau_j}$. For a {\dt} policy, internal nodes $(f_j, \tau_j)$ encode observation-dependent decision criteria, while leaf nodes $l \in \mathcal{L}$ map partitioned observations to actions: $\hat{\pi}_i: \mathcal{O}_i \rightarrow \mathcal{A}_i, \forall i \in [N]$.

\paragraph{VIPER}
VIPER \cite{Bastani2018} is an imitation learning framework, adapted from the more general DAGGER \cite{Ross2011}, that trains {\dt}s as surrogate policies. Given a trained \emph{expert} (\nn) policy $\pi^*$, VIPER iteratively generates \emph{student} (\dt) policies $\hat{\pi}^m$. Specifically, in each iteration $m$, VIPER:
\begin{enumerate}[(1)]
    \item \emph{Collects} $K$ new rollouts $\{\jointob, \hat{\pi}^{m-1}(\jointob)\}$ using the previous students from iteration $m-1$ (where $\hat{\pi}^0 := \pi^*$)
    \item \emph{Resamples} a dataset $\mathcal{D}$ from all trajectories collected so far, based on upweighting critical states where taking a suboptimal action may be costly in terms of $Q$-values:
    \begin{align*}
        p_k \propto V^{\pi^*}(\jointob_k) - \min_\jointact Q^{\pi^*}(\jointob_k, \jointact)
    \end{align*}
    \item \emph{Relabels} the dataset with the expert actions $\pi^*(\jointob_k)$
    \item \emph{Trains} new {\dt} students $\hat{\pi}^m$ on $\{\jointob_k, \pi^*(\jointob_k) \mid \jointob_k \in \mathcal{D}\}$
\end{enumerate}
After $M$ iterations, VIPER (5) \emph{selects} a student through validation on an additional set of rollouts. \citet{Ross2011} showed that such a procedure is guaranteed to find a student that is performant on the distribution of states that it induces.

