\section{Proof of Resampling Theorem}
\label{sec:app:rs-proof}

Here, we provide a proof for \Cref{thm:rs} in \Cref{sec:hydraviper:training}.

\setcounter{theorem}{0}
\begin{theorem}
    Given a dataset of observation-action pairs for team $\team_\ell$ in iteration $m$ of HYDRAVIPER, $\mathcal{D}_\ell = \{(\jointob_\ell, \jointact_\ell)\}$, assume there exists a pair $(\jointob_{\ell k}, \jointact_{\ell k})$ that receives the weight $p_{\ell k}^{(m)} = 0$. Then, in iteration $m+1$ of HYDRAVIPER, this pair also receives the weight $p_{\ell k}^{(m+1)} = 0$.
\end{theorem}

\begin{proof}
    If $p_{\ell k}^{(m)} \propto \bar{V}^{\pi_\ell^*}(\jointob_k) - \min_{\jointact_\ell} \bar{Q}^{\pi_\ell^*}(\jointob_k, \jointact_\ell, \pi^*_{-\ell}(\jointob_{-\ell k})) = 0$, then by definition
    \begin{align}
    \begin{split}
        \bar{V}^{\pi_\ell^*}(\jointob_k) := \max_{\jointact_\ell} \bar{Q}^{\pi_\ell^*}(\jointob_k, \jointact_\ell, \pi^*_{-\ell}(\jointob_{-\ell k})) 
        = \min_{\jointact_\ell} \bar{Q}^{\pi_\ell^*}(\jointob_k, \jointact_\ell, \pi^*_{-\ell}(\jointob_{-\ell k})),
    \label{eq:p-iteration-m}
    \end{split}
    \end{align}
    i.e. joint team actions $\jointact_\ell$ have no effect on the value given observation $\jointob_k$. When HYDRAVIPER resamples the dataset in iteration $m$ (\Cref{alg:c-q}, line~3), $(\jointob_{\ell k}, \jointact_{\ell k})$ will not be part of the resampled dataset $\mathcal{D}_\ell'$. However, the resampled dataset $\mathcal{D}_\ell'$ does not replace the original dataset $\mathcal{D}_\ell$.

    In iteration $m + 1$, $\mathcal{D}_\ell$ is aggregated with a newly-collected dataset of observation-action pairs $\mathcal{D}_\ell^m$ (\Cref{alg:tr-a}, line~5), and $(\jointob_{\ell k}, \jointact_{\ell k})$ continues to be part of this dataset. A new set of weights $p_\ell^{(m+1)}$ are computed using this expanded dataset (\Cref{alg:hydraviper}, line~8). Assume that $p_{\ell k}^{(m+1)} \ne 0$. Without loss of generality, let $p_{\ell k}^{(m+1)} > 0$. Then by definition
    \begin{align*}
        \bar{V}^{\pi_\ell^*}(\jointob_k) := \max_{\jointact_\ell} \bar{Q}^{\pi_\ell^*}(\jointob_k, \jointact_\ell, \pi^*_{-\ell}(\jointob_{-\ell k}))  
        > \min_{\jointact_\ell} \bar{Q}^{\pi_\ell^*}(\jointob_k, \jointact_\ell, \pi^*_{-\ell}(\jointob_{-\ell k})).
    \end{align*}
    None of $\jointob_k$, $\pi^*_{-\ell}$, $\bar{V}^{\pi_\ell^*}$, or $\bar{Q}^{\pi_\ell^*}$ changed between iteration $m$ and $m+1$, since HYDRAVIPER uses experts and expert value functions to compute the weights. This contradicts \Cref{eq:p-iteration-m}. Thus, if $p_{\ell k}^{(m)} = 0$, then $p_{\ell k}^{(m+1)} = 0$.
\end{proof}

A similar proof holds if the strict equality is replaced by the threshold $\epsilon$.

