\subsection{Basic Definitions}
\begin{definition}\label{def:Psi}
    Given an input semantics $\mathbf{s}_{0}$ and a set of programs $\mathcal{P}$, the semantic space $\Psi(\mathbf{s}_{0} | \mathcal{P})$ is the set of output semantics of all the programs $\rho$ in $\mathcal{P}$ taking $\mathbf{s}_{0}$ as inputs.
    $$\Psi(\mathbf{s}_{0} | \mathcal{P}) = \{ \rho(\mathbf{s}_{0}) | \rho \in \mathcal{P} \}.$$
\end{definition}

