\begin{definition}
    Given a set of optimal programs $\mathcal{P}^*$, $\mathcal{I}^*$ is the instruction set of all the possible instructions in $\rho^*$.
    $$\mathcal{I}^*=\{\sigma|\sigma\in \rho^*, \rho^*\in\mathcal{P}^* \}.$$
\end{definition}

\begin{definition}
    Given a set of optimal programs $\mathcal{P}^*$, $\Psi^*$ is the semantic set that includes $\mathbf{s}_0$ and all the intermediate and output semantics after sequentially executing each instruction in $\rho^*\in \mathcal{P}^*$ given $\mathbf{s}_0$.
\end{definition}
