\begin{definition}
\label{def:theta_s}
    Given a semantic space $\Psi$ and an optimal semantic space $\Psi^* \subseteq \Psi$, $\Delta_{\Psi}$ is the minimal upper bound on the distance between any semantics in $\Psi$ and any semantics in $\Psi^*$.
    $$\Delta_{\Psi} = \sup_{\mathbf{s}_1\in\Psi, \mathbf{s}_2\in \Psi^*} ||\mathbf{s}_1 - \mathbf{s}_2||.$$
\end{definition}

\begin{remark}%[Minimum value of $\Delta_{\Psi}$]
