    % Suppose there is a null function $f_{null}$ in the set of instructions $\mathbb{F}$, where $f_{null}(S)=S$, then $ \overline{\theta_s} \geq ||g^*(S_{input}) - f_{null}( S_{input})||$ based on \textbf{Definition \ref{def:theta_s}}.
    If $\mathcal{P}$ contains the identity program $\rho_{\mathbb{I}}(\mathbf{s}) = \mathbf{s}$, then $ \Delta_{\Psi} \geq ||\mathbf{s}^* - \mathbf{s}_0||$
\end{remark}

\begin{definition}
\label{def:K}
    Given a semantic space $\Psi$ and a fitness function $f: \Psi \mapsto \mathbb{R}$, $\Delta_{f(\Psi)}$ is the minimal upper bound on the fitness difference between any one semantics in $\Psi$ and the target semantics $\mathbf{s}^*$, normalized by their semantic difference.
    % Given any two semantics $S_1$ and $S_2$ ($\forall S_1, S_2 \in \Psi$) and a fitness evaluation function $fit(\cdot)$, $K$ is the minimum upper bound on $\frac{||fit(S_1) - fit(S_2)||}{\overline{ \theta_{s}}} $.
    $$\Delta_{f(\Psi)} = \sup_{\mathbf{s} \in \Psi} \frac{||f(\mathbf{s}) - f(\mathbf{s}^*)||}{||\mathbf{s} - \mathbf{s}^*||}.$$
\end{definition}

\begin{definition}
\label{def:theta_f}
    Given a semantic space $\Psi$ and the instruction set of optimal programs $\mathcal{I}^*$, 
    % so that $\sigma(\mathbf{s}) \in \Psi$ $(\forall \mathbf{s} \in \Psi, \sigma \in \mathcal{I})$, 
    % Given $S_1, S_2 \in \Psi$ and a set of instructions $\mathbb{F}$ $\st f(S)\in \Psi( \forall f\in \mathbb{F})$, when $||S_1 - S_2||=\theta_{s12}$,
    $\Delta_{(\mathcal{I}^*,\Psi)}$ is the minimal upper bound on the change in the difference between any two semantics in $\Psi$ by applying any single instruction in $\mathcal{I}^*$ to them.
    $$\Delta_{(\mathcal{I}^*,\Psi)} =\sup_{\substack{
        \mathbf{s}_1, \mathbf{s}_2 \in \Psi, \\
        \sigma\in \mathcal{I}^*}} (||\sigma(\mathbf{s}_1) - \sigma(\mathbf{s}_2)||-||\mathbf{s}_1 - \mathbf{s}_2||).$$
\end{definition}

\begin{definition}
\label{def:theta_F}
    % Given $S_1, S_2 \in \Psi$ and a set of instructions $\mathbb{F}$ $\st f(S)\in \Psi( \forall f\in \mathbb{F})$, when $||S_1 - S_2||=\theta_{s12}$, 
    % $\overline{\theta_F}$ is the minimum upper bound on $||f_1(S_1) - f_2(S_2)||-\theta_{s12} $.
