    Given a semantic space $\Psi$, a set of instructions $\mathcal{I}$ so that $\sigma(\mathbf{s}) \in \Psi$ $(\forall \mathbf{s} \in \Psi, \sigma \in \mathcal{I})$, and a set of instructions of optimal programs $\mathcal{I}^*\subseteq \mathcal{I}$,
    $\Delta_{(\mathcal{I}^2,\Psi)}$ is the minimal upper bound on the difference between the two differences: the difference between any two semantics in $\Psi$ and the difference after applying any instruction in $\mathcal{I}$ and any instruction in $\mathcal{I}^*$ to them, respectively.
    $$\Delta_{(\mathcal{I}^2,\Psi)} =\sup_{\substack{
        \mathbf{s}_1, \mathbf{s}_2 \in \Psi, \\
        \sigma_1\in \mathcal{I}, \sigma_2\in \mathcal{I}^*}} (||\sigma_1(\mathbf{s}_1) - \sigma_2(\mathbf{s}_2)||-||\mathbf{s}_1 - \mathbf{s}_2||).$$
\end{definition}

\begin{lemma}
\label{lemma:theta}
    Given a semantic space $\Psi$ and a set of instructions $\mathcal{I}$, we have $0 \leq \Delta_{(\mathcal{I}^*,\Psi)} \leq \Delta_{(\mathcal{I}^2,\Psi)}$. (For proof refer to Appendix \ref{prf:theta})
\end{lemma}

