\section{Smaller Instruction Editing Distance Implies Smaller Fitness Supremum}\label{sec:fitnessgaptheo}
This section first develops a linear relationship between instruction editing distance $\delta$ and fitness supremums. Second, we prove that the probability of fitness values over different instruction editing distance $\delta_{\rho_1,\rho_2}$ is similar when $\mathcal{I}$ and $f(\Psi)$ are well designed. The empirical results verify the relationship. 
% Finally, we propose an approximation framework for LGP based on the fitness supremums.

\subsection{Fitness Supremums and Fitness Distributions}

\begin{theorem}[Supremums on Fitness Gaps]
    \label{theo:dtofit}
    Given an LGP search space 
    $$\mathcal{P}_{\mathcal{I}, L} := \{\sigma_L \circ \sigma_{L-1} \circ \dots \circ \sigma_1(\cdot)\ |\ \sigma_1, \dots, \sigma_L \in \mathcal{I} \},$$ 
    and its corresponding semantic space $\Psi$, where $\mathcal{I}$ is the set of instructions and $L$ is the maximal program length,
    a set of optimal LGP programs $\mathcal{P}^*_{\mathcal{I}^*,L}$
    % $$\mathcal{P}^*_{\mathcal{I}^*,L}:=\{\sigma_L \circ \sigma_{L-1} \circ \dots \circ \sigma_1(\cdot)\ |\ \sigma_1, \dots, \sigma_L \in \mathcal{I}^*\},$$
    and its corresponding semantic space $\Psi^*$ where $\mathcal{I}^*$ is the set of all the possible instructions in $\mathcal{P}^*$,
    an input semantics $\mathbf{s}_0$, 
    and a fitness function $f(\cdot)$, then the fitness gap between any LGP program $\rho \in \mathcal{P}_{\mathcal{I}, L}$ and any program $\rho^*\in\mathcal{P}^*_{\mathcal{I}^*,L}$ has the following supremums.
    \begin{equation}
        |f(\rho)-f(\rho^*)| \leq
        \Delta_{f(\Psi)} (\Delta_{(\mathcal{I}^2,\Psi)} \delta_{\rho,\rho^*} + \Delta_{(\mathcal{I}^*,\Psi)} (L-\delta_{\rho,\rho^*})), \label{eq:fitgap1}
    \end{equation}
    \begin{equation}
