\begin{theorem}[Similar Fitness Probability]\label{theo:similar_fit_dist}
Assuming an LGP search space $\mathcal{P}$ containing the target program ($\rho^* \in \mathcal{P}$) 
% and its corresponding semantic space $\psi$ are
is
given, for any editing distance $d$, let the program subspace $\mathcal{P}^d = \{\rho \in \mathcal{P} | \delta_{\rho, \rho^*} \leq d\}$, and for any fitness $v \in f(\mathcal{P}^{d}) = \{f(\rho) | \rho \in \mathcal{P}^d\}$, let the program subspace $\mathcal{P}^{(d, v)} = \{\rho \in \mathcal{P}^d | f(\rho) = v\}$, then for any distances $d \geq d_0 > 0$ and $v \in f(\mathcal{P}^{d_0})$, if
\begin{equation}
\frac{||\mathcal{P}^{(d+1,v)}\setminus \mathcal{P}^{(d,v)}||}{||\mathcal{P}^{d+1}\setminus \mathcal{P}^{d}||} \leq \frac{||\mathcal{P}^{(d,v)}||}{||\mathcal{P}^{d}||} + \frac{||\mathcal{P}^{(d,v)}||}{||\mathcal{P}^{d+1}\setminus \mathcal{P}^{d}||}, \label{eq:small_dist_variation}
\end{equation}
then we have 
\begin{equation}
    \left | \frac{||\mathcal{P}^{(d+1,v)}||}{||\mathcal{P}^{d+1}||} - \frac{||\mathcal{P}^{(d,v)}||}{||\mathcal{P}^{d}||} \right | < \frac{||\mathcal{P}^{(d,v)}||}{||\mathcal{P}^{d}||}, \label{eq:similar_fit_dist}
\end{equation}
where $||\mathcal{P}||$ stands for the number of programs in the program space $\mathcal{P}$.
\end{theorem}
\begin{proof}
First, we have
% \begin{footnotesize}
    \begin{align*}
   & \frac{||\mathcal{P}^{(d+1,v)}||}{||\mathcal{P}^{d+1}||} - \frac{||\mathcal{P}^{(d,v)}||}{||\mathcal{P}^{d}||} \\
    = \;& \frac{||\mathcal{P}^{(d+1,v)}||\cdot ||\mathcal{P}^{d}|| - ||\mathcal{P}^{(d,v)}|| \cdot ||\mathcal{P}^{d+1}||}{||\mathcal{P}^{d+1}|| \cdot ||\mathcal{P}^{d}||} \\
    = \;& \frac{(||\mathcal{P}^{(d+1,v)}\setminus \mathcal{P}^{(d,v)}|| + || \mathcal{P}^{(d,v)} ||)\cdot ||\mathcal{P}^{d}|| - ||\mathcal{P}^{(d,v)}|| \cdot ||\mathcal{P}^{d+1}||}{||\mathcal{P}^{d+1}|| \cdot ||\mathcal{P}^{d}||} \\
    = \;& \frac{||\mathcal{P}^{(d+1,v)}\setminus \mathcal{P}^{(d,v)}||\cdot ||\mathcal{P}^{d}|| - ||\mathcal{P}^{(d,v)}|| \cdot ||\mathcal{P}^{d+1}\setminus \mathcal{P}^{d}||}{||\mathcal{P}^{d+1}|| \cdot ||\mathcal{P}^{d}||}.
\end{align*}
% \end{footnotesize}%
In addition, since
$$
\frac{||\mathcal{P}^{(d+1,v)}\setminus \mathcal{P}^{(d,v)}||}{||\mathcal{P}^{d+1}\setminus \mathcal{P}^{d}||} \leq \frac{||\mathcal{P}^{(d,v)}||}{||\mathcal{P}^{d}||} + \frac{||\mathcal{P}^{(d,v)}||}{||\mathcal{P}^{d+1}\setminus \mathcal{P}^{d}||},
$$
we have
\begin{align*}
   & ||\mathcal{P}^{(d+1,v)}\setminus \mathcal{P}^{(d,v)}||\cdot ||\mathcal{P}^{d}|| - ||\mathcal{P}^{(d,v)}|| \cdot ||\mathcal{P}^{d+1}\setminus \mathcal{P}^{d}|| \\
   \leq \; & ||\mathcal{P}^{(d,v)}|| \cdot ||\mathcal{P}^{d}||.
\end{align*}
Therefore, 
\begin{equation*}
    \frac{||\mathcal{P}^{(d+1,v)}||}{||\mathcal{P}^{d+1}||} - \frac{||\mathcal{P}^{(d,v)}||}{||\mathcal{P}^{d}||} \leq \frac{||\mathcal{P}^{(d,v)}||}{||\mathcal{P}^{d+1}||} < \frac{||\mathcal{P}^{(d,v)}||}{||\mathcal{P}^{d}||}. \label{eq:sim_fit_dist_pos}
\end{equation*}
Second, if 
$$
\frac{||\mathcal{P}^{(d+1,v)}||}{||\mathcal{P}^{d+1}||} - \frac{||\mathcal{P}^{(d,v)}||}{||\mathcal{P}^{d}||} < 0,
$$
Then
\begin{align*}
& \frac{||\mathcal{P}^{(d,v)}||}{||\mathcal{P}^{d}||} 
 - \frac{||\mathcal{P}^{(d+1,v)}||}{||\mathcal{P}^{d+1}||} \\
    = \;& \frac{||\mathcal{P}^{(d,v)}|| \cdot ||\mathcal{P}^{d+1}\setminus \mathcal{P}^{d}|| - ||\mathcal{P}^{(d+1,v)}\setminus \mathcal{P}^{(d,v)}||\cdot ||\mathcal{P}^{d}||}{||\mathcal{P}^{d+1}|| \cdot ||\mathcal{P}^{d}||} \\
    \leq \;& \frac{||\mathcal{P}^{(d,v)}|| \cdot ||\mathcal{P}^{d+1}\setminus \mathcal{P}^{d}||}{||\mathcal{P}^{d}||\cdot ||\mathcal{P}^{d+1}||} < \frac{||\mathcal{P}^{(d,v)}||}{||\mathcal{P}^{d}||}.
\end{align*}
Overall, we have 
$$
\left | \frac{||\mathcal{P}^{(d+1,v)}||}{||\mathcal{P}^{d+1}||} - \frac{||\mathcal{P}^{(d,v)}||}{||\mathcal{P}^{d}||} \right | < \frac{||\mathcal{P}^{(d,v)}||}{||\mathcal{P}^{d}||}.
$$
Note that $||\mathcal{P}^{d+1}||>||\mathcal{P}^{d}||>0$ as they can be easily constructed by adding instructions into $\rho^*$.
\end{proof}
\begin{remark}
    In \textbf{Theorem \ref{theo:similar_fit_dist}}, $\frac{||\mathcal{P}^{(d,v)}||}{||\mathcal{P}^{d}||}$ stands for the conditional probability 
    $$
    \frac{||\mathcal{P}^{(d,v)}||}{||\mathcal{P}^{d}||} =: \Pr(f(\rho) = v | \delta_{\rho,\rho^*} \leq d),
    $$ 
    and $\frac{||\mathcal{P}^{(d+1,v)}\setminus \mathcal{P}^{(d,v)}||}{||\mathcal{P}^{d+1}\setminus \mathcal{P}^{d}||}$ stands for the conditional probability 
    $$
    \frac{||\mathcal{P}^{(d+1,v)}\setminus \mathcal{P}^{(d,v)}||}{||\mathcal{P}^{d+1}\setminus \mathcal{P}^{d}||} =: \Pr(f(\rho) = v | \delta_{\rho,\rho^*} = d+1),
    $$
    where ``$=:$'' indicates denoting the left side by the right notation.
    Therefore, \textbf{Theorem \ref{theo:similar_fit_dist}} implies that when the LGP program space expands from distance $d$ to distance $d+1$ (by including more distant programs from the target program), if the probability for each fitness value does not increase by more than $\frac{||\mathcal{P}^{(d,v)}||}{||\mathcal{P}^{d+1}\setminus \mathcal{P}^{d}||}$ (Eq. (\ref{eq:small_dist_variation})), then the fitness probability over the search spaces $\mathcal{P}^{d+1}$ and $\mathcal{P}^{d}$ are also similar to each other (at most by $\Pr(f(\rho) = v | \delta_{\rho,\rho^*} \leq d)$ for the probability of each fitness value). 
    $\Pr(f(\rho) = v | \delta_{\rho,\rho^*} \leq d)$ is small enough when the fitness function has multiple possible values across the search space. For example, the R-square fitness function $R^2(\rho)\in [0,1]$ in regression results in small enough $\Pr(f(\rho) = v | \delta_{\rho,\rho^*} \leq d)$, while an indicator function of finding optimal programs or not $f(\rho)\in\{0,1\}$ does not.

\end{remark}

