\label{eq:Edsm}
\mathbb{E}[\delta^*(\rho)\ |\ \rho \in  \mathcal{P}_{m}] = \frac{\sum_{\rho \in \mathcal{P}_{m}} \delta^*_{\rho}}{n^m} = \sum_{d=\inf{\delta^*_{(m)}}}^{\sup{\delta^*_{(m)}}} \frac{d}{n^m}\cdot ||\mathcal{P}^{\delta^*=d}_m ||.
