\begin{theorem}[Similar $\delta^*$ Probability]
    \label{theo:similar_delta_m}
    The probability of $\delta^*=d$ given a program size  $m$ ($||\mathcal{P}^{\delta^*=d}_m||/n^m$) is similar over different $m$, i.e., $$| \frac{||\mathcal{P}^{\delta^*=d}_m||}{n^m} - \frac{||\mathcal{P}^{\delta^*=d}_{m+1}||}{n^{m+1}}|\leq \epsilon,$$ 
where $\epsilon$ is a small enough positive number.
\end{theorem}
\begin{proof}
    The program set $\mathcal{P}^{\delta^*=d}_{m+1}$ can be constructed from $\mathcal{P}^{\delta^*=d}_{m}$, $\mathcal{P}^{\delta^*=d-1}_{m}$, and $\mathcal{P}^{\delta^*=d+1}_{m}$ by adding one intron, or one wrong instruction, or one correct instruction, respectively. Then we have
    $$||\mathcal{P}^{\delta^*=d}_{m+1}|| = ||\mathcal{P}^{\delta^*=d}_{m}||\Omega(m,m+1) + ||\mathcal{P}^{\delta^*=d\pm1}_{m}||\Lambda(m,m+1).$$
    Therefore,
    \begin{equation}
    | \frac{||\mathcal{P}^{\delta^*=d}_m||}{n^m} - \frac{||\mathcal{P}^{\delta^*=d}_{m+1}||}{n^{m+1}}| 
    = \frac{1}{n^m}|||\mathcal{P}^{\delta^*=d}_{m}|| -\frac{||\mathcal{P}^{\delta^*=d}_{m}||\Omega(m,m+1) + ||\mathcal{P}^{\delta^*=d\pm1}_{m}||\Lambda(m,m+1)}{n}|. \nonumber
    \end{equation}
    Based on \textbf{Lemma \ref{lemma:UBLBomega}} and \textbf{Lemma \ref{lemma:UBLBlambda}}, both $\Omega(m,m+1)$ and $\Lambda(m,m+1)$ are linearly correlated to $n$ as both of their upper and lower bounds are linearly correlated to $n$. Therefore, we have
    $$| \frac{||\mathcal{P}^{\delta^*=d}_m||}{n^m} - \frac{||\mathcal{P}^{\delta^*=d}_{m+1}||}{n^{m+1}}|=\frac{1}{n^m}|\alpha_1||\mathcal{P}^{\delta^*=d}_{m}||+\alpha_2||\mathcal{P}^{\delta^*=d\pm1}_{m}|||,$$
    where $\alpha_1$ and $\alpha_2$ are coefficients of $\Omega(m,m+1)$ and $\Lambda(m,m+1)$ by reducing $n$. 
    Because $n$ is a combinatorial number of $\alpha_1$ and $\alpha_2$, and $\mathcal{P}^{\delta^*=\{d,d\pm1\}}_{m}$ is a subset of $\mathcal{P}_m$, 
    $|\alpha_1||\mathcal{P}^{\delta^*=d}_{m}||+\alpha_2||\mathcal{P}^{\delta^*=d\pm1}_{m}|||$ is much smaller than $n^m$ especially when $d$ is relatively small.
    Thus,
    $$| \frac{||\mathcal{P}^{\delta^*=d}_m||}{n^m} - \frac{||\mathcal{P}^{\delta^*=d}_{m+1}||}{n^{m+1}}|\leq \epsilon.$$
\end{proof}

\begin{theorem}
    \label{theo:UB_Emin}
    The expectation of $\delta^*(\rho)$ increases with program size $m$, i.e., 
    $$\mathbb{E}[\delta^*(\rho)\ |\ \rho \in  \mathcal{P}_{m+1}] - \mathbb{E}[\delta^*(\rho)\ |\ \rho \in  \mathcal{P}_{m}]>0$$
\end{theorem}
\begin{proof}
    \begin{equation}
     \mathbb{E}[\delta^*(\rho)\ |\ \rho \in  \mathcal{P}_{m+1}] - \mathbb{E}[\delta^*(\rho)\ |\ \rho \in  \mathcal{P}_{m}] 
     = \sum_{d=\inf{\delta^*_{(m+1)}}}^{\sup{\delta^*_{(m+1)}}} \frac{d}{n^{m+1}}\cdot ||\mathcal{P}^{\delta^*=d}_{m+1} || - \sum_{d=\inf{\delta^*_{(m)}}}^{\sup{\delta^*_{(m)}}} \frac{d}{n^m}\cdot ||\mathcal{P}^{\delta^*=d}_m ||
    \end{equation}

    Based on \textbf{Lemma \ref{lemma:d}}, $\inf{\delta^*_{(m+1)}}\leq \inf{\delta^*_{(m)}}$, and $\sup{\delta^*_{(m+1)}}> \sup{\delta^*_{(m)}}$. Because $\frac{||\mathcal{P}^{\delta^*=d}_m||}{n^m}$ and $ \frac{||\mathcal{P}^{\delta^*=d}_{m+1}||}{n^{m+1}}$ are similar enough and there are more possible $d$ in $\mathbb{E}[\delta^*(\rho)\ |\ \rho \in  \mathcal{P}_{m+1}]$,
    $$\mathbb{E}[\delta^*(\rho)\ |\ \rho \in  \mathcal{P}_{m+1}] - \mathbb{E}[\delta^*(\rho)\ |\ \rho \in  \mathcal{P}_{m}]>0.$$
\end{proof}

