\subsection{Bloat Effect in LGP}
The bloat effect is the phenomenon that GP program size increases significantly while fitness changes slightly or not at all.
This section models the LGP bloat effect by \textbf{Definition \ref{def:constructMove}}.
% Based on $E(d^*|m)$, we further define $E( d'< d|m+\Delta m,d)$ as shown in \textbf{Definition \ref{def:constructMove}}. 
Let $\mathbb{E}[d_m - \delta^*(\rho)\ |\ \rho\in\mathcal{P}^{d_m}_{m + \Delta m}]$ be the expectation of $\delta^*$ reduction and invariance when we sample programs from the search space with a program size of $m+\Delta m$, given a certain program size $m$ and an editing distance $d_m$. The expectation of $\delta^*$ reduction and invariance implies the fitness reduction and invariance after adding or removing $\Delta m$ instructions. Given that LGP prefers moving to search spaces with small or the same fitness (in minimizing problems), we would analyze the variation of program size $\Delta m$ based on the expectation of $\delta^*$.
\begin{definition}
     \label{def:constructMove}
    Given a program size $m$ and an editing distance $d_m$, the expectation of $\delta^*$ reduction and invariance after adding or removing instructions is defined as:
    \begin{equation}
        \mathbb{E}[d_m - \delta^*(\rho)\ |\ \rho\in\mathcal{P}^{d_m}_{m + \Delta m}] 
        % &= \sum_{d=\underline{d}}^{\overline{d}}P(d^*=d | m)\cdot E(\min d'< d | m+V, m\pm V, d) \nonumber \\
        % &=\sum_{d=\underline{d}}^{\overline{d}}P(d^*=d | m)\cdot \nonumber \\
        =\left(\sum_{d=\inf{\delta^*_{(m+\Delta m)}}}^{\min\{\sup{\delta^*_{(m+\Delta m)}},d_m\}} \frac{||\mathcal{P}^{\delta^*=d}_{m+\Delta m}||}{n^{m+\Delta m}} (d_m-d) \right). 
    \end{equation}
    % where $d\leq d_m$ indicates the better and equal $d^*$ after variation.
    % $V$ is the variation size of the program size.
\end{definition}

\begin{corollary}
\label{corol:bloat_effect}
    Given a program size $m$ and an editing distance $d_m$, the expectation of editing distance reduction of newly sampled program $\rho$ in the program set with size of $m+1$ is larger than in the program set with size of $m$, i.e.,   
    $$\mathbb{E}[d_m - \delta^*(\rho)\ |\ \rho\in\mathcal{P}^{d_m}_{m + 1}] - \mathbb{E}[d_m - \delta^*(\rho)\ |\ \rho\in\mathcal{P}^{d_m}_{m }]\geq0.$$
\end{corollary}
\begin{proof}
    Based on \textbf{Lemma \ref{lemma:d}}, we have $\inf{\delta^*_{(m+1)}} \leq \inf{\delta^*_{(m)}}$ and $\min\{\sup{\delta^*_{(m+1)}},d_m\} \geq \min\{\sup{\delta^*_{(m)}},d_m\}$. In other words, there are more adding items in $\mathbb{E}[d_m - \delta^*(\rho)\ |\ \rho\in\mathcal{P}^{d_m}_{m + 1}]$ than in $\mathbb{E}[d_m - \delta^*(\rho)\ |\ \rho\in\mathcal{P}^{d_m}_{m }]$.
    Then based on \textbf{Theorem \ref{theo:similar_delta_m}}, we have
    $$\mathbb{E}[d_m - \delta^*(\rho)\ |\ \rho\in\mathcal{P}^{d_m}_{m + 1}] - \mathbb{E}[d_m - \delta^*(\rho)\ |\ \rho\in\mathcal{P}^{d_m}_{m }]\geq0.$$
\end{proof}

\begin{remark}
    \textbf{Corollary \ref{corol:bloat_effect}} implies 
    $$\mathbb{E}[d_m - \delta^*(\rho)\ |\ \rho\in\mathcal{P}^{d_m}_{m + 1}] - \mathbb{E}[d_m - \delta^*(\rho)\ |\ \rho\in\mathcal{P}^{d_m}_{m-1}]\geq0.$$
    Adding instructions is more likely to reduce and maintain $\delta^*(\rho)$ than removing instructions. Given that the reduction of $\delta^*(\rho)$ implies the reduction of fitness expectation, LGP prefers larger programs than smaller programs, that is, bloat effect.
\end{remark}
Fig. \ref{fig:prog_size} verifies the bloat effect. Fig. \ref{fig:prog_size} shows that the program size of the LGP population consistently grows during evolution, although there is no bias in genetic operators (50\% for adding instructions and 50\% for removing).
