\end{remark}

\begin{corollary}\label{corol:minigeneration}
When LGP only has two operators, adding and removing $u$ random instructions, each with 50\% operator rate, then an LGP individual $\rho$ accesses the neighborhood of $\rho^*$ ($\{\rho|\delta^*(\rho) \leq \epsilon\}$) with a minimum number of generations $q$ so that
    % $$q \geq \log_{1-\overline{ |E_{con}(\Delta d | g)|}/d}(\delta / d)$$
    $$ \underbrace{ D \circ \cdots \circ D(\delta^*(\rho))}_{q \times D(\cdot)} \leq \epsilon,$$
where $D(\delta^*(\rho))=\delta^*(\rho)-\overline{|\mathbb{E}[\Delta \delta^*_{(\rho)}\ |\ \Delta \delta^*_{(\rho)}<0]|}$, and $\epsilon$ is a small enough positive constant.
\end{corollary}

