\subsection{Lemma \ref{lemma:theta}}\label{prf:theta}
Given a semantic space $\Psi$ and a set of instructions $\mathcal{I}$, we have $0 \leq \Delta_{(\mathcal{I}^*,\Psi)} \leq \Delta_{(\mathcal{I}^2,\Psi)}$.
% Given a semantic space $\Psi$ and $\mathbb{F}$, we have $0\leq \overline{\theta_f} \leq \overline{\theta_F}$.

\begin{proof}
    First, by \textbf{Definition \ref{def:theta_f}} ($\Delta_{(\mathcal{I}^*,\Psi)}$ is the minimum upper bound of $||\sigma(\mathbf{s}_1) - \sigma(\mathbf{s}_2)||-||\mathbf{s}_1 - \mathbf{s}_2||$), we must have 
    $$
    \Delta_{(\mathcal{I}^*,\Psi)} \geq ||\sigma(\mathbf{s}) - \sigma(\mathbf{s})|| - ||\mathbf{s} - \mathbf{s}|| = 0, \text{ where } \mathbf{s} \in \Psi.
    $$
    Second, by \textbf{Definition \ref{def:theta_f}} and \textbf{Definition \ref{def:theta_F}}, we have 
    \begin{equation}
        \Delta_{(\mathcal{I}^2,\Psi)} \geq \sup_{\substack{
        \mathbf{s}_1, \mathbf{s}_2 \in \Psi, \sigma \in \mathcal{I}^*}} (||\sigma(\mathbf{s}_1) - \sigma(\mathbf{s}_2)||-||\mathbf{s}_1 - \mathbf{s}_2||) = \Delta_{(\mathcal{I}^*,\Psi)}.
    \end{equation}
    Therefore, $0 \leq \Delta_{(\mathcal{I}^*,\Psi)} \leq \Delta_{(\mathcal{I}^2,\Psi)}$.
\end{proof}
